            raw = pos.get('raw') or {}

            def _pick(*keys):
                for k in keys:
                    v = pos.get(k)
                    if v not in (None, '', '--'):
                        return str(v)
                for k in keys:
                    v = raw.get(k)
                    if v not in (None, '', '--'):
                        return str(v)
                return None

            def _num(s):
                try:
                    m = re.search(r'[-+]?\d[\d,]*\.?\d*', str(s).replace(' ', ''))
                    return float(m.group(0).replace(',', '')) if m else None
                except Exception:
                    return None

            def _sign_color(s):
                v = _num(s)
                if v is None:
                    return NORD_THEME['text_bright']
                if v > 0:
                    return NORD_THEME['accent_red']      # 红涨
                if v < 0:
                    return NORD_THEME['accent_green']    # 绿跌
                return NORD_THEME['text_bright']

            def _fmt_money(s):
                v = _num(s)
                if v is None:
                    return str(s)
                if abs(v) >= 1e6:
                    return f"{v/1e6:.2f}M"
                if abs(v) >= 1e3:
                    return f"{v/1e3:.1f}K"
                return f"{v:.0f}"

