        if let type = manager.pendingOpenType {
            manager.pendingOpenType = nil
            let candidates = manager.threads.filter { $0.thread_type == type }
            if let target = candidates.first(where: { $0.unread > 0 }) ?? candidates.first {
                path = [target]
            }
        }
    }
