// MARK: - 供音频/自动播放判断「会不会弹窗」（只有真的弹窗才需要打断音频）

extension NewsPointsCoordinator {
    /// 解锁这篇文章是否会弹出任何阻塞式 UI
    func willPromptForUnlock(_ article: Article,
                             auth: AuthManager,
                             viewModel: NewsViewModel) -> Bool {
        if NewsPointsCoordinator.canAccess(article, auth: auth, viewModel: viewModel) { return false }
        if !auth.isLoggedIn { return true }                                   // 未登录 → 登录/订阅门禁
        if !NewsPointsPrefs.autoDeduct { return true }                        // 需要确认弹窗
        return NewsQuotaManager.shared.remainingPointsForAutoDeduct <= 0      // 点数不足 → 邀请/订阅弹窗
    }
}

import SwiftUI

@MainActor
final class NewsQuotaManager: ObservableObject {
    static let shared = NewsQuotaManager()
    private init() {}

    private static let base = "http://106.15.183.158:5001/api/ONews"

    // 与 FreeQuotaManager 保持一致的用户 ID 解析（新闻各处复用）
    static func currentUserId(auth: AuthManager) -> String {
        return FreeQuotaManager.currentUserId(auth: auth)
    }

    @Published var dailyQuota: Int = 0
    @Published var remaining: Int = 0
    @Published var bonusRemaining: Int = 0
    @Published var dailyRemaining: Int = 0
    @Published private(set) var unlockedNewsKeys: Set<String> = []
    @Published var pendingBonusWelcome: Int = 0

    @Published var inviteCode: String = ""
    @Published var inviteRewardCount: Int = 0
    @Published var hasRedeemedInvite: Bool = false
    @Published var inviteRewardPoints: Int = 28
    @Published var loggedIn: Bool = false

    func isNewsUnlocked(_ key: String) -> Bool { unlockedNewsKeys.contains(key) }
    func clearBonusWelcome() { pendingBonusWelcome = 0 }

    /// 【新增】登出/删号时清空本地点数，避免胶囊还显示旧点数
    func reset() {
        dailyQuota = 0
        remaining = 0
        bonusRemaining = 0
        dailyRemaining = 0
        unlockedNewsKeys = []
        pendingBonusWelcome = 0
        inviteCode = ""
        inviteRewardCount = 0
        hasRedeemedInvite = false
        loggedIn = false
        NewsPointsPrefs.reset()      // 可选：登出后恢复"每次询问"
    }

    func refresh(userId: String) async {
        guard let enc = userId.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed),
              let url = URL(string: "\(Self.base)/quota/status?user_id=\(enc)") else { return }
        var req = URLRequest(url: url); req.timeoutInterval = 12
        do {
            let (data, _) = try await URLSession.shared.data(for: req)
            let resp = try JSONDecoder().decode(FreeQuotaManager.QuotaStatus.self, from: data)
            self.dailyQuota      = resp.daily_quota
            self.dailyRemaining  = resp.daily_remaining ?? resp.remaining
            self.bonusRemaining  = resp.bonus_remaining ?? 0
            self.remaining       = resp.total_remaining ?? resp.remaining
            self.unlockedNewsKeys = Set(resp.unlocked_news ?? [])
            self.inviteCode      = resp.invite_code ?? ""
            self.inviteRewardCount = resp.invite_reward_count ?? 0
            self.hasRedeemedInvite = resp.has_redeemed_invite ?? false
            self.inviteRewardPoints = resp.invite_reward_points ?? self.inviteRewardPoints
            self.loggedIn        = resp.logged_in ?? true
            if (resp.bonus_just_granted ?? false), (resp.bonus_remaining ?? 0) > 0 {
                self.pendingBonusWelcome = resp.bonus_remaining ?? 0
            }
        } catch { }
    }

    enum NewsUnlockResult { case success, alreadyUnlocked, quotaExceeded, failed(String) }

    func unlockNews(userId: String, articleKey: String, topic: String) async -> NewsUnlockResult {
        guard let url = URL(string: "\(Self.base)/quota/unlock") else { return .failed("地址无效") }
        var req = URLRequest(url: url); req.httpMethod = "POST"
        req.setValue("application/json", forHTTPHeaderField: "Content-Type"); req.timeoutInterval = 12
        req.httpBody = try? JSONSerialization.data(withJSONObject: [
            "user_id": userId, "article_key": articleKey, "article_topic": topic])
        do {
            let (data, _) = try await URLSession.shared.data(for: req)
            let resp = try JSONDecoder().decode(FreeQuotaManager.UnlockResponse.self, from: data)
            func apply() {
                self.remaining      = resp.total_remaining ?? resp.remaining
                self.bonusRemaining = resp.bonus_remaining ?? self.bonusRemaining
                self.dailyRemaining = resp.daily_remaining ?? self.dailyRemaining
            }
            switch resp.status {
            case "success":          unlockedNewsKeys.insert(articleKey); apply(); return .success
            case "already_unlocked": unlockedNewsKeys.insert(articleKey); apply(); return .alreadyUnlocked
            case "quota_exceeded":   remaining=0; bonusRemaining=0; dailyRemaining=0; return .quotaExceeded
            default: return .failed("未知状态")
            }
        } catch { return .failed(error.localizedDescription) }
    }

    func redeemInvite(userId: String, code: String) async throws -> Int {
        guard let url = URL(string: "\(Self.base)/invite/redeem") else { throw URLError(.badURL) }
        var req = URLRequest(url: url); req.httpMethod = "POST"
        req.setValue("application/json", forHTTPHeaderField: "Content-Type"); req.timeoutInterval = 15
        req.httpBody = try JSONSerialization.data(withJSONObject: ["user_id": userId, "invite_code": code])
        let (data, resp) = try await URLSession.shared.data(for: req)
        guard let http = resp as? HTTPURLResponse else { throw URLError(.badServerResponse) }
        if http.statusCode != 200 {
            if let obj = try? JSONDecoder().decode([String: String].self, from: data), let msg = obj["error"] {
                throw NSError(domain: "Invite", code: http.statusCode, userInfo: [NSLocalizedDescriptionKey: msg])
            }
            throw URLError(.badServerResponse)
        }
        struct R: Codable { let reward_points: Int?; let bonus_remaining: Int?; let remaining_total: Int? }
        let r = try JSONDecoder().decode(R.self, from: data)
        if let b = r.bonus_remaining { self.bonusRemaining = b }
        if let t = r.remaining_total { self.remaining = t }
        return r.reward_points ?? 0
    }
}

//  OSupportChat.swift
//  统一"在线客服"模块（ONews / 美股精灵 通用，仅需改 SupportAppConfig.appName）

import SwiftUI
import UIKit

// MARK: - 配置
enum SupportAppConfig {
    /// ⚠️ ONews 工程填 "ONews"；美股精灵工程填 "Finance"
    static let appName = "ONews"
    static let baseURL = "http://106.15.183.158:5001/api/support"
}

// MARK: - 用户标识（apple id 优先，未登录用 dev_ 设备号）
enum SupportIdentity {
    private static let deviceKey = "SupportDeviceID"

    static var deviceId: String {
        if let s = UserDefaults.standard.string(forKey: deviceKey), !s.isEmpty { return s }
        let vid = UIDevice.current.identifierForVendor?.uuidString ?? UUID().uuidString
        let id = "dev_" + vid
        UserDefaults.standard.set(id, forKey: deviceKey)
        return id
    }

    /// 传入 authManager.userIdentifier 即可
    static func userId(appleId: String?) -> String {
        if let uid = appleId, !uid.isEmpty { return uid }
        return deviceId
    }

    static func userType(_ id: String) -> String { id.hasPrefix("dev_") ? "device" : "apple" }
}

// MARK: - 模型
struct SupportThread: Codable, Hashable, Identifiable {
    let thread_key: String
    let thread_type: String
    let title: String?
    let subtitle: String?
    let status: String?
    let last_sender: String?
    let last_message: String?
    let unread_user: Int?
    let updated_at: String?

    var id: String { thread_key }
    var unread: Int { unread_user ?? 0 }

    var icon: String {
        switch thread_type {
        case "wish":   return "magnifyingglass.circle.fill"
        case "report": return "exclamationmark.bubble.fill"
        default:       return "headphones.circle.fill"
        }
    }
    var tint: Color {
        switch thread_type {
        case "wish":   return .orange
        case "report": return .green
        default:       return .blue
        }
    }
    func typeName(_ en: Bool) -> String {
        switch thread_type {
        case "wish":   return en ? "Request" : "寻片请求"
        case "report": return en ? "Bad link" : "坏链接反馈"
        default:       return en ? "Support"  : "在线咨询"
        }
    }
}

struct SupportMessage: Codable, Hashable, Identifiable {
    let id: Int
    let sender: String
    let content: String
    let created_at: String?
    var isUser: Bool { sender == "user" }
}

private struct SupportThreadsResponse: Codable {
    let threads: [SupportThread]
    let unread_total: Int
}
private struct SupportMessagesResponse: Codable {
    let messages: [SupportMessage]
}

// MARK: - 管理器
@MainActor
final class SupportChatManager: ObservableObject {
    static let shared = SupportChatManager()

    @Published var threads: [SupportThread] = []
    @Published var unreadTotal: Int = 0
    @Published var isLoading = false
    @Published var showChat = false
    /// 从横幅"回复"进来时，指定要自动打开的会话类型（wish / report）
    @Published var pendingOpenType: String? = nil

    private init() {}

    func generalThreadKey(userId: String) -> String {
        "\(SupportAppConfig.appName)|support|\(userId)"
    }

    /// 打开客服窗（type 为 nil 时只显示列表）
    func openChat(type: String? = nil) {
        pendingOpenType = type
        showChat = true
    }

    func refresh(userId: String?) async {
        guard let uid = userId, !uid.isEmpty else { return }
        guard var comp = URLComponents(string: "\(SupportAppConfig.baseURL)/threads") else { return }
        comp.queryItems = [.init(name: "app", value: SupportAppConfig.appName),
                           .init(name: "user_id", value: uid)]
        guard let url = comp.url else { return }
        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            let r = try JSONDecoder().decode(SupportThreadsResponse.self, from: data)
            self.threads = r.threads
            self.unreadTotal = r.unread_total
        } catch {
            // 静默失败，不打扰用户
        }
    }

    func messages(threadKey: String, userId: String) async -> [SupportMessage] {
        guard var comp = URLComponents(string: "\(SupportAppConfig.baseURL)/messages") else { return [] }
        comp.queryItems = [.init(name: "app", value: SupportAppConfig.appName),
                           .init(name: "user_id", value: userId),
                           .init(name: "thread_key", value: threadKey)]
        guard let url = comp.url else { return [] }
        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            let r = try JSONDecoder().decode(SupportMessagesResponse.self, from: data)
            return r.messages
        } catch { return [] }
    }

    @discardableResult
    func send(content: String, threadKey: String?, userId: String) async -> Bool {
        guard let url = URL(string: "\(SupportAppConfig.baseURL)/send") else { return false }
        var req = URLRequest(url: url)
        req.httpMethod = "POST"
        req.setValue("application/json", forHTTPHeaderField: "Content-Type")
        req.timeoutInterval = 15
        var body: [String: Any] = [
            "app": SupportAppConfig.appName,
            "user_id": userId,
            "user_type": SupportIdentity.userType(userId),
            "content": content,
            "app_version": Bundle.main.infoDictionary?["CFBundleShortVersionString"] as? String ?? ""
        ]
        if let tk = threadKey { body["thread_key"] = tk }
        req.httpBody = try? JSONSerialization.data(withJSONObject: body)
        do {
            let (_, resp) = try await URLSession.shared.data(for: req)
            guard let http = resp as? HTTPURLResponse, http.statusCode == 200 else { return false }
            await refresh(userId: userId)
            return true
        } catch { return false }
    }
}

// MARK: - 悬浮客服按钮（长按可拖拽，类似 AssistiveTouch）
struct SupportBubbleOverlay: ViewModifier {
    let userId: String

    @ObservedObject private var manager = SupportChatManager.shared
    @AppStorage("SupportFAB_FX") private var fx: Double = 0.10   // 默认：左侧
    @AppStorage("SupportFAB_FY") private var fy: Double = 0.68   // 默认：偏下
    @State private var dragBase: CGPoint? = nil
    @State private var isDragging = false

    // 【新增】悬浮球自己的弹窗状态：不再直接绑定 manager.showChat，
    // 避免「根首页的全局 sheet」与「悬浮球 sheet」同时触发导致冲突。
    @State private var showChatLocal = false

    private let diameter: CGFloat = 52

    func body(content: Content) -> some View {
        content
            .overlay(
                GeometryReader { geo in
                    let size = geo.size
                    bubble(size: size)
                        .position(current(in: size))
                }
                .ignoresSafeArea(.keyboard)
            )
            // 【修改】改为本地状态
            .sheet(isPresented: $showChatLocal) {
                SupportChatView(userId: userId)
            }
            .task { await manager.refresh(userId: userId) }
    }

    private func current(in size: CGSize) -> CGPoint {
        let x = min(max(CGFloat(fx) * size.width, diameter/2 + 6), size.width - diameter/2 - 6)
        let y = min(max(CGFloat(fy) * size.height, diameter/2 + 10), size.height - diameter/2 - 10)
        return CGPoint(x: x, y: y)
    }

    private func bubble(size: CGSize) -> some View {
        ZStack {
            Circle()
                .fill(LinearGradient(colors: [Color.blue, Color.purple],
                                     startPoint: .topLeading, endPoint: .bottomTrailing))
                .frame(width: diameter, height: diameter)
                .shadow(color: Color.black.opacity(0.28), radius: 8, x: 0, y: 4)

            Image(systemName: "bubble.left.and.bubble.right.fill")
                .font(.system(size: 20, weight: .semibold))
                .foregroundColor(.white)

            if manager.unreadTotal > 0 {
                Text(manager.unreadTotal > 99 ? "99+" : "\(manager.unreadTotal)")
                    .font(.system(size: 11, weight: .heavy))
                    .foregroundColor(.white)
                    .padding(.horizontal, 5)
                    .padding(.vertical, 2)
                    .background(Capsule().fill(Color.red))
                    .overlay(Capsule().stroke(Color.white.opacity(0.9), lineWidth: 1.2))
                    .offset(x: diameter/2 - 4, y: -diameter/2 + 4)
            }
        }
        .opacity(isDragging ? 0.9 : 0.94)
        .scaleEffect(isDragging ? 1.14 : 1.0)
        .animation(.spring(response: 0.3, dampingFraction: 0.7), value: isDragging)
        .contentShape(Circle())
        .onTapGesture {
            // 【修改】点击 = 打开列表（清掉可能残留的定位类型）
            manager.pendingOpenType = nil
            showChatLocal = true
        }
        .simultaneousGesture(dragGesture(in: size))
        .accessibilityLabel("在线客服")
    }

    private func dragGesture(in size: CGSize) -> some Gesture {
        LongPressGesture(minimumDuration: 0.3)
            .onEnded { _ in
                isDragging = true
                dragBase = current(in: size)
                UIImpactFeedbackGenerator(style: .medium).impactOccurred()
            }
            .sequenced(before: DragGesture(minimumDistance: 0))
            .onChanged { value in
                if case .second(true, let drag?) = value {
                    let base = dragBase ?? current(in: size)
                    let nx = base.x + drag.translation.width
                    let ny = base.y + drag.translation.height
                    fx = Double(min(max(nx, diameter/2 + 6), size.width - diameter/2 - 6) / max(size.width, 1))
                    fy = Double(min(max(ny, diameter/2 + 10), size.height - diameter/2 - 10) / max(size.height, 1))
                }
            }
            .onEnded { _ in
                isDragging = false
                dragBase = nil
                // 贴边吸附
                withAnimation(.spring(response: 0.35, dampingFraction: 0.75)) {
                    fx = fx < 0.5 ? 0.08 : 0.92
                }
            }
    }
}

