                         : "确定要取消下载并清除所有已下载的数据吗？")
                }
            }

            if !network.isWiFi {
                HStack(spacing: 6) {
                    Image(systemName: "exclamationmark.triangle.fill").foregroundColor(.orange)
                    Text(isGlobalEnglishMode
                         ? "Switched to cellular, mind your data usage"
                         : "已切换到5G，下载请关注流量")
                        .font(.system(size: 11)).foregroundColor(.orange)
                }
            }
        }
    }

