                )

                ScrollView {
                    WaterfallGridView(items: results, dataManager: dataManager,
                                      playSource: "search")            // ⭐ 搜索结果
                        .padding(.top, 8)

                    Color.clear.frame(height: 20)
                }
                .scrollDismissesKeyboard(.immediately)
                .simultaneousGesture(TapGesture().onEnded {
