    // 整屏（空结果）
    private var emptyWishView: some View {
        VStack(spacing: 20) {
            ZStack {
                Circle()
                    .fill(LinearGradient(colors: [Color.accentColor.opacity(0.18),
                                                  Color.accentColor.opacity(0.04)],
