// MARK: - ⭐ 寻片提交弹窗
private struct WishSubmitSheet: View {
    let initialContent: String
    let keyword: String
    let userId: String?
    let userType: String
    @Binding var isPresented: Bool

    @AppStorage("isGlobalEnglishMode") private var isGlobalEnglishMode = false
    @State private var content: String = ""
    @State private var isSubmitting = false
    @State private var submitted = false
    @State private var errorMsg: String? = nil
    @FocusState private var focused: Bool

    var body: some View {
        VStack(spacing: 0) {
            // header
            HStack {
                Text(isGlobalEnglishMode ? "Request a title" : "告诉我们你想看什么")
                    .font(.headline)
                Spacer()
                Button { isPresented = false } label: {
                    Image(systemName: "xmark.circle.fill")
                        .font(.system(size: 22)).foregroundColor(.secondary)
                }
            }
            .padding(.horizontal, 18).padding(.vertical, 16)
            Divider()

            if submitted {
                successView
            } else {
                inputView
            }
        }
        .presentationBackground(.regularMaterial)
        .onAppear { content = initialContent }
    }

    private var inputView: some View {
        VStack(alignment: .leading, spacing: 16) {
            Text(isGlobalEnglishMode
                 ? "Enter the title / show name. We'll do our best to find it for you."
                 : "输入你想看的剧集 / 电影名称，我们会全力为你寻找。")
                .font(.system(size: 13))
                .foregroundColor(.secondary)

            TextField(isGlobalEnglishMode ? "e.g. The Movie Name" : "例如：想看的剧集名称",
                      text: $content)
                .font(.system(size: 16))
                .focused($focused)
                .submitLabel(.done)
                .padding(14)
                .background(
                    RoundedRectangle(cornerRadius: 12, style: .continuous)
                        .fill(Color(UIColor.secondarySystemBackground))
                )
                .overlay(
                    RoundedRectangle(cornerRadius: 12, style: .continuous)
                        .stroke(Color.accentColor.opacity(0.3), lineWidth: 1)
                )

            if let err = errorMsg {
                Text(err).font(.system(size: 13)).foregroundColor(.red)
            }

            Button { Task { await submit() } } label: {
                HStack {
                    if isSubmitting { ProgressView().tint(.white) }
                    Text(isGlobalEnglishMode ? "Submit" : "提交")
                        .font(.system(size: 16, weight: .bold))
                        .foregroundColor(.white)
                }
                .frame(maxWidth: .infinity).padding(.vertical, 14)
                .background(
                    RoundedRectangle(cornerRadius: 14, style: .continuous)
                        .fill(content.trimmingCharacters(in: .whitespaces).isEmpty
                              ? AnyShapeStyle(Color.secondary.opacity(0.4))
                              : AnyShapeStyle(LinearGradient(colors: [Color.accentColor,
                                                                      Color.accentColor.opacity(0.8)],
                                                             startPoint: .leading, endPoint: .trailing)))
                )
            }
            .disabled(isSubmitting || content.trimmingCharacters(in: .whitespaces).isEmpty)

            Spacer(minLength: 0)
        }
        .padding(18)
    }

    private var successView: some View {
        VStack(spacing: 18) {
            Image(systemName: "checkmark.circle.fill")
                .font(.system(size: 56)).foregroundColor(.green)
            Text(isGlobalEnglishMode ? "Submitted!" : "提交成功！")
                .font(.system(size: 18, weight: .bold))
            Text(isGlobalEnglishMode
                 ? "Thanks! We'll do our best to find it for you."
                 : "感谢反馈，我们会尽快为你寻找。")
                .font(.system(size: 14)).foregroundColor(.secondary)
                .multilineTextAlignment(.center)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .padding(24)
        .onAppear {
            DispatchQueue.main.asyncAfter(deadline: .now() + 1.6) { isPresented = false }
        }
    }

    private func submit() async {
        let text = content.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !text.isEmpty else { return }
        focused = false
        isSubmitting = true
        errorMsg = nil
        do {
            try await OVideoAPI.submitWish(content: text, keyword: keyword,
                                           userId: userId, userType: userType)
            withAnimation { submitted = true }
        } catch {
            errorMsg = error.localizedDescription
        }
        isSubmitting = false
    }
}

// MARK: - 自适应换行布局（不变）
struct FlowLayout: Layout {
    var spacing: CGFloat = 8
    func sizeThatFits(proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) -> CGSize {
        let maxWidth = proposal.width ?? .infinity
        var rowWidth: CGFloat = 0, rowHeight: CGFloat = 0
        var totalHeight: CGFloat = 0, totalWidth: CGFloat = 0
        for sub in subviews {
            let size = sub.sizeThatFits(.unspecified)
            if rowWidth + size.width > maxWidth, rowWidth > 0 {
                totalHeight += rowHeight + spacing
                totalWidth = max(totalWidth, rowWidth - spacing)
                rowWidth = 0; rowHeight = 0
            }
            rowWidth += size.width + spacing
            rowHeight = max(rowHeight, size.height)
        }
        totalHeight += rowHeight
        totalWidth = max(totalWidth, rowWidth - spacing)
        return CGSize(width: maxWidth.isFinite ? maxWidth : totalWidth, height: totalHeight)
    }
    func placeSubviews(in bounds: CGRect, proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) {
        var x: CGFloat = bounds.minX, y: CGFloat = bounds.minY, rowHeight: CGFloat = 0
        for sub in subviews {
            let size = sub.sizeThatFits(.unspecified)
            if x + size.width > bounds.maxX, x > bounds.minX {
                x = bounds.minX; y += rowHeight + spacing; rowHeight = 0
            }
            sub.place(at: CGPoint(x: x, y: y), anchor: .topLeading, proposal: ProposedViewSize(size))
            x += size.width + spacing
            rowHeight = max(rowHeight, size.height)
        }
    }
}

// ONetworkMonitor.swift
// 监听网络状态：是否联网、是否 Wi-Fi

import Foundation
import Network

final class NetworkMonitor: ObservableObject {
    static let shared = NetworkMonitor()

    private let monitor = NWPathMonitor()
    private let queue = DispatchQueue(label: "ONews.NetworkMonitor")

    @Published var isConnected: Bool = true
    @Published var isWiFi: Bool = true
    @Published var isCellular: Bool = false
    @Published var hasResolvedPath: Bool = false

    /// 上一次状态，用来识别"切换"事件
    private var lastIsWiFi: Bool = true
    /// Wi-Fi → 蜂窝的切换回调（可被 HLSDownloadManager 订阅）
    var onSwitchedToCellular: (() -> Void)?

    private init() {
        monitor.pathUpdateHandler = { [weak self] path in
            guard let self = self else { return }
            let connected = path.status == .satisfied
            let wifi = path.usesInterfaceType(.wifi)
            let cellular = path.usesInterfaceType(.cellular)

            DispatchQueue.main.async {
                self.isConnected = connected
                self.isWiFi = wifi
                self.isCellular = cellular
                self.hasResolvedPath = true

                // Wi-Fi → 蜂窝
                if self.lastIsWiFi && !wifi && cellular {
                    self.onSwitchedToCellular?()
                }
                self.lastIsWiFi = wifi
            }
        }
        monitor.start(queue: queue)
    }
}

