                // 付费套餐
                Button(action: { handlePurchase() }) {
                    HStack {
                        VStack(alignment: .leading, spacing: 8) {
                            Text(Localized.planPro).font(.title2.bold()).foregroundColor(.primary)
                            Text(Localized.planProDesc).font(.subheadline).foregroundColor(.secondary)
