                                .fill((isSuccess ? Color.green : Color.orange).opacity(0.1))
                        )
                    }
                    submitButton
                }
                .padding(16)
            }
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button(isGlobalEnglishMode ? "Close" : "关闭") { dismiss() }
                }
