struct SeriesTrackListView: View {
    @EnvironmentObject private var dataManager: OVideoDataManager
    @ObservedObject private var manager = SeriesTrackManager.shared
    @AppStorage("isGlobalEnglishMode") private var isGlobalEnglishMode = false
    @AppStorage("OVideo_TrackNoAutoPopup") private var noAutoPopup = false
    @Environment(\.dismiss) private var dismiss

    @State private var path = NavigationPath()
    @State private var loadingURL: String? = nil
    @State private var detent: PresentationDetent = .medium
    @State private var failMessage: String? = nil
    // 新增：用于控制取消追剧选项弹窗
    @State private var showMuteOptions = false
    @State private var seriesToMute: TrackedSeries? = nil

    var body: some View {
        NavigationStack(path: $path) {
            VStack(spacing: 0) {
                if manager.updatedList.isEmpty {
                    emptyView
                } else {
                    listView
                }
                Divider()
                footer
            }
            .background(Color(UIColor.systemGroupedBackground))
            .navigationTitle(isGlobalEnglishMode ? "New Episodes" : "您追的剧，有更新了！")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .navigationBarTrailing) {
                    Button {
                        dismiss()
                    } label: {
                        Image(systemName: "xmark")
                    }
                }
            }
            .navigationDestination(for: OVideoItem.self) { item in
                VideoDetailView(item: item, dataManager: dataManager, playSource: "tracking")
            }
        }
        .presentationDetents([.medium, .large], selection: $detent)
        .presentationDragIndicator(.visible)
        .onAppear { manager.markAllSeen() }
        .alert(isGlobalEnglishMode ? "Failed to open" : "打开失败",
               isPresented: Binding(get: { failMessage != nil },
                                    set: { if !$0 { failMessage = nil } })) {
            Button("OK", role: .cancel) {}
        } message: { Text(failMessage ?? "") }
        // 新增：取消追剧的选项弹窗
        .confirmationDialog(
            isGlobalEnglishMode ? "If you cancel tracking, you won't be notified of future updates!" : "取消追剧后，不会再提醒您后续的更新了！",
            isPresented: $showMuteOptions,
            titleVisibility: .visible,
            presenting: seriesToMute
        ) { s in
            Button(isGlobalEnglishMode ? "Temporarily Clear" : "临时清除") {
                withAnimation { manager.markWatched(s.sourceURL) }
            }
            Button(isGlobalEnglishMode ? "Cancel Tracking" : "取消追剧", role: .destructive) {
                withAnimation { manager.mute(s.sourceURL) }
            }
            Button(isGlobalEnglishMode ? "Cancel" : "取消", role: .cancel) {}
        }
    }

    // MARK: 列表
    private var listView: some View {
        ScrollView {
            LazyVStack(spacing: 10) {
                ForEach(manager.updatedList) { s in
                    row(s)
                }
            }
            .padding(.horizontal, 14)
            .padding(.vertical, 12)
        }
    }

    private func row(_ s: TrackedSeries) -> some View {
        HStack(spacing: 12) {
            cover(s)

            VStack(alignment: .leading, spacing: 5) {
                Text(s.title)
                    .font(.system(size: 15, weight: .semibold))
                    .foregroundColor(.primary)
                    .lineLimit(2)
                    .multilineTextAlignment(.leading)

                HStack(spacing: 6) {
                    Text(isGlobalEnglishMode ? "+\(s.newEpisodeCount) new" : "新增 \(s.newEpisodeCount) 集")
                        .font(.system(size: 11, weight: .bold))
                        .foregroundColor(.white)
                        .padding(.horizontal, 7).padding(.vertical, 2)
                        .background(Capsule().fill(Color.red.opacity(0.9)))
                    if let info = s.latestInfo, !info.isEmpty {
                        Text(info)
                            .font(.system(size: 11))
                            .foregroundColor(.secondary)
                            .lineLimit(1)
                    }
                }

                if let ep = s.lastWatchedEpisode, !ep.isEmpty {
                    Text((isGlobalEnglishMode ? "Watched: " : "上次看到：") + ep)
                        .font(.system(size: 11))
                        .foregroundColor(.secondary)
                        .lineLimit(1)
                }

                if !s.latestUpdate.isEmpty {
                    Text((isGlobalEnglishMode ? "Updated " : "更新于 ")
                         + String(s.latestUpdate.prefix(16)))
                        .font(.system(size: 10))
                        .foregroundColor(.secondary.opacity(0.8))
                }

                if s.unavailable {
                    Text(isGlobalEnglishMode ? "Source unavailable" : "资源暂不可用")
                        .font(.system(size: 10, weight: .semibold))
                        .foregroundColor(.orange)
                }
            }
            Spacer(minLength: 4)

            if loadingURL == s.sourceURL {
                ProgressView().padding(.trailing, 4)
            } else {
                Button {
                    // 修改这里：不再直接 mute，而是触发弹窗
                    seriesToMute = s
                    showMuteOptions = true
                } label: {
                    Image(systemName: "xmark")
                        .font(.system(size: 12, weight: .bold))
                        .foregroundColor(.secondary)
                        .frame(width: 30, height: 30)
                        .background(Circle().fill(Color.secondary.opacity(0.12)))
                }
                .buttonStyle(PlainButtonStyle())
            }
        }
        .padding(12)
        .background(
            RoundedRectangle(cornerRadius: 14, style: .continuous)
                .fill(Color(UIColor.secondarySystemGroupedBackground))
        )
        .contentShape(Rectangle())
        .onTapGesture { open(s) }
    }

    @ViewBuilder
    private func cover(_ s: TrackedSeries) -> some View {
        ZStack {
            RoundedRectangle(cornerRadius: 8).fill(Color.secondary.opacity(0.12))
            if let img = s.coverImage, !img.isEmpty,
               let url = OVideoAPI.coverURL(for: img) {
                CachedAsyncImage(url: url) { phase in
                    switch phase {
                    case .success(let image): image.resizable().scaledToFill()
                    default: Image(systemName: "film").foregroundColor(.secondary)
                    }
                }
            } else {
                Image(systemName: "film").foregroundColor(.secondary)
            }
        }
        .frame(width: 58, height: 82)
        .clipShape(RoundedRectangle(cornerRadius: 8))
    }

    // MARK: 空态
    private var emptyView: some View {
        VStack(spacing: 14) {
            Image(systemName: "bell.slash")
                .font(.system(size: 44))
                .foregroundColor(.secondary.opacity(0.35))
            Text(isGlobalEnglishMode ? "No new episodes yet" : "暂无剧集更新")
                .font(.system(size: 15, weight: .semibold))
                .foregroundColor(.secondary)
            Text(isGlobalEnglishMode
                 ? "Following \(manager.trackedCount) series. We'll notify you when new episodes arrive."
                 : "已在追 \(manager.trackedCount) 部剧，有新集数时会在这里提醒你")
                .font(.system(size: 12))
                .foregroundColor(.secondary.opacity(0.8))
                .multilineTextAlignment(.center)
                .padding(.horizontal, 40)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .padding(.vertical, 40)
    }

    // MARK: 底部
    private var footer: some View {
        Toggle(isOn: $noAutoPopup) {
            Text(isGlobalEnglishMode ? "Don't pop up automatically" : "以后不再主动弹出")
                .font(.system(size: 13))
                .foregroundColor(.secondary)
        }
        .toggleStyle(SwitchToggleStyle(tint: .accentColor))
        .padding(.horizontal, 18)
        .padding(.vertical, 10)
        .background(Color(UIColor.systemBackground))
    }

    // MARK: 打开详情页
    private func open(_ s: TrackedSeries) {
        guard loadingURL == nil else { return }
        loadingURL = s.sourceURL
        Task {
            let item = await OVideoAPI.fetchDetail(url: s.sourceURL)
            loadingURL = nil
            guard let item = item else {
                failMessage = isGlobalEnglishMode
                    ? "This series is no longer available."
                    : "该剧集资源已不可用"
                return
            }
            detent = .large                 // 跳详情页时自动展开为全屏，体验更好
            path.append(item)
            // 不再自动追平：点击进详情页后仍保留在列表中，
            // 仅通过"临时清除""取消追剧"或后续更新覆盖才移除。
            // DispatchQueue.main.asyncAfter(deadline: .now() + 0.6) {
            //     SeriesTrackManager.shared.markWatched(s.sourceURL)
            // }
        }
    }
}

import Foundation

final class TrackingManager {
    static let shared = TrackingManager()
    private let baseURL = "http://106.15.183.158:5001/api/OVideo/track"

    private let lock = NSRecursiveLock()
    private var sentInSession: Set<String> = []

    private init() {}

    enum EventType: String {
        case play              = "play"
        case downloadStart     = "download_start"
        case downloadComplete  = "download_complete"
    }

    /// 通用上报。失败不抛错，不影响主流程
    /// - Parameters:
    ///   - source: 播放来源（仅在线播放传入，如 "home"/"filter"/"search"）
    ///   - episodeKey: 【新增】本集的解锁 key（与 FreeQuotaManager.unlock 用的一致），
    ///                 传了服务端就能细分「赠送点数 / 每日免费点数」
    ///   - accessType: 【新增】权限来源；不传则自动推断
    func track(event: EventType,
               userId: String?,
               userType: String? = nil,
               videoURL: String,
               videoTitle: String,
               source: String? = nil,
               episodeKey: String? = nil,
               accessType: String? = nil) {
        guard let userId = userId, !userId.isEmpty else { return }
        let resolvedType = userType ?? (userId.hasPrefix("dev_") ? "device" : "apple")
        let key = "\(userId)|\(videoURL)|\(event.rawValue)"

        lock.lock()
        if sentInSession.contains(key) {
            lock.unlock()
            return
        }
        sentInSession.insert(key)
        lock.unlock()

        Task {
            // 【需求3】权限来源：优先用调用方传入，否则自动推断（避免在 ?? 自动闭包中 await）
            let access: String
            if let accessType = accessType {
                access = accessType
            } else {
                access = await Self.resolveAccessType(episodeKey: episodeKey)
            }

            await Self.send(
                userId: userId,
                userType: resolvedType,
                videoURL: videoURL,
                videoTitle: videoTitle,
                eventType: event.rawValue,
                source: source,
                episodeKey: episodeKey,
                accessType: access
            )
        }
    }

    /// 【新增】自动推断这次播放是"订阅看"还是"点数看"
    @MainActor
    private static func resolveAccessType(episodeKey: String?) -> String {
        let auth = AuthManager.shared
        if auth.isPermanentVIP { return "vip_permanent" }
        if auth.isSubscribed   { return "subscription" }
        // 未订阅：视频模块必须先解锁(扣点)才能播放
        if let k = episodeKey, FreeQuotaManager.shared.isUnlocked(k) { return "points" }
        return auth.isLoggedIn ? "points" : "free"
    }

    private static func send(userId: String, userType: String, videoURL: String,
                             videoTitle: String, eventType: String,
                             source: String?, episodeKey: String?,
                             accessType: String) async {
        guard let url = URL(string: "http://106.15.183.158:5001/api/OVideo/track") else { return }
        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        request.timeoutInterval = 10

        var body: [String: Any] = [
            "user_id": userId,
            "user_type": userType,
            "video_url": videoURL,
            "video_title": videoTitle,
            "event_type": eventType,
            "access_type": accessType,          // 【新增】
            "app_version": Bundle.main.infoDictionary?["CFBundleShortVersionString"] as? String ?? ""
        ]
        if let source = source, !source.isEmpty { body["source"] = source }
        if let ek = episodeKey, !ek.isEmpty { body["episode_key"] = ek }   // 【新增】

        request.httpBody = try? JSONSerialization.data(withJSONObject: body)
        _ = try? await URLSession.shared.data(for: request)
    }
}

import SwiftUI
import StoreKit

class ReviewManager {
    // 单例模式
    static let shared = ReviewManager()

    // 持久化存储新闻阅读计数
    @AppStorage("userReadArticleCount") private var readCount: Int = 0

    // 【新增】持久化存储视频交互计数（包括播放返回、详情页返回等）
    @AppStorage("userVideoInteractionCount") private var videoInteractionCount: Int = 0

    // 新闻触发弹窗的阈值：
    private let reviewThresholds: Set<Int> = [10, 25, 50, 100, 200]

    // 【新增】视频触发弹窗的阈值：第 10, 20, 50, 100 次交互（考虑到视频消费频次低于新闻，阈值设得稍低且有节制）
    private let videoThresholds: Set<Int> = [10, 20, 50, 100]

    private init() {}

    /// 记录一次“有效的阅读行为”
    func recordInteraction() {
        readCount += 1
        print("ReviewManager: 当前新闻阅读计数为 \(readCount)")

        if reviewThresholds.contains(readCount) {
            requestReview()
        }
    }

    /// 【新增】记录一次“有效的视频交互行为”（如播放完毕返回、退出详情页等）
    func recordVideoInteraction() {
        videoInteractionCount += 1
        print("ReviewManager: 当前视频交互计数为 \(videoInteractionCount)")

        if videoThresholds.contains(videoInteractionCount) {
            requestReview()
        }
    }

    /// 请求评分弹窗
    private func requestReview() {
        print("ReviewManager: 达到阈值，请求评分弹窗...")

        DispatchQueue.main.async {
            // 获取当前活跃的 WindowScene
            guard let scene = UIApplication.shared.connectedScenes
                .first(where: { $0.activationState == .foregroundActive }) as? UIWindowScene else {
                return
            }

            // 根据系统版本调用不同的 API
            if #available(iOS 16.0, *) {
                // iOS 16+ / iOS 18+ 使用新的 AppStore API
                AppStore.requestReview(in: scene)
            } else {
                // 旧版本兼容 (iOS 14.0 - 15.x)
                SKStoreReviewController.requestReview(in: scene)
            }
        }
    }
}

import SwiftUI
import Foundation

// 文件名: Source_Add.swift
// 职责: 提供列表让用户添加/移除视频订阅与新闻源订阅，并集中管理新闻订阅持久化。

class SubscriptionManager: ObservableObject {
    static let shared = SubscriptionManager() // 单例

    private let subscribedSourceIDsKey = "subscribedNewsSourceIDs"
    let oldSubscribedSourcesKey = "subscribedNewsSources"

    @Published var subscribedSourceIDs: Set<String> {
        didSet { saveSubscribedIDs() }
    }

    private init() {
        let savedIDs = UserDefaults.standard.stringArray(forKey: subscribedSourceIDsKey) ?? []
        self.subscribedSourceIDs = Set(savedIDs)
    }

    private func saveSubscribedIDs() {
        UserDefaults.standard.set(Array(subscribedSourceIDs), forKey: subscribedSourceIDsKey)
    }

    // MARK: - 公共方法
    func isSubscribed(sourceId: String) -> Bool { subscribedSourceIDs.contains(sourceId) }
    func addSubscription(sourceId: String) { subscribedSourceIDs.insert(sourceId) }
    func removeSubscription(sourceId: String) { subscribedSourceIDs.remove(sourceId) }
    func subscribeToAll(_ sourceIds: [String]) { subscribedSourceIDs.formUnion(sourceIds) }
    func removeAll(_ sourceIds: [String]) { sourceIds.forEach { subscribedSourceIDs.remove($0) } }

    func migrateOldSubscription(name: String, id: String) {
        let oldNames = UserDefaults.standard.stringArray(forKey: oldSubscribedSourcesKey) ?? []
        if oldNames.contains(name) {
            print("迁移订阅: 发现旧名称订阅 [\(name)]，自动映射为 ID [\(id)]")
            addSubscription(sourceId: id)
        }
    }
}

struct AddSourceView: View {
    // 新闻源 (ID, Name)
    @State private var allAvailableSources: [(id: String, name: String)] = []
    @State private var isLoading = true
    @State private var errorMessage: String?

    // 视频订阅选择
    @State private var selectedVideoKeys: Set<String> = []

    // 一键全选全部按钮显隐标记
    @State private var showSelectAllTotalBtn = true

    @ObservedObject private var subscriptionManager = SubscriptionManager.shared

    @EnvironmentObject var resourceManager: ResourceManager
    @AppStorage("isGlobalEnglishMode") private var isGlobalEnglishMode = false
    @AppStorage("prefersVideoHome") private var prefersVideoHome = false

    let isFirstTimeSetup: Bool
    var onComplete: (() -> Void)?
    var onConfirm: (() -> Void)?

    @Environment(\.presentationMode) var presentationMode

    private let selectedVideoStorageKey = "selectedVideoCategories"
    private let videoKeyOrder = ["vid_movie", "vid_west_drama", "vid_asia_drama", "vid_anime", "vid_show"]

    // 两列网格
    private let twoColumns = [GridItem(.flexible(), spacing: 12),
                              GridItem(.flexible(), spacing: 12)]

    // MARK: - 计算属性
    private var videoCategories: [(key: String, name: String)] {
        guard resourceManager.showVideoModule else { return [] }
        let mappings = resourceManager.videoCategoryMappings
        return videoKeyOrder.compactMap { key in
            guard let raw = mappings[key] else { return nil }
            let parts = raw.components(separatedBy: "|")
            let name = isGlobalEnglishMode
                ? (parts.count > 1 ? parts[1] : (parts.first ?? raw))
                : (parts.first ?? raw)
            return (key, name)
        }
    }

    private var hasAnySelection: Bool {
        !subscriptionManager.subscribedSourceIDs.isEmpty || !selectedVideoKeys.isEmpty
    }

    // 是否所有视频、所有新闻全部勾选完成
    private var isAllSourcesSelected: Bool {
        let allVideoIds = videoCategories.map(\.key)
        let allVideoSelected = selectedVideoKeys.count == allVideoIds.count && !allVideoIds.isEmpty

        let allNewsIds = allAvailableSources.map(\.id)
        let allNewsSelected = subscriptionManager.subscribedSourceIDs.count == allNewsIds.count && !allNewsIds.isEmpty

        // 如果视频模块关闭（无视频分类），只判断新闻全选；否则两者都要全选
        if videoCategories.isEmpty {
            return allNewsSelected
        } else {
            return allVideoSelected && allNewsSelected
        }
    }

    var body: some View {
        Group {
            if isLoading {
                loadingView
            } else if let error = errorMessage {
                errorView(error)
            } else {
                ScrollView {
                    VStack(alignment: .leading, spacing: 24) {
                        // 上部：视频订阅（仅在应显示视频内容时出现）
                        if !videoCategories.isEmpty {
                            VStack(alignment: .leading, spacing: 14) {
                                moduleHeader(
                                    title: isGlobalEnglishMode ? "Video Sources" : "视频订阅源",
                                    accent: .purple,
                                    onAll: selectAllVideos,
                                    onNone: selectNoneVideos
                                )
                                LazyVGrid(columns: twoColumns, spacing: 12) {
                                    ForEach(videoCategories, id: \.key) { cat in
                                        selectCard(
                                            name: cat.name,
                                            isSelected: selectedVideoKeys.contains(cat.key),
                                            accent: .purple
                                        ) { toggleVideo(cat.key) }
                                    }
                                }
                            }
                        }

                        // 下部：新闻来源
                        VStack(alignment: .leading, spacing: 14) {
                            moduleHeader(
                                title: isGlobalEnglishMode ? "News Sources" : "新闻订阅源",
                                accent: .blue,
                                onAll: selectAllNews,
                                onNone: selectNoneNews
                            )
                            LazyVGrid(columns: twoColumns, spacing: 12) {
                                ForEach(allAvailableSources, id: \.id) { source in
                                    selectCard(
                                        name: source.name,
                                        isSelected: subscriptionManager.isSubscribed(sourceId: source.id),
                                        accent: .blue
                                    ) { toggleNews(source.id) }
                                }
                            }
                        }
                    }
                    .padding(.horizontal, 16)
                    .padding(.top, 14)
                    .padding(.bottom, 24)
                }
                .background(Color.viewBackground)
                .safeAreaInset(edge: .bottom) { bottomBar }
            }
        }
        .navigationTitle(Localized.addSourceTitle)
        .navigationBarTitleDisplayMode(.inline)
        .onAppear {
            loadSelectedVideoKeys()
            loadAvailableSources()
        }
        // 新增下面两行监听
        .onChange(of: selectedVideoKeys) { _ in
            showSelectAllTotalBtn = !isAllSourcesSelected
        }
        .onChange(of: subscriptionManager.subscribedSourceIDs) { _ in
            showSelectAllTotalBtn = !isAllSourcesSelected
        }
    }

    // MARK: - 模块标题 + 全选/全不选
    private func moduleHeader(title: String, accent: Color,
                              onAll: @escaping () -> Void,
                              onNone: @escaping () -> Void) -> some View {
        HStack(spacing: 8) {
            RoundedRectangle(cornerRadius: 2)
                .fill(accent)
                .frame(width: 4, height: 18)
            Text(title)
                .font(.system(size: 18, weight: .bold))
                .foregroundColor(.primary)
            Spacer()
            Button(action: onAll) {
                Text(isGlobalEnglishMode ? "All" : "全选")
                    .font(.system(size: 12, weight: .bold))
                    .foregroundColor(.white)
                    .padding(.horizontal, 14).padding(.vertical, 6)
                    .background(Capsule().fill(accent))
            }
            .buttonStyle(PlainButtonStyle())
            Button(action: onNone) {
                Text(isGlobalEnglishMode ? "None" : "全不选")
                    .font(.system(size: 12, weight: .bold))
                    .foregroundColor(.secondary)
                    .padding(.horizontal, 14).padding(.vertical, 6)
                    .background(Capsule().fill(Color.secondary.opacity(0.15)))
            }
            .buttonStyle(PlainButtonStyle())
        }
    }

    // MARK: - 通用选择卡片
    private func selectCard(name: String, isSelected: Bool,
                            accent: Color, action: @escaping () -> Void) -> some View {
        Button(action: action) {
            HStack(spacing: 10) {
                Text(name)
                    .font(.system(size: 14, weight: .medium))
                    .foregroundColor(.primary)
                    .lineLimit(1)
                    .minimumScaleFactor(0.75)
                Spacer(minLength: 2)
                Image(systemName: isSelected ? "checkmark.circle.fill" : "circle")
                    .font(.system(size: 19))
                    .foregroundColor(isSelected ? accent : Color.secondary.opacity(0.35))
            }
            .padding(.horizontal, 12)
            .padding(.vertical, 13)
            .background(
                RoundedRectangle(cornerRadius: 14, style: .continuous)
                    .fill(isSelected ? accent.opacity(0.10) : Color.cardBackground)
            )
            .overlay(
                RoundedRectangle(cornerRadius: 14, style: .continuous)
                    .stroke(isSelected ? accent.opacity(0.55) : Color.secondary.opacity(0.12),
                            lineWidth: isSelected ? 1.5 : 1)
            )
            .shadow(color: Color.black.opacity(isSelected ? 0.05 : 0.02),
                    radius: 4, x: 0, y: 2)
        }
        .buttonStyle(PlainButtonStyle())
    }

    // MARK: - 底部栏（新增一键全选全部按钮）
    private var bottomBar: some View {
        VStack(spacing: 12) {
            Divider()

            // 新增：一键全选全部按钮，全部选中后自动消失
            if showSelectAllTotalBtn {
                Button(action: selectAllTotal) {
                    Text(isGlobalEnglishMode ? "Select All Sources" : "一键选择全部")
                        .font(.system(size: 25, weight: .semibold))
                        .foregroundColor(.white)
                        .frame(maxWidth: .infinity)
                        .frame(height: 46)
                        .background(Color.indigo)
                        .cornerRadius(14)
                }
                .buttonStyle(PlainButtonStyle())
                .padding(.horizontal, 16)
            }

            // 原有完成按钮
            Button(action: handleConfirm) {
                Text(hasAnySelection ? Localized.finishSetup : Localized.selectAtLeastOne)
                    .font(.headline)
                    .foregroundColor(hasAnySelection ? .white : .secondary)
                    .frame(maxWidth: .infinity)
                    .frame(height: 52)
                    .background(hasAnySelection ? Color.blue : Color.secondary.opacity(0.2))
                    .cornerRadius(16)
            }
            .disabled(!hasAnySelection)
            .padding(.horizontal, 16)
            .padding(.bottom, 16)
            .background(Material.regular)
        }
    }

    // MARK: - 交互
    private func haptic(_ style: UIImpactFeedbackGenerator.FeedbackStyle = .light) {
        let g = UIImpactFeedbackGenerator(style: style)
        g.impactOccurred()
    }

    private func toggleVideo(_ key: String) {
        haptic()
        withAnimation(.spring(response: 0.3, dampingFraction: 0.7)) {
            if selectedVideoKeys.contains(key) { selectedVideoKeys.remove(key) }
            else { selectedVideoKeys.insert(key) }
        }
        saveSelectedVideoKeys()
    }

    private func toggleNews(_ id: String) {
        haptic()
        withAnimation(.spring(response: 0.3, dampingFraction: 0.7)) {
            if subscriptionManager.isSubscribed(sourceId: id) {
                subscriptionManager.removeSubscription(sourceId: id)
            } else {
                subscriptionManager.addSubscription(sourceId: id)
            }
        }
    }

    private func selectAllVideos() {
        haptic(.medium)
        withAnimation(.spring()) { selectedVideoKeys.formUnion(videoCategories.map { $0.key }) }
        saveSelectedVideoKeys()
    }
    private func selectNoneVideos() {
        haptic()
        withAnimation(.spring()) { videoCategories.forEach { selectedVideoKeys.remove($0.key) } }
        saveSelectedVideoKeys()
    }
    private func selectAllNews() {
        haptic(.medium)
        withAnimation(.spring()) { subscriptionManager.subscribeToAll(allAvailableSources.map { $0.id }) }
    }
    private func selectNoneNews() {
        haptic()
        withAnimation(.spring()) { subscriptionManager.removeAll(allAvailableSources.map { $0.id }) }
    }

    // MARK: - 全局一键全选（视频+新闻）
    private func selectAllTotal() {
    haptic(.heavy)
    withAnimation(.spring(response: 0.35, dampingFraction: 0.7)) {
        // 全选视频
        selectedVideoKeys.formUnion(videoCategories.map { $0.key })
        // 全选新闻
        subscriptionManager.subscribeToAll(allAvailableSources.map { $0.id })
    }
    saveSelectedVideoKeys()
    }

    // MARK: - 子视图：加载 / 错误
    private var loadingView: some View {
        VStack(spacing: 16) {
            ProgressView().scaleEffect(1.2)
            Text(Localized.fetchingSources)
                .font(.subheadline)
                .foregroundColor(.secondary)
        }
        .frame(maxHeight: .infinity)
        .background(Color.viewBackground)
    }

    private func errorView(_ error: String) -> some View {
        VStack(spacing: 16) {
            Image(systemName: "exclamationmark.triangle.fill")
                .font(.largeTitle)
                .foregroundColor(.orange)
            Text(error)
                .multilineTextAlignment(.center)
                .padding(.horizontal)
                .foregroundColor(.secondary)
            Button(Localized.refresh) { syncThenLoadSources() }
                .buttonStyle(.bordered)
        }
        .frame(maxHeight: .infinity)
        .background(Color.viewBackground)
    }

    // MARK: - 确认逻辑
    private func handleConfirm() {
        saveSelectedVideoKeys()

        if isFirstTimeSetup {
            let hasNews = !subscriptionManager.subscribedSourceIDs.isEmpty
            let hasVideo = !selectedVideoKeys.isEmpty

            if resourceManager.serverReviewMode {
                // 审核模式：永远进入新闻列表；兜底确保新闻可审
                prefersVideoHome = false
                if subscriptionManager.subscribedSourceIDs.isEmpty {
                    subscriptionManager.subscribeToAll(allAvailableSources.map { $0.id })
                }
            } else {
                // 非审核：只选了视频（没选新闻）→ 直接进视频首页
                prefersVideoHome = hasVideo && !hasNews
            }

            onComplete?()
        } else {
            if let onConfirm {
                onConfirm()
            } else {
                presentationMode.wrappedValue.dismiss()
            }
        }
    }

    // MARK: - 视频订阅本地持久化
    private func loadSelectedVideoKeys() {
        let arr = UserDefaults.standard.stringArray(forKey: selectedVideoStorageKey) ?? []
        selectedVideoKeys = Set(arr)
    }

    private func saveSelectedVideoKeys() {
        UserDefaults.standard.set(Array(selectedVideoKeys), forKey: selectedVideoStorageKey)
    }

    // MARK: - 先同步服务器资源，成功后再加载本地新闻源列表
    private func syncThenLoadSources() {
        isLoading = true
        errorMessage = nil

        Task {
            do {
                try await resourceManager.checkAndDownloadAllNewsManifests(isManual: true)
                resourceManager.showAlreadyUpToDateAlert = false
            } catch {
                await MainActor.run {
                    self.errorMessage = Localized.networkError
                    self.isLoading = false
                }
                return
            }
            loadAvailableSources()
        }
    }

    private func loadAvailableSources() {
        isLoading = true
        errorMessage = nil

        let mappings = resourceManager.sourceMappings
        let useEnglish = self.isGlobalEnglishMode

        DispatchQueue.global(qos: .userInitiated).async {
            do {
                let documentsDirectory = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
                let allFiles = try FileManager.default.contentsOfDirectory(at: documentsDirectory, includingPropertiesForKeys: nil)

                let newsJSONURLs = allFiles
                    .filter { $0.lastPathComponent.starts(with: "onews_") && $0.pathExtension == "json" }

                guard !newsJSONURLs.isEmpty else {
                    let errorMsg = useEnglish
                        ? "No news data found in local storage.\nPlease go back and sync resources first."
                        : "本地未发现新闻数据。\n请先返回主页同步资源。"
                    throw NSError(domain: "AppError", code: 1, userInfo: [NSLocalizedDescriptionKey: errorMsg])
                }

                var sourceMap = [String: String]()
                let decoder = JSONDecoder()

                for url in newsJSONURLs {
                    guard let data = try? Data(contentsOf: url),
                          let decoded = try? decoder.decode([String: [Article]].self, from: data) else {
                        continue
                    }

                    for (fileKeyName, articles) in decoded {
                        if let firstArticle = articles.first, let sourceId = firstArticle.source_id, !sourceId.isEmpty {
                            let rawDisplayName = mappings[sourceId] ?? fileKeyName
                            let parts = rawDisplayName.components(separatedBy: "|")
                            let finalName: String
                            if useEnglish {
                                finalName = parts.count > 1 ? parts[1] : (parts.first ?? rawDisplayName)
                            } else {
                                finalName = parts.first ?? rawDisplayName
                            }
                            sourceMap[sourceId] = finalName
                        }
                    }
                }

                let preferredOrder = NewsViewModel.preferredSourceOrder
                let sortedSources = sourceMap.map { (id: $0.key, name: $0.value) }
                    .sorted { source1, source2 in
                        let index1 = preferredOrder.firstIndex(of: source1.id) ?? Int.max
                        let index2 = preferredOrder.firstIndex(of: source2.id) ?? Int.max
                        if index1 != index2 { return index1 < index2 }
                        return source1.name < source2.name
                    }

                DispatchQueue.main.async {
                    self.allAvailableSources = sortedSources
                    self.isLoading = false
                }
            } catch {
                DispatchQueue.main.async {
                    self.errorMessage = error.localizedDescription
                    self.isLoading = false
                }
            }
        }
    }
}

