struct WelcomeView: View {
    @Binding var hasCompletedInitialSetup: Bool
    @EnvironmentObject var resourceManager: ResourceManager

    @State private var showErrorAlert = false
    @State private var errorMessage = ""
    @State private var showAddSourceView = false
    @State private var ripple = false
    @State private var showAlreadyUpToDateAlert = false

    @Environment(\.scenePhase) private var scenePhase

    @State private var hasAttemptedInitialSync = false
    @State private var hasSyncedSuccessfully = false

    private let fabSize: CGFloat = 60

    private var hasLocalNewsData: Bool {
        let docDir = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
        guard let files = try? FileManager.default.contentsOfDirectory(at: docDir, includingPropertiesForKeys: nil) else { return false }
        return files.contains { $0.lastPathComponent.starts(with: "onews_") && $0.pathExtension == "json" }
    }

    var body: some View {
        NavigationStack {
            ZStack {
                Color.viewBackground.ignoresSafeArea()

                // 【核心改动】审核模式 → 字串飞屏；正式模式 → 整齐展示墙
                VStack(spacing: 0) {
                    Spacer().frame(height: 32)

                    Text(Localized.welcomeInstruction)
                        .font(.system(size: 28, weight: .black, design: .rounded))
                        .foregroundColor(.secondary)
                        .multilineTextAlignment(.center)
                        .padding(.horizontal, 20)

                    if resourceManager.serverReviewMode {
                        FloatingWordsView()
                            .environmentObject(resourceManager)
                            .frame(height: 380)
                            .mask(LinearGradient(gradient: Gradient(colors: [.clear, .black, .black, .clear]),
                                                 startPoint: .top, endPoint: .bottom))
                        Spacer()
                    } else {
                        SourceShowcaseView()
                            .environmentObject(resourceManager)
                            .padding(.top, 4)
                        Spacer(minLength: 32)
                    }
                }

                // 底部按钮层
                if !showAddSourceView {
                    VStack {
                        Spacer()
                        HStack(alignment: .bottom) {
                            if !resourceManager.isSyncing {
                                Button(action: { Task { await syncInitialResources(isManual: true) } }) {
                                    Image(systemName: "arrow.clockwise")
                                        .font(.system(size: 20, weight: .bold))
                                        .foregroundColor(.secondary)
                                        .frame(width: 50, height: 50)
                                        .background(Material.thinMaterial)
                                        .clipShape(Circle())
                                }
                                .padding(.leading, 30)
                            }

                            Spacer()

                            Button(action: {
                                guard !resourceManager.isSyncing else { return }
                                Task {
                                    if !hasSyncedSuccessfully && !hasLocalNewsData {
                                        do {
                                            try await resourceManager.checkAndDownloadAllNewsManifests(isManual: true)
                                            hasSyncedSuccessfully = true
                                            resourceManager.showAlreadyUpToDateAlert = false
                                            showAlreadyUpToDateAlert = false
                                            showAddSourceView = true
                                        } catch {
                                            errorMessage = Localized.syncFailed
                                            showErrorAlert = true
                                        }
                                    } else {
                                        showAddSourceView = true
                                    }
                                }
                            }) {
                                ZStack {
                                    Circle()
                                        .stroke(Color.blue.opacity(ripple ? 0 : 0.5), lineWidth: 2)
                                        .frame(width: fabSize, height: fabSize)
                                        .scaleEffect(ripple ? 1.5 : 1.0)
                                        .opacity(ripple ? 0 : 1)

                                    Image(systemName: "plus")
                                        .font(.system(size: 28, weight: .semibold))
                                        .foregroundColor(.white)
                                        .frame(width: fabSize, height: fabSize)
                                        .background(LinearGradient(colors: [.blue, .purple],
                                            startPoint: .topLeading, endPoint: .bottomTrailing))
                                        .clipShape(Circle())
                                        .shadow(color: .blue.opacity(0.4), radius: 8, x: 0, y: 4)
                                }
                            }
                            .disabled(resourceManager.isSyncing)
                            .padding(.trailing, 30)
                            .onAppear {
                                withAnimation(.easeInOut(duration: 2.0).repeatForever(autoreverses: false)) { ripple.toggle() }
                            }
                        }
                        .padding(.bottom, 40)
                    }
                }

                if resourceManager.isSyncing {
                    ZStack {
                        Color.black.opacity(0.4).ignoresSafeArea()
                        VStack(spacing: 20) {
                            ProgressView()
                                .progressViewStyle(CircularProgressViewStyle(tint: .white))
                                .scaleEffect(1.5)
                            Text(resourceManager.syncMessage)
                                .font(.headline).foregroundColor(.white)
                        }
                    }
                }
            }
            .navigationDestination(isPresented: $showAddSourceView) {
                AddSourceView(isFirstTimeSetup: true, onComplete: {
                    UserDefaults.standard.set(resourceManager.serverReviewMode,
                                              forKey: "setupCompletedDuringReviewMode")
                    self.hasCompletedInitialSetup = true
                })
                .environmentObject(resourceManager)
            }
        }
        .tint(.blue)
        .alert(Localized.fetchFailed, isPresented: $showErrorAlert, actions: {
            Button(Localized.ok, role: .cancel) { }
        }, message: { Text(errorMessage) })
        .alert("", isPresented: $showAlreadyUpToDateAlert) {
            Button(Localized.ok, role: .cancel) {}
        } message: { Text(Localized.upToDateMessage) }
        .onChange(of: scenePhase) { newPhase in
            if newPhase == .active && !hasSyncedSuccessfully && !resourceManager.isSyncing {
                if !hasAttemptedInitialSync {
                    hasAttemptedInitialSync = true
                    Task { await autoSyncWithRetries() }
                } else {
                    Task {
                        try? await Task.sleep(for: .seconds(1))
                        guard !hasSyncedSuccessfully && !resourceManager.isSyncing else { return }
                        await syncInitialResources(isManual: false)
                    }
                }
            }
        }
        .onChange(of: resourceManager.isNetworkAvailable) { isAvailable in
            if isAvailable && !hasSyncedSuccessfully && !resourceManager.isSyncing {
                Task {
                    try? await Task.sleep(for: .seconds(1))
                    guard !hasSyncedSuccessfully && !resourceManager.isSyncing else { return }
                    await syncInitialResources(isManual: false)
                }
            }
        }
        .onChange(of: resourceManager.showAlreadyUpToDateAlert) { newValue in
            if newValue {
                if !showAddSourceView { self.showAlreadyUpToDateAlert = true }
                resourceManager.showAlreadyUpToDateAlert = false
            }
        }
    }

    private func autoSyncWithRetries() async {
        let retryDelays: [UInt64] = [0, 3, 8]
        for (index, delay) in retryDelays.enumerated() {
            guard !hasSyncedSuccessfully else { return }
            if delay > 0 {
                try? await Task.sleep(for: .seconds(delay))
                guard !hasSyncedSuccessfully && !resourceManager.isSyncing else { return }
            }
            print("WelcomeView: 自动同步尝试 #\(index + 1)")
            await syncInitialResources(isManual: false)
        }
        if !hasSyncedSuccessfully {
            print("WelcomeView: 自动同步多次尝试后仍未成功。")
        }
    }

    private func syncInitialResources(isManual: Bool = false) async {
        do {
            try await resourceManager.checkAndDownloadAllNewsManifests(isManual: isManual)
            hasSyncedSuccessfully = true
        } catch {
            if isManual {
                self.errorMessage = Localized.syncFailed
                self.showErrorAlert = true
            }
        }
    }
}

import SwiftUI

// MARK: - ⭐ 季度解析辅助（全局）
// 中文数字转阿拉伯数字（够用到 99）
func chineseNumeralToInt(_ raw: String) -> Int? {
    let s = raw.trimmingCharacters(in: .whitespaces)
    if let n = Int(s) { return n }
    let map: [Character: Int] = ["零":0,"一":1,"二":2,"三":3,"四":4,"五":5,
                                 "六":6,"七":7,"八":8,"九":9,"十":10]
    let chars = Array(s)
    guard !chars.isEmpty else { return nil }
    if s == "十" { return 10 }
    if let idx = chars.firstIndex(of: "十") {
        let before = chars[..<idx]
        let after  = chars[(idx+1)...]
        let tens = before.isEmpty ? 1 : (map[before.first!] ?? 0)
        let ones = after.isEmpty ? 0 : (map[after.first!] ?? 0)
        return tens * 10 + ones
    }
    var val = 0
    for ch in chars {
        guard let d = map[ch] else { return nil }
        val = val * 10 + d
    }
    return val
}

// 罗马数字转整数（I V X L 组合）
func romanNumeralToInt(_ raw: String) -> Int? {
    let map: [Character: Int] = ["I":1,"V":5,"X":10,"L":50,"C":100,"D":500,"M":1000]
    let chars = Array(raw.uppercased())
    guard !chars.isEmpty else { return nil }
    var total = 0, prev = 0
    for ch in chars.reversed() {
        guard let v = map[ch] else { return nil }
        if v < prev { total -= v } else { total += v; prev = v }
    }
    return total > 0 ? total : nil
}

// 从片名解析 (基础名, 季/部号)。支持：
//   第X季 / 洛奇2 / 洛奇4：最后的决战 / 冲上云霄II / 绝望一
//   无任何标记 → 视为第 1 部（base 为整名），以便与后续续集归为同系列
func videoSeasonInfo(from name: String) -> (base: String, season: Int)? {
    let trimmed = name.trimmingCharacters(in: .whitespaces)
    guard !trimmed.isEmpty else { return nil }

    if let r = seasonByExplicitMarker(trimmed) { return r }   // 1. 第X季
    if let r = seasonByRomanSuffix(trimmed)    { return r }   // 2. 冲上云霄II
    if let r = seasonByArabicSuffix(trimmed)   { return r }   // 3. 洛奇2 / 洛奇4：xxx
    if let r = seasonByChineseSuffix(trimmed)  { return r }   // 4. 绝望一
    return (trimmed, 1)                                       // 5. 无标记 → 第1部
}

// 1. 第X季
private func seasonByExplicitMarker(_ name: String) -> (base: String, season: Int)? {
    let pattern = "第\\s*([0-9零一二三四五六七八九十百]+)\\s*季"
    guard let regex = try? NSRegularExpression(pattern: pattern) else { return nil }
    let full = NSRange(name.startIndex..., in: name)
    guard let match = regex.firstMatch(in: name, range: full),
          let numRange = Range(match.range(at: 1), in: name),
          let matchRange = Range(match.range, in: name),
          let season = chineseNumeralToInt(String(name[numRange])) else { return nil }
    var base = name
    base.removeSubrange(matchRange)
    base = base.trimmingCharacters(in: .whitespaces)
    return (base, season)
}

// 2. 结尾罗马数字：冲上云霄II
private func seasonByRomanSuffix(_ name: String) -> (base: String, season: Int)? {
    let pattern = "^(.*?)\\s*([IVXL]{1,7})$"
    guard let regex = try? NSRegularExpression(pattern: pattern) else { return nil }
    let full = NSRange(name.startIndex..., in: name)
    guard let match = regex.firstMatch(in: name, range: full),
          let baseRange = Range(match.range(at: 1), in: name),
          let romanRange = Range(match.range(at: 2), in: name) else { return nil }
    let base = String(name[baseRange]).trimmingCharacters(in: .whitespaces)
    guard !base.isEmpty else { return nil }
    // base 结尾若是 ASCII 字母，多半是英文单词末尾（如 MIX），放弃
    if let last = base.last, last.isLetter, last.isASCII { return nil }
    guard let season = romanNumeralToInt(String(name[romanRange])),
          season >= 1, season <= 39 else { return nil }
    return (base, season)
}

// 3. 结尾阿拉伯数字（可带副标题）：洛奇2 / 洛奇4：最后的决战
private func seasonByArabicSuffix(_ name: String) -> (base: String, season: Int)? {
    let pattern = "^(\\D+?)([0-9]{1,3})(?:[：:\\s\\-—·].*)?$"
    guard let regex = try? NSRegularExpression(pattern: pattern) else { return nil }
    let full = NSRange(name.startIndex..., in: name)
    guard let match = regex.firstMatch(in: name, range: full),
          let baseRange = Range(match.range(at: 1), in: name),
          let numRange = Range(match.range(at: 2), in: name) else { return nil }
    let base = String(name[baseRange]).trimmingCharacters(in: .whitespaces)
    guard !base.isEmpty, let season = Int(String(name[numRange])),
          season >= 1, season <= 99 else { return nil }
    return (base, season)
}

// 4. 结尾中文数字：绝望一 / 绝望二
private func seasonByChineseSuffix(_ name: String) -> (base: String, season: Int)? {
    let numerals = "零一二三四五六七八九十"
    let pattern = "^(.*?[^\(numerals)])([\(numerals)]{1,3})$"
    guard let regex = try? NSRegularExpression(pattern: pattern) else { return nil }
    let full = NSRange(name.startIndex..., in: name)
    guard let match = regex.firstMatch(in: name, range: full),
          let baseRange = Range(match.range(at: 1), in: name),
          let numRange = Range(match.range(at: 2), in: name) else { return nil }
    let base = String(name[baseRange]).trimmingCharacters(in: .whitespaces)
    guard !base.isEmpty, let season = chineseNumeralToInt(String(name[numRange])),
          season >= 1, season <= 99 else { return nil }
    return (base, season)
}

