                    quotaManager.clearBonusWelcome()      // ⭐ 会员不弹礼包
                } else {
                    bonusWelcomeAmount = quotaManager.pendingBonusWelcome
                    showBonusWelcome = true
                }
            }
            if loadedChannels.isEmpty {
                let channels = await dataManager.fetchPlaylist(url: item.url)
