                    }
                } else {
                    ZStack {
                        Color.gray.opacity(0.12)
                        Image(systemName: "film").foregroundColor(.secondary.opacity(0.5))
                    }
                }
            }
            .frame(width: 72, height: 100)
            .clipped()
            .cornerRadius(8)
            .overlay(
                RoundedRectangle(cornerRadius: 8)
                    .stroke(isCurrent ? Color.accentColor : Color.white.opacity(0.15),
