                                      : Color.primary.opacity(0.03))
                        )
                        .overlay(
                            RoundedRectangle(cornerRadius: 12)
                                .stroke(selectedType == type
                                        ? Color.accentColor.opacity(0.4)
                                        : Color.clear, lineWidth: 1)
                        )
