        } message: {
            Text(isGlobalEnglishMode
                ? "You are on a cellular network. Downloading will use mobile data. Continue?"
                : "当前处于蜂窝网络，下载将消耗流量，是否继续？")
        }
        // ⭐ 新人礼包欢迎弹窗
