            Text(seasonLabel(for: s))
                .font(.system(size: 11, weight: isCurrent ? .bold : .medium))
                .foregroundColor(isCurrent ? .accentColor : .secondary)
                .lineLimit(1)
        }
        .frame(width: 72)
    }

