    private var episodeGrid: some View {
        LazyVGrid(columns: [GridItem(.adaptive(minimum: 110), spacing: 10)], spacing: 10) {
            ForEach(episodes, id: \.url) { ep in
                episodeCell(ep)
            }
        }
