        if !network.isWiFi {
            showCellularAlert = true
        } else {
            downloadManager.startDownload(urlString: realURL, title: videoTitle,
                                          coverImage: coverImage, seriesTitle: seriesTitle,
                                          episodeName: episodeName, episodeKey: episodeKey,
