                    .aspectRatio(16.0/9.0, contentMode: .fit)
                    .frame(maxWidth: .infinity)
                    .background(Color.black)

                // ⭐ 固定广告防骗提示条（播放操作面板下方、标题上方）
                //    「反馈修复」现在直达填写页（ReportSheet），省掉中间说明弹窗
