                ScrollView {
                    VStack(alignment: .leading, spacing: 18) {
                        titleCard

                        if let real = realURL {
                            CacheCard(realURL: real,
                                    videoTitle: displayTitle,
                                    coverImage: coverImage,
                                    seriesTitle: seriesBaseTitle,
                                    episodeName: activeEpisodeName,
                                    episodeKey: activeEpisodeURL,
                                    sourceURL: sourceURL)
                        }
                    }
                    .padding(.top, 16)
                }
