/* Firstrade 桥接后台 v4：所有与本机 Python 的 HTTP 通信都在这里做。 */

const BRIDGE_BASE = 'http://127.0.0.1:18888';
const LOG = '[FT-BG]';

async function jsonFetch(url, options) {
  const res = await fetch(url, options);
  const txt = await res.text();
  let data;
  try { data = JSON.parse(txt); } catch (e) { data = { raw: txt }; }
  if (res.status === 409) {
    // 服务端安全阀：需要人工确认，原样把数据交回调用方
    return Object.assign({ __needConfirm: true }, data);
  }
  if (!res.ok) throw new Error(`HTTP ${res.status}: ${txt.slice(0, 300)}`);
  return data;
}

/* 同步持仓（overwrite=true 时服务端会做买卖差异比对） */
async function syncPositions(positions, overwrite = false, force = false) {
  const count = positions ? Object.keys(positions).length : 0;
  if (!count && !(overwrite && force)) {
    return { status: 'skip', reason: 'empty' };
  }
  return jsonFetch(`${BRIDGE_BASE}/sync_positions`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      positions: positions || {},
      overwrite: !!overwrite,
      record_trades: !!overwrite,
      force: !!force
    })
  });
}

/* 一次请求同时落盘 + 拉起图表（增量合并，不做差异比对） */
async function plotWithPositions(symbol, positions) {
  return jsonFetch(`${BRIDGE_BASE}/plot`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ symbol: symbol, positions: positions || {} })
  });
}

async function ping() {
  return jsonFetch(`${BRIDGE_BASE}/ping`, { method: 'GET' });
}

async function fetchServerPositions() {
  return jsonFetch(`${BRIDGE_BASE}/positions`, { method: 'GET' });
}

async function fetchTrades(limit) {
  return jsonFetch(`${BRIDGE_BASE}/trades?limit=${limit || 30}`, { method: 'GET' });
}

chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
  if (!msg || !msg.action) return;

  const done = (p) => {
    p.then((data) => sendResponse({ ok: true, data }))
      .catch((err) => {
        console.warn(LOG, msg.action, '失败:', err);
        sendResponse({ ok: false, error: String(err && err.message ? err.message : err) });
      });
    return true;
  };

  switch (msg.action) {
    case 'FT_SYNC': return done(syncPositions(msg.payload, msg.overwrite, msg.force));
    case 'FT_PLOT': return done(plotWithPositions(msg.symbol, msg.payload));
    case 'FT_PING': return done(ping());
    case 'FT_SERVER_POSITIONS': return done(fetchServerPositions());
    case 'FT_TRADES': return done(fetchTrades(msg.limit));
    default: return;
  }
});

