/* Firstrade 股票标签助手 & 快捷看图 & 持仓回传 & 自动全量抓取 —— content script v4 */
(() => {
  if (window.__FT_TAG_HELPER_V4__) return;
  window.__FT_TAG_HELPER_V4__ = true;

  const LOG_PREFIX = '[FT-TAG]';
  let DEBUG = false;
  let stockTagMap = {};
  let maxTags = 2;

  /* ---------------- 持仓抓取缓存 ---------------- */
  const positionCache = Object.create(null); // { SYMBOL: {...} }
  let lastSentSig = '';
  let syncTimer = null;

  const log = (...a) => { if (DEBUG) console.log(LOG_PREFIX, ...a); };

  /* 列名 -> Python 端友好字段名 */
  const COL_ALIAS = {
    quantity: 'quantity',
    changePercent: 'day_change',
    gainlossPercent: 'gainloss',
    totalCost: 'cost',
    allocationPercent: 'allocation',
    marketValue: 'market_value',
    price: 'last_price',
    lastPrice: 'last_price',
    averageCost: 'avg_cost',
    avgCost: 'avg_cost',
    gainloss: 'gainloss_amount',
    change: 'day_change_amount'
  };

  const sleep = (ms) => new Promise(r => setTimeout(r, ms));

  const getStorage = (keys) => new Promise((res) => {
    try { chrome.storage.local.get(keys, (r) => res(r || {})); } catch (e) { res({}); }
  });
  const setStorage = (obj) => new Promise((res) => {
    try { chrome.storage.local.set(obj, () => res()); } catch (e) { res(); }
  });

  function safeSendMessage(msg) {
    return new Promise((resolve) => {
      try {
        chrome.runtime.sendMessage(msg, (resp) => {
          if (chrome.runtime.lastError) {
            resolve({ ok: false, error: chrome.runtime.lastError.message });
            return;
          }
          resolve(resp || { ok: false, error: 'no response' });
        });
      } catch (e) {
        resolve({ ok: false, error: String(e) });
      }
    });
  }

  /* ---------------- 1. 全局悬浮 Popover ---------------- */
  let popoverEl = null;
  let popoverTimer = null;

  function initGlobalPopover() {
    if (popoverEl && document.body.contains(popoverEl)) return;
    popoverEl = document.createElement('div');
    popoverEl.id = 'ft-global-tag-popover';
    document.body.appendChild(popoverEl);
    popoverEl.addEventListener('mouseenter', () => clearTimeout(popoverTimer));
    popoverEl.addEventListener('mouseleave', () => hidePopover());
  }

  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, (c) => (
      { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]
    ));
  }

  function showPopover(anchorEl, symbol, tags) {
    initGlobalPopover();
    clearTimeout(popoverTimer);

    const hasTags = tags && tags.length > 0;
    const tagsHtml = hasTags
      ? tags.map(t => `<span class="ft-popover-fulltag">${escapeHtml(t)}</span>`).join('')
      : '<span style="color:#94a3b8;font-size:11px;">(无对应标签)</span>';

    const p = positionCache[symbol];
    let posHtml = '';
    if (p) {
      const bits = [];
      if (p.cost) bits.push(`成本 ${escapeHtml(p.cost)}`);
      if (p.day_change) bits.push(`今日 ${escapeHtml(p.day_change)}`);
      if (p.gainloss) bits.push(`盈亏 ${escapeHtml(p.gainloss)}`);
      if (p.quantity) bits.push(`数量 ${escapeHtml(p.quantity)}`);
      if (bits.length) posHtml = `<div class="ft-popover-position">${bits.join(' · ')}</div>`;
    } else {
      posHtml = `<div class="ft-popover-position" style="color:#bf616a;">⚠ 未抓到该行持仓数据</div>`;
    }

    popoverEl.innerHTML = `
      <div class="ft-popover-header">
        <span class="ft-popover-symbol">${escapeHtml(symbol)}</span>
        <span class="ft-popover-openchart-tip" id="ft-popover-btn-launch">📈 打开本机图表</span>
      </div>
      ${posHtml}
      <div class="ft-popover-tags-box">${tagsHtml}</div>
    `;

    const btn = popoverEl.querySelector('#ft-popover-btn-launch');
    if (btn) {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        triggerLocalChart(symbol);
      });
    }

    const rect = anchorEl.getBoundingClientRect();
    popoverEl.style.display = 'block';
    const popWidth = Math.max(popoverEl.offsetWidth, 180);
    const popHeight = popoverEl.offsetHeight;

    let left = rect.left;
    let top = rect.bottom + 4;
    if (left + popWidth > window.innerWidth - 10) left = window.innerWidth - popWidth - 10;
    if (top + popHeight > window.innerHeight - 10) top = rect.top - popHeight - 4;

    popoverEl.style.left = `${Math.max(10, left)}px`;
    popoverEl.style.top = `${top}px`;
    requestAnimationFrame(() => popoverEl.classList.add('ft-popover-show'));
  }

  function hidePopover(delay = 120) {
    if (!popoverEl) return;
    clearTimeout(popoverTimer);
    popoverTimer = setTimeout(() => {
      popoverEl.classList.remove('ft-popover-show');
      setTimeout(() => {
        if (popoverEl && !popoverEl.classList.contains('ft-popover-show')) {
          popoverEl.style.display = 'none';
        }
      }, 150);
    }, delay);
  }

  /* ---------------- 2. 拉起本机 Python 图表 ---------------- */
  async function triggerLocalChart(symbol) {
    if (!symbol) return;
    scrapeGridData();
    const payload = buildPayload();
    log('请求画图:', symbol, '携带持仓条数:', Object.keys(payload).length);

    const resp = await safeSendMessage({ action: 'FT_PLOT', symbol, payload });
    if (!resp.ok) {
      console.warn(`${LOG_PREFIX} 无法连接本地桥接服务(bridge_server.py 是否在运行?)：`, resp.error);
      flashToast(`❌ 桥接失败: ${resp.error}`);
    } else {
      log('图表已启动:', resp.data);
      flashToast(`📈 ${symbol} 已发送（持仓 ${Object.keys(payload).length} 条）`);
    }
  }

  function flashToast(text, ms = 2600) {
    let el = document.getElementById('ft-toast');
    if (!el) {
      el = document.createElement('div');
      el.id = 'ft-toast';
      document.body.appendChild(el);
    }
    el.textContent = text;
    el.classList.add('ft-toast-show');
    clearTimeout(el._t);
    el._t = setTimeout(() => el.classList.remove('ft-toast-show'), ms);
  }

  /* ---------------- 3. 抓取网页真实持仓数据 ---------------- */
  function cleanText(el) {
    let t = (el.innerText || el.textContent || '');
    return t.replace(/\u00a0/g, ' ')
      .replace(/\s+/g, ' ')
      .replace(/(\d),\s+(\d)/g, '$1,$2')
      .trim();
  }

  function symbolFromRowId(rowId) {
    if (!rowId) return '';
    const raw = String(rowId).split('|')[0].trim().toUpperCase();
    if (!/^[A-Z][A-Z0-9.\-]{0,9}$/.test(raw)) return '';
    return raw;
  }

  function scrapeGridData() {
    const rows = document.querySelectorAll('[row-id]');
    if (!rows.length) return 0;

    const buf = Object.create(null);

    rows.forEach((row) => {
      if (row.closest('.ag-floating-top, .ag-floating-bottom')) return;
      const sym = symbolFromRowId(row.getAttribute('row-id'));
      if (!sym) return;
      const rec = buf[sym] || (buf[sym] = { symbol: sym, raw: {} });

      row.querySelectorAll('[col-id]').forEach((cell) => {
        const col = cell.getAttribute('col-id');
        if (!col || col === 'symbol') return;
        const txt = cleanText(cell);
        if (!txt) return;
        rec.raw[col] = txt;
        const alias = COL_ALIAS[col];
        if (alias) rec[alias] = txt;
      });
    });

    let changed = 0;
    Object.keys(buf).forEach((sym) => {
      const rec = buf[sym];
      if (!(rec.cost || rec.day_change || rec.gainloss || rec.quantity)) return;
      const old = positionCache[sym];
      const merged = Object.assign({}, old || {}, rec, {
        raw: Object.assign({}, (old && old.raw) || {}, rec.raw),
        updated_at: Date.now()
      });
      const oldSig = old ? [old.cost, old.day_change, old.gainloss, old.quantity].join('|') : '';
      const newSig = [merged.cost, merged.day_change, merged.gainloss, merged.quantity].join('|');
      positionCache[sym] = merged;
      if (oldSig !== newSig) changed++;
    });

    if (changed > 0) {
      log('抓取更新', changed, '条，累计', Object.keys(positionCache).length, '条');
      debounceSync();
    }
    return Object.keys(buf).length;
  }

  function validPositionCount() {
    return Object.keys(positionCache).filter(k => {
      const p = positionCache[k];
      return p && (p.cost || p.quantity);
    }).length;
  }

  function signature() {
    return Object.keys(positionCache).sort().map(k => {
      const p = positionCache[k];
      return `${k}:${p.cost}|${p.day_change}|${p.gainloss}|${p.quantity}`;
    }).join(';');
  }

  function buildPayload() {
    const out = {};
    Object.keys(positionCache).forEach(k => { out[k] = positionCache[k]; });
    return out;
  }

  function debounceSync(delay = 1500) {
    clearTimeout(syncTimer);
    syncTimer = setTimeout(() => { flushPositions(); }, delay);
  }

  /**
   * overwrite=false 增量合并（服务端不做差异比对）
   * overwrite=true  全量覆盖（服务端会做买卖差异比对）
   * force=true      跳过服务端“疑似抓取不全”安全阀
   */
  async function flushPositions(force = false, overwrite = false, forceTrades = false) {
    const payload = buildPayload();
    const count = Object.keys(payload).length;

    if (overwrite && !count && !forceTrades) {
      return { ok: false, error: '抓取到 0 条持仓，已放弃写入（防误删）。若确实已清仓，请用“强制确认”。' };
    }
    if (!overwrite && !count) return { ok: false, error: 'cache empty' };

    const sig = signature();
    if (!force && !overwrite && sig === lastSentSig) {
      return { ok: true, data: { status: 'unchanged' } };
    }

    const resp = await safeSendMessage({
      action: 'FT_SYNC', payload, overwrite, force: forceTrades
    });
    if (resp.ok) {
      if (!(resp.data && resp.data.__needConfirm)) lastSentSig = sig;
      log('已同步到本机:', resp.data);
    } else {
      log('同步失败:', resp.error);
    }
    return resp;
  }

  /* 自动滚动整张表格，抓齐（含虚拟滚动未渲染的）所有持仓 */
  async function fullScan(opts) {
    const options = opts || {};
    for (const sym of Object.keys(positionCache)) delete positionCache[sym];
    lastSentSig = '';

    const vp = document.querySelector('.ag-body-viewport');
    scrapeGridData();

    if (vp) {
      const original = vp.scrollTop;
      const step = Math.max(150, vp.clientHeight - 60);
      let guard = 0;
      vp.scrollTop = 0;
      await sleep(250);
      scrapeGridData();
      while (guard++ < 400) {
        const atBottom = vp.scrollTop + vp.clientHeight >= vp.scrollHeight - 2;
        if (atBottom) break;
        vp.scrollTop = vp.scrollTop + step;
        await sleep(200);
        scrapeGridData();
      }
      await sleep(250);
      scrapeGridData();
      vp.scrollTop = original;
      await sleep(150);
    }

    const r = await flushPositions(true, true, !!options.force);
    reportScanResult(r, options);
    return r;
  }

  function reportScanResult(r, options) {
    const n = Object.keys(positionCache).length;
    if (!r || !r.ok) {
      flashToast(`❌ 保存失败：${(r && r.error) || '未知错误'}`, 5000);
      return;
    }
    const d = r.data || {};
    if (d.__needConfirm) {
      flashToast(`⚠ 持仓 ${d.old_count} → ${d.new_count} 只，疑似未加载完整，本次未写入。`
        + `请在插件面板点「强制确认」。`, 8000);
      return;
    }
    if (d.status === 'skip') {
      flashToast(`⚠ ${d.warning || '本次未写入'}`, 4000);
      return;
    }
    let msg = `✅ 已保存 ${n} 只持仓`;
    if (d.baseline) {
      msg += '（首次建立基线，未生成交易记录）';
    } else if (d.trades && d.trades.detected > 0) {
      const items = (d.trades.items || []).slice(0, 6)
        .map(t => `${t.symbol}${t.action === 'BUY' ? '买' : '卖'}$${Math.round(t.amount)}`)
        .join('、');
      msg += `\n📝 ${d.trades.detected} 笔交易记为 ${d.trades.trade_date}：${items}`;
    } else if (d.trades) {
      msg += '（持仓无变化）';
    }
    flashToast(msg, options && options.auto ? 5000 : 7000);
  }

  /* ---------------- 4. 自动全量抓取 ---------------- */
  const AUTO_DEFAULT_MIN = 15;
  let autoScanRunning = false;
  let autoScanDoneThisPage = false;
  let lastHref = location.href;

  function gridRowSamples() {
    let n = 0;
    document.querySelectorAll('[row-id]').forEach(r => {
      if (r.closest('.ag-floating-top, .ag-floating-bottom')) return;
      if (symbolFromRowId(r.getAttribute('row-id'))) n++;
    });
    return n;
  }

  async function waitForGridStable(timeoutMs = 45000) {
    const t0 = Date.now();
    let last = -1, stable = 0;
    while (Date.now() - t0 < timeoutMs) {
      if (document.visibilityState !== 'visible') { await sleep(1200); continue; }
      const n = gridRowSamples();
      if (n > 0 && n === last) {
        stable++;
        if (stable >= 2) {
          scrapeGridData();
          if (validPositionCount() > 0) return n;
          stable = 0;
        }
      } else {
        stable = 0;
      }
      last = n;
      await sleep(700);
    }
    return 0;
  }

  async function maybeAutoScan(reason) {
    if (autoScanRunning) return;
    const cfg = await getStorage(['ftAutoScan', 'ftAutoScanAt', 'ftAutoScanMin']);
    if (cfg.ftAutoScan === false) return;                    // 默认开启
    const gapMs = Math.max(1, parseInt(cfg.ftAutoScanMin || AUTO_DEFAULT_MIN, 10)) * 60000;
    if (Date.now() - (cfg.ftAutoScanAt || 0) < gapMs) return;

    autoScanRunning = true;
    try {
      log('自动抓取候选，原因:', reason);
      const n = await waitForGridStable();
      if (!n) { log('等待表格超时，放弃自动抓取'); return; }

      const c2 = await getStorage(['ftAutoScanAt']);          // 二次确认（可能别的标签页刚扫过）
      if (Date.now() - (c2.ftAutoScanAt || 0) < gapMs) return;

      await setStorage({ ftAutoScanAt: Date.now() });
      autoScanDoneThisPage = true;
      flashToast('🔄 正在自动抓取全部持仓…', 2500);
      await fullScan({ auto: true });
    } catch (e) {
      log('自动抓取异常:', e);
    } finally {
      autoScanRunning = false;
    }
  }

  function initAutoScan() {
    setTimeout(() => maybeAutoScan('page-load'), 2500);
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'visible') {
        setTimeout(() => maybeAutoScan('visible'), 1500);
      }
    });
    // SPA 路由切换 / 表格延迟渲染 兜底
    setInterval(() => {
      if (location.href !== lastHref) {
        lastHref = location.href;
        autoScanDoneThisPage = false;
        setTimeout(() => maybeAutoScan('spa-route'), 2500);
        return;
      }
      if (!autoScanDoneThisPage) maybeAutoScan('retry');
    }, 45000);
  }

  /* ---------------- 5. 标签匹配 ---------------- */
  function getTagsForSymbol(symbol) {
    if (!symbol) return [];
    if (stockTagMap[symbol]) return stockTagMap[symbol];
    if (symbol.includes('.')) {
      const alt = symbol.replace(/\./g, '-');
      if (stockTagMap[alt]) return stockTagMap[alt];
    }
    if (symbol.includes('-')) {
      const alt = symbol.replace(/-/g, '.');
      if (stockTagMap[alt]) return stockTagMap[alt];
    }
    return [];
  }

  function loadTags() {
    chrome.storage.local.get(['stockData', 'maxTags', 'ftDebug'], (res) => {
      stockTagMap = res.stockData || {};
      maxTags = res.maxTags || 2;
      DEBUG = !!res.ftDebug;
      clearAllTags();
      scheduleInject();
    });
  }

  chrome.storage.onChanged.addListener((changes, area) => {
    if (area !== 'local') return;
    if (changes.stockData || changes.maxTags || changes.ftDebug) loadTags();
  });

  function clearAllTags() {
    document.querySelectorAll('.ft-custom-tag-container').forEach(el => el.remove());
  }

  function extractSymbol(el) {
    let t = (el.textContent || '').trim().toUpperCase();
    if (!t) return '';
    t = t.split(/[\s\n\r\t/(]/)[0];
    return t.replace(/[^A-Z0-9.\-]/g, '');
  }

  /* ---------------- 6. 构造徽章 ---------------- */
  function buildTagContainer(symbol, tags) {
    const box = document.createElement('span');
    box.className = 'ft-custom-tag-container';
    box.dataset.ftSymbol = symbol;

    if (tags && tags.length) {
      const shown = tags.slice(0, maxTags);
      shown.forEach((txt) => {
        const s = document.createElement('span');
        s.className = 'ft-custom-tag-badge';
        s.textContent = txt;
        box.appendChild(s);
      });
      if (tags.length > shown.length) {
        const more = document.createElement('span');
        more.className = 'ft-custom-tag-badge ft-custom-tag-more';
        more.textContent = `+${tags.length - shown.length}`;
        box.appendChild(more);
      }
    } else {
      const only = document.createElement('span');
      only.className = 'ft-custom-tag-badge ft-custom-tag-chart';
      only.textContent = '📈';
      box.appendChild(only);
    }

    box.addEventListener('mouseenter', () => showPopover(box, symbol, tags));
    box.addEventListener('mouseleave', () => hidePopover());
    box.addEventListener('click', (e) => {
      e.stopPropagation();
      e.preventDefault();
      triggerLocalChart(symbol);
    });
    return box;
  }

  /* ---------------- 7. 注入 ---------------- */
  function injectTags() {
    const cells = document.querySelectorAll('[col-id="symbol"]');
    if (cells.length) {
      cells.forEach((cell) => {
        if (cell.closest('.ag-header')) return;
        const anchor =
          cell.querySelector('button[data-tooltip-trigger]') ||
          cell.querySelector('button') ||
          cell.querySelector('[data-ref="eValue"]');
        if (!anchor) return;

        const row = cell.closest('[row-id]');
        const symbol = (row && symbolFromRowId(row.getAttribute('row-id'))) || extractSymbol(anchor);
        if (!symbol) return;

        anchor.dataset.ftSymbol = symbol;

        const existing = cell.querySelector('.ft-custom-tag-container');
        if (existing && existing.dataset.ftSymbol === symbol) return;
        if (existing) existing.remove();

        const tags = getTagsForSymbol(symbol);
        anchor.insertAdjacentElement('afterend', buildTagContainer(symbol, tags));
      });
    }
    scrapeGridData();
  }

  /* ---------------- 8. 调度 ---------------- */
  let timer = null;
  function scheduleInject(delay = 80) {
    if (timer) return;
    timer = setTimeout(() => { timer = null; try { injectTags(); } catch (e) { log(e); } }, delay);
  }

  function isOurNode(node) {
    if (!node || node.nodeType !== 1) return false;
    return !!(node.classList && (
      node.classList.contains('ft-custom-tag-container') ||
      node.id === 'ft-global-tag-popover' ||
      node.id === 'ft-toast'
    ));
  }

  const observer = new MutationObserver((records) => {
    for (const r of records) {
      if (isOurNode(r.target)) continue;
      scheduleInject();
      return;
    }
  });
  observer.observe(document.documentElement, { childList: true, subtree: true });

  document.addEventListener('scroll', () => scheduleInject(20), true);
  window.addEventListener('resize', () => scheduleInject(100));
  setInterval(() => scheduleInject(0), 2000);
  // 定期兜底：只做增量合并，绝不 overwrite（避免误判卖出）
  setInterval(() => { scrapeGridData(); flushPositions(); }, 30000);

  /* ---------------- 9. 与 popup 通信 ---------------- */
  chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
    if (!msg || !msg.action) return;
    if (msg.action === 'refreshTags') { loadTags(); sendResponse({ ok: true }); return; }
    if (msg.action === 'FT_DUMP') {
      scrapeGridData();
      sendResponse({ ok: true, count: Object.keys(positionCache).length, data: positionCache });
      return;
    }
    if (msg.action === 'FT_SYNC_ALL') {
      fullScan({ force: !!msg.force, auto: false })
        .then(r => sendResponse({
          ok: true,
          count: Object.keys(positionCache).length,
          server: r
        }))
        .catch(e => sendResponse({ ok: false, error: String(e) }));
      return true;
    }
  });

  initGlobalPopover();
  loadTags();
  initAutoScan();
  console.log(LOG_PREFIX, 'Content Script v4 初始化完成（含自动全量抓取）');
})();

const $ = (id) => document.getElementById(id);
const fileInput = $('fileInput');
const pasteArea = $('pasteArea');
const pasteBtn = $('pasteBtn');
const clearBtn = $('clearBtn');
const maxTagsInput = $('maxTags');
const statusEl = $('status');
const bridgeEl = $('bridgeStatus');
const dbgChk = $('dbgChk');
const autoChk = $('autoChk');
const autoMin = $('autoMin');

function setStatus(text, isError) {
  statusEl.style.color = isError ? '#b91c1c' : '#059669';
  statusEl.innerText = text;
}
function setBridge(text, isError) {
  bridgeEl.style.color = isError ? '#b91c1c' : '#059669';
  bridgeEl.innerText = text;
}

/* ---------- 初始化 ---------- */
chrome.storage.local.get(
  ['stockData', 'maxTags', 'ftDebug', 'ftAutoScan', 'ftAutoScanMin', 'ftAutoScanAt'],
  (res) => {
    if (res.maxTags) maxTagsInput.value = res.maxTags;
    dbgChk.checked = !!res.ftDebug;
    autoChk.checked = res.ftAutoScan !== true;      // 默认关闭
    autoMin.value = res.ftAutoScanMin || 15;

    if (res.stockData) {
      const keys = Object.keys(res.stockData);
      setStatus(`已缓存 ${keys.length} 个标的\n示例：${keys.slice(0, 8).join(', ')}`);
    } else {
      setStatus('尚未导入数据，请选择 description.json');
    }
    if (res.ftAutoScanAt) {
      const mins = Math.round((Date.now() - res.ftAutoScanAt) / 60000);
      setBridge(`上次自动抓取：${mins} 分钟前`);
    }
  });

/* ---------- description.json -> {SYMBOL:[tag]} ---------- */
function buildMap(json) {
  const map = {};
  Object.keys(json).forEach((key) => {
    const arr = json[key];
    if (!Array.isArray(arr)) return;
    arr.forEach((item) => {
      if (!item || typeof item !== 'object') return;
      const sym = (item.symbol || '').toString().trim().toUpperCase();
      if (!sym) return;
      let tags = item.tag;
      if (typeof tags === 'string') tags = [tags];
      if (!Array.isArray(tags)) return;
      tags = tags.map(t => String(t).trim()).filter(Boolean);
      if (tags.length) {
        map[sym] = tags;
        if (sym.includes('-')) map[sym.replace(/-/g, '.')] = tags;
        else if (sym.includes('.')) map[sym.replace(/\./g, '-')] = tags;
      }
    });
  });
  return map;
}

function save(map) {
  const count = Object.keys(map).length;
  if (!count) {
    setStatus('解析成功，但没找到任何含 tag 的 symbol，请检查 JSON 结构', true);
    return;
  }
  const maxTags = Math.max(1, Math.min(20, parseInt(maxTagsInput.value, 10) || 2));
  chrome.storage.local.set({ stockData: map, maxTags }, () => {
    if (chrome.runtime.lastError) {
      setStatus('写入失败：' + chrome.runtime.lastError.message, true);
      return;
    }
    setStatus(`导入成功！共 ${count} 个标的\n示例：${Object.keys(map).slice(0, 8).join(', ')}`);
    sendToTab({ action: 'refreshTags' });
  });
}

function sendToTab(msg) {
  return new Promise((resolve) => {
    chrome.tabs.query({ active: true, currentWindow: true }, (tabs) => {
      if (!tabs || !tabs[0] || !tabs[0].id) { resolve({ ok: false, error: '没有活动标签页' }); return; }
      chrome.tabs.sendMessage(tabs[0].id, msg, (resp) => {
        if (chrome.runtime.lastError) {
          resolve({
            ok: false,
            error: chrome.runtime.lastError.message + '（请在 Firstrade 持仓页面打开本插件并刷新页面）'
          });
          return;
        }
        resolve(resp || { ok: false, error: '无响应' });
      });
    });
  });
}

function sendToBg(msg) {
  return new Promise((resolve) => {
    chrome.runtime.sendMessage(msg, (resp) => {
      if (chrome.runtime.lastError) { resolve({ ok: false, error: chrome.runtime.lastError.message }); return; }
      resolve(resp || { ok: false, error: '无响应' });
    });
  });
}

function handleText(text) {
  try { save(buildMap(JSON.parse(text))); }
  catch (err) { setStatus('解析 JSON 失败：' + err.message, true); }
}

/* ---------- 事件：标签部分 ---------- */
fileInput.addEventListener('change', (e) => {
  const file = e.target.files && e.target.files[0];
  if (!file) return;
  setStatus('读取中…');
  const reader = new FileReader();
  reader.onerror = () => setStatus('文件读取失败，请改用粘贴方式', true);
  reader.onload = (ev) => handleText(ev.target.result);
  reader.readAsText(file, 'utf-8');
});

pasteBtn.addEventListener('click', () => {
  const text = pasteArea.value.trim();
  if (!text) { setStatus('粘贴框是空的', true); return; }
  handleText(text);
});

maxTagsInput.addEventListener('change', () => {
  const maxTags = Math.max(1, Math.min(20, parseInt(maxTagsInput.value, 10) || 2));
  chrome.storage.local.set({ maxTags }, () => {
    setStatus(`已设置为每行最多显示 ${maxTags} 个标签`);
    sendToTab({ action: 'refreshTags' });
  });
});

clearBtn.addEventListener('click', () => {
  chrome.storage.local.remove('stockData', () => {
    setStatus('已清空标签缓存');
    sendToTab({ action: 'refreshTags' });
  });
});

dbgChk.addEventListener('change', () => {
  chrome.storage.local.set({ ftDebug: dbgChk.checked }, () => {
    setBridge(dbgChk.checked ? '调试日志已开启（看页面 Console）' : '调试日志已关闭');
  });
});

/* ---------- 事件：自动抓取设置 ---------- */
autoChk.addEventListener('change', () => {
  chrome.storage.local.set({ ftAutoScan: autoChk.checked }, () => {
    setBridge(autoChk.checked ? '✅ 已开启自动全量抓取' : '⏸ 已关闭自动全量抓取');
  });
});

autoMin.addEventListener('change', () => {
  const v = Math.max(1, Math.min(1440, parseInt(autoMin.value, 10) || 15));
  autoMin.value = v;
  chrome.storage.local.set({ ftAutoScanMin: v }, () => setBridge(`自动抓取最小间隔：${v} 分钟`));
});

$('resetAutoBtn').addEventListener('click', () => {
  chrome.storage.local.set({ ftAutoScanAt: 0 }, () =>
    setBridge('已解除间隔限制，刷新 Firstrade 页面即会自动抓取'));
