/* ---------- 事件：桥接部分 ---------- */
$('pingBtn').addEventListener('click', async () => {
  setBridge('正在连接 127.0.0.1:18888 …');
  const r = await sendToBg({ action: 'FT_PING' });
  if (r.ok) {
    const d = r.data || {};
    setBridge('✅ 桥接服务正常\n'
      + `持仓文件: ${d.positions_file_exists ? '存在' : '不存在'}\n`
      + `流水文件: ${d.trades_file_exists ? '存在' : '不存在'}\n`
      + `差异将记为交易日: ${d.next_trade_date}`);
  } else {
    setBridge('❌ 连不上桥接服务：' + r.error + '\n请在终端运行 bridge_server.py', true);
  }
});

function renderScanResult(r) {
  if (!r.ok) { setBridge('抓取失败：' + r.error, true); return; }
  const srv = r.server || {};
  if (!srv.ok) { setBridge(`共抓取 ${r.count} 只\n写入本机失败：${srv.error}`, true); return; }
  const d = srv.data || {};

  if (d.__needConfirm) {
    const dis = (d.disappeared || []).join(', ');
    setBridge(`⚠️ 安全保护：持仓 ${d.old_count} → ${d.new_count} 只，疑似页面未加载完整。\n`
      + `本次未写入任何文件。\n消失的标的：${dis}\n`
      + `如果确认这些确实已卖出，请点击上面的「⚠️ 强制确认」。`, true);
    return;
  }
  if (d.status === 'skip') { setBridge(`⚠️ ${d.warning || '未写入'}`, true); return; }

  let msg = `✅ 共抓取 ${r.count} 只，已写入本机持仓 JSON（共 ${d.total} 条）`;
  if (d.baseline) {
    msg += '\n📌 这是首次基线，未生成交易记录。下次抓取才会开始比对。';
  } else if (d.trades && d.trades.detected > 0) {
    const lines = (d.trades.items || []).map(t =>
      `  ${t.action === 'BUY' ? '🟢买' : '🔴卖'} ${t.symbol}  $${t.amount.toLocaleString()}  (${t.type})`);
    msg += `\n📝 检测到 ${d.trades.detected} 笔变动，记为交易日 ${d.trades.trade_date}\n`
      + lines.join('\n')
      + `\n新增 ${d.trades.added} / 合并 ${d.trades.merged} / 抵消删除 ${d.trades.removed}`
      + `\n流水累计 ${d.trades.total} 条`;
  } else {
    msg += '\n😴 与上次快照一致，无交易记录。';
  }
  setBridge(msg);
}

$('scanBtn').addEventListener('click', async () => {
  setBridge('正在自动滚动抓取全表，请勿操作页面…');
  const r = await sendToTab({ action: 'FT_SYNC_ALL' });
  renderScanResult(r);
});

$('forceBtn').addEventListener('click', async () => {
  if (!confirm('强制模式会跳过“抓取不全”保护，直接按当前页面内容记录买卖并覆盖持仓快照。\n'
    + '请确认持仓表格已完整加载。继续？')) return;
  setBridge('强制模式：正在重新抓取并写入…');
  const r = await sendToTab({ action: 'FT_SYNC_ALL', force: true });
