});

$('forceBtn').addEventListener('click', async () => {
  if (!confirm('强制模式会跳过“抓取不全”保护，直接按当前页面内容记录买卖并覆盖持仓快照。\n'
    + '请确认持仓表格已完整加载。继续？')) return;
  setBridge('强制模式：正在重新抓取并写入…');
  const r = await sendToTab({ action: 'FT_SYNC_ALL', force: true });
  renderScanResult(r);
});

$('dumpBtn').addEventListener('click', async () => {
  const r = await sendToTab({ action: 'FT_DUMP' });
  if (!r.ok) { setBridge('读取失败：' + r.error, true); return; }
  const keys = Object.keys(r.data || {});
  const sample = keys.slice(0, 3).map(k => {
    const p = r.data[k];
    return `${k}: 成本=${p.cost} 今日=${p.day_change} 盈亏=${p.gainloss}`;
  }).join('\n');
  setBridge(`已抓取 ${r.count} 只：\n${sample || '(空，请确认在持仓页面)'}\n…${keys.slice(0, 20).join(',')}`);
  console.log('[FT-POPUP] 抓取结果', r.data);
});

$('serverBtn').addEventListener('click', async () => {
  const r = await sendToBg({ action: 'FT_SERVER_POSITIONS' });
  if (!r.ok) { setBridge('读取失败：' + r.error, true); return; }
  const d = r.data || {};
  const meta = d._meta || {};
  const keys = Object.keys(d).filter(k => !k.startsWith('_'));
  setBridge(`本机持仓 JSON 共 ${keys.length} 条（更新于 ${meta.updated_at_str || '未知'}，模式 ${meta.mode || '-'}）\n`
    + keys.slice(0, 30).join(', '));
  console.log('[FT-POPUP] 本机持仓 JSON', d);
});

$('tradesBtn').addEventListener('click', async () => {
  const r = await sendToBg({ action: 'FT_TRADES', limit: 20 });
  if (!r.ok) { setBridge('读取失败：' + r.error, true); return; }
  const d = r.data || {};
  const list = d.trades || [];
  if (!list.length) { setBridge('流水文件为空（还没检测到任何买卖变动）'); return; }
  const lines = list.map(t =>
    `${t.date}  ${t.action === 'BUY' ? '🟢买' : '🔴卖'} ${t.symbol}  $${Number(t.amount).toLocaleString()}  (${t.type})`);
  setBridge(`买卖流水（累计 ${d.count} 条，显示最近 ${list.length} 条）：\n` + lines.join('\n'));
  console.log('[FT-POPUP] 交易流水', d);
});

