        self.subtitle_artists.append(t_comp)

        iv2_v, iv2_s = metrics_data['iv2']
        c, w, s = get_style(iv2_v, 'secondary')
        t_iv2 = fig.text(center_x - spacing_inner, y_pos + 0.003, iv2_s,
