/* ==================== 标签外层容器（主交互热区） ==================== */
.ft-custom-tag-container {
  display: inline-flex !important;
  align-items: center !important;
  flex-wrap: nowrap !important;
  gap: 3px !important;
  margin-left: 6px !important;
  vertical-align: middle !important;
  line-height: 1 !important;
  pointer-events: auto !important;
  flex-shrink: 0 !important;
  z-index: 2 !important;
  cursor: pointer !important;
}

/* ==================== 单个微型徽章 ==================== */
.ft-custom-tag-badge {
  display: inline-block !important;
  font-size: 10px !important;
  line-height: 15px !important;
  padding: 0 5px !important;
  border-radius: 4px !important;
  background-color: rgba(59, 130, 246, 0.16) !important;
  color: #7cb6ff !important;
  border: 1px solid rgba(59, 130, 246, 0.35) !important;
  white-space: nowrap !important;
  user-select: none !important;
  max-width: 85px !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  font-weight: 500 !important;
  cursor: pointer !important;
  transition: all 0.15s ease !important;
}

.ft-custom-tag-badge:hover {
  background-color: rgba(59, 130, 246, 0.35) !important;
  border-color: rgba(59, 130, 246, 0.6) !important;
  color: #ffffff !important;
}

.ft-custom-tag-more {
  background-color: rgba(148, 163, 184, 0.18) !important;
  color: #cbd5e1 !important;
  border-color: rgba(148, 163, 184, 0.35) !important;
}

.ft-custom-tag-more:hover {
  background-color: rgba(148, 163, 184, 0.35) !important;
  color: #ffffff !important;
}

/* 无 tag 时的「仅看图」徽章 */
.ft-custom-tag-chart {
  background-color: rgba(163, 190, 140, 0.14) !important;
  border-color: rgba(163, 190, 140, 0.30) !important;
  color: #a3be8c !important;
  font-size: 9px !important;
  padding: 0 4px !important;
  opacity: 0.45 !important;
}

.ft-custom-tag-container:hover .ft-custom-tag-chart {
  opacity: 1 !important;
  background-color: rgba(163, 190, 140, 0.35) !important;
}

/* ==================== 还原原股票代码为默认样式 ==================== */
[col-id="symbol"] button[data-tooltip-trigger],
[col-id="symbol"] button,
[col-id="symbol"] [data-ref="eValue"] {
  cursor: default !important;
}

/* ==================== 全局悬浮 Popover ==================== */
#ft-global-tag-popover {
  position: fixed !important;
  z-index: 99999999 !important;
  background: #2E3440 !important;
  border: 1px solid #4C566A !important;
  border-radius: 8px !important;
  padding: 10px 12px !important;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.5), 0 8px 10px -6px rgba(0, 0, 0, 0.4) !important;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif !important;
  color: #ECEFF4 !important;
  font-size: 12px !important;
  pointer-events: auto !important;
  max-width: 320px !important;
  min-width: 160px !important;
  opacity: 0;
  transform: translateY(4px);
  transition: opacity 0.15s ease, transform 0.15s ease !important;
  display: none;
}

#ft-global-tag-popover.ft-popover-show {
  display: block !important;
  opacity: 1 !important;
  transform: translateY(0) !important;
}

.ft-popover-header {
  display: flex !important;
  justify-content: space-between !important;
  align-items: center !important;
  margin-bottom: 6px !important;
  border-bottom: 1px solid #434C5E !important;
  padding-bottom: 4px !important;
  gap: 10px !important;
}

.ft-popover-symbol {
