                execute_external_script('panel_delete', name, on_done=on_delete_done, block=True)
        execute_external_script('panel_input', name, on_done=on_insert_done, block=True)

    def build_colored_line_collection(f_dates, f_prices, f_opens):
        if colored_lc[0] is not None:
            colored_lc[0].remove()
            colored_lc[0] = None

        if not has_ohlc or not f_dates or len(f_dates) < 2: return

        date_nums_lc = matplotlib.dates.date2num(f_dates)
        segments, seg_colors = [], []

        for i in range(len(f_dates) - 1):
            segments.append([(date_nums_lc[i], f_prices[i]), (date_nums_lc[i + 1], f_prices[i + 1])])
            if show_colored_lines:
                next_open = f_opens[i + 1] if (f_opens and i + 1 < len(f_opens)) else None
                next_close = f_prices[i + 1]
                if next_open is not None and next_close is not None:
                    if next_close > next_open: seg_colors.append(NORD_THEME['accent_red'])
                    elif next_close < next_open: seg_colors.append(NORD_THEME['accent_green'])
                    else: seg_colors.append(NORD_THEME['accent_cyan'])
                else:
                    seg_colors.append(NORD_THEME['accent_cyan'])
            else:
                seg_colors.append(NORD_THEME['accent_cyan'])

        lc = LineCollection(segments, colors=seg_colors, linewidths=2, zorder=2, alpha=0.8)
        ax1.add_collection(lc)
        colored_lc[0] = lc

    def build_trade_markers():
        """买入/卖出痕迹（来自 Chrome 插件抓取的 order-status 页面）"""
        for scatter, _, _, _ in buy_scatter_points + sell_scatter_points:
            try: scatter.remove()
            except Exception: pass
        buy_scatter_points.clear()
        sell_scatter_points.clear()
        buy_markers.clear()
        sell_markers.clear()
        if not trade_map:
            return

        dmin, dmax = min(dates).date(), max(dates).date()
        np_dates = np.array(dates)
        for d in sorted(trade_map.keys()):
            if d < dmin or d > dmax:
                continue
            target = datetime.combine(d, datetime.min.time())
            idx = int((np.abs(np_dates - target)).argmin())
            px = prices[idx]
            for side in ('buy', 'sell'):
                agg = trade_map[d].get(side)
                if not agg:
                    continue
                txt = build_marker_text(side, d, agg, close_price=px)
                is_buy = (side == 'buy')
                sc = ax1.scatter(
                    [dates[idx]], [px], s=150,
                    marker=(BUY_MARKER if is_buy else SELL_MARKER),
                    color=(BUY_COLOR if is_buy else SELL_COLOR),
                    edgecolors=NORD_THEME['text_bright'], linewidths=0.7,
                    alpha=0.95, zorder=4.6, picker=5,
                    visible=(show_buy_markers if is_buy else show_sell_markers)
                )
                if is_buy:
                    buy_markers[dates[idx]] = txt
                    buy_scatter_points.append((sc, dates[idx], px, txt))
                else:
                    sell_markers[dates[idx]] = txt
                    sell_scatter_points.append((sc, dates[idx], px, txt))

        trade_offsets = [(45, 45), (-170, 45), (45, -95), (-170, -95)]
        all_trade_pts = buy_scatter_points + sell_scatter_points
        n_buy = len(buy_scatter_points)
        for i, (sc, date_v, price_v, txt) in enumerate(all_trade_pts):
            is_buy = i < n_buy
            color = BUY_COLOR if is_buy else SELL_COLOR
