                        if not line:
                            continue
                        parts = [p.strip() for p in line.split(':')]
                        if len(parts) >= 3:
                            sym, date_str = parts[0], parts[2]
                            if sym not in result:
                                try:
                                    result[sym] = datetime.strptime(date_str, "%Y-%m-%d").date()
                                except ValueError:
                                    pass
            except Exception as e:
                continue
    except Exception as e:
        pass
    _EARNING_RELEASE_CACHE = result
    return result

