    script_configs = {
        'earning_input': os.path.join(BASE_CODING_DIR, 'Financial_System', 'Operations', 'Insert_Earning_Manual.py'),
        'earning_edit': os.path.join(BASE_CODING_DIR, 'Financial_System', 'Operations', 'Editor_Earning_DB.py'),
