            pre_after_str = f"{pre_after_pct:+.2f}%"
            pa_color = NORD_THEME['accent_red'] if pre_after_pct > 0 else NORD_THEME['accent_green']

        t_pa = fig.text(base_x - 0.08, y_pos, f"P/A:{pre_after_str}",
