            current_filtered_date_nums = matplotlib.dates.date2num(current_filtered_dates) if current_filtered_dates else np.array([])
            current_filtered_opens = f_opens
            current_filtered_highs = f_highs
            current_filtered_lows = f_lows

            update_plot(
                line1, gradient_image, line2,
                f_dates, f_prices, f_turnovers,
                ax1, ax2, show_volume,
                cyan_transparent_cmap,
                force_recreate=False,
                gradient_clip_patch=gradient_clip_patch,
                zero_line=zero_line
            )
            build_colored_line_collection(f_dates, f_prices, f_opens)
            fig.canvas.draw_idle()
        except Exception: pass

    def launch_and_close_for_y():
        def on_done(return_code):
            if return_code == 0:
                if callback: callback('deleted')
                try: plt.close('all')
                except: pass
                try:
                    if panel: sys.exit(0)
                except: pass
        execute_external_script('panel_delete', name, on_done=on_done, block=True)

    def refresh_description_data_and_redraw():
        nonlocal title_artist, clickable
        try:
            with open(DESCRIPTION_JSON_PATH, 'r', encoding='utf-8') as f:
                new_data = json.load(f)
            current_json_data['data'] = new_data
            new_title_text, new_title_color, clickable = create_or_update_title()
            title_artist.set_text(new_title_text)
            draw_subtitle() 
            create_markers_and_annotations()
            update_marker_visibility()
            fig.canvas.draw_idle()
        except Exception as e:
            display_dialog(f"刷新出错: {e}")

    def on_key(event):
        try:
            actions = {'v': toggle_volume, 'r': toggle_global_markers, 'x': toggle_all_annotations,
                       'a': toggle_earning_markers,
                       'c': toggle_specific_markers,
                       'i': toggle_buy_markers,
                       'u': toggle_sell_markers,
                       'g': refresh_description_data_and_redraw,
                       'n': lambda: execute_external_script('earning_input', name),
                       'e': lambda: execute_external_script('earning_edit', name),
                       't': lambda: execute_external_script('tags_edit', name),
                       'w': lambda: execute_external_script('event_input', name),
                       'y': launch_insert_then_delete_chain, 
                       'j': launch_and_close_for_y,
                       's': toggle_colored_lines,
                       'q': lambda: execute_external_script('event_edit', name),
                       'k': lambda: execute_external_script('check_kimi', name),
                       'z': lambda: execute_external_script('check_futu', name),
                       'o': lambda: execute_external_script('check_seekingalpha', name),
                       'p': lambda: execute_external_script('symbol_compare', name),
                       'l': lambda: execute_external_script('similar_tags', name),
                       'b': lambda: execute_external_script('check_history', name),
                       '/': lambda: execute_external_script('stock_chart', name),
                       '1': lambda: radio.set_active(7), '2': lambda: radio.set_active(1),
                       '3': lambda: radio.set_active(3), '4': lambda: radio.set_active(4),
                       '5': lambda: radio.set_active(5), '6': lambda: radio.set_active(6),
                       '7': lambda: radio.set_active(8), '8': lambda: radio.set_active(2),
                       '9': lambda: radio.set_active(0), '`': show_stock_etf_info,
                       'd': lambda: on_keyword_selected(db_path, table_name, name)}
            if event.key in actions: actions[event.key]()
            current_index = list(time_options.keys()).index(radio.value_selected)
            if event.key == 'up' and current_index > 0: radio.set_active(current_index - 1)
            elif event.key == 'down' and current_index < len(time_options) - 1: radio.set_active(current_index + 1)
            elif event.key == 'right':
                plt.close('all')
                if callback: callback('next')
            elif event.key == 'left':
                plt.close('all')
                if callback: callback('prev')
        except Exception: pass

    def close_everything(event, panel_flag):
        if event.key == 'escape':
            plt.close('all')
            if panel_flag: sys.exit(0)

    def on_mouse_press(event):
        nonlocal mouse_pressed, initial_price, initial_volume, initial_date
        try:
            if event.button == 1 and event.xdata is not None and current_filtered_dates:
                mouse_pressed = True
                if len(current_filtered_date_nums) > 0:
                    idx = np.searchsorted(current_filtered_date_nums, event.xdata)
                    if idx >= len(current_filtered_date_nums): idx = len(current_filtered_date_nums) - 1
                    elif idx > 0:
                        if abs(current_filtered_date_nums[idx-1] - event.xdata) < abs(current_filtered_date_nums[idx] - event.xdata):
                            idx = idx - 1
                else: idx = 0
                if idx < len(current_filtered_prices):
                    initial_price, initial_date = current_filtered_prices[idx], current_filtered_dates[idx]
                    initial_volume = current_filtered_volumes[idx] if (current_filtered_volumes and idx < len(current_filtered_volumes)) else None
        except Exception: pass

    def on_mouse_release(event):
        nonlocal mouse_pressed
        try:
            if event.button == 1: mouse_pressed = False
        except Exception: pass

    vline = ax1.axvline(x=dates[0], color=NORD_THEME['accent_cyan'], linestyle='--', linewidth=1, visible=False)

    plt.gcf().canvas.mpl_connect("motion_notify_event", hover)
    plt.gcf().canvas.mpl_connect('key_press_event', on_key)
    plt.gcf().canvas.mpl_connect('key_press_event', lambda e: close_everything(e, panel))
    plt.gcf().canvas.mpl_connect('button_press_event', on_mouse_press)
    plt.gcf().canvas.mpl_connect('button_release_event', on_mouse_release)
    radio.on_clicked(update)

    def hide_annot_on_leave(event):
        try:
            annot.set_visible(False)
            highlight_point.set_visible(False)
            vline.set_visible(False)
            fig.canvas.draw_idle()
        except Exception: pass

    plt.gcf().canvas.mpl_connect('figure_leave_event', hide_annot_on_leave)

    _RT_MANAGER.set_symbol(name)

    def _ui_poll_realtime():
        rt_price = _RT_MANAGER.get_latest(name)
        if rt_price is None or not prices or prices[-1] == 0: return
        pct = ((rt_price - prices[-1]) / prices[-1]) * 100
        if current_pre_after_pct[0] is not None and abs(current_pre_after_pct[0] - pct) < 1e-9: return
        current_pre_after_pct[0] = pct
        if pa_text_artist[0] is not None:
            pa_color = NORD_THEME['accent_red'] if pct > 0 else NORD_THEME['accent_green']
            pa_text_artist[0].set_text(f"P/A:{pct:+.2f}%")
            pa_text_artist[0].set_color(pa_color)
            fig.canvas.draw_idle()

    ui_timer = fig.canvas.new_timer(interval=1000)
    ui_timer.add_callback(_ui_poll_realtime)
    ui_timer.start()
    fig._ui_timer = ui_timer

    def _on_close(evt):
        try: ui_timer.stop()
        except Exception: pass

    fig.canvas.mpl_connect('close_event', _on_close)

    try: fig.canvas.toolbar_visible = False
    except Exception: pass

    update(default_time_range)
    plt.show()

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
ft_quotes.py —— Firstrade 本地数据读取层（Chart_input.py / Chart_input_single.py 共用）

数据来源（均由 Chrome 插件 + bridge_server.py 落盘）:
    Modules/firstrade_positions.json   持仓快照（覆盖式）
    Modules/firstrade_watchlist.json   自选股「变更%」快照（覆盖式，1800+ 只）

显示优先级（build_market_items）:
    1) 该 symbol 在持仓里  -> 显示 成本 / 日 / 总 / 仓位
    2) 不在持仓、但在自选股 -> 显示 盘前变更% / 现价
    3) 都没有              -> 视 FT_SHOW_MISS 决定是否显示灰色占位
"""
import os
import re
import json
import time

USER_HOME = os.path.expanduser("~")
BASE_CODING_DIR = os.path.join(USER_HOME, "Coding")
MODULES_DIR = os.path.join(BASE_CODING_DIR, "Financial_System", "Modules")

FIRSTRADE_POSITIONS_FILE = os.path.join(MODULES_DIR, "firstrade_positions.json")
FIRSTRADE_WATCHLIST_FILE = os.path.join(MODULES_DIR, "firstrade_watchlist.json")

FT_DEBUG = os.environ.get("FT_DEBUG", "") == "1"
FT_SHOW_MISS = os.environ.get("FT_SHOW_MISS", "1") == "1"

# 自选股数据超过该小时数就打「N天前」标记
FT_STALE_HOURS = float(os.environ.get("FT_STALE_HOURS", "20"))

_CACHE = {}          # path -> (mtime, data)


# ----------------------------------------------------------------------
# 基础工具
# ----------------------------------------------------------------------
def _ft_norm_sym(s):
    """AAPL / brk.b / BRK-B 统一成大写且以 '-' 为分隔的形式"""
    return str(s).strip().upper().replace('.', '-')


def _norm_key(s):
    """比较用：去掉一切分隔符 BRK.B / BRK-B / BRKB -> BRKB"""
    return re.sub(r'[^A-Z0-9]', '', str(s).strip().upper())


def _load_json_cached(path):
    """按 mtime 缓存，避免 matplotlib 频繁重画时反复读盘"""
    try:
        mtime = os.path.getmtime(path) if os.path.exists(path) else 0.0
    except Exception:
        mtime = 0.0
    ent = _CACHE.get(path)
    if ent and ent[0] == mtime:
        return ent[1]
    data = {}
    if mtime:
        try:
            with open(path, 'r', encoding='utf-8') as f:
                loaded = json.load(f)
            if isinstance(loaded, dict):
                data = loaded
        except Exception as e:
            print(f"[FT] 读取 {os.path.basename(path)} 失败: {e}")
    _CACHE[path] = (mtime, data)
    return data


def _num(s):
    try:
        m = re.search(r'[-+]?\d[\d,]*\.?\d*', str(s).replace(' ', ''))
        return float(m.group(0).replace(',', '')) if m else None
    except Exception:
        return None


def _fmt_money(s):
    v = _num(s)
    if v is None:
        return str(s)
    if abs(v) >= 1e6:
        return f"{v/1e6:.2f}M"
    if abs(v) >= 1e3:
        return f"{v/1e3:.1f}K"
    return f"{v:.0f}"


def _age_hours(ts):
    """兼容秒 / 毫秒时间戳"""
    try:
        t = float(ts)
    except Exception:
        return None
    if t <= 0:
        return None
    if t > 1e11:          # 毫秒
        t /= 1000.0
    return (time.time() - t) / 3600.0


def _sign_color(s, theme):
    v = _num(s)
    if v is None:
        return theme['text_bright']
    if v > 0:
        return theme['accent_red']        # 红涨
    if v < 0:
        return theme['accent_green']      # 绿跌
    return theme['text_bright']


# ----------------------------------------------------------------------
# 持仓
# ----------------------------------------------------------------------
def get_firstrade_position(symbol):
    """读取插件回传的真实持仓数据，返回 dict 或 None"""
    if not symbol:
        return None
    data = _load_json_cached(FIRSTRADE_POSITIONS_FILE)
    if not data:
        if FT_DEBUG:
            print(f"[FT] 持仓文件为空或不存在: {FIRSTRADE_POSITIONS_FILE}")
        return None
    target = _norm_key(symbol)
    for k, v in data.items():
        if str(k).startswith('_') or not isinstance(v, dict):
            continue
        if _norm_key(k) == target:
            if FT_DEBUG:
                print(f"[FT] 命中持仓 {k}: {v}")
            return v
    if FT_DEBUG:
        keys = [k for k in data.keys() if not str(k).startswith('_')]
        print(f"[FT] 持仓未找到 {symbol}（共 {len(keys)} 条）: {keys[:25]}")
    return None


# ----------------------------------------------------------------------
# 自选股行情（变更%）
# ----------------------------------------------------------------------
def get_watchlist_quote(symbol):
    """返回 {'symbol','change_pct','change_pct_num','last','updated_at'} 或 None"""
    if not symbol:
        return None
    data = _load_json_cached(FIRSTRADE_WATCHLIST_FILE)
    if not data:
        return None
    quotes = data.get('quotes')
    if not isinstance(quotes, dict):
        quotes = {k: v for k, v in data.items()
                  if isinstance(v, dict) and not str(k).startswith('_')}
    target = _norm_key(symbol)
    meta_ts = (data.get('_meta') or {}).get('updated_at')
    for k, v in quotes.items():
        if not isinstance(v, dict):
            continue
        if _norm_key(k) == target:
            out = dict(v)
            out.setdefault('symbol', str(k).upper())
            if not out.get('updated_at'):
                out['updated_at'] = meta_ts
            if FT_DEBUG:
                print(f"[FT] 命中自选股行情 {k}: {out}")
            return out
    if FT_DEBUG:
        print(f"[FT] 自选股行情未找到 {symbol}（共 {len(quotes)} 条）")
    return None


# ----------------------------------------------------------------------
# 供图表副标题使用：[(文本, 颜色, 粗细), ...]
# ----------------------------------------------------------------------
def _items_from_position(pos, theme):
    raw = pos.get('raw') or {}

    def _pick(*keys):
        for k in keys:
            v = pos.get(k)
            if v not in (None, '', '--'):
                return str(v)
        for k in keys:
            v = raw.get(k)
            if v not in (None, '', '--'):
                return str(v)
        return None

    cost_val = _pick('cost', 'totalCost')
    day_val = _pick('day_change', 'changePercent')
    gl_val = _pick('gainloss', 'gainlossPercent')
    alloc_val = _pick('allocation', 'allocationPercent')

    items = []
    if cost_val:
        items.append((f"成本 {_fmt_money(cost_val)}", theme['accent_yellow'], 'bold'))
    if day_val:
        items.append((f"日{day_val}", _sign_color(day_val, theme), 'bold'))
    if gl_val:
        items.append((f"总{gl_val}", _sign_color(gl_val, theme), 'bold'))
    if alloc_val:
        items.append((f"仓{alloc_val}", theme['accent_cyan'], 'normal'))

    age = _age_hours(pos.get('updated_at'))
    if age is not None and age > FT_STALE_HOURS:
        items.append((f"({age/24:.0f}天前)", theme['border'], 'normal'))
    return items


def _items_from_watchlist(q, theme):
    txt = q.get('change_pct')
    if txt in (None, '', '--'):
        n = q.get('change_pct_num')
        txt = f"{float(n):+.2f}%" if isinstance(n, (int, float)) else None
    if not txt:
        return []

    items = [(f"盘前 {txt}", _sign_color(txt, theme), 'bold')]
    last = q.get('last')
    if last not in (None, '', '--'):
        items.append((f"现价 {last}", theme['text_light'], 'normal'))

    age = _age_hours(q.get('updated_at'))
    if age is not None and age > FT_STALE_HOURS:
        items.append((f"({age/24:.0f}天前)", theme['border'], 'normal'))
    return items


def build_market_items(symbol, theme, show_miss=None):
    """
    图表副标题左侧一行的内容。
    持仓优先；无持仓则用自选股「变更%」；都没有按 show_miss 决定占位。
    """
    if show_miss is None:
        show_miss = FT_SHOW_MISS

    pos = get_firstrade_position(symbol)
    if pos:
        items = _items_from_position(pos, theme)
        if items:
            return items

    q = get_watchlist_quote(symbol)
    if q:
        items = _items_from_watchlist(q, theme)
        if items:
            return items

    if show_miss:
        return [("持仓/自选: 无数据", theme['border'], 'normal')]
    return []

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Firstrade 买入/卖出痕迹读取与聚合（供 Chart_input.py / Chart_input_single.py 共用）

数据来源: ~/Coding/Financial_System/Modules/firstrade_orders.json
结构:
{
  "_meta": {...},
  "orders": {
    "<order_id>": {
      "symbol": "AAPL", "side": "buy"/"sell", "date": "2026-09-09",
      "datetime": "9/9/2026, 9:39:41 PM",
      "amount": 3110.0, "quantity": 1000, "price": 49.38,
      "amount_source": "dollar" | "qty*price" | "qty_only",
      "status": "已执行", ...
    }
  }
}

环境变量:
  FT_TRADE_DEBUG=1        打印调试信息
  FT_ORDER_INCLUDE_ALL=1  连"已取消/已拒绝"的订单也画出来（默认剔除）
"""
import os
import re
import json
from datetime import datetime

USER_HOME = os.path.expanduser("~")
BASE_CODING_DIR = os.path.join(USER_HOME, "Coding")
ORDERS_FILE = os.path.join(BASE_CODING_DIR, "Financial_System", "Modules", "firstrade_orders.json")

# 图上颜色/形状（与已有的 红=global / 白=specific / 黄=earning 明确区分）
BUY_COLOR = '#5E81AC'      # 蓝色 ▲ 买入
SELL_COLOR = '#D08770'     # 橙色 ▼ 卖出
BUY_MARKER = '^'
SELL_MARKER = 'v'

FT_TRADE_DEBUG = os.environ.get("FT_TRADE_DEBUG", "") == "1"
FT_ORDER_INCLUDE_ALL = os.environ.get("FT_ORDER_INCLUDE_ALL", "") == "1"

# 只剔除“明确没有成交”的状态；其余全部保留
_CANCEL_RE = re.compile(r"取消|撤销|撤单|拒绝|失效|过期|无效|作废|cancel|reject|expire|void", re.I)

_CACHE = {"mtime": None, "map": None}


# ----------------------------------------------------------------------
def _norm_sym(s):
    return str(s).strip().upper().replace('.', '-')


def _to_float(v):
    if v is None:
        return None
    if isinstance(v, (int, float)):
        return float(v)
    m = re.search(r'-?\d[\d,]*\.?\d*', str(v).replace(' ', ''))
    return float(m.group(0).replace(',', '')) if m else None


def _to_date(s):
    if not s:
        return None
    head = str(s).split(',')[0].strip()
    for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y/%m/%d", "%m/%d/%y"):
        try:
            return datetime.strptime(head, fmt).date()
        except ValueError:
            continue
    return None


def _is_effective(order):
    if FT_ORDER_INCLUDE_ALL:
        return True
    st = f"{order.get('status', '')} {order.get('status_text', '')}"
    return not _CANCEL_RE.search(st)


def _load_orders_raw():
    if not os.path.exists(ORDERS_FILE):
        if FT_TRADE_DEBUG:
            print(f"[FT-TRADE] 订单文件不存在: {ORDERS_FILE}")
        return {}
    try:
        with open(ORDERS_FILE, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except Exception as e:
        print(f"[FT-TRADE] 读取订单文件失败: {e}")
        return {}
    if not isinstance(data, dict):
        return {}
    orders = data.get('orders')
    if isinstance(orders, dict):
        return orders
    return {k: v for k, v in data.items()
            if isinstance(v, dict) and not str(k).startswith('_')}


# ----------------------------------------------------------------------
def load_trade_map(force=False):
    """返回 { 'AAPL': { date: {'buy': agg, 'sell': agg} } }
       agg = {'amount': float|None, 'quantity': float, 'count': int, 'items': [...]}"""
    try:
        mtime = os.path.getmtime(ORDERS_FILE) if os.path.exists(ORDERS_FILE) else 0
    except OSError:
        mtime = 0
    if (not force) and _CACHE["map"] is not None and _CACHE["mtime"] == mtime:
        return _CACHE["map"]

    out = {}
    skipped = 0
    for _key, o in _load_orders_raw().items():
        if not isinstance(o, dict):
            continue
        if not _is_effective(o):
            skipped += 1
            continue

        sym = _norm_sym(o.get('symbol', ''))
        d = _to_date(o.get('date') or o.get('datetime') or o.get('updated'))
        side = str(o.get('side', '')).strip().lower()
        if side not in ('buy', 'sell'):
            t = str(o.get('side_text') or o.get('transaction') or '')
            if re.search(r'买|buy|bought', t, re.I):
                side = 'buy'
            elif re.search(r'卖|sell|sold', t, re.I):
                side = 'sell'
            else:
                continue
        if not sym or d is None:
            continue

        amount = _to_float(o.get('amount'))
        qty = _to_float(o.get('quantity'))
        price = _to_float(o.get('price'))
        if amount is None and qty and price:
            amount = qty * price

        node = out.setdefault(sym, {}).setdefault(d, {})
        agg = node.setdefault(side, {'amount': None, 'quantity': 0.0, 'count': 0, 'items': []})
        if amount is not None:
            agg['amount'] = (agg['amount'] or 0.0) + amount
        if qty:
            agg['quantity'] += qty
        agg['count'] += 1
        agg['items'].append({
            'time': str(o.get('datetime', '')),
            'quantity': qty,
            'amount': amount,
            'price': price,
            'status': str(o.get('status', '')),
            'price_type': str(o.get('price_type', '')),
            'source': str(o.get('amount_source', '')),
        })

    for sym in out:
        for d in out[sym]:
            for side in out[sym][d]:
                out[sym][d][side]['items'].sort(key=lambda x: x.get('time') or '')

    if FT_TRADE_DEBUG:
        print(f"[FT-TRADE] 载入 {sum(len(v) for v in out.values())} 个交易日，"
              f"覆盖 {len(out)} 只标的，剔除无效 {skipped} 笔")

    _CACHE["mtime"] = mtime
    _CACHE["map"] = out
    return out


def get_trades_for_symbol(symbol):
    """返回 { date: {'buy': agg, 'sell': agg} }；兼容 BRK.B / BRK-B"""
    if not symbol:
        return {}
    return load_trade_map().get(_norm_sym(symbol), {})


# ----------------------------------------------------------------------
def fmt_money(v):
    if v is None:
        return '--'
    a = abs(v)
    if a >= 1e6:
        return f"${v/1e6:.2f}M"
    if a >= 1e3:
        return f"${v/1e3:.1f}K"
    return f"${v:.0f}"


def short_trade_label(side, agg, close_price=None):
    """一行短标签，给 hover 汇总用：'买入 $3.1K'"""
    amount = agg.get('amount')
    est = False
    if amount is None and agg.get('quantity') and close_price:
        amount = float(agg['quantity']) * float(close_price)
        est = True
    label = '买入' if side == 'buy' else '卖出'
    return f"{label} {fmt_money(amount)}{'(估)' if est else ''}"


def build_marker_text(side, d, agg, close_price=None):
    """浮框完整文案"""
    label = '买入' if side == 'buy' else '卖出'
    amount = agg.get('amount')
    est = False
    if amount is None and agg.get('quantity') and close_price:
        amount = float(agg['quantity']) * float(close_price)
        est = True

    day = d.isoformat() if hasattr(d, 'isoformat') else str(d)
    lines = [f"● {label}  {day}"]

    money = fmt_money(amount) + ('(按收盘价估算)' if est else '')
    qty = agg.get('quantity') or 0
    lines.append(f"{money}" + (f"  /  {qty:.0f}股" if qty else ""))

    cnt = agg.get('count', 1)
    if cnt > 1:
        lines.append(f"当日共 {cnt} 笔")

    for it in agg.get('items', [])[:5]:
        bits = []
        if it.get('quantity'):
            bits.append(f"{it['quantity']:.0f}股")
        if it.get('amount') is not None:
            bits.append(fmt_money(it['amount']))
        if it.get('price'):
            bits.append(f"@{it['price']:.2f}")
        if it.get('status'):
            bits.append(str(it['status']))
        if bits:
            lines.append("  · " + " ".join(bits))
    return "\n".join(lines)

