        COLOR_SEC_UP = "#E57373"
        COLOR_SEC_DN = "#81C784"
        COLOR_NULL = "#DDDDDD"
        COLOR_BADGE_BG = "#2c3e50"

        def get_style(val, role):
            if val == 0 or val is None or isinstance(val, str):
                return COLOR_NULL, 'normal', 13
            is_up = val > 0
            if role == 'primary':
