// ==================== Gmail 式滑动手势 ====================
/// 滑动参数集中管理，方便统一微调手感
enum ONewsSwipeConfig {
    /// 触发阈值 = 行宽 * ratio，并被夹在 [minThreshold, maxThreshold]
    static let thresholdRatio: CGFloat = 0.26
    static let minThreshold: CGFloat = 80
    static let maxThreshold: CGFloat = 130
    /// 手势起始最小位移：小于该值完全交给 List 滚动（≥15 才能保证纵向滚动不被吞）
    static let engageDistance: CGFloat = 18
    /// 横向占优系数：|dx| 必须大于 |dy| * bias 才接管
    static let horizontalBias: CGFloat = 1.3
    /// 超过阈值后的橡皮筋阻尼
    static let rubberBandDamping: CGFloat = 0.32
    /// 甩动触发系数（predictedEndTranslation 超过 threshold * factor 即触发）
    static let flingFactor: CGFloat = 1.6
    static let cornerRadius: CGFloat = 16
}

/// Gmail 风格「左滑到位松手即执行」容器：
/// - 永不留下需要点击的按钮
/// - 只在横向占优时接管手势，纵向滚屏完全不受影响
/// - 滑动过程中显示动作提示（纯展示，不可点击）
struct SwipeToMarkRow<Content: View>: View {
    private enum Phase { case idle, engaged, rejected, committing }

    /// 当前是否已读（决定提示文案 / 颜色 / 图标）
    let isRead: Bool
    /// 是否允许滑动（多选模式下应为 false）
    let isEnabled: Bool
    /// 行身份，变化时立即复位（防止 List 复用导致的偏移残留）
    let resetKey: UUID
    /// 到位松手后的执行动作
    let onCommit: () -> Void

    private let content: Content

    init(isRead: Bool,
         isEnabled: Bool,
         resetKey: UUID,
         onCommit: @escaping () -> Void,
         @ViewBuilder content: () -> Content) {
        self.isRead = isRead
        self.isEnabled = isEnabled
        self.resetKey = resetKey
        self.onCommit = onCommit
        self.content = content()
    }

    @State private var offsetX: CGFloat = 0
    @State private var contentOpacity: Double = 1
    @State private var phase: Phase = .idle
    @State private var isArmed = false          // 已越过阈值（松手即执行）
    @State private var rowWidth: CGFloat = 320

    private var threshold: CGFloat {
        min(max(rowWidth * ONewsSwipeConfig.thresholdRatio, ONewsSwipeConfig.minThreshold),
            ONewsSwipeConfig.maxThreshold)
    }
    private var dragDistance: CGFloat { max(0, -offsetX) }
    private var progress: CGFloat { threshold <= 0 ? 0 : min(1, dragDistance / threshold) }

    private var actionTitle: String { isRead ? Localized.markAsUnread_text : Localized.markAsRead_text }
    private var actionIcon: String { isRead ? "envelope.badge.fill" : "checkmark.circle.fill" }
    private var actionTint: Color { isRead ? .orange : .blue }

    var body: some View {
        ZStack(alignment: .trailing) {
            backdrop
            content
                .offset(x: offsetX)
                .opacity(contentOpacity)
        }
        .background(widthReader)
        // ★ 只有横向占优才接管；多选模式下把手势让给子视图
        .gesture(swipeGesture, including: isEnabled ? .all : .subviews)
        .onChange(of: resetKey) { _ in resetImmediately() }
        .onChange(of: isEnabled) { _ in resetImmediately() }
    }

    // MARK: 背景提示层（纯展示，不可点击）
    private var backdrop: some View {
        ZStack(alignment: .trailing) {
            RoundedRectangle(cornerRadius: ONewsSwipeConfig.cornerRadius, style: .continuous)
                .fill(isArmed ? actionTint : actionTint.opacity(0.16))

            HStack(spacing: 8) {
                Image(systemName: actionIcon)
                    .font(.system(size: 16, weight: .bold))
                Text(actionTitle)
                    .font(.system(size: 15, weight: .bold))
                    .lineLimit(1)
                    .fixedSize()
            }
            .foregroundColor(isArmed ? .white : actionTint)
            .padding(.trailing, 22)
            .scaleEffect(isArmed ? 1.06 : 1.0)
            .opacity(Double(min(1, progress * 1.35)))
        }
        .animation(.easeOut(duration: 0.16), value: isArmed)
        .opacity(dragDistance > 0.5 ? 1 : 0)   // 静止时完全隐藏
        .allowsHitTesting(false)
    }

    private var widthReader: some View {
        GeometryReader { proxy in
            Color.clear
                .onAppear { rowWidth = proxy.size.width }
                .onChange(of: proxy.size.width) { w in rowWidth = w }
        }
    }

    // MARK: 手势
    private var swipeGesture: some Gesture {
        DragGesture(minimumDistance: ONewsSwipeConfig.engageDistance, coordinateSpace: .local)
            .onChanged { value in
                guard isEnabled, phase != .committing else { return }
                let dx = value.translation.width
                let dy = value.translation.height

                if phase == .idle {
                    // 首帧方向仲裁：纵向占优或向右 → 本次手势整体放弃，交还 List 滚动
                    guard dx < 0, abs(dx) > abs(dy) * ONewsSwipeConfig.horizontalBias else {
                        phase = .rejected
                        return
                    }
                    phase = .engaged
                }
                guard phase == .engaged else { return }

                offsetX = rubberBand(min(0, dx))

                let armed = dragDistance >= threshold
                if armed != isArmed {
                    if armed { ONewsHaptics.selection() }   // 越过阈值：松手即执行
                    isArmed = armed
                }
            }
            .onEnded { value in
                let wasEngaged = (phase == .engaged)
                if phase != .committing { phase = .idle }
                guard isEnabled, wasEngaged else { snapBack(); return }

                let predicted = value.predictedEndTranslation.width
                let shouldCommit = dragDistance >= threshold
                    || predicted <= -threshold * ONewsSwipeConfig.flingFactor
                if shouldCommit { commit() } else { snapBack() }
            }
    }

    private func rubberBand(_ x: CGFloat) -> CGFloat {
        let soft = threshold * 1.35
        guard x < -soft else { return x }
        let extra = -x - soft
        return -(soft + extra * ONewsSwipeConfig.rubberBandDamping)
    }

    private func snapBack() {
        isArmed = false
        withAnimation(.spring(response: 0.32, dampingFraction: 0.82)) { offsetX = 0 }
    }

    private func commit() {
        phase = .committing
        isArmed = false
        withAnimation(.easeOut(duration: 0.20)) {
            offsetX = -(rowWidth + 60)
            contentOpacity = 0
        }
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.20) {
            onCommit()                      // 真正改状态（内部已带 undo）
            var t = Transaction(); t.disablesAnimations = true
            withTransaction(t) { offsetX = 0 }
            withAnimation(.easeOut(duration: 0.18)) { contentOpacity = 1 }
            phase = .idle
        }
    }

    private func resetImmediately() {
        var t = Transaction(); t.disablesAnimations = true
        withTransaction(t) {
            offsetX = 0
            contentOpacity = 1
            isArmed = false
            phase = .idle
        }
    }
}

// ==================== 多选模式模型 ====================
enum GroupSelectionState { case none, partial, all }

@MainActor
final class ArticleSelectionModel: ObservableObject {
    @Published var isActive: Bool = false
    @Published var selected: Set<UUID> = []

    func enter(preselect: UUID? = nil) {
        guard !isActive else {
            if let p = preselect { selected.insert(p) }
            return
        }
        withAnimation(.easeInOut(duration: 0.22)) {
            isActive = true
            if let p = preselect { selected = [p] } else { selected = [] }
        }
        ONewsHaptics.rigid()
    }

    func exit() {
        withAnimation(.easeInOut(duration: 0.22)) {
            isActive = false
            selected.removeAll()
        }
    }

    func toggle(_ id: UUID) {
        if selected.contains(id) { selected.remove(id) } else { selected.insert(id) }
        ONewsHaptics.selection()
    }

    func toggleGroup(_ ids: [UUID]) {
        guard !ids.isEmpty else { return }
        if ids.allSatisfy({ selected.contains($0) }) {
            ids.forEach { selected.remove($0) }
        } else {
            ids.forEach { selected.insert($0) }
        }
        ONewsHaptics.selection()
    }

    func groupState(_ ids: [UUID]) -> GroupSelectionState {
        guard !ids.isEmpty else { return .none }
        let hit = ids.filter { selected.contains($0) }.count
        if hit == 0 { return .none }
        return hit == ids.count ? .all : .partial
    }
}

