                    .font(.headline)
                    .foregroundColor(.blue.opacity(0.7))
                    .padding(.vertical, 4)
            }
        } else {
            let grouped = Dictionary(grouping: results, by: { $0.article.timestamp })
                .mapValues { Array($0.reversed()) }
