struct AllArticlesListView: View {
    @ObservedObject var viewModel: NewsViewModel
    @ObservedObject var resourceManager: ResourceManager
    @EnvironmentObject var authManager: AuthManager

    @AppStorage("isGlobalEnglishMode") private var isGlobalEnglishMode = false
    @Environment(\.appNavPath) var appNavPath

    @State private var filterMode: ArticleFilterMode = .unread
    @State private var isSearching = false
    @State private var searchText = ""
    @State private var isSearchActive = false
    @State private var showErrorAlert = false
    @State private var errorMessage = ""
    @State private var isDownloadingImages = false
    @State private var downloadProgress: Double = 0.0
    @State private var downloadProgressText = ""
    @State private var showProfileSheet = false
    @State private var hasPerformedAutoExpansion = false

    @StateObject private var selection = ArticleSelectionModel()
    @StateObject private var undo = ArticleUndoCenter()

    private var baseFilteredArticles: [ArticleItem] {
        viewModel.allArticlesSortedForDisplay
            .filter { item in
                let isReadEff = viewModel.isArticleEffectivelyRead(item.article)
                return (filterMode == .unread) ? !isReadEff : isReadEff
            }
            .map { ArticleItem(article: $0.article, sourceName: $0.sourceName, sourceNameEN: $0.sourceNameEN) }
    }

    private var totalUnreadCount: Int {
        viewModel.allArticlesSortedForDisplay.filter { !viewModel.isArticleEffectivelyRead($0.article) }.count
    }
    private var totalReadCount: Int {
        viewModel.allArticlesSortedForDisplay.filter { viewModel.isArticleEffectivelyRead($0.article) }.count
    }

    private var searchResults: [ArticleItem] {
        guard isSearchActive, !searchText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return [] }
        let keyword = searchText.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        return viewModel.allArticlesSortedForDisplay.compactMap { item -> ArticleItem? in
            if item.article.topic.lowercased().contains(keyword) {
                return ArticleItem(article: item.article, sourceName: item.sourceName,
                                   sourceNameEN: item.sourceNameEN, isContentMatch: false)
            }
            if item.article.article.lowercased().contains(keyword) {
                return ArticleItem(article: item.article, sourceName: item.sourceName,
                                   sourceNameEN: item.sourceNameEN, isContentMatch: true)
            }
            return nil
        }
    }

    private func getCount(for mode: ArticleFilterMode) -> Int {
        mode == .unread ? totalUnreadCount : totalReadCount
    }

    private func getFilterTitle(for mode: ArticleFilterMode) -> String {
        "\(mode.localizedName) (\(getCount(for: mode)))"
    }

    var body: some View {
        ZStack(alignment: .bottom) {
            VStack(spacing: 0) {
                if isSearching && !selection.isActive {
                    SearchBarInline(
                        text: $searchText,
                        placeholder: Localized.searchPlaceholder,
                        onCommit: {
                            isSearchActive = !searchText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                        },
                        onCancel: {
                            withAnimation { isSearching = false; isSearchActive = false; searchText = "" }
                        }
                    )
                }

                if let message = resourceManager.activeNotification {
                    NotificationBannerView(message: message) {
                        resourceManager.dismissNotification()
                    }
                    .background(Color.viewBackground)
                }

                listArea

                bottomBar
            }
            .background(Color.viewBackground.ignoresSafeArea())

            if undo.isVisible {
                UndoSnackBar(message: undo.message, onUndo: { undo.performUndo() })
                    .padding(.bottom, selection.isActive ? 130 : 70)
                    .transition(.move(edge: .bottom).combined(with: .opacity))
                    .zIndex(60)
            }
        }
        .onAppear {
            viewModel.finishReadingIfNeeded()
            if !hasPerformedAutoExpansion {
                autoExpandGroups(); hasPerformedAutoExpansion = true
            }
            Task { await resourceManager.silentRefresh(minInterval: 60, reason: "all-list-appear") }
        }
        .navigationBarTitleDisplayMode(.inline)
        .toolbar {
            ToolbarItem(placement: .topBarLeading) {
                UserStatusToolbarItem(showProfileSheet: $showProfileSheet)
            }
            ToolbarItem(placement: .principal) {
                if !selection.isActive && authManager.isLoggedIn && !authManager.isSubscribed {
                    NewsPointsPill()
                }
            }
            ToolbarItem(placement: .topBarTrailing) {
                if !selection.isActive {
                    ArticleListToolbarActions(
                        isGlobalEnglishMode: $isGlobalEnglishMode,
                        onEnterSelection: { enterSelection(preselect: nil) },
                        onToggleSearch: {
                            withAnimation {
                                isSearching.toggle()
                                if !isSearching { isSearchActive = false; searchText = "" }
                            }
                        }
                    )
                }
            }
        }
        .overlay(
            DownloadOverlay(isDownloading: isDownloadingImages,
                            progress: downloadProgress,
                            progressText: downloadProgressText)
        )
        .alert("", isPresented: $showErrorAlert,
               actions: { Button(Localized.confirm, role: .cancel) { } },
               message: { Text(errorMessage) })
        .sheet(isPresented: $showProfileSheet) { UserProfileView() }
        .onChange(of: authManager.isLoggedIn) { newValue in
            if newValue {
                Task {
                    await NewsQuotaManager.shared.refresh(
                        userId: NewsQuotaManager.currentUserId(auth: authManager))
                }
            }
        }
    }

    @ViewBuilder
    private var listArea: some View {
        if !isSearchActive && baseFilteredArticles.isEmpty {
            EmptyStateView(filterMode: filterMode)
        } else {
            List {
                if isSearchActive {
                    SearchResultsList(
                        results: searchResults,
                        viewModel: viewModel,
                        authManager: authManager,
                        showEnglish: isGlobalEnglishMode,
                        onArticleTap: { item in await handleArticleTap(item, autoPlay: false) },
                        onMarkRead: { markOne($0, asRead: true) },
                        onMarkUnread: { markOne($0, asRead: false) }
                    )
                } else {
                    ArticleListContent(
                        items: baseFilteredArticles,
                        filterMode: filterMode,
                        expandedTimestamps: viewModel.expandedTimestampsBySource[viewModel.allArticlesKey, default: Set<String>()],
                        viewModel: viewModel,
                        authManager: authManager,
                        showEnglish: isGlobalEnglishMode,
                        isSelectionMode: selection.isActive,
                        selectedIDs: selection.selected,
                        onToggleTimestamp: { timestamp in
                            viewModel.toggleTimestampExpansion(for: viewModel.allArticlesKey, timestamp: timestamp)
                        },
                        onPlayTimestamp: { timestamp in
                            if let firstItem = baseFilteredArticles.first(where: { $0.article.timestamp == timestamp }) {
                                Task { await handleArticleTap(firstItem, autoPlay: true) }
                            }
                        },
                        onArticleTap: { item in await handleArticleTap(item, autoPlay: false) },
                        onToggleSelect: { selection.toggle($0.id) },
                        onToggleGroupSelect: { group in selection.toggleGroup(group.map { $0.id }) },
                        onEnterSelection: { item in enterSelection(preselect: item.id) },
                        onMarkRead: { markOne($0, asRead: true) },
                        onMarkUnread: { markOne($0, asRead: false) }
                    )
                }
            }
            .listStyle(PlainListStyle())
            .environment(\.defaultMinListRowHeight, 0)
            .animation(.easeInOut(duration: 0.25), value: baseFilteredArticles.count)
        }
    }

    @ViewBuilder
    private var bottomBar: some View {
        if selection.isActive {
            SelectionActionBar(
                selectedCount: selection.selected.count,
                totalCount: baseFilteredArticles.count,
                filterMode: filterMode,
                onSelectAll: { selection.selected = Set(baseFilteredArticles.map { $0.id }) },
                onClearAll: { selection.selected.removeAll() },
                onMarkRead: { applySelection(asRead: true) },
                onMarkUnread: { applySelection(asRead: false) },
                onCancel: { exitSelection() }
            )
        } else if !isSearchActive {
            Picker("Filter", selection: $filterMode) {
                ForEach(ArticleFilterMode.allCases, id: \.self) { mode in
                    Text(getFilterTitle(for: mode)).tag(mode)
                }
            }
            .pickerStyle(.segmented)
            .padding(.horizontal, 16)
            .padding(.top, 6)
            .padding(.bottom, 10)
            .onChange(of: filterMode) { _ in
                ONewsHaptics.selection()
                autoExpandGroups()
            }
        }
    }

    // MARK: - 多选处理
    private func enterSelection(preselect: UUID?) {
        undo.hide()
        selection.enter(preselect: preselect)
    }

    private func exitSelection() {
        selection.exit()
    }

    private func applySelection(asRead: Bool) {
        let ids = selection.selected
        guard !ids.isEmpty else { exitSelection(); return }
        let articles = baseFilteredArticles.filter { ids.contains($0.id) }.map { $0.article }
        guard !articles.isEmpty else { exitSelection(); return }

        ONewsHaptics.success()
        withAnimation(.easeInOut(duration: 0.28)) { viewModel.markArticles(articles, asRead: asRead) }
        exitSelection()

        let n = articles.count
        let msg = isGlobalEnglishMode
            ? "\(n) marked as \(asRead ? "read" : "unread")"
            : "已将 \(n) 篇标记为\(asRead ? "已读" : "未读")"
        undo.show(msg) {
            withAnimation(.easeInOut(duration: 0.28)) { viewModel.markArticles(articles, asRead: !asRead) }
        }
    }

    private func markOne(_ item: ArticleItem, asRead: Bool) {
        ONewsHaptics.light()
        let a = item.article
        withAnimation(.easeInOut(duration: 0.25)) { viewModel.markArticles([a], asRead: asRead) }
        let msg = isGlobalEnglishMode
            ? (asRead ? "Marked as read" : "Marked as unread")
            : (asRead ? "已标记为已读" : "已标记为未读")
        undo.show(msg) {
            withAnimation(.easeInOut(duration: 0.25)) { viewModel.markArticles([a], asRead: !asRead) }
        }
    }

    private func handleArticleTap(_ item: ArticleItem, autoPlay: Bool = false) async {
        let article = item.article
        guard let sourceName = item.sourceName else { return }

        if !NewsPointsCoordinator.canAccess(article, auth: authManager, viewModel: viewModel) {
            NewsPointsCoordinator.shared.attemptUnlockArticle(article, auth: authManager, viewModel: viewModel) {
                Task { await self.handleArticleTap(item, autoPlay: autoPlay) }
            }
            return
        }

        AnonFreeReadTracker.note(article, auth: authManager, viewModel: viewModel)
        undo.hide()

        if !article.images.isEmpty {
            resourceManager.enqueueImageDownloads(timestamp: article.timestamp,
                                                  imageNames: article.images,
                                                  priority: true)
        }
        await MainActor.run {
            appNavPath?.wrappedValue.append(
                NavigationTarget.articleDetail(article, sourceName, "all", autoPlay))
        }
    }

    private func autoExpandGroups() {
        let key = viewModel.allArticlesKey
        let groupedArticles = Dictionary(grouping: baseFilteredArticles, by: { $0.article.timestamp })
        let sortedTimestamps = groupedArticles.keys.sorted(by: >)
        if authManager.isSubscribed {
            viewModel.expandedTimestampsBySource[key] = sortedTimestamps.first.map { [$0] } ?? []
        } else {
            if sortedTimestamps.count == 1, let s = sortedTimestamps.first {
                viewModel.expandedTimestampsBySource[key] = [s]
            } else {
                viewModel.expandedTimestampsBySource[key] = []
            }
        }
    }
}

import SwiftUI

@MainActor
final class NewsQuotaManager: ObservableObject {
    static let shared = NewsQuotaManager()
    private init() {}

    private static let base = "http://106.15.183.158:5001/api/ONews"

    // 与 FreeQuotaManager 保持一致的用户 ID 解析（新闻各处复用）
    static func currentUserId(auth: AuthManager) -> String {
        return FreeQuotaManager.currentUserId(auth: auth)
    }

    @Published var dailyQuota: Int = 0
    @Published var remaining: Int = 0
    @Published var bonusRemaining: Int = 0
    @Published var dailyRemaining: Int = 0
    @Published private(set) var unlockedNewsKeys: Set<String> = []
    @Published var pendingBonusWelcome: Int = 0

    @Published var inviteCode: String = ""
    @Published var inviteRewardCount: Int = 0
    @Published var hasRedeemedInvite: Bool = false
    @Published var inviteRewardPoints: Int = 28
    @Published var loggedIn: Bool = false

    func isNewsUnlocked(_ key: String) -> Bool { unlockedNewsKeys.contains(key) }
    func clearBonusWelcome() { pendingBonusWelcome = 0 }

    /// 【新增】登出/删号时清空本地点数，避免胶囊还显示旧点数
    func reset() {
        dailyQuota = 0
        remaining = 0
        bonusRemaining = 0
        dailyRemaining = 0
        unlockedNewsKeys = []
        pendingBonusWelcome = 0
        inviteCode = ""
        inviteRewardCount = 0
        hasRedeemedInvite = false
        loggedIn = false
        NewsPointsPrefs.reset()      // 可选：登出后恢复"每次询问"
    }

    func refresh(userId: String) async {
        guard let enc = userId.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed),
              let url = URL(string: "\(Self.base)/quota/status?user_id=\(enc)") else { return }
        var req = URLRequest(url: url); req.timeoutInterval = 12
        do {
            let (data, _) = try await URLSession.shared.data(for: req)
            let resp = try JSONDecoder().decode(FreeQuotaManager.QuotaStatus.self, from: data)
            self.dailyQuota      = resp.daily_quota
            self.dailyRemaining  = resp.daily_remaining ?? resp.remaining
            self.bonusRemaining  = resp.bonus_remaining ?? 0
            self.remaining       = resp.total_remaining ?? resp.remaining
            self.unlockedNewsKeys = Set(resp.unlocked_news ?? [])
            self.inviteCode      = resp.invite_code ?? ""
            self.inviteRewardCount = resp.invite_reward_count ?? 0
            self.hasRedeemedInvite = resp.has_redeemed_invite ?? false
            self.inviteRewardPoints = resp.invite_reward_points ?? self.inviteRewardPoints
            self.loggedIn        = resp.logged_in ?? true
            if (resp.bonus_just_granted ?? false), (resp.bonus_remaining ?? 0) > 0 {
                self.pendingBonusWelcome = resp.bonus_remaining ?? 0
            }
        } catch { }
    }

    enum NewsUnlockResult { case success, alreadyUnlocked, quotaExceeded, failed(String) }

    func unlockNews(userId: String, articleKey: String, topic: String) async -> NewsUnlockResult {
        guard let url = URL(string: "\(Self.base)/quota/unlock") else { return .failed("地址无效") }
        var req = URLRequest(url: url); req.httpMethod = "POST"
        req.setValue("application/json", forHTTPHeaderField: "Content-Type"); req.timeoutInterval = 12
        req.httpBody = try? JSONSerialization.data(withJSONObject: [
            "user_id": userId, "article_key": articleKey, "article_topic": topic])
        do {
            let (data, _) = try await URLSession.shared.data(for: req)
            let resp = try JSONDecoder().decode(FreeQuotaManager.UnlockResponse.self, from: data)
            func apply() {
                self.remaining      = resp.total_remaining ?? resp.remaining
                self.bonusRemaining = resp.bonus_remaining ?? self.bonusRemaining
                self.dailyRemaining = resp.daily_remaining ?? self.dailyRemaining
            }
            switch resp.status {
            case "success":          unlockedNewsKeys.insert(articleKey); apply(); return .success
            case "already_unlocked": unlockedNewsKeys.insert(articleKey); apply(); return .alreadyUnlocked
            case "quota_exceeded":   remaining=0; bonusRemaining=0; dailyRemaining=0; return .quotaExceeded
            default: return .failed("未知状态")
            }
        } catch { return .failed(error.localizedDescription) }
    }

    func redeemInvite(userId: String, code: String) async throws -> Int {
        guard let url = URL(string: "\(Self.base)/invite/redeem") else { throw URLError(.badURL) }
        var req = URLRequest(url: url); req.httpMethod = "POST"
        req.setValue("application/json", forHTTPHeaderField: "Content-Type"); req.timeoutInterval = 15
        req.httpBody = try JSONSerialization.data(withJSONObject: ["user_id": userId, "invite_code": code])
        let (data, resp) = try await URLSession.shared.data(for: req)
        guard let http = resp as? HTTPURLResponse else { throw URLError(.badServerResponse) }
        if http.statusCode != 200 {
            if let obj = try? JSONDecoder().decode([String: String].self, from: data), let msg = obj["error"] {
                throw NSError(domain: "Invite", code: http.statusCode, userInfo: [NSLocalizedDescriptionKey: msg])
            }
            throw URLError(.badServerResponse)
        }
        struct R: Codable { let reward_points: Int?; let bonus_remaining: Int?; let remaining_total: Int? }
        let r = try JSONDecoder().decode(R.self, from: data)
        if let b = r.bonus_remaining { self.bonusRemaining = b }
        if let t = r.remaining_total { self.remaining = t }
        return r.reward_points ?? 0
    }
}

final_prompt:
在列表里文章较多，分组较多时，快速来回上下滑动，有时会出现卡顿，手指滑动了，但列表没动。这是上次AI给我的建议"在列表文章和分组较多时，出现快速上下滑动时列表卡住、手指划动了但页面毫无反应的现象，是由 “手势拦截死锁” 和 “主线程密集计算严重掉帧” 两个致命原因共同导致的：

为什么会出现“手指滑了，列表没动”？
手势死锁（最核心原因）：
每个列表项都挂了自定义的 DragGesture（在 SwipeToMarkRow 中）。
当手指触摸屏幕开始上下滑动时，一旦手指稍有倾斜，SwiftUI 的 DragGesture 就会先于 List 的上下滚动手势捕获触控事件。
即使你在代码里写了 phase = .rejected，那只是你自己的 Swift 状态变量，底层的触控事件依然被该手势占有着，无法交还给底层的滚动视图。结果就是整个纵向滚动被完全吞噬，表现为“手指滑了，列表纹丝不动”。

主线程掉帧卡死（加剧元凶）：

body 里做重度分组运算：在 ArticleListContent.body 中，每次重新渲染都在执行全量 Dictionary(grouping: items) 和 keys.sorted(by: >)。文章一多，主线程每一帧都在建字典和排序。
每个 Cell 挂了 GeometryReader：每个卡片都放了一个 GeometryReader 并在 .onChange 里写回 @State var rowWidth。快速滑动时，大量 Cell 进出屏幕触发 Geometry 重新计算并修改状态，导致高频布局震荡。
DateFormatter 在渲染时反复创建：TimestampHeader 的 displayFormatter 是个计算属性，每渲染一个 Header 就会 new 一个极其昂贵的 DateFormatter。
无效的 @ObservedObject 监听：ArticleRowButton 里声明了 @ObservedObject private var newsQuota，但内部完全没用到，导致配额任何细微刷新都会引发可见 Cell 全量重绘。
解决方案与具体修改
我们需要从 “手势优化” 和 “渲染性能瘦身” 两处着手。

1. 修复手势阻断 List 滚动的死锁，并干掉每个 Cell 的 GeometryReader
用固定逻辑宽度替代 GeometryReader（手机屏幕宽度一般在 375~430 之间，滑动触发阈值用固定的 90~110pt 最符合人类拇指肌肉记忆，不需要动态测量）。
同时，手势改用组合手势判定，并提供更平滑的手势优先级：

在 ArticleListView.swift 中修改 SwipeToMarkRow：

swift
struct SwipeToMarkRow<Content: View>: View {
    private enum Phase { case idle, engaged, rejected, committing }

    let isRead: Bool
    let isEnabled: Bool
    let resetKey: UUID
    let onCommit: () -> Void
    private let content: Content

    init(isRead: Bool,
         isEnabled: Bool,
         resetKey: UUID,
         onCommit: @escaping () -> Void,
         @ViewBuilder content: () -> Content) {
        self.isRead = isRead
        self.isEnabled = isEnabled
        self.resetKey = resetKey
        self.onCommit = onCommit
        self.content = content()
    }

    @State private var offsetX: CGFloat = 0
    @State private var contentOpacity: Double = 1
    @State private var phase: Phase = .idle
    @State private var isArmed = false

    // 固定滑动阈值（95pt），无需 GeometryReader 动态测量，节省大量布局耗时
    private let threshold: CGFloat = 95
    private var dragDistance: CGFloat { max(0, -offsetX) }
    private var progress: CGFloat { threshold <= 0 ? 0 : min(1, dragDistance / threshold) }

    private var actionTitle: String { isRead ? Localized.markAsUnread_text : Localized.markAsRead_text }
    private var actionIcon: String { isRead ? "envelope.badge.fill" : "checkmark.circle.fill" }
    private var actionTint: Color { isRead ? .orange : .blue }

    var body: some View {
        ZStack(alignment: .trailing) {
            backdrop
            content
                .offset(x: offsetX)
                .opacity(contentOpacity)
        }
        // 使用 highPriorityGesture 或只在启用时生效
        .highPriorityGesture(isEnabled ? swipeGesture : nil)
        .onChange(of: resetKey) { _ in resetImmediately() }
        .onChange(of: isEnabled) { _ in resetImmediately() }
    }

    // MARK: 背景提示层
    private var backdrop: some View {
        ZStack(alignment: .trailing) {
            RoundedRectangle(cornerRadius: ONewsSwipeConfig.cornerRadius, style: .continuous)
                .fill(isArmed ? actionTint : actionTint.opacity(0.16))

            HStack(spacing: 8) {
                Image(systemName: actionIcon)
                    .font(.system(size: 16, weight: .bold))
                Text(actionTitle)
                    .font(.system(size: 15, weight: .bold))
                    .lineLimit(1)
                    .fixedSize()
            }
            .foregroundColor(isArmed ? .white : actionTint)
            .padding(.trailing, 22)
            .scaleEffect(isArmed ? 1.06 : 1.0)
            .opacity(Double(min(1, progress * 1.35)))
        }
        .animation(.easeOut(duration: 0.16), value: isArmed)
        .opacity(dragDistance > 0.5 ? 1 : 0)
        .allowsHitTesting(false)
    }

    // MARK: 手势：更严格的横向仲裁，防止吃掉上下滑动
    private var swipeGesture: some Gesture {
        DragGesture(minimumDistance: 20, coordinateSpace: .local)
            .onChanged { value in
                guard isEnabled, phase != .committing else { return }
                let dx = value.translation.width
                let dy = value.translation.height

                if phase == .idle {
                    // 纵向占优或向右滑：立即判定为 rejected，不拦截后续操作
                    if abs(dy) >= abs(dx) || dx >= 0 {
                        phase = .rejected
                        return
                    }
                    phase = .engaged
                }
                guard phase == .engaged else { return }

                offsetX = rubberBand(min(0, dx))

                let armed = dragDistance >= threshold
                if armed != isArmed {
                    if armed { ONewsHaptics.selection() }
                    isArmed = armed
                }
            }
            .onEnded { value in
                let wasEngaged = (phase == .engaged)
                if phase != .committing { phase = .idle }
                guard isEnabled, wasEngaged else { snapBack(); return }

                let predicted = value.predictedEndTranslation.width
                let shouldCommit = dragDistance >= threshold
                    || predicted <= -threshold * ONewsSwipeConfig.flingFactor
                if shouldCommit { commit() } else { snapBack() }
            }
    }

    private func rubberBand(_ x: CGFloat) -> CGFloat {
        let soft = threshold * 1.35
        guard x < -soft else { return x }
        let extra = -x - soft
        return -(soft + extra * ONewsSwipeConfig.rubberBandDamping)
    }

    private func snapBack() {
        isArmed = false
        withAnimation(.spring(response: 0.32, dampingFraction: 0.82)) { offsetX = 0 }
    }

    private func commit() {
        phase = .committing
        isArmed = false
        withAnimation(.easeOut(duration: 0.20)) {
            offsetX = -400
            contentOpacity = 0
        }
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.20) {
            onCommit()
            var t = Transaction(); t.disablesAnimations = true
            withTransaction(t) { offsetX = 0 }
            withAnimation(.easeOut(duration: 0.18)) { contentOpacity = 1 }
            phase = .idle
        }
    }

    private func resetImmediately() {
        var t = Transaction(); t.disablesAnimations = true
        withTransaction(t) {
            offsetX = 0
            contentOpacity = 1
            isArmed = false
            phase = .idle
        }
    }
}

