import SwiftUI
import UIKit

// MARK: - 触感反馈
enum ONewsHaptics {
    static func light() { UIImpactFeedbackGenerator(style: .light).impactOccurred() }
    static func rigid() { UIImpactFeedbackGenerator(style: .rigid).impactOccurred() }
