        return

    _CHART_WINDOW.show()
    print(f"图表已加载: {name}（窗口{'复用' if reuse else '新建'}）")

    # 只有在完全独立运行（外部没有 Qt 事件循环）时才阻塞
    if created_app:
        plt.show()

