                    idx = dates.index(closest_date)
                    earning_p = prices[idx]

                    if earning_p != 0:
                        er_pct = (latest_p - earning_p) / earning_p * 100
                        er_pct_str = f"{er_pct:.1f}%"
                        er_color = NORD_THEME['accent_red'] if er_pct > 0 else NORD_THEME['accent_green']
                except Exception:
                    pass

