_ST_CANCEL = re.compile(r"取消|撤销|撤单|拒绝|失效|过期|无效|作废|cancel|reject|expire|void", re.I)
_ST_PEND = re.compile(r"待|挂单|未成交|排队|已提交|open|pending|queued|working|accept", re.I)

