def load_sector_symbols():
    data = _load_json(SECTORS_ALL_PATH)
    out, seen, per_group = [], set(), {}
    for g in SECTOR_GROUPS_FOR_WATCHLIST:
        arr = data.get(g)
        if not isinstance(arr, list):
            per_group[g] = 0
            continue
        cnt = 0
        for raw in arr:
            sym = str(raw).strip().upper()
            if not sym:
                continue
            key = sym.replace(".", "").replace("-", "")
