                        f"{datetime.strftime(xval, '%Y-%m-%d')}",
                        price_display,
                        f"{turnover_str}",
                        f"{days_diff}天",
                        ""
                    ]

                    marker_texts = []
                    if g_text: marker_texts.append(g_text)
                    if s_text: marker_texts.append(s_text + "\n")
                    has_earning = False
                    if e_text:
                        for line in e_text.split('\n'):
