    private func statusText(_ it: DownloadItem) -> String {
        switch it.state {
        case .queued:      return lang.t("排队中", "Queued")
        case .preparing:   return lang.t("解析中…", "Preparing…")
        case .downloading: return "\(Int(it.progress * 100))% · \(it.done)/\(it.total)"
        case .paused:      return lang.t("已暂停 \(Int(it.progress * 100))%", "Paused \(Int(it.progress * 100))%")
        case .completed:   return lang.t("已完成 · 可离线播放", "Completed · offline ready")
        case .failed:      return lang.t("失败：", "Failed: ") + (it.errorText ?? "")
        }
    }
    private func statusColor(_ it: DownloadItem) -> Color {
        switch it.state {
        case .completed: return .green
        case .failed:    return .red
        case .paused:    return .orange
        case .queued:    return .blue
        default:         return .secondary
        }
    }
}

struct DownloadItem: Codable, Identifiable, Hashable {
    enum State: String, Codable { case queued, preparing, downloading, paused, completed, failed }
    var id: String
    var episodeKey: String       // 原始播放页 URL（解锁/去重判断）
    var mediaURL: String         // 解析后的 m3u8
    var title: String            // "剧名 · 第01集"
    var seriesTitle: String
    var episodeName: String
    var cover: String?
    var sourceURL: String?
    var folder: String
    var total: Int = 0
    var done: Int = 0
    var bytes: Int64 = 0
    var state: State = .queued
    var createdAt: Date = Date()
    var errorText: String?

    var progress: Double { total > 0 ? min(1, Double(done) / Double(total)) : 0 }
    var groupKey: String { seriesTitle.isEmpty ? "u:" + id : "s:" + seriesTitle }
}

/// 分片描述（Sendable，可安全跨并发边界传递）
private struct HLSSegment: Sendable {
    let url: URL
    let file: String
}

/// 纯网络工具：不属于任何 actor，保证下载不占用主线程
private enum HLSNet {
    static func request(_ url: URL) -> URLRequest {
        var r = URLRequest(url: url)
        r.timeoutInterval = 30
        r.cachePolicy = .reloadIgnoringLocalCacheData
        r.setValue("Mozilla/5.0 (Macintosh; Intel Mac OS X 13_0) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/16.0 Safari/605.1.15",
                   forHTTPHeaderField: "User-Agent")
        r.setValue("*/*", forHTTPHeaderField: "Accept")
        return r
    }
    static func data(_ url: URL) async throws -> Data {
        let (d, resp) = try await URLSession.shared.data(for: request(url))
        if let h = resp as? HTTPURLResponse, h.statusCode >= 400 { throw URLError(.badServerResponse) }
        return d
    }
    static func text(_ url: URL) async throws -> String {
        let d = try await data(url)
        return String(data: d, encoding: .utf8) ?? String(decoding: d, as: UTF8.self)
    }
}

/// m3u8 文本解析（纯函数，无隔离）
private nonisolated enum M3U8 {
    static func pickVariant(_ text: String, base: URL) -> URL? {
        var best: (Int, URL)?
        let lines = text.components(separatedBy: .newlines)
        for (i, l) in lines.enumerated() where l.hasPrefix("#EXT-X-STREAM-INF") {
            var bw = 0
            if let r = l.range(of: "BANDWIDTH=") {
                let tail = l[r.upperBound...].prefix { $0.isNumber }
                bw = Int(tail) ?? 0
            }
            var j = i + 1
            while j < lines.count,
                  lines[j].trimmingCharacters(in: .whitespaces).isEmpty || lines[j].hasPrefix("#") { j += 1 }
            guard j < lines.count,
                  let u = URL(string: lines[j].trimmingCharacters(in: .whitespaces),
                              relativeTo: base)?.absoluteURL else { continue }
            if best == nil || bw > best!.0 { best = (bw, u) }
        }
        return best?.1
    }
    static func extractURI(_ line: String) -> String? {
        guard let r = line.range(of: "URI=\"") else { return nil }
        let rest = line[r.upperBound...]
        guard let e = rest.firstIndex(of: "\"") else { return nil }
        return String(rest[..<e])
    }
    static func replaceURI(_ line: String, with local: String) -> String {
        guard let uri = extractURI(line) else { return line }
        return line.replacingOccurrences(of: "URI=\"\(uri)\"", with: "URI=\"\(local)\"")
    }
}

@MainActor
final class HLSDownloadManager: ObservableObject {
    static let shared = HLSDownloadManager()

    @Published private(set) var items: [DownloadItem] = []
    @Published private(set) var speeds: [String: Double] = [:]

    private var running: Set<String> = []
    private var cancelFlags: Set<String> = []
    private var lastBytes: [String: Int64] = [:]
    private var activity: NSObjectProtocol?
    private var timer: Timer?

    private let maxConcurrentDownloads = 2
    private var maxSegmentConcurrency: Int {
        let v = UserDefaults.standard.integer(forKey: "GW_SegConcurrency")
        return max(2, min(12, v == 0 ? 6 : v))
    }

    // MARK: 路径（nonisolated，后台线程也能安全取）
    nonisolated private var rootDir: URL {
        let base = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
            .appendingPathComponent(Bundle.main.bundleIdentifier ?? "GWVideo")
            .appendingPathComponent("Downloads")
        try? FileManager.default.createDirectory(at: base, withIntermediateDirectories: true)
        return base
    }
    nonisolated private var stateFile: URL { rootDir.appendingPathComponent("state.json") }
    nonisolated func folderURL(_ item: DownloadItem) -> URL { rootDir.appendingPathComponent(item.folder) }
    nonisolated func playlistURL(_ item: DownloadItem) -> URL { folderURL(item).appendingPathComponent("local.m3u8") }
    nonisolated var storageRoot: URL { rootDir }

    private init() {
        load()
        for i in items.indices where items[i].state == .downloading || items[i].state == .preparing {
            items[i].state = .queued
        }
        save()
        // ⭐ 先强绑定 self，再进 Task，避免「捕获的 weak self 在并发代码中被引用」
        let t = Timer(timeInterval: 1, repeats: true) { [weak self] _ in
            guard let self else { return }
            Task { @MainActor in self.tick() }
        }
        RunLoop.main.add(t, forMode: .common)
        timer = t
        pump()
    }

    // MARK: 查询
    func item(forEpisodeKey key: String) -> DownloadItem? { items.first { $0.episodeKey == key } }
    func isQueuedOrDone(_ key: String) -> Bool { item(forEpisodeKey: key) != nil }
    func localURL(forEpisodeKey key: String) -> URL? {
        guard let it = item(forEpisodeKey: key), it.state == .completed else { return nil }
        let u = playlistURL(it)
        return FileManager.default.fileExists(atPath: u.path) ? u : nil
    }
    var completedKeys: Set<String> { Set(items.filter { $0.state == .completed }.map(\.episodeKey)) }
    var totalDiskUsage: Int64 { items.reduce(0) { $0 + $1.bytes } }

    // MARK: 对外操作
    func start(episodeKey: String, mediaURL: String, title: String, seriesTitle: String,
               episodeName: String, cover: String?, sourceURL: String?) {
        if let i = items.firstIndex(where: { $0.episodeKey == episodeKey }) {
            if items[i].state == .paused || items[i].state == .failed {
                items[i].state = .queued; items[i].errorText = nil; save(); pump()
            }
            return
        }
        let it = DownloadItem(id: UUID().uuidString, episodeKey: episodeKey, mediaURL: mediaURL,
                              title: title, seriesTitle: seriesTitle, episodeName: episodeName,
                              cover: cover, sourceURL: sourceURL, folder: UUID().uuidString)
        items.append(it)
        try? FileManager.default.createDirectory(at: folderURL(it), withIntermediateDirectories: true)
        save(); pump()
        let id = AuthManager.shared.trackIdentity
        TrackingManager.shared.track(.downloadStart, userId: id.id, userType: id.type,
                                     videoURL: episodeKey, videoTitle: title)
    }

    func pause(_ id: String) {
        guard let i = items.firstIndex(where: { $0.id == id }) else { return }
        cancelFlags.insert(id)
        items[i].state = .paused
        running.remove(id); speeds[id] = 0
        save(); pump()
    }
    func resume(_ id: String) {
        guard let i = items.firstIndex(where: { $0.id == id }),
              items[i].state == .paused || items[i].state == .failed else { return }
        cancelFlags.remove(id)
        items[i].state = .queued; items[i].errorText = nil
        save(); pump()
    }
    func pauseAll() {
        items.filter { $0.state == .downloading || $0.state == .queued || $0.state == .preparing }
             .forEach { pause($0.id) }
    }
    func resumeAll() { items.filter { $0.state == .paused || $0.state == .failed }.forEach { resume($0.id) } }

    func delete(_ id: String) {
        guard let i = items.firstIndex(where: { $0.id == id }) else { return }
        cancelFlags.insert(id); running.remove(id)
        try? FileManager.default.removeItem(at: folderURL(items[i]))
        items.remove(at: i)
        speeds[id] = nil; lastBytes[id] = nil
        save(); pump()
    }
    func revealInFinder(_ id: String) {
        guard let it = items.first(where: { $0.id == id }) else { return }
        NSWorkspace.shared.activateFileViewerSelecting([folderURL(it)])
    }

    // MARK: 调度
    private func pump() {
        updateActivity()
        while running.count < maxConcurrentDownloads,
              let next = items.first(where: { $0.state == .queued && !running.contains($0.id) }) {
            running.insert(next.id)
            let id = next.id
            Task { await self.run(id) }
        }
    }

    private func run(_ id: String) async {
        // run 本身在 MainActor 上，defer 直接同步执行即可
        defer {
            running.remove(id)
            speeds[id] = 0
            pump()
        }
        guard let it = items.first(where: { $0.id == id }) else { return }
        setState(id, .preparing)
        do {
            let segs = try await prepare(it)
            if cancelFlags.contains(id) { return }
            setState(id, .downloading)
            try await downloadSegments(id: id, folder: folderURL(it), segments: segs)
            if cancelFlags.contains(id) { return }
            setState(id, .completed)
            save()
            let ident = AuthManager.shared.trackIdentity
            TrackingManager.shared.track(.downloadComplete, userId: ident.id, userType: ident.type,
                                         videoURL: it.episodeKey, videoTitle: it.title)
        } catch is CancellationError {
            // 用户暂停
        } catch {
            if !cancelFlags.contains(id), let i = items.firstIndex(where: { $0.id == id }) {
                items[i].state = .failed
                items[i].errorText = error.localizedDescription
                save()
            }
        }
    }

    private func setState(_ id: String, _ s: DownloadItem.State) {
        guard let i = items.firstIndex(where: { $0.id == id }) else { return }
        items[i].state = s; save()
    }

    private func setCounts(id: String, total: Int, done: Int) {
        guard let i = items.firstIndex(where: { $0.id == id }) else { return }
        items[i].total = total
        items[i].done = min(done, total)
        save()
    }

    private func isCancelled(_ id: String) -> Bool { cancelFlags.contains(id) }

    private func bump(_ id: String, bytes: Int64) {
        guard let i = items.firstIndex(where: { $0.id == id }) else { return }
        items[i].done = min(items[i].total, items[i].done + 1)
        items[i].bytes += bytes
    }

    // MARK: 准备：拉 m3u8 → 选码率 → 重写为本地播放列表（nonisolated，不卡 UI）
    nonisolated private func prepare(_ it: DownloadItem) async throws -> [HLSSegment] {
        let dir = folderURL(it)
        let fm = FileManager.default
        try? fm.createDirectory(at: dir.appendingPathComponent("segments"), withIntermediateDirectories: true)
        try? fm.createDirectory(at: dir.appendingPathComponent("keys"), withIntermediateDirectories: true)

        // 已准备过 → 直接读缓存清单（断点续传）
        let manifest = dir.appendingPathComponent("segments.json")
        if let d = try? Data(contentsOf: manifest),
           let arr = try? JSONDecoder().decode([[String]].self, from: d), !arr.isEmpty {
            let segs = arr.compactMap { p -> HLSSegment? in
                guard p.count == 2, let u = URL(string: p[0]) else { return nil }
                return HLSSegment(url: u, file: p[1])
            }
            if !segs.isEmpty {
                await setCounts(id: it.id, total: segs.count, done: Self.countExisting(dir, segs))
                return segs
            }
        }

        guard var playlistURL = URL(string: it.mediaURL) else { throw URLError(.badURL) }
        var text = try await HLSNet.text(playlistURL)

        // Master playlist → 选最高码率
        if text.contains("#EXT-X-STREAM-INF") {
            guard let variant = M3U8.pickVariant(text, base: playlistURL) else { throw URLError(.cannotParseResponse) }
            playlistURL = variant
            text = try await HLSNet.text(playlistURL)
        }

        var out: [String] = []
        var segs: [HLSSegment] = []
        var urlToFile: [String: String] = [:]
        var keyIdx = 0, mapIdx = 0

        for rawLine in text.components(separatedBy: .newlines) {
            let line = rawLine.trimmingCharacters(in: .whitespaces)
            if line.isEmpty { continue }
            if line.hasPrefix("#") {
                if line.hasPrefix("#EXT-X-KEY"), let uri = M3U8.extractURI(line),
                   let abs = URL(string: uri, relativeTo: playlistURL)?.absoluteURL {
                    let name = "keys/key_\(keyIdx).key"; keyIdx += 1
                    let data = try await HLSNet.data(abs)
                    try data.write(to: dir.appendingPathComponent(name))
                    out.append(M3U8.replaceURI(line, with: name))
                } else if line.hasPrefix("#EXT-X-MAP"), let uri = M3U8.extractURI(line),
                          let abs = URL(string: uri, relativeTo: playlistURL)?.absoluteURL {
                    let ext = abs.pathExtension.isEmpty ? "mp4" : abs.pathExtension
                    let name = "segments/init_\(mapIdx).\(ext)"; mapIdx += 1
                    let data = try await HLSNet.data(abs)
                    try data.write(to: dir.appendingPathComponent(name))
                    out.append(M3U8.replaceURI(line, with: name))
                } else if line.hasPrefix("#EXT-X-ENDLIST") {
                    continue
                } else {
                    out.append(line)
                }
                continue
            }
            guard let abs = URL(string: line, relativeTo: playlistURL)?.absoluteURL else { continue }
            if let existing = urlToFile[abs.absoluteString] {
                out.append(existing)
            } else {
                let ext = abs.pathExtension.isEmpty ? "ts" : abs.pathExtension
                let name = String(format: "segments/%05d.%@", segs.count, ext)
                urlToFile[abs.absoluteString] = name
                segs.append(HLSSegment(url: abs, file: name))
                out.append(name)
            }
        }

        guard !segs.isEmpty else { throw URLError(.zeroByteResource) }
        if !out.contains(where: { $0.hasPrefix("#EXT-X-PLAYLIST-TYPE") }) {
            if let i = out.firstIndex(where: { $0.hasPrefix("#EXT-X-TARGETDURATION") }) {
                out.insert("#EXT-X-PLAYLIST-TYPE:VOD", at: i + 1)
            } else { out.insert("#EXT-X-PLAYLIST-TYPE:VOD", at: min(1, out.count)) }
        }
        out.append("#EXT-X-ENDLIST")
        try out.joined(separator: "\n").write(to: dir.appendingPathComponent("local.m3u8"),
                                              atomically: true, encoding: .utf8)
        let dump = segs.map { [$0.url.absoluteString, $0.file] }
        try JSONEncoder().encode(dump).write(to: manifest)

        await setCounts(id: it.id, total: segs.count, done: Self.countExisting(dir, segs))
        return segs
    }

    nonisolated private static func countExisting(_ dir: URL, _ segs: [HLSSegment]) -> Int {
        segs.reduce(0) { acc, s in
            let p = dir.appendingPathComponent(s.file).path
            let attrs = try? FileManager.default.attributesOfItem(atPath: p)
            let sz = (attrs?[.size] as? Int) ?? 0     // ⭐ 修复多余的 ??
            return acc + (sz > 0 ? 1 : 0)
        }
    }

    // MARK: 分片并发下载（滑动窗口）
    private func downloadSegments(id: String, folder: URL, segments: [HLSSegment]) async throws {
        let limit = maxSegmentConcurrency
        var next = 0
        try await withThrowingTaskGroup(of: Void.self) { group in
            while next < segments.count, next < limit {
                let seg = segments[next]; next += 1
                group.addTask { try await self.processSegment(id: id, folder: folder, seg: seg) }
            }
            while try await group.next() != nil {
                if isCancelled(id) { group.cancelAll(); throw CancellationError() }   // ⭐ 去掉多余 await
                if next < segments.count {
                    let seg = segments[next]; next += 1
                    group.addTask { try await self.processSegment(id: id, folder: folder, seg: seg) }
                }
            }
        }
    }

    nonisolated private func processSegment(id: String, folder: URL, seg: HLSSegment) async throws {
        if await isCancelled(id) { throw CancellationError() }
        let fm = FileManager.default
        let dest = folder.appendingPathComponent(seg.file)
        if let attrs = try? fm.attributesOfItem(atPath: dest.path),
           let sz = attrs[.size] as? Int, sz > 0 {
            return                                   // 已存在（续传时已计入 done）
        }
        var lastErr: Error?
        for attempt in 0..<3 {
            if await isCancelled(id) { throw CancellationError() }
            do {
                let data = try await HLSNet.data(seg.url)
                try data.write(to: dest, options: .atomic)
                await bump(id, bytes: Int64(data.count))
                return
            } catch {
                lastErr = error
                try? await Task.sleep(nanoseconds: UInt64(400_000_000 * (attempt + 1)))
            }
        }
        throw lastErr ?? URLError(.unknown)
    }

    // MARK: 每秒 tick：测速 + 持久化
    private func tick() {
        for it in items where it.state == .downloading {
            let prev = lastBytes[it.id] ?? it.bytes
            speeds[it.id] = Double(max(0, it.bytes - prev))
            lastBytes[it.id] = it.bytes
        }
        if items.contains(where: { $0.state == .downloading }) { save(throttled: true) }
        updateActivity()
    }

    /// 下载时禁止 App Nap 与系统休眠
    private func updateActivity() {
        let busy = items.contains { $0.state == .downloading || $0.state == .preparing }
        if busy, activity == nil {
            activity = ProcessInfo.processInfo.beginActivity(
                options: [.userInitiated, .idleSystemSleepDisabled], reason: "Downloading video")
        } else if !busy, let a = activity {
            ProcessInfo.processInfo.endActivity(a); activity = nil
        }
    }

    // MARK: 持久化
    private var lastSave = Date.distantPast
    private func save(throttled: Bool = false) {
        if throttled, Date().timeIntervalSince(lastSave) < 2 { return }
        lastSave = Date()
        if let d = try? JSONEncoder().encode(items) { try? d.write(to: stateFile, options: .atomic) }
    }
    private func load() {
        guard let d = try? Data(contentsOf: stateFile),
              let a = try? JSONDecoder().decode([DownloadItem].self, from: d) else { return }
        items = a
    }
}

import SwiftUI
import AVKit
import AVFoundation
import Combine
import AppKit

// MARK: - Payload
struct PlayPayload: Codable, Hashable, Identifiable {
    var id: String { episodeKey }
    var seriesTitle: String
    var episodeName: String
    var episodeKey: String
    var sourceURL: String?
    var cover: String?
    var channelName: String?
    var episodes: [EpisodeItem]
    var playSource: String?
}

enum SpeedStore {
    private static let key = "GW_PlaybackRate"
    static var rate: Float {
        get { let v = UserDefaults.standard.float(forKey: key); return (v > 0 && v <= 3) ? v : 1 }
        set { UserDefaults.standard.set(min(max(newValue, 0.5), 3), forKey: key) }
    }
}

enum VolumeStore {
    private static let key = "GW_PlayerVolume"
    static var value: Float {
        get {
            guard UserDefaults.standard.object(forKey: key) != nil else { return 1 }
            return min(max(UserDefaults.standard.float(forKey: key), 0), 1)
        }
        set { UserDefaults.standard.set(min(max(newValue, 0), 1), forKey: key) }
    }
}

enum PositionStore {
    private static func k(_ s: String) -> String { "GW_Pos_" + s }
    static func save(_ sec: Double, _ key: String) {
        guard sec > 5, !key.isEmpty else { return }
        UserDefaults.standard.set(sec, forKey: k(key))
    }
    static func load(_ key: String) -> Double { UserDefaults.standard.double(forKey: k(key)) }
    static func clear(_ key: String) { UserDefaults.standard.removeObject(forKey: k(key)) }
}

/// 秒 → 0:00 / 1:02:03
func gwTimeString(_ t: Double) -> String {
    guard t.isFinite, t >= 0 else { return "--:--" }
    let total = Int(t.rounded())
    let h = total / 3600, m = (total % 3600) / 60, s = total % 60
    return h > 0 ? String(format: "%d:%02d:%02d", h, m, s) : String(format: "%d:%02d", m, s)
}

// MARK: - 视频渲染层（消除 AVPictureInPicturePlayerLayerView 层级冲突警告）
final class PlayerSurfaceView: NSView {
    override func makeBackingLayer() -> CALayer {
        let l = AVPlayerLayer()
        l.videoGravity = .resizeAspect
        l.backgroundColor = NSColor.black.cgColor
        return l
    }

    var playerLayer: AVPlayerLayer { layer as! AVPlayerLayer }

    override init(frame frameRect: NSRect) {
        super.init(frame: frameRect)
        wantsLayer = true
    }
    required init?(coder: NSCoder) { nil }
}

struct PlayerSurface: NSViewRepresentable {
    let player: AVPlayer
    let onReady: (PlayerSurfaceView) -> Void

    func makeNSView(context: Context) -> PlayerSurfaceView {
        let v = PlayerSurfaceView()
        v.playerLayer.player = player
        let cb = onReady
        DispatchQueue.main.async { cb(v) }
        return v
    }
    func updateNSView(_ v: PlayerSurfaceView, context: Context) {
        if v.playerLayer.player !== player { v.playerLayer.player = player }
    }
}

/// 拿到承载视图所在的 NSWindow（用于全屏切换）
struct WindowAccessor: NSViewRepresentable {
    let onWindow: (NSWindow?) -> Void
    func makeNSView(context: Context) -> NSView {
        let v = NSView(frame: .zero)
        let cb = onWindow
        DispatchQueue.main.async { cb(v.window) }
        return v
    }
    func updateNSView(_ v: NSView, context: Context) {
        let cb = onWindow
        DispatchQueue.main.async { cb(v.window) }
    }
}

// MARK: - 播放模型
@MainActor
final class PlayerModel: ObservableObject {

    /// ⭐ 播放状态机：把「意图」和「实际状态」彻底分开
    enum Phase: Equatable {
        case idle       // 空
        case loading    // 首次解析 / 起播中
        case playing    // 真正在出画面
        case buffering  // 想播但卡住了（网络/解码/seek）
        case paused     // 用户主动暂停或播完
        case failed     // 出错
    }

    let player = AVPlayer()

    // MARK: 对外状态
    @Published var phase: Phase = .idle
    @Published var loading = true
    @Published var error: String?
    @Published var current: EpisodeItem?
    @Published var isLocal = false

    /// 真正在出画面（用于：控制栏自动隐藏、防休眠判断）
    @Published var isPlaying = false
    /// ⭐ 用户「想播」的意图（用于：播放/暂停按钮图标）—— 卡顿时依然为 true
    @Published var intendsToPlay = false
    /// ⭐ 正在卡顿 / 缓冲
    @Published var isBuffering = false
    /// ⭐ 去抖后真正显示的转圈（避免 seek 时闪一下）
    @Published var showBusySpinner = false
    /// ⭐ 卡了较久 → 提示网络可能有问题
    @Published var slowNetwork = false
    /// ⭐ 卡太久 → 给用户手动"重新加载"按钮
    @Published var offerManualRetry = false

    @Published var currentTime: Double = 0
    @Published var duration: Double = 0
    @Published var bufferedTime: Double = 0
    @Published var isScrubbing = false
    @Published var scrubTime: Double = 0

    @Published var rate: Float = SpeedStore.rate
    @Published var volume: Float = VolumeStore.value
    @Published var isMuted = false
    @Published var isPiPActive = false
    @Published var pipReady = false

    var payload: PlayPayload?
    var onEnded: (() -> Void)?

    // MARK: 私有
    private var timeObs: Any?
    private var endObs: NSObjectProtocol?
    private var stallObs: NSObjectProtocol?
    private var failEndObs: NSObjectProtocol?
    private var statusObs: NSKeyValueObservation?
    private var tcsObs: NSKeyValueObservation?
    private var waitReasonObs: NSKeyValueObservation?
    private var bufferEmptyObs: NSKeyValueObservation?
    private var keepUpObs: NSKeyValueObservation?
    private var pip: AVPictureInPictureController?
    private var sleepToken: NSObjectProtocol?
    private var episodeKey = ""
    private var lastSavedAt: Double = -100

    /// 用户意图（唯一真源）
    private var wantsPlayback = false
    /// 起播/恢复时要跳到的位置
    private var pendingStart: Double?

    // 卡顿看门狗
    private var watchdog: Task<Void, Never>?
    private var recoveryAttempts = 0
    private var lastRecoveryAt = Date.distantPast
    private var isRecovering = false

    // 时间线（可按喜好调整）
    private let spinnerDelay: UInt64        = 350_000_000      // 0.35s 后才转圈
    private let slowHintDelay: UInt64       = 5_650_000_000    // 累计 ~6s 提示网络慢
    private let autoRecoverDelay: UInt64    = 9_000_000_000    // 累计 ~15s 自动自愈
    private let manualRetryDelay: UInt64    = 10_000_000_000   // 累计 ~25s 给手动按钮

    /// UI 用的"当前时间"（拖动时显示拖动位置）
    var displayTime: Double { isScrubbing ? scrubTime : currentTime }

    init() {
        player.volume = VolumeStore.value
        player.actionAtItemEnd = .pause
        observeTimeControlStatus()
    }

    // MARK: - 载入
    func load(payload p: PlayPayload,
              episode: EpisodeItem,
              startAt: Double? = nil,
              resetRecovery: Bool = true) async {

        payload = p; current = episode
        teardownItemObservers()
        stopWatchdog()

        wantsPlayback = false          // 起播前意图归零，readyToPlay 后再置 true
        loading = true; error = nil
        currentTime = 0; duration = 0; bufferedTime = 0
        isScrubbing = false; lastSavedAt = -100
        episodeKey = episode.url
        pendingStart = startAt
        if resetRecovery { recoveryAttempts = 0 }
        recomputePhase()

        var target: URL?
        if let local = HLSDownloadManager.shared.localURL(forEpisodeKey: episode.url) {
            target = local; isLocal = true
        } else {
            isLocal = false
            do {
                let real = try await VideoAPI.resolveRealURL(episodeURL: episode.url)
                target = URL(string: real)
            } catch {
                fail(with: error.localizedDescription)
                return
            }
        }
        guard let url = target else {
            fail(with: T("无法播放", "Unable to play"))
            return
        }

        let item = AVPlayerItem(asset: AVURLAsset(url: url))
        if !isLocal { item.preferredForwardBufferDuration = 10 }
        player.replaceCurrentItem(with: item)
        player.automaticallyWaitsToMinimizeStalling = !isLocal

        let key = episode.url

        statusObs = item.observe(\.status, options: [.new, .initial]) { [weak self] observed, _ in
            guard let self else { return }
            let status = observed.status
            let errText = observed.error?.localizedDescription
            Task { @MainActor in self.handleStatus(status, errorText: errText, episodeKey: key) }
        }

        // ⭐ 缓冲相关 KVO：只用来触发状态重算（timeControlStatus 是主判据）
        bufferEmptyObs = item.observe(\.isPlaybackBufferEmpty, options: [.new]) { [weak self] _, _ in
            Task { @MainActor in self?.recomputePhase() }
        }
        keepUpObs = item.observe(\.isPlaybackLikelyToKeepUp, options: [.new]) { [weak self] _, _ in
            Task { @MainActor in self?.recomputePhase() }
        }

        // ⭐ 0.2s 一次：驱动进度条 / 缓冲 / 断点续播存档
        timeObs = player.addPeriodicTimeObserver(
            forInterval: CMTime(seconds: 0.2, preferredTimescale: 600), queue: .main) { [weak self] t in
                guard let self else { return }
                let sec = t.seconds
                Task { @MainActor in self.tick(sec) }
            }

        endObs = NotificationCenter.default.addObserver(forName: .AVPlayerItemDidPlayToEndTime,
                                                       object: item, queue: .main) { [weak self] _ in
            guard let self else { return }
            Task { @MainActor in
                PositionStore.clear(key)
                self.wantsPlayback = false      // ⭐ 播完不是"卡住"
                self.recomputePhase()
                self.onEnded?()
            }
        }

        // ⭐ 真·卡顿通知（HLS 常见）
        stallObs = NotificationCenter.default.addObserver(forName: .AVPlayerItemPlaybackStalled,
                                                         object: item, queue: .main) { [weak self] _ in
            Task { @MainActor in self?.recomputePhase() }
        }

        // ⭐ 播放中断链失败：先尝试一次重载，而不是直接丢错误页
        failEndObs = NotificationCenter.default.addObserver(forName: .AVPlayerItemFailedToPlayToEndTime,
                                                           object: item, queue: .main) { [weak self] note in
            let msg = (note.userInfo?[AVPlayerItemFailedToPlayToEndTimeErrorKey] as? Error)?.localizedDescription
            Task { @MainActor in
                guard let self else { return }
                if self.recoveryAttempts < 2 {
                    await self.recoverNow(hard: true)
                } else {
                    self.fail(with: msg ?? T("播放中断", "Playback interrupted"))
                }
            }
        }

        recordPlayback(p, episode)
    }

    private func handleStatus(_ status: AVPlayerItem.Status, errorText: String?, episodeKey: String) {
        switch status {
        case .readyToPlay:
            loading = false
            if let d = player.currentItem?.duration.seconds, d.isFinite, d > 0 { duration = d }

            let saved = PositionStore.load(episodeKey)
            let startAt = pendingStart ?? (saved > 5 ? saved : 0)
            pendingStart = nil
            if startAt > 1 {
                player.seek(to: CMTime(seconds: startAt, preferredTimescale: 600))
                currentTime = startAt
            }
            resumePlayback()
        case .failed:
            fail(with: errorText ?? T("播放失败", "Playback failed"))
        default:
            recomputePhase()
        }
    }

    private func fail(with msg: String) {
        loading = false
        error = msg
        wantsPlayback = false
        stopWatchdog()
        recomputePhase()
    }

    private func tick(_ sec: Double) {
        guard sec.isFinite else { return }
        if !isScrubbing { currentTime = sec }
        if let item = player.currentItem {
            let d = item.duration.seconds
            if d.isFinite, d > 0, abs(d - duration) > 0.5 { duration = d }
            if let r = item.loadedTimeRanges.last?.timeRangeValue {
                let end = r.start.seconds + r.duration.seconds
                if end.isFinite { bufferedTime = end }
            }
        }
        if abs(sec - lastSavedAt) >= 5 {
            lastSavedAt = sec
            PositionStore.save(sec, episodeKey)
        }
        if let p = pip {
            let active = p.isPictureInPictureActive
            if active != isPiPActive { isPiPActive = active }
        }
        // 连续顺畅播放一段时间后，重置自愈计数
        if phase == .playing, recoveryAttempts > 0,
           Date().timeIntervalSince(lastRecoveryAt) > 20 {
            recoveryAttempts = 0
        }
    }

    private func recordPlayback(_ p: PlayPayload, _ ep: EpisodeItem) {
        let ident = AuthManager.shared.trackIdentity
        TrackingManager.shared.track(.play, userId: ident.id, userType: ident.type,
                                     videoURL: ep.url,
                                     videoTitle: "\(p.seriesTitle) · \(ep.name)",
                                     source: p.playSource)
        PlayRecordStore.shared.add(title: p.seriesTitle, episode: ep.name, url: ep.url,
                                   cover: p.cover, channel: p.channelName, source: p.sourceURL)
        SeriesTrackManager.shared.recordWatch(sourceURL: p.sourceURL, title: p.seriesTitle,
                                             cover: p.cover, episodeName: ep.name,
                                             channelName: p.channelName)
    }

    // MARK: - 播放控制
    func togglePlay() {
        if wantsPlayback { pausePlayback() } else { resumePlayback() }
    }

    private func resumePlayback() {
        guard error == nil else { return }
        wantsPlayback = true
        player.play()
        player.rate = SpeedStore.rate
        rate = SpeedStore.rate
        recomputePhase()
    }

    private func pausePlayback() {
        wantsPlayback = false
        player.pause()
        recomputePhase()
    }

    func setRate(_ r: Float) {
        SpeedStore.rate = r
        rate = r
        if wantsPlayback { player.rate = r }   // 卡顿中也保留目标速率
    }

    /// 相对跳转（±15 秒 / ±5 秒）
    func seek(by delta: Double) { seek(to: displayTime + delta) }

    func seek(to t: Double) {
        let upper = duration > 1 ? duration - 0.3 : max(t, 0)
        let clamped = min(max(0, t), upper)
        currentTime = clamped
        player.seek(to: CMTime(seconds: clamped, preferredTimescale: 600)) { [weak self] _ in
            Task { @MainActor in self?.recomputePhase() }
        }
        PositionStore.save(clamped, episodeKey)
        lastSavedAt = clamped
        recomputePhase()   // seek 引起的 waiting 会被识别为 buffering（按钮仍是暂停图标）
    }

    /// 拖动进度条时的实时预览（不真正 seek，拖完再跳）
    func previewScrub(_ t: Double) { isScrubbing = true; scrubTime = t }
    func endScrub(_ t: Double) {
        scrubTime = t
        seek(to: t)
        isScrubbing = false
    }

    func setVolume(_ v: Float) {
        let nv = min(max(v, 0), 1)
        volume = nv
        player.volume = nv
        VolumeStore.value = nv
        if nv > 0, isMuted { isMuted = false; player.isMuted = false }
    }
    func nudgeVolume(_ d: Float) { setVolume(volume + d) }
    func toggleMute() { isMuted.toggle(); player.isMuted = isMuted }

    // MARK: - ⭐ 状态机
    private func observeTimeControlStatus() {
        tcsObs = player.observe(\.timeControlStatus, options: [.new, .initial]) { [weak self] _, _ in
            Task { @MainActor in self?.recomputePhase() }
        }
        waitReasonObs = player.observe(\.reasonForWaitingToPlay, options: [.new]) { [weak self] _, _ in
            Task { @MainActor in self?.recomputePhase() }
        }
    }

    private func recomputePhase() {
        let newPhase: Phase
        if error != nil {
            newPhase = .failed
        } else if loading {
            newPhase = .loading
        } else {
            switch player.timeControlStatus {
            case .playing:
                newPhase = .playing
            case .waitingToPlayAtSpecifiedRate:
                // 想播 + 播不动 = 卡顿；不想播（极少见）视为暂停
                newPhase = wantsPlayback ? .buffering : .paused
            case .paused:
                // 想播却是 paused：本地文件 stall / 系统打断，同样算卡顿
                newPhase = wantsPlayback ? .buffering : .paused
            @unknown default:
                newPhase = wantsPlayback ? .buffering : .paused
            }
        }

        let cameFromLoading = (phase == .loading)

        if phase != newPhase { phase = newPhase }

        let playing = (newPhase == .playing)
        if isPlaying != playing { isPlaying = playing }

        let intent = wantsPlayback && newPhase != .failed
        if intendsToPlay != intent { intendsToPlay = intent }

        let buffering = (newPhase == .buffering)
        if isBuffering != buffering {
            isBuffering = buffering
            if buffering {
                // 从"加载中"直接转入缓冲 → 不去抖，避免转圈闪断
                startWatchdog(immediate: cameFromLoading)
            } else {
                stopWatchdog()
            }
        }

        updateSleepAssertion()
    }

    // MARK: - ⭐ 卡顿看门狗：转圈 → 提示 → 自愈 → 手动重试
    private func startWatchdog(immediate: Bool) {
        watchdog?.cancel()
        if immediate { showBusySpinner = true }
        watchdog = Task { @MainActor [weak self] in
            guard let self else { return }

            if !immediate {
                try? await Task.sleep(nanoseconds: self.spinnerDelay)
                guard !Task.isCancelled, self.isBuffering else { return }
                self.showBusySpinner = true
            }

            try? await Task.sleep(nanoseconds: self.slowHintDelay)
            guard !Task.isCancelled, self.isBuffering else { return }
            self.slowNetwork = true

            try? await Task.sleep(nanoseconds: self.autoRecoverDelay)
            guard !Task.isCancelled, self.isBuffering else { return }
            await self.recoverNow(hard: self.recoveryAttempts >= 1)

            try? await Task.sleep(nanoseconds: self.manualRetryDelay)
            guard !Task.isCancelled, self.isBuffering else { return }
            self.offerManualRetry = true
        }
    }

    private func stopWatchdog() {
        watchdog?.cancel(); watchdog = nil
        if showBusySpinner { showBusySpinner = false }
        if slowNetwork { slowNetwork = false }
        if offerManualRetry { offerManualRetry = false }
    }

    /// hard = true 时重新解析播放地址（应对直链过期），否则只做原地"踢一脚"
    private func recoverNow(hard: Bool) async {
        guard !isRecovering, let p = payload, let ep = current else { return }
        isRecovering = true
        recoveryAttempts += 1
        lastRecoveryAt = Date()
        let at = currentTime

        if hard && !isLocal {
            await load(payload: p, episode: ep, startAt: at, resetRecovery: false)
        } else {
            player.pause()
            player.seek(to: CMTime(seconds: at, preferredTimescale: 600)) { [weak self] _ in
                Task { @MainActor in self?.resumePlayback() }
            }
        }
        isRecovering = false
    }

    /// UI 上的"重新加载"
    func retryNow() {
        guard let p = payload, let ep = current else { return }
        let at = currentTime
        offerManualRetry = false
        Task { await load(payload: p, episode: ep, startAt: at, resetRecovery: true) }
    }

    // MARK: - 画中画
    func attach(surface: PlayerSurfaceView) {
        guard pip == nil, AVPictureInPictureController.isPictureInPictureSupported() else { return }
        pip = AVPictureInPictureController(playerLayer: surface.playerLayer)
        pipReady = true
    }
    func togglePiP() {
        guard let p = pip else { return }
        if p.isPictureInPictureActive { p.stopPictureInPicture() } else { p.startPictureInPicture() }
    }

    // MARK: - ⭐ 防休眠：跟随"意图"（缓冲中也不许睡）
    private func updateSleepAssertion() {
        let shouldHold = wantsPlayback && error == nil
        if shouldHold {
            if sleepToken == nil {
                sleepToken = ProcessInfo.processInfo.beginActivity(
                    options: [.userInitiated, .idleDisplaySleepDisabled, .idleSystemSleepDisabled],
                    reason: "OVideo playback")
            }
        } else {
            releaseSleepAssertion()
        }
    }

    private func releaseSleepAssertion() {
        if let t = sleepToken {
            ProcessInfo.processInfo.endActivity(t)
            sleepToken = nil
        }
    }

    // MARK: - 清理
    func stop() {
        wantsPlayback = false
        player.pause()
        if let p = pip, p.isPictureInPictureActive { p.stopPictureInPicture() }
        teardownItemObservers()
        stopWatchdog()
        releaseSleepAssertion()
        player.replaceCurrentItem(with: nil)
        pip = nil
        pipReady = false
        phase = .idle
        isPlaying = false; intendsToPlay = false; isBuffering = false
    }

    private func teardownItemObservers() {
        if let t = timeObs { player.removeTimeObserver(t); timeObs = nil }
        for o in [endObs, stallObs, failEndObs].compactMap({ $0 }) {
            NotificationCenter.default.removeObserver(o)
        }
        endObs = nil; stallObs = nil; failEndObs = nil
        statusObs?.invalidate(); statusObs = nil
        bufferEmptyObs?.invalidate(); bufferEmptyObs = nil
        keepUpObs?.invalidate(); keepUpObs = nil
    }
    // ⚠️ 不写 deinit：@MainActor 类的 deinit 访问隔离属性在 Swift 6 是错误；
    //    视图 onDisappear 调用 stop() 完成清理。
}

// MARK: - 自绘时间轴（悬停 / 拖动都显示具体时间）
struct TimelineSlider: View {
    let duration: Double
    let current: Double
    let buffered: Double
    var buffering: Bool = false          // ⭐ 卡顿时进度头做呼吸效果
    let onScrub: (Double) -> Void
    let onCommit: (Double) -> Void

    @State private var dragging = false
    @State private var dragValue: Double = 0
    @State private var hoverX: CGFloat?
    @State private var hoverTime: Double = 0
    @State private var pulse = false

    private let barHeight: CGFloat = 5

    var body: some View {
        GeometryReader { geo in
            let w = max(geo.size.width, 1)
            let usable = duration > 0
            let ratio = usable ? min(max((dragging ? dragValue : current) / duration, 0), 1) : 0
            let bufRatio = usable ? min(max(buffered / duration, 0), 1) : 0
            let active = dragging || hoverX != nil
            let knob: CGFloat = active ? 13 : 9

            ZStack(alignment: .leading) {
                Capsule().fill(Color.white.opacity(0.22)).frame(height: barHeight)
                Capsule().fill(Color.white.opacity(0.38))
                    .frame(width: w * CGFloat(bufRatio), height: barHeight)
                Capsule().fill(Color.accentColor)
                    .frame(width: w * CGFloat(ratio), height: barHeight)
                Circle().fill(Color.white)
                    .frame(width: knob, height: knob)
                    .shadow(radius: 2)
                    .opacity(buffering && !dragging ? (pulse ? 0.35 : 1) : 1)
                    .offset(x: w * CGFloat(ratio) - knob / 2)
            }
            .frame(height: 22)
            .contentShape(Rectangle())
            .onContinuousHover(coordinateSpace: .local) { phase in
                guard usable else { return }
                switch phase {
                case .active(let p):
                    let x = min(max(0, p.x), w)
                    hoverX = x
                    hoverTime = duration * Double(x / w)
                case .ended:
                    if !dragging { hoverX = nil }
                }
            }
            .gesture(
                DragGesture(minimumDistance: 0)
                    .onChanged { v in
                        guard usable else { return }
                        dragging = true
                        let x = min(max(0, v.location.x), w)
                        dragValue = duration * Double(x / w)
                        hoverX = x; hoverTime = dragValue
                        onScrub(dragValue)
                    }
                    .onEnded { v in
                        guard usable else { return }
                        let x = min(max(0, v.location.x), w)
                        dragging = false
                        onCommit(duration * Double(x / w))
                    }
            )
            .overlay(alignment: .topLeading) { tooltip(width: w) }
            .animation(.easeOut(duration: 0.12), value: active)
        }
        .frame(height: 22)
        .onAppear {
            withAnimation(.easeInOut(duration: 0.7).repeatForever(autoreverses: true)) { pulse = true }
        }
    }

    @ViewBuilder private func tooltip(width: CGFloat) -> some View {
        if let x = hoverX, duration > 0 {
            Text(gwTimeString(dragging ? dragValue : hoverTime))
                .font(.system(size: 11, weight: .semibold).monospacedDigit())
                .foregroundStyle(.white)
                .padding(.horizontal, 7).padding(.vertical, 3)
                .background(.black.opacity(0.82), in: RoundedRectangle(cornerRadius: 5))
                .overlay(RoundedRectangle(cornerRadius: 5).stroke(.white.opacity(0.15)))
                .fixedSize()
                .offset(x: min(max(x - 27, 0), max(width - 54, 0)), y: -28)
                .allowsHitTesting(false)
                .transition(.opacity)
        }
    }
}

// MARK: - 播放窗口
struct PlayerWindowView: View {
    let payload: PlayPayload
    @StateObject private var model = PlayerModel()
    @EnvironmentObject var auth: AuthManager
    @EnvironmentObject var lang: LanguageManager
    @ObservedObject private var quota = QuotaManager.shared
    @AppStorage("GW_AutoNext") private var autoNext = true

    @State private var showEpisodes = false
    @State private var showReport = false
    @State private var pendingEp: EpisodeItem?
    @State private var showConsume = false
    @State private var showSubscribe = false

    @State private var controlsVisible = true
    @State private var hideTask: Task<Void, Never>?
    @State private var window: NSWindow?
    @State private var isFullScreen = false

    @FocusState private var isPlayPauseFocused: Bool

    private var modalUp: Bool { showReport || showSubscribe || showConsume }
    private var currentIndex: Int {
        payload.episodes.firstIndex(where: { $0.url == model.current?.url }) ?? 0
    }
    /// 卡顿 / 暂停 / 加载时控制栏常驻
    private var barVisible: Bool {
        controlsVisible || !model.isPlaying || model.loading || model.isBuffering
    }
    private var busyVisible: Bool {
        model.error == nil && (model.loading || model.showBusySpinner)
    }

    var body: some View {
        ZStack {
            Color.black.ignoresSafeArea()

            PlayerSurface(player: model.player) { v in model.attach(surface: v) }
                .ignoresSafeArea()

            // 透明层：hover 唤出控制条 + 单击暂停 / 双击全屏
            Color.clear
                .contentShape(Rectangle())
                .onContinuousHover { phase in
                    if case .active = phase { bumpControls() }
                }
                .onTapGesture(count: 2) { toggleFullScreen() }
                .onTapGesture(count: 1) { model.togglePlay() }

            // ⭐ 统一的"忙碌"遮罩：首次加载 + 卡顿缓冲
            if busyVisible {
                busyOverlay
                    .transition(.opacity)
                    .animation(.easeInOut(duration: 0.2), value: busyVisible)
            }

            if let e = model.error { errorOverlay(e) }

            VStack(spacing: 0) {
                Spacer()
                controlBar
            }
            .opacity(barVisible ? 1 : 0)
            .allowsHitTesting(barVisible)
            .animation(.easeInOut(duration: 0.22), value: barVisible)

            extraShortcuts
        }
        .frame(minWidth: 720, minHeight: 420)
        .background(WindowAccessor { w in if window !== w { window = w } })
        .navigationTitle(isFullScreen ? "" : "\(payload.seriesTitle) · \(model.current?.name ?? payload.episodeName)")
        .toolbar(isFullScreen ? .hidden : .visible)
        .toolbar {
            ToolbarItemGroup {
                if payload.episodes.count > 1 {
                    Button { showEpisodes = true } label: {
                        Label(lang.t("选集", "Episodes"), systemImage: "list.bullet")
                    }
                    .popover(isPresented: $showEpisodes) { episodePopover }
                }
                if model.isLocal {
                    Label(lang.t("离线", "Offline"), systemImage: "arrow.down.circle.fill")
                        .foregroundStyle(.green)
                }
                Button { showReport = true } label: {
                    Label(lang.t("反馈修复", "Report"), systemImage: "wrench.and.screwdriver")
                }
            }
        }
        .task {
            let ep = payload.episodes.first(where: { $0.url == payload.episodeKey })
                ?? EpisodeItem(number: "1", name: payload.episodeName, url: payload.episodeKey)
            model.onEnded = { if autoNext { jump(1) } }

            if HLSDownloadManager.shared.localURL(forEpisodeKey: ep.url) != nil {
                await model.load(payload: payload, episode: ep)
            } else {
                select(ep)
            }

            DispatchQueue.main.asyncAfter(deadline: .now() + 0.15) {
                isPlayPauseFocused = true
            }
        }
        .onDisappear {
            hideTask?.cancel()
            model.stop()
        }
        .onReceive(NotificationCenter.default.publisher(for: NSWindow.didEnterFullScreenNotification)) { n in
            if (n.object as? NSWindow) === window { isFullScreen = true }
        }
        .onReceive(NotificationCenter.default.publisher(for: NSWindow.didExitFullScreenNotification)) { n in
            if (n.object as? NSWindow) === window { isFullScreen = false }
        }
        .onChangeCompat(of: model.isPlaying) { playing in
            if playing { bumpControls() } else { controlsVisible = true; hideTask?.cancel() }
        }
        .onChangeCompat(of: model.isBuffering) { buffering in
            // 卡顿时把光标和控制栏找回来，别让用户以为死机
            if buffering {
                controlsVisible = true
                hideTask?.cancel()
                NSCursor.setHiddenUntilMouseMoves(false)
            }
        }
        .sheet(isPresented: $showReport) {
            ReportSheet(title: "\(payload.seriesTitle) · \(model.current?.name ?? "")",
                        sourceURL: payload.sourceURL ?? payload.episodeKey,
                        episodeURL: model.current?.url ?? payload.episodeKey,
                        channel: payload.channelName, episode: model.current?.name,
                        realURL: nil)
        }
        .sheet(isPresented: $showSubscribe) { SubscriptionView() }
        .alert(lang.t("使用免费点数", "Use 1 Free Pass"), isPresented: $showConsume) {
            Button(lang.t("取消", "Cancel"), role: .cancel) { pendingEp = nil }
            Button(lang.t("确认使用", "Confirm")) { Task { await consumeAndPlay() } }
        } message: {
            Text(quota.consumeNote(lang.isEnglish) + "\n" + quota.remainingSummary(lang.isEnglish))
        }
    }

    // MARK: ⭐ 忙碌 / 卡顿遮罩
    private var busyOverlay: some View {
        VStack(spacing: 12) {
            ProgressView()
                .progressViewStyle(.circular)
                .controlSize(.large)
                .tint(.white)

            Text(busyText)
                .font(.system(size: 12, weight: .medium))
                .foregroundStyle(.white.opacity(0.9))
                .multilineTextAlignment(.center)
                .frame(maxWidth: 260)

            if model.offerManualRetry {
                HStack(spacing: 10) {
                    Button(lang.t("重新加载", "Reload")) { model.retryNow() }
                        .buttonStyle(.borderedProminent)
                    Button(lang.t("反馈修复", "Report")) { showReport = true }
                        .buttonStyle(.bordered)
                }
                .controlSize(.small)
            }
        }
        .padding(.horizontal, 24)
        .padding(.vertical, 20)
        .background(.black.opacity(0.55), in: RoundedRectangle(cornerRadius: 14))
        .overlay(RoundedRectangle(cornerRadius: 14).stroke(.white.opacity(0.08)))
        // ⭐ 只有出现按钮时才吃点击，否则不挡"单击暂停 / 双击全屏"
        .allowsHitTesting(model.offerManualRetry)
        .accessibilityLabel(busyText)
    }

    private var busyText: String {
        if model.loading { return lang.t("正在加载…", "Loading…") }
        if model.offerManualRetry {
            return lang.t("加载一直没完成，可以重新加载或换个线路",
                          "Still not loading. Try reloading or another source.")
        }
        if model.slowNetwork {
            return lang.t("网络似乎不太稳定，正在缓冲…", "Network seems unstable, buffering…")
        }
        return lang.t("缓冲中…", "Buffering…")
    }

    // MARK: 错误层
    private func errorOverlay(_ e: String) -> some View {
        VStack(spacing: 14) {
            Image(systemName: "exclamationmark.triangle")
                .font(.system(size: 40)).foregroundStyle(.orange)
            Text(e).foregroundStyle(.white)
                .multilineTextAlignment(.center).frame(maxWidth: 420)
            HStack {
                Button(lang.t("重试", "Retry")) {
                    if let c = model.current {
                        Task { await model.load(payload: payload, episode: c) }
                    }
                }
                Button(lang.t("反馈修复", "Report")) { showReport = true }
            }
        }
        .padding(24)
        .background(.black.opacity(0.6), in: RoundedRectangle(cornerRadius: 16))
    }

    // MARK: 控制条
    private var controlBar: some View {
        VStack(spacing: 4) {
            TimelineSlider(duration: model.duration,
                           current: model.displayTime,
                           buffered: model.bufferedTime,
                           buffering: model.isBuffering,
                           onScrub: { model.previewScrub($0) },
                           onCommit: { model.endScrub($0) })

            HStack(spacing: 14) {
                Text(gwTimeString(model.displayTime))
                    .font(.system(size: 11).monospacedDigit())
                Text("/").font(.system(size: 11)).foregroundStyle(.white.opacity(0.5))
                Text(gwTimeString(model.duration))
                    .font(.system(size: 11).monospacedDigit())
                    .foregroundStyle(.white.opacity(0.75))

                // ⭐ 控制栏内的小转圈 + 文案（全屏也能一眼看出在缓冲）
                if model.isBuffering {
                    HStack(spacing: 5) {
                        ProgressView()
                            .progressViewStyle(.circular)
                            .controlSize(.small)
                            .tint(.white)
                            .scaleEffect(0.7)
                            .frame(width: 14, height: 14)
                        Text(lang.t("缓冲中", "Buffering"))
                            .font(.system(size: 10, weight: .medium))
                            .foregroundStyle(.white.opacity(0.75))
                    }
                    .transition(.opacity)
                }

                Spacer(minLength: 8)

                if payload.episodes.count > 1 {
                    ctrl("backward.end.fill", size: 13,
                         help: lang.t("上一集 (⌘[)", "Previous episode (⌘[)")) { jump(-1) }
                        .disabled(currentIndex <= 0)
                        .keyboardShortcut("[", modifiers: .command)
                        .focusable(false)
                }

                ctrl("gobackward.15", size: 19,
                     help: lang.t("后退 15 秒 (J)", "Back 15s (J)")) { model.seek(by: -15) }
                    .focusable(false)

                // ⭐ 图标由「意图」决定：卡顿中依然显示暂停符号
                ctrl(model.intendsToPlay ? "pause.fill" : "play.fill", size: 22,
                     help: lang.t("播放 / 暂停 (空格)", "Play / Pause (Space)")) { model.togglePlay() }
                    .keyboardShortcut(.space, modifiers: [])
                    .focused($isPlayPauseFocused)
                    .accessibilityLabel(model.intendsToPlay
                                        ? lang.t("暂停", "Pause")
                                        : lang.t("播放", "Play"))

                ctrl("goforward.15", size: 19,
                     help: lang.t("前进 15 秒 (L/D)", "Forward 15s (L/D)")) { model.seek(by: 15) }
                    .focusable(false)

                if payload.episodes.count > 1 {
                    ctrl("forward.end.fill", size: 13,
                         help: lang.t("下一集 (⌘])", "Next episode (⌘])")) { jump(1) }
                        .disabled(currentIndex >= payload.episodes.count - 1)
                        .keyboardShortcut("]", modifiers: .command)
                        .focusable(false)
                }

                Spacer(minLength: 8)

                volumeControl
                speedMenu

                if payload.episodes.count > 1 {
                    ctrl("list.bullet", size: 14,
                         help: lang.t("选集", "Episodes")) { showEpisodes = true }
                        .popover(isPresented: $showEpisodes) { episodePopover }
                        .focusable(false)
                }
                if model.pipReady {
                    ctrl(model.isPiPActive ? "pip.exit" : "pip.enter", size: 14,
                         help: lang.t("画中画", "Picture in Picture")) { model.togglePiP() }
                        .focusable(false)
                }
                ctrl(isFullScreen ? "arrow.down.right.and.arrow.up.left"
                                  : "arrow.up.left.and.arrow.down.right",
                     size: 14,
                     help: lang.t("全屏 (F)", "Full screen (F)")) { toggleFullScreen() }
                    .keyboardShortcut("f", modifiers: [])
                    .focusable(false)
            }
            .frame(height: 34)
            .animation(.easeInOut(duration: 0.18), value: model.isBuffering)
        }
        .padding(.horizontal, 18)
        .padding(.top, 8)
        .padding(.bottom, 12)
        .foregroundStyle(.white)
        .background(
            LinearGradient(colors: [.clear, .black.opacity(0.28), .black.opacity(0.8)],
                           startPoint: .top, endPoint: .bottom)
        )
        .onContinuousHover { phase in
            if case .active = phase { controlsVisible = true; hideTask?.cancel() }
            else { bumpControls() }
        }
    }

    private func ctrl(_ icon: String, size: CGFloat, help: String,
                      action: @escaping () -> Void) -> some View {
        Button(action: action) {
            Image(systemName: icon)
                .font(.system(size: size, weight: .medium))
                .frame(width: max(size + 10, 26), height: 26)
                .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .help(help)
    }

    private var volumeControl: some View {
        HStack(spacing: 5) {
            Button {
                model.toggleMute()
            } label: {
                Image(systemName: model.isMuted || model.volume == 0 ? "speaker.slash.fill"
                      : (model.volume < 0.45 ? "speaker.wave.1.fill" : "speaker.wave.2.fill"))
                    .font(.system(size: 12))
                    .frame(width: 20, height: 22)
                    .contentShape(Rectangle())
            }
            .buttonStyle(.plain)
