        sym = None
        mgr = self.symbol_manager
        if mgr.symbols and 0 <= mgr.current_index < len(mgr.symbols):
            sym = mgr.symbols[mgr.current_index]
        if not sym:
            QMessageBox.information(self, "提示", "请先点一下某个股票卡片，或用右键菜单添加")
