    def _add_to_watchlist(self, group=None):
        if not FT_WL_ADD_OK:
            display_dialog("未找到 ft_watchlist_add.py，无法使用「一键加自选」")
            return
        sym = self.name
        if not sym:
            return
        if not group:
            group = choose_group_dialog(sym, watchlist_groups())
            if not group:
                self._show_wl_status("已取消", NORD_THEME['text_light'], ttl=1.5)
