    // 【修改】PriceData - 移除 id 依赖，改用 date 作为 Identifiable
    struct PriceData: Identifiable, Codable {
        // 【关键修改】使用 date 的 timeIntervalSince1970 作为 id
        var id: Double { date.timeIntervalSince1970 }

        let date: Date
        let price: Double
        let volume: Int64?

        // 【新增】支持新数据库的 OHLC 字段
        let open: Double?
        let high: Double?
        let low: Double?

        enum CodingKeys: String, CodingKey {
            case date, price, volume, open, high, low
        }

        // 【修改】手动初始化器 - 移除 id 参数
        init(date: Date, price: Double, volume: Int64?, open: Double? = nil, high: Double? = nil, low: Double? = nil) {
            self.date = date
            self.price = price
            self.volume = volume
            self.open = open
            self.high = high
            self.low = low
        }

        init(from decoder: Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            price = try container.decode(Double.self, forKey: .price)
            volume = try container.decodeIfPresent(Int64.self, forKey: .volume)

            // 【新增】解码 OHLC 字段
            open = try container.decodeIfPresent(Double.self, forKey: .open)
            high = try container.decodeIfPresent(Double.self, forKey: .high)
            low = try container.decodeIfPresent(Double.self, forKey: .low)

            let dateString = try container.decode(String.self, forKey: .date)
            let formatter = DateFormatter()
            formatter.dateFormat = "yyyy-MM-dd"
            if let date = formatter.date(from: dateString) {
                self.date = date
            } else {
                self.date = Date.distantPast // Fallback
            }
        }
    }

    // MARK: - Models (追加新的模型)
    struct OptionHistoryItem: Codable, Identifiable {
        let id = UUID() //以此符合 Identifiable
        let date: Date
        let price: Double
        // 【新增】存储处理后的 IV 数值
        let iv: Double 

        enum CodingKeys: String, CodingKey {
            case date, price, iv
        }

        // 手动初始化器（用于本地数据库读取）
        init(date: Date, price: Double, ivString: String?) {
            self.date = date
            self.price = price
            if let ivStr = ivString {
                let cleanIv = ivStr.replacingOccurrences(of: "%", with: "")
                let val = Double(cleanIv) ?? 0.0
                self.iv = val * 100
            } else {
                self.iv = 0.0
            }
        }

        init(from decoder: Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            price = try container.decode(Double.self, forKey: .price)

            // 【新增】解析 IV 字符串并进行数学转换
            // 逻辑：Server 返回 "50.2%", 去掉 "%" -> 50.2, * 100 -> 5020.0
            if let ivString = try? container.decode(String.self, forKey: .iv) {
                let cleanIv = ivString.replacingOccurrences(of: "%", with: "")
                let val = Double(cleanIv) ?? 0.0
                self.iv = val * 100 
            } else {
                self.iv = 0.0
            }

            let dateString = try container.decode(String.self, forKey: .date)
            let formatter = DateFormatter()
            formatter.dateFormat = "yyyy-MM-dd"
            // 容错处理
            if let date = formatter.date(from: dateString) {
                self.date = date
            } else {
                self.date = Date.distantPast
            }
        }
    }

