                if s.contains("抄底") {
                    symbolsWithChaodi.insert(s.cleanTicker.uppercased())
                }
            }

            // 3. 清洗 Symbol 并去重
            let cleanSymbols = Set(symbols.map { $0.cleanTicker.uppercased() })

            // 4. 记录该 Symbol 所在的分组
            for sym in cleanSymbols {
                symbolGroups[sym, default: []].insert(group)
            }
