// MARK: - 【新增】5列数据显示组件 (Latest IV | Prev IV | Compare | Prev Price | Latest Price)
struct PriceFiveColumnView: View {
    let symbol: String

    // 1. Latest IV (大)
    let latestIv: String?
    // 2. Prev IV (小)
    let prevIv: String?

    // 4. Prev Price (小)
    let prevPrice: Double?
    // 5. Latest Price (大)
    let latestPrice: Double?
    let latestChange: Double? // 用于判断颜色

    @EnvironmentObject var dataService: DataService

    var body: some View {
        HStack(spacing: 6) { // 稍微紧凑一点的间距

            // 1. Latest IV (大字体)
            Text(latestIv ?? "--")
                .font(.system(size: 16, weight: .bold, design: .monospaced))
                .foregroundColor(getIvColor(latestIv)) 
                .fixedSize()

            // 2. Previous IV (小字体)
            Text(prevIv ?? "--")
                .font(.system(size: 12, design: .monospaced)) // 正常/偏小
                .foregroundColor(.secondary)
                .fixedSize()

            // 3. CompareStr (涨跌百分比)
            if let compareStr = dataService.compareDataUppercased[symbol.uppercased()] {
                let rawPercentage = extractPercentage(from: compareStr)
                let formattedPercentage = formatToPrecision(rawPercentage, precision: 1)
                let themeColor = getCompareColor(from: rawPercentage)

                Text(formattedPercentage)
                    .font(.system(size: 12, design: .monospaced))
                    .foregroundColor(themeColor)
                    .padding(.horizontal, 2)
                    .background(themeColor.opacity(0.1))
                    .cornerRadius(4)
                    .fixedSize()
            }

            // 4. Previous Price (小字体)
            if let pPrice = prevPrice {
                Text(String(format: "%.2f", pPrice))
                    .font(.system(size: 12, design: .monospaced)) // 正常/偏小
                    .foregroundColor(.gray)
                    .fixedSize()
            } else {
                Text("--")
                    .font(.system(size: 12))
                    .foregroundColor(.gray)
            }

            // 5. Latest Price (大字体)
            if let lPrice = latestPrice {
                Text(String(format: "%.2f", lPrice))
                    .font(.system(size: 16, weight: .bold, design: .monospaced))
                    .foregroundColor(lPrice >= 0 ? .red : .green)
                    .fixedSize()
            } else {
                Text("--")
                    .font(.system(size: 16, weight: .bold))
                    .foregroundColor(.secondary)
            }
        }
    }

    // 辅助函数
    private func extractPercentage(from text: String) -> String {
        let pattern = "([+-]?\\d+(\\.\\d+)?%)"
        if let range = text.range(of: pattern, options: .regularExpression) {
            return String(text[range])
        }
        return text
    }

    private func getIvColor(_ text: String?) -> Color {
        guard let text = text else { return .secondary }
        let cleanText = text.replacingOccurrences(of: "%", with: "")
        if let value = Double(cleanText) {
            return value >= 0 ? .red : .green
        }
        return .red
    }

    private func formatToPrecision(_ text: String, precision: Int) -> String {
        let cleanText = text.replacingOccurrences(of: "%", with: "")
        if let value = Double(cleanText) {
            return String(format: "%+.\(precision)f%%", value)
        }
        return text
    }

    private func getCompareColor(from text: String) -> Color {
        if text.contains("-") { return .green }
        return .red
    }
}

// MARK: - 【修改后】Strike vs Price 分布图组件 (优化X轴空间)
struct OptionsStrikePriceChartView: View {
    let allItems: [OptionItem]
    let latestStockPrice: Double? // 【新增】接收最新标的价格

    @State private var selectedExpiry: String = ""
    @State private var selectedType: ChartType = .all

    enum ChartType: String, CaseIterable, Identifiable {
        case all = "All"
        case call = "Call"
        case put = "Put"
        case cp = "CP" // 【新增】CP 模式
        var id: String { self.rawValue }
    }

    struct ChartDataPoint: Identifiable {
        let id = UUID()
        let strike: Double
        let price: Double
        let type: String // "Call", "Put", "Total"
    }

    var uniqueExpiries: [String] {
        let expiries = Set(allItems.map { $0.expiryDate })
        return expiries.sorted()
    }

    // 【修改】计算图表数据 - 新增动态阈值过滤
    var chartData: [ChartDataPoint] {
        let targetExpiry = selectedExpiry.isEmpty ? (uniqueExpiries.first ?? "") : selectedExpiry

        // 1. 获取该日期下所有有效的基础数据点 (Call 和 Put)
        let basePoints = allItems.filter { $0.expiryDate == targetExpiry }
            .compactMap { item -> (strike: Double, price: Double, type: String)? in
                let cleanStrike = item.strike.replacingOccurrences(of: ",", with: "")
                guard let strikeVal = Double(cleanStrike) else { return nil }

                let cleanPrice = item.price.replacingOccurrences(of: ",", with: "")
                guard let priceVal = Double(cleanPrice) else { return nil }

                // 保留 Price > 0 的数据用于计算最大值
                if priceVal <= 0 { return nil }

                let type = (item.type.uppercased().contains("CALL") || item.type.uppercased() == "C") ? "Call" : "Put"
                return (strikeVal, priceVal, type)
            }

        // 2. 计算 Total 数据 (Call + Put)
        // 按 strike 分组
        let groupedByStrike = Dictionary(grouping: basePoints, by: { $0.strike })
        let totalPoints = groupedByStrike.map { (strike, points) in
            let sum = points.reduce(0) { $0 + $1.price }
            return ChartDataPoint(strike: strike, price: sum, type: "Total")
        }

        // 3. 根据选中的 Picker 类型组装最终显示的数据
        var finalPoints: [ChartDataPoint] = []

        switch selectedType {
        case .all:
            // 显示红、绿、蓝三条线
            finalPoints.append(contentsOf: basePoints.map { ChartDataPoint(strike: $0.strike, price: $0.price, type: $0.type) })
            finalPoints.append(contentsOf: totalPoints)
        case .call:
            // 只显示红线
            finalPoints.append(contentsOf: basePoints.filter { $0.type == "Call" }.map { ChartDataPoint(strike: $0.strike, price: $0.price, type: $0.type) })
        case .put:
            // 只显示绿线
            finalPoints.append(contentsOf: basePoints.filter { $0.type == "Put" }.map { ChartDataPoint(strike: $0.strike, price: $0.price, type: $0.type) })
        case .cp:
            // 只显示蓝线 (Call + Put)
            finalPoints.append(contentsOf: totalPoints)
        }

        // 4. 应用价格阈值过滤 (防止极小值干扰)
        let maxPrice = basePoints.map { $0.price }.max() ?? 0
        let threshold = maxPrice * 0.05

        return finalPoints
            .filter { $0.price >= threshold }
            .sorted { $0.strike < $1.strike }
    }

    // 【新增】计算 Y 轴最大值，用于锁定 Scale
    var yAxisMax: Double {
        let maxVal = chartData.map { $0.price }.max() ?? 10
        return maxVal * 1.1 // 留出 10% 的顶部空间
    }

    var allStrikes: [Double] {
        let strikes = Set(chartData.map { $0.strike })
        return strikes.sorted()
    }

    // 计算 X 轴的显示范围
    var xDomain: ClosedRange<Double> {
        let strikes = chartData.map { $0.strike }
        guard let min = strikes.min(), let max = strikes.max() else { return 0...100 }
        return min == max ? (min - 1)...(max + 1) : min...max
    }

    // 【新增】计算 Call+Put (Total) 所有点的价格加权平均 Strike
    // 公式：Σ(strike_i × totalPrice_i) / Σ(totalPrice_i)
    // 代表期权活动在 Strike 轴上的"重心"位置
    var weightedAverageStrike: Double? {
        let targetExpiry = selectedExpiry.isEmpty ? (uniqueExpiries.first ?? "") : selectedExpiry

        // 获取基础数据点 (与 chartData 逻辑一致)
        let basePoints = allItems.filter { $0.expiryDate == targetExpiry }
            .compactMap { item -> (strike: Double, price: Double)? in
                let cleanStrike = item.strike.replacingOccurrences(of: ",", with: "")
                guard let strikeVal = Double(cleanStrike) else { return nil }
                let cleanPrice = item.price.replacingOccurrences(of: ",", with: "")
                guard let priceVal = Double(cleanPrice), priceVal > 0 else { return nil }
                return (strikeVal, priceVal)
            }

        // 按 Strike 分组，计算 Call+Put 合计
        let groupedByStrike = Dictionary(grouping: basePoints, by: { $0.strike })
        let totalPoints = groupedByStrike.map { (strike, points) -> (strike: Double, totalPrice: Double) in
            let sum = points.reduce(0.0) { $0 + $1.price }
            return (strike, sum)
        }

        guard !totalPoints.isEmpty else { return nil }

        // 应用与 chartData 相同的阈值过滤
        let maxPrice = totalPoints.map { $0.totalPrice }.max() ?? 0
        let threshold = maxPrice * 0.05
        let filteredTotal = totalPoints.filter { $0.totalPrice >= threshold }
        guard !filteredTotal.isEmpty else { return nil }

        // 计算加权平均 Strike
        let totalWeight = filteredTotal.reduce(0.0) { $0 + $1.totalPrice }
        guard totalWeight > 0 else { return nil }
        let weightedSum = filteredTotal.reduce(0.0) { $0 + $1.strike * $1.totalPrice }

        return weightedSum / totalWeight
    }

    var body: some View {
        VStack(spacing: 8) {
            // 顶部控制栏
            HStack {
                Text("Strike vs Price")
                    .font(.caption2)
                    .fontWeight(.bold)
                    .foregroundColor(.secondary)

                Spacer()

                // 这里的 Picker 会自动包含 CP 选项
                Picker("Type", selection: $selectedType) {
                    ForEach(ChartType.allCases) { type in
                        Text(type.rawValue).tag(type)
                    }
                }
                .pickerStyle(.segmented)
                .fixedSize()
                .scaleEffect(0.8)

                Spacer()

                // 日期选择
                Menu {
                    ForEach(uniqueExpiries, id: \.self) { expiry in
                        Button(expiry) {
                            selectedExpiry = expiry
                        }
                    }
                } label: {
                    HStack(spacing: 2) {
                        Text(selectedExpiry.isEmpty ? (uniqueExpiries.first ?? "Select Date") : selectedExpiry)
                            .font(.caption)
                            .fontWeight(.medium)
                        Image(systemName: "chevron.down")
                            .font(.caption2)
                    }
                    .padding(.horizontal, 8)
                    .padding(.vertical, 4)
                    .background(Color.blue.opacity(0.1))
                    .cornerRadius(6)
                }
            }
            .padding(.horizontal, 8)
            .padding(.top, 8)
            .zIndex(1)

            // 图表区域
            if chartData.isEmpty {
                Spacer()
                Text("该筛选条件下无数据")
                    .font(.caption)
                    .foregroundColor(.secondary)
                Spacer()
            } else {
                Chart {
                    // 1. 绘制期权分布曲线
                    ForEach(chartData) { point in
                        LineMark(
                            x: .value("Strike", point.strike),
                            y: .value("Price", point.price)
                        )
                        .foregroundStyle(by: .value("Type", point.type))
                        .interpolationMethod(.catmullRom)
                        // 如果是 Total 线，可以稍微加粗一点
                        .lineStyle(StrokeStyle(lineWidth: point.type == "Total" ? 3 : 2))

                        PointMark(
                            x: .value("Strike", point.strike),
                            y: .value("Price", point.price)
                        )
                        .foregroundStyle(by: .value("Type", point.type))
                        .symbolSize(point.type == "Total" ? 20 : 30)
                    }

                    // 2. 【新增】Call+Put 加权平均 Strike 竖直虚线 (蓝色)
                    if let avgStrike = weightedAverageStrike {
                        RuleMark(x: .value("Avg Strike", avgStrike))
                            .lineStyle(StrokeStyle(lineWidth: 1.5, dash: [5]))
                            .foregroundStyle(.blue.opacity(0.6))
                            .annotation(position: .bottom, alignment: .center) {
                                Text(String(format: "Avg:%.1f", avgStrike))
                                    .font(.system(size: 9, weight: .bold, design: .monospaced))
                                    .foregroundColor(.white)
                                    .padding(.horizontal, 4).padding(.vertical, 2)
                                    .background(Color.blue.opacity(0.8)).cornerRadius(4)
                            }
                    }

                    // 3. 【修改】最新标的价格垂直虚线 (蓝色 → 紫色)
                    if let currentPrice = latestStockPrice {
                        RuleMark(x: .value("Current Price", currentPrice))
                            .lineStyle(StrokeStyle(lineWidth: 1.5, dash: [5]))
                            .foregroundStyle(.purple.opacity(0.6))
                            .annotation(position: .top, alignment: .center) {
                                Text(String(format: "%.2f", currentPrice))
                                    .font(.system(size: 10, weight: .bold, design: .monospaced))
                                    .foregroundColor(.white)
                                    .padding(.horizontal, 4).padding(.vertical, 2)
                                    .background(Color.purple.opacity(0.8)).cornerRadius(4)
                            }
                    }
                }
                // 【关键修改】添加 Total 对应的蓝色映射
                .chartForegroundStyleScale([
                    "Call": .red,
                    "Put": .green,
                    "Total": .blue
                ])
                // 【关键修改】设置 X 轴范围，强制撑满
                .chartXScale(domain: xDomain)
                // 【修复点 2】强制 Y 轴从 0 开始，绝不显示负数
                .chartYScale(domain: 0...yAxisMax)
                .chartXAxis {
                    // 每一个 Strike 都显示出来
                    AxisMarks(values: allStrikes) { value in
                        AxisGridLine()
                        AxisTick()
                        AxisValueLabel(orientation: .vertical) {
                            if let strikeValue = value.as(Double.self) {
                                let label = strikeValue.truncatingRemainder(dividingBy: 1) == 0 
                                    ? String(format: "%.0f", strikeValue) 
                                    : String(format: "%.1f", strikeValue)
                                Text(label)
                                    .font(.system(size: 10, design: .monospaced))
                            }
                        }
                    }
                }
                .chartYAxis {
                    AxisMarks { _ in
                        AxisGridLine()
                        AxisValueLabel()
                    }
                }
                .padding(.horizontal, 8)
                .padding(.bottom, 8)
            }
        }
        .onAppear {
            if selectedExpiry.isEmpty, let first = uniqueExpiries.first {
                selectedExpiry = first
            }
        }
    }
}

// MARK: - 【新增】3列数据显示组件
struct PriceThreeColumnView: View {
    let symbol: String
    let latestIv: String?
    let prevIv: String?

    @EnvironmentObject var dataService: DataService

    var body: some View {
        HStack(spacing: 6) {
            Text(latestIv ?? "--")
                .font(.system(size: 16, weight: .bold, design: .monospaced))
                .foregroundColor(getIvColor(latestIv))
                .fixedSize()

            Text(prevIv ?? "--")
                .font(.system(size: 12, design: .monospaced))
                .foregroundColor(.secondary)
                .fixedSize()

            if let compareStr = dataService.compareDataUppercased[symbol.uppercased()] {
                let rawPercentage = extractPercentage(from: compareStr)
                let formattedPercentage = formatToPrecision(rawPercentage, precision: 1)
                let themeColor = getCompareColor(from: rawPercentage)

                Text(formattedPercentage)
                    .font(.system(size: 12, design: .monospaced))
                    .foregroundColor(themeColor)
                    .padding(.horizontal, 2)
                    .background(themeColor.opacity(0.1))
                    .cornerRadius(4)
                    .fixedSize()
            }
        }
    }

    private func extractPercentage(from text: String) -> String {
        let pattern = "([+-]?\\d+(\\.\\d+)?%)"
        if let range = text.range(of: pattern, options: .regularExpression) {
            return String(text[range])
        }
        return text
    }

    private func getIvColor(_ text: String?) -> Color {
        guard let text = text else { return .secondary }
        let cleanText = text.replacingOccurrences(of: "%", with: "")
        if let value = Double(cleanText) {
            return value >= 0 ? .red : .green
        }
        return .red
    }

    private func formatToPrecision(_ text: String, precision: Int) -> String {
        let cleanText = text.replacingOccurrences(of: "%", with: "")
        if let value = Double(cleanText) {
            return String(format: "%+.\(precision)f%%", value)
        }
        return text
    }

    private func getCompareColor(from text: String) -> Color {
        if text.contains("-") { return .green }
        return .red
    }
}

// MARK: - 【重构】期权价格历史图表组件
struct OptionsHistoryChartView: View {
    let symbol: String
    let currentOptions: [OptionItem] 
    let latestStockPrice: Double? // 【新增】

    @State private var historyData: [DatabaseManager.OptionHistoryItem] = []
    @State private var selectedTimeRange: TimeRangeOption = .oneMonth
    @State private var isLoading = false
    @State private var currentPage = 0 

    enum TimeRangeOption: String, CaseIterable, Identifiable {
        case oneMonth = "1M"
        case threeMonths = "3M"
        case oneYear = "1Y"
        case tenYears = "10Y"

        var id: String { self.rawValue }

        var monthsBack: Int {
            switch self {
            case .oneMonth: return 1
            case .threeMonths: return 3
            case .oneYear: return 12
            case .tenYears: return 120
            }
        }
    }

    var filteredData: [DatabaseManager.OptionHistoryItem] {
        let calendar = Calendar.current
        guard let startDate = calendar.date(byAdding: .month, value: -selectedTimeRange.monthsBack, to: Date()) else {
            return historyData
        }
        return historyData.filter { $0.date >= startDate }
    }

    var body: some View {
        VStack(spacing: 8) {

            // 1. 顶部指示点
            HStack(spacing: 8) {
                ForEach(0..<3) { index in
                    Circle()
                        .fill(currentPage == index ? Color.primary : Color.secondary.opacity(0.3))
                        .frame(width: 6, height: 6)
                }
            }
            .padding(.top, 4)
            .animation(.easeInOut, value: currentPage)

            // 2. 图表主体
            ZStack {
                RoundedRectangle(cornerRadius: 16)
                    .fill(Color(UIColor.secondarySystemGroupedBackground))
                    .shadow(color: Color.black.opacity(0.05), radius: 5, x: 0, y: 2)

                if isLoading {
                    ProgressView()
                } else if historyData.isEmpty {
                    Text("暂无历史数据")
                        .font(.caption)
                        .foregroundColor(.secondary)
                } else if filteredData.isEmpty {
                    Text("该时间段内无数据")
                        .font(.caption)
                        .foregroundColor(.secondary)
                } else {
                    TabView(selection: $currentPage) {

                        // Page 0: Strike vs Price
                        // 【修改】传入最新标的价格
                        OptionsStrikePriceChartView(
                            allItems: currentOptions, 
                            latestStockPrice: latestStockPrice
                        )
                        .tag(0)
                        .padding(.bottom, 10)

                        // Page 1: IV
                        if isLoading {
                            ProgressView().tag(1)
                        } else if historyData.isEmpty {
                            Text("暂无历史数据").tag(1)
                        } else {
                            SingleChartContent(data: filteredData, dataType: .iv)
                                .tag(1)
                        }

                        // Page 2: Price
                        if isLoading {
                            ProgressView().tag(2)
                        } else if historyData.isEmpty {
                            Text("暂无历史数据").tag(2)
                        } else {
                            SingleChartContent(data: filteredData, dataType: .price)
                                .tag(2)
                        }
                    }
                    .tabViewStyle(.page(indexDisplayMode: .never))
                }
            }
            .frame(height: 280)
            .padding(.horizontal)

            // 3. 时间切换条
            timeRangeSelector
                .opacity(currentPage == 0 ? 0 : 1)
                .animation(.easeInOut, value: currentPage)
        }
        .task {
            await loadData()
        }
    }

    private var timeRangeSelector: some View {
        HStack(spacing: 0) {
            ForEach(TimeRangeOption.allCases) { option in
                Button(action: {
                    withAnimation(.easeInOut) {
                        selectedTimeRange = option
                    }
                }) {
                    Text(option.rawValue)
                        .font(.system(size: 13, weight: .medium))
                        .frame(maxWidth: .infinity)
                        .padding(.vertical, 8)
                        .background(
                            selectedTimeRange == option
                            ? Color.blue.opacity(0.15)
                            : Color.clear
                        )
                        .foregroundColor(
                            selectedTimeRange == option
                            ? .blue
                            : .secondary
                        )
                        .clipShape(RoundedRectangle(cornerRadius: 8))
                }
            }
        }
        .padding(4)
        .background(Color(UIColor.tertiarySystemFill))
        .cornerRadius(10)
        .padding(.horizontal)
    }

    private func loadData() async {
        isLoading = true
        let rawData = await DatabaseManager.shared.fetchOptionsHistory(forSymbol: symbol)
        await MainActor.run {
            self.historyData = rawData
            self.isLoading = false
        }
    }
}

// MARK: - 【新增】单一图表绘制组件
struct SingleChartContent: View {
    let data: [DatabaseManager.OptionHistoryItem]
    let dataType: ChartDataType

    enum ChartDataType {
        case price
        case iv

        var title: String {
            switch self {
            case .price: return "Calls+Puts"
            case .iv: return "IV Trend"
            }
        }
    }

    private var dayFormatter: DateFormatter {
        let formatter = DateFormatter()
        formatter.dateFormat = "dd"
        return formatter
    }

    private var uniqueIDFormatter: DateFormatter {
        let formatter = DateFormatter()
        formatter.dateFormat = "yyyy-MM-dd"
        return formatter
    }

    var body: some View {
        VStack(spacing: 4) {
            Text(dataType.title)
                .font(.caption2)
                .fontWeight(.bold)
                .foregroundColor(.secondary)
                .frame(maxWidth: .infinity, alignment: .leading)
                .padding(.leading, 8)
                .padding(.top, 8)

            chartBody
        }
    }

    private var chartBody: some View {
        let sortedData = data.sorted { $0.date < $1.date }
        let allDateIDs = sortedData.map { uniqueIDFormatter.string(from: $0.date) }
        let stride = getAxisStride(count: sortedData.count)
        let totalCount = allDateIDs.count
        let tickValues = allDateIDs.enumerated().compactMap { index, idValue in
            let distanceFromEnd = totalCount - 1 - index
            if distanceFromEnd % stride == 0 {
                return idValue
            }
            return nil
        }

        return Chart {
            ForEach(sortedData) { item in
                let value = (dataType == .price) ? item.price : item.iv

                BarMark(
                    x: .value("Date", uniqueIDFormatter.string(from: item.date)),
                    y: .value("Value", value)
                )
                .foregroundStyle(barGradient(for: value))
                .cornerRadius(4)
            }

            RuleMark(y: .value("Zero", 0))
                .lineStyle(StrokeStyle(lineWidth: 1, dash: [5]))
                .foregroundStyle(.gray.opacity(0.5))
        }
        .chartXAxis {
            AxisMarks(values: tickValues) { value in
                if let fullDateString = value.as(String.self),
                   let dateObject = uniqueIDFormatter.date(from: fullDateString) {

                    AxisValueLabel(centered: true) {
                        let dayString = dayFormatter.string(from: dateObject)
                        Text(dayString)
                            .font(.system(size: 10, design: .monospaced))
                            .multilineTextAlignment(.center)
                            .lineSpacing(0)
                            .fixedSize()
                    }
                }
            }
        }
        .padding(.vertical, 8)
        .padding(.horizontal, 8)
    }

    private func getAxisStride(count: Int) -> Int {
        switch count {
        case 0...10: return 1
        case 11...30: return 3
        case 31...70: return 5
        case 71...150: return 10
        default: return 20
        }
    }

    private func barGradient(for value: Double) -> LinearGradient {
        let isPositive = value >= 0
        let colors: [Color] = isPositive
            ? [.red.opacity(0.8), .red.opacity(0.4)]
            : [.green.opacity(0.8), .green.opacity(0.4)]

        return LinearGradient(
            colors: colors,
            startPoint: isPositive ? .bottom : .top,
            endPoint: isPositive ? .top : .bottom
        )
    }
}

// MARK: - 【重构】界面 A：期权 Symbol 列表
struct OptionsListView: View {
    @EnvironmentObject var dataService: DataService
    @EnvironmentObject var authManager: AuthManager
    @EnvironmentObject var usageManager: UsageManager

    @State private var selectedSymbol: String?
    @State private var navigateToDetail = false
    @State private var showSubscriptionSheet = false
    @State private var navigateToBigOrders = false
    @State private var navigateToChart = false

    @State private var showSearchBar = false
    @State private var searchText = ""
    @State private var highlightedSymbol: String?
    @FocusState private var isSearchFieldFocused: Bool 

    var sortedSymbols: [String] {
        let allSymbols = dataService.optionsData.keys
        let noCapSymbols = allSymbols.filter { symbol in
            guard let item = dataService.marketCapData[symbol.uppercased()] else { return true }
            return item.rawMarketCap <= 0
        }.sorted()

        let hasCapSymbols = allSymbols.filter { symbol in
            guard let item = dataService.marketCapData[symbol.uppercased()] else { return false }
            return item.rawMarketCap > 0
        }.sorted { s1, s2 in
            let cap1 = dataService.marketCapData[s1.uppercased()]?.rawMarketCap ?? 0
            let cap2 = dataService.marketCapData[s2.uppercased()]?.rawMarketCap ?? 0
            return cap1 > cap2
        }
        return noCapSymbols + hasCapSymbols
    }

    var body: some View {
        ScrollViewReader { proxy in
            VStack(spacing: 0) {
                if showSearchBar {
                    HStack {
                        Image(systemName: "magnifyingglass")
                            .foregroundColor(.gray)

                        TextField("输入 Symbol 跳转 (如 AAPL)", text: $searchText)
                            .textFieldStyle(RoundedBorderTextFieldStyle())
                            .submitLabel(.search)
                            .focused($isSearchFieldFocused) 
                            .onAppear {
                                isSearchFieldFocused = true
                            }
                            .onSubmit {
                                performSearch(proxy: proxy)
                            }

                        Button("取消") {
                            withAnimation {
                                isSearchFieldFocused = false 
                                showSearchBar = false
                                searchText = ""
                                highlightedSymbol = nil
                            }
                        }
                    }
                    .padding()
                    .background(Color(UIColor.secondarySystemBackground))
                    .transition(.move(edge: .top).combined(with: .opacity))
                }

                List {
                    if sortedSymbols.isEmpty {
                        Text("暂无期权异动数据")
                            .foregroundColor(.secondary)
                    } else {
                        ForEach(sortedSymbols, id: \.self) { symbol in
                            OptionListRow(
                                symbol: symbol,
                                action: { handleSelection(symbol) },
                                longPressAction: { handleLongPress(symbol) },
                                isHighlighted: symbol == highlightedSymbol
                            )
                            .id(symbol) 
                        }
                    }
                }
                .listStyle(PlainListStyle())
            }
        }
        .navigationTitle("期权异动")
        .navigationBarTitleDisplayMode(.inline)
        .toolbar {
            ToolbarItem(placement: .navigationBarTrailing) {
                HStack(spacing: 12) {
                    Button(action: {
                        withAnimation {
                            showSearchBar.toggle()
                            if !showSearchBar {
                                highlightedSymbol = nil
                            }
                        }
                    }) {
                        Image(systemName: "magnifyingglass")
                            .font(.system(size: 16, weight: .bold))
                            .foregroundColor(.primary)
                            .padding(8)
                            .background(Color(UIColor.secondarySystemBackground))
                            .clipShape(Circle())
                    }

                    Button(action: {
                        PointsCoordinator.shared.attempt(action: .viewOptionsRank, itemKey: "big_orders",
                            displayName: "期权大单榜单", authManager: authManager) {
                            self.navigateToBigOrders = true
                        }
                    }) {
                        HStack(spacing: 4) {
                            Image(systemName: "dollarsign.circle.fill") 
                                .font(.system(size: 14, weight: .bold))
                            Text("期权大单")
                                .font(.system(size: 13, weight: .bold))
                        }
                        .padding(.vertical, 6)
                        .padding(.horizontal, 12)
                        .foregroundColor(.white)
                        .background(
                            LinearGradient(
                                gradient: Gradient(colors: [Color.purple, Color.blue]),
                                startPoint: .topLeading,
                                endPoint: .bottomTrailing
                            )
                        )
                        .clipShape(Capsule())
                        .shadow(color: Color.purple.opacity(0.3), radius: 4, x: 0, y: 2)
                        .overlay(
                            Capsule().stroke(Color.white.opacity(0.2), lineWidth: 1)
                        )
                    }
                }
            }
        }
        .navigationDestination(isPresented: $navigateToDetail) {
            if let sym = selectedSymbol {
                OptionsDetailView(symbol: sym)
            }
        }
        .navigationDestination(isPresented: $navigateToBigOrders) {
            OptionBigOrdersView()
        }
        .navigationDestination(isPresented: $navigateToChart) {
            if let sym = selectedSymbol {
                let groupName = dataService.getCategory(for: sym) ?? "US"
                ChartView(symbol: sym, groupName: groupName)
            }
        }
        .sheet(isPresented: $showSubscriptionSheet) { SubscriptionView() }
    }

    private func handleSelection(_ symbol: String) {
        PointsCoordinator.shared.attempt(action: .viewOptionsDetail, itemKey: symbol,
            displayName: "查看 \(symbol) 期权详情", authManager: authManager) {
            self.selectedSymbol = symbol
            self.navigateToDetail = true
        }
    }

    private func handleLongPress(_ symbol: String) {
        PointsCoordinator.shared.attempt(action: .viewChart, itemKey: symbol,
            displayName: "查看 \(symbol) 图表", authManager: authManager) {
            self.selectedSymbol = symbol
            self.navigateToChart = true
            let impact = UIImpactFeedbackGenerator(style: .medium)
            impact.impactOccurred()
        }
    }

    private func performSearch(proxy: ScrollViewProxy) {
        let target = searchText.trimmingCharacters(in: .whitespacesAndNewlines).uppercased()
        guard !target.isEmpty else { return }

        if let foundSymbol = sortedSymbols.first(where: { $0.contains(target) }) {
            self.highlightedSymbol = foundSymbol
            withAnimation(.spring()) {
                proxy.scrollTo(foundSymbol, anchor: .center)
            }
            UIApplication.shared.sendAction(#selector(UIResponder.resignFirstResponder), to: nil, from: nil, for: nil)
        } else {
            let generator = UINotificationFeedbackGenerator()
            generator.notificationOccurred(.error)
            self.highlightedSymbol = nil
        }
    }
}

