        .onChange(of: isCachedLoading) { loading in
            if loading {
                scheduleLoadTimeout()
            } else {
                loadTimeoutWork?.cancel()
                loadTimeoutWork = nil
            }
        }
        // ⭐⭐ 退出全屏后补弹被压住的反馈修复
        .onChange(of: isPlayerFullScreen) { full in
