    private var lineBar: some View {
        HStack(alignment: .center, spacing: 8) {
            ForEach(sortedLines.indices, id: \.self) { i in
                Button { lineIndex = i } label: {
                    Text(lang.t("线路 \(i + 1)", "Line \(i + 1)"))
