                    .background(Color.black.opacity(0.4))
                    .cornerRadius(20)
                }

                // 2. 【新增】"已是最新" 的自动消失弹窗
                if resourceManager.showAlreadyUpToDateAlert {
                    VStack(spacing: 15) {
                        Image(systemName: "checkmark.circle.fill")
