                    .cornerRadius(20)
                    .transition(.opacity.combined(with: .scale)) // 出现动画
                    .zIndex(100) // 确保在最上层
                }

                // 3. 图片下载遮罩
                DownloadOverlay(isDownloading: isDownloadingImages, progress: downloadProgress, progressText: downloadProgressText)
