    private func cachedOriginalURLs() -> Set<String> {
        var s = Set<String>()
        for (key, meta) in downloadManager.cacheMetadata
        where downloadManager.localBookmarks[key] != nil {
            s.insert(key)
            if let orig = meta.originalEpisodeURL, !orig.isEmpty { s.insert(orig) }
