    if (needConfirm(btn, `⚠️ 再点一次：确认全清「${targetGroup}」后重建`)) {
      setWl(`⚠️ 全清重建：会把目标分组「${targetGroup}」内全部标的删掉再按数据源重建` +
        (rows ? `（当前分组显示 ${rows} 只）` : '') + `\n8 秒内再点一次确认。`);
      return;
