  const strictSync = $('wlStrict').checked;
  const targetGroup = ($('wlTarget').value || 'ALL').trim() || 'ALL';

  // 只有「全清重建」这种一定会删掉全部的动作才强制二次确认；
  // 严格同步只删「多余」，网页 HUD 里另有 5 秒红色倒计时可取消。
  if (clearFirst) {
    const st = await sendToTab({ action: 'FT_WL_STATUS' });
