TASK_TTL = 600
TASK_LEASE = 90
AGENT_ALIVE_SEC = 8

_TASKS = OrderedDict()
_TASK_LOCK = threading.Lock()
_TASK_SEQ = [0]
_LAST_AGENT_POLL = [0.0]

ORDER_LEAN_FIELDS = ("symbol", "side", "date", "quantity", "amount", "price", "st")
ORDER_EXTRA_FIELDS = ("order_id", "side_text", "datetime", "status", "price_type",
