                if self.panel:
                    sys.exit(0)
                return

            actions = {'v': self.toggle_volume, 'r': self.toggle_global_markers, 'x': self.toggle_all_annotations,
                       'a': self.toggle_earning_markers,
                       'c': self.toggle_specific_markers,
