        }
        .onChange(of: engine.errorText) { _, msg in
            if let msg = msg {
                resolveError = msg
                requestRepairSheet()
            }
        }
        .onChange(of: isPlayerFullScreen) { _, full in
            if !full, pendingRepairPrompt {
