class _RealtimeManager:
    def __init__(self):
        self._lock = threading.Lock()
        self._symbol = None
        self._latest = {}
        self._thread = None
        self._stop = threading.Event()
        self._fetcher = None

    def _ensure_thread(self):
        if self._thread is None or not self._thread.is_alive():
            self._stop.clear()
            self._thread = threading.Thread(target=self._run, daemon=True)
            self._thread.start()

    def set_symbol(self, symbol):
        with self._lock:
            self._symbol = symbol
        self._ensure_thread()

    def get_latest(self, symbol):
        with self._lock:
            return self._latest.get(symbol)

    def _run(self):
        try:
            self._fetcher = _get_global_fetcher()
        except Exception as e:
            print(f"初始化 fetcher 失败: {e}")
            return
        while not self._stop.is_set():
            with self._lock:
                sym = self._symbol
            if sym:
                try:
                    quote = self._fetcher.get_realtime_quote(sym)
                    if quote and 'price' in quote:
                        with self._lock:
                            self._latest[sym] = quote['price']
                except Exception as e:
                    print(f"后台获取实时价格失败: {e}")
            if self._stop.wait(timeout=5.0):
                break

_RT_MANAGER = _RealtimeManager()

