    def launch_insert_then_delete_chain(self):
        name = self.name

        def on_delete_done(delete_return_code):
            if delete_return_code == 0:
                if self.callback:
                    self.callback('deleted')
                print("删除操作完成 (Code 0)，正在关闭窗口...")
                try:
                    plt.close('all')
