    def on_keyword_selected_chart(self, sym):
        global symbol_manager
        sector = next((s for s, lst in sector_data.items() if sym in lst), None)
        if sector:
            symbol_manager.set_current_symbol(sym)
            cmp = compare_data.get(sym, "N/A")
