                callback=lambda action: self.handle_chart_callback(sym, action)
            )

            self.setFocus()

    # --- 新增：处理图表传回的按键动作 ---
    def handle_chart_callback(self, current_symbol, action):
        if action in ('next', 'prev'):
            # 使用 QTimer 稍微延迟，确保旧的 matplotlib 窗口完全关闭后再打开新的
            # 避免出现窗口卡死或黑屏的冲突
            QTimer.singleShot(50, lambda: self.navigate_from_chart(action))

    def navigate_from_chart(self, direction):
        global symbol_manager
        # 复用已经写好的 SymbolManager 逻辑
        if direction == 'next':
            sym = symbol_manager.next_symbol()
        elif direction == 'prev':
            sym = symbol_manager.previous_symbol()
        else:
            sym = None

        if sym:
            print(f"图表内快捷键触发: 切换到 {sym}")
            self.on_keyword_selected_chart(sym)

    def keyPressEvent(self, ev):
        k = ev.key()

        # 退出
        if k == Qt.Key.Key_Escape:
            self.close()

        # 向下切换 Symbol
        elif k == Qt.Key.Key_Down:
            self.on_arrow('down')

        # 向上切换 Symbol
        elif k == Qt.Key.Key_Up:
            self.on_arrow('up')

        # --- 新增功能：按 "/" 键聚焦搜索框 ---
        elif k == Qt.Key.Key_Slash:
            self.search_line.setFocus()   # 让光标跳到输入框
            self.search_line.selectAll()  # (可选) 选中框内已有文字，方便直接打字覆盖

        else:
            super().keyPressEvent(ev)

    def on_arrow(self, dir_):
        global symbol_manager
        sym = symbol_manager.next_symbol() if dir_ == 'down' else symbol_manager.previous_symbol()
        if sym:
            self.on_keyword_selected_chart(sym)

    def closeEvent(self, ev):
        global symbol_manager
        symbol_manager.reset()
        QApplication.quit()


