    def show(self):
        """非阻塞显示 / 前置窗口，并把键盘焦点交给画布"""
        try:
            mgr = self.fig.canvas.manager
            mgr.show()
            try:
                win = mgr.window
                if win.isMinimized():
                    win.showNormal()
                win.raise_()
                win.activateWindow()
            except Exception:
                pass
            try:
                self.fig.canvas.setFocus()
            except Exception:
                pass
        except Exception:
            pass


