    def _show_wl_status(self, text, color, ttl=6.0):
        try:
            self.wl_status_artist.set_text(text)
            self.wl_status_artist.set_color(color)
            self.wl_status_artist.set_visible(True)
            self._wl_hide_at = time.time() + ttl
