    def _ui_poll_realtime(self):
        try:
            self._drain_wl_results()
        except Exception:
            pass
        try:
            if self.name:
                dsig = _file_sig(self.DESCRIPTION_JSON_PATH)[0]
                if self._desc_sig is not None and dsig != self._desc_sig:
                    self.refresh_description_data_and_redraw(silent=True)   # 改完 Tag 自动刷新
                if self._draw_blacklist_badge():
                    self.fig.canvas.draw_idle()
        except Exception:
            pass
        try:
            if self.name and self._draw_membership():
                self.fig.canvas.draw_idle()
        except Exception:
            pass
        try:
            if self.name is None or not self.prices or self.prices[-1] == 0:
                return
            rt_price = _RT_MANAGER.get_latest(self.name)
            if rt_price is None:
                return
            pct = ((rt_price - self.prices[-1]) / self.prices[-1]) * 100
            if self.current_pre_after_pct[0] is not None and abs(self.current_pre_after_pct[0] - pct) < 1e-9:
                return
            self.current_pre_after_pct[0] = pct
            if self.pa_text_artist[0] is not None:
                self.pa_text_artist[0].set_text(f"P/A:{pct:+.2f}%")
                self.pa_text_artist[0].set_color(NORD_THEME['accent_red'] if pct > 0 else NORD_THEME['accent_green'])
                self.fig.canvas.draw_idle()
        except Exception:
            pass

    def _on_close(self, evt):
        self.closed = True
        try:
            self.ui_timer.stop()
        except Exception:
            pass

    def discard(self):
        """丢弃一个尚未显示过的窗口（首次加载失败时使用）"""
        self.closed = True
        try:
            self.ui_timer.stop()
        except Exception:
            pass
        try:
            plt.close(self.fig)
        except Exception:
            pass

    def show(self):
        """非阻塞显示 / 前置窗口，并把键盘焦点交给画布"""
        try:
            mgr = self.fig.canvas.manager
            mgr.show()
            try:
                win = mgr.window
                if win.isMinimized():
                    win.showNormal()
                win.raise_()
                win.activateWindow()
            except Exception:
                pass
            try:
                self.fig.canvas.setFocus()
            except Exception:
                pass
        except Exception:
            pass


