        # ★ 黑名单文件监视（Check_Group 设置 / 手动编辑后同步显示）
        self._bl_sig = TB.signature() if TB_OK else None
        self._bl_timer = QTimer(self)
        self._bl_timer.setInterval(1000)
        self._bl_timer.timeout.connect(self._poll_blacklist)
        self._bl_timer.start()
        self.refresh_blacklist_view()

    # ------------------------------------------------------------------
    def eventFilter(self, source, event):
        et = event.type()
        # 输入框：Enter 顶部添加 / Shift+Enter 底部添加
        if source is self.new_tag_input and et == QEvent.KeyPress:
            if event.key() in (Qt.Key_Return, Qt.Key_Enter):
                if event.modifiers() & Qt.ShiftModifier:
                    QTimer.singleShot(0, lambda: self.add_tag(bottom=True))
                else:
                    QTimer.singleShot(0, lambda: self.add_tag(bottom=False))
                return True
        # 列表：键盘操作（放在过滤器里，避免被 QListWidget 的键盘搜索吞掉）
        if source is self.tags_list and et == QEvent.KeyPress and self.tags_list.currentItem():
            k = event.key()
            if TB_OK and k == Qt.Key_1:
                self.toggle_current_blacklist(TB.GROUP_SURE); return True
            if TB_OK and k == Qt.Key_2:
                self.toggle_current_blacklist(TB.GROUP_MAYBE); return True
            if k in (Qt.Key_Return, Qt.Key_Enter):
                self.edit_current_tag(); return True
            if k in (Qt.Key_Delete, Qt.Key_Backspace):
                self.delete_current_tag(); return True
        # 列表视口：悬停跟踪
        if source is self.tags_list.viewport():
            if et == QEvent.MouseMove:
                idx = self.tags_list.indexAt(event.pos())
                self.tag_delegate.hover_row = idx.row() if idx.isValid() else -1
                self.tag_delegate.hover_pos = event.pos()
                over = self.tag_delegate.hit(idx, event.pos()) is not None
                source.setCursor(QCursor(Qt.PointingHandCursor if over else Qt.ArrowCursor))
                source.update()
            elif et == QEvent.Leave:
                self.tag_delegate.hover_row = -1
                self.tag_delegate.hover_pos = None
                source.unsetCursor()
                source.update()
        return super().eventFilter(source, event)

    def init_ui(self):
        self.symbol_label = QLabel("Symbol: ")
