    # ==================================================================
    # ★ 黑名单：命中计算 / 过滤
    # ==================================================================
    def _blacklist_hits(self, symbol, groups=None):
        if not TB_OK:
            return []
        tags = self.tags_index.get(norm_symbol(symbol), [])
        return TB.blacklisted_tags(tags, groups)

    def _compute_views(self):
        self.hidden_info = {}
        active = self.bl_active

        def visible(sym):
            if not active or not TB_OK:
                return True
            hits = self._blacklist_hits(sym, active)
            if hits:
                self.hidden_info[sym] = hits
                return False
            return True

        self.view_turning = [r for r in self.turning_data if visible(r['symbol'])]
        self.turning_hidden = len(self.turning_data) - len(self.view_turning)
        self.view_resonance = []
        for item in self.resonance_data:
            vis = [s for s in item['symbols'] if visible(s)]
            self.view_resonance.append({'count': item['count'], 'symbols': vis,
                                        'hidden': len(item['symbols']) - len(vis)})
        self.list_turning = [r['symbol'] for r in self.view_turning]
        self.list_resonance = [s for item in self.view_resonance for s in item['symbols']]

    def apply_blacklist_filter(self):
        self._compute_views()
        self._sync_navigation_list()
        self._rebuild_content()
        self._update_bl_bar()
        self._update_window_title()

    def _set_bl_active(self, groups):
        self.bl_active = set(groups)
        self.apply_blacklist_filter()
        desc = "、".join(g for g in (TB.GROUPS if TB_OK else ()) if g in self.bl_active) or "不屏蔽"
        self.statusBar().showMessage(f"黑名单屏蔽：{desc} ｜ 已隐藏 {len(self.hidden_info)} 只", 6000)

    def _on_bl_check_toggled(self, _checked=False):
        self._set_bl_active({g for g, cb in self.bl_checks.items() if cb.isChecked()})

    def open_blacklist_settings(self):
        if not TB_OK:
            QMessageBox.warning(self, "不可用", "tag_blacklist.py 未加载")
            return
        dlg = BlacklistChoiceDialog(self.bl_active, parent=self, startup=False)
        if dlg.exec():
            self._set_bl_active(dlg.selected())

    def open_blacklist_file(self):
        if TB_OK:
            TB.open_in_editor()
            self.statusBar().showMessage(f"已打开 {TB.BLACKLIST_PATH}（保存后约 1 秒自动生效）", 8000)

    def _poll_external_changes(self, force=False):
        changed = False
        try:
            dsig = file_mtime(DESCRIPTION_PATH)
            if force or dsig != self._desc_sig:
                self._desc_sig = dsig
                try:
                    new = load_json(DESCRIPTION_PATH)
                except Exception as e:
                    print(f"[联动] description.json 读取失败（可能正在写入），稍后重试: {e}")
                    self._desc_sig = None
                    new = None
                if isinstance(new, dict) and new:
                    # 原地更新：Chart 持有同一个 dict 引用，也能拿到新数据
                    self.json_data.clear()
                    self.json_data.update(new)
                    self.tags_index = build_tags_index(self.json_data)
                    changed = True
            if TB_OK:
                bsig = TB.signature()
                if force or bsig != self._bl_sig:
                    self._bl_sig = bsig
                    TB.load(force=True)
                    changed = True
        except Exception:
            traceback.print_exc()
        if changed:
            before = set(self.hidden_info)
            self.apply_blacklist_filter()
            after = set(self.hidden_info)
            add_n, rm_n = len(after - before), len(before - after)
            msg = "黑名单 / Tag 已更新"
            if add_n or rm_n:
                msg += f"：新隐藏 {add_n} 只，恢复显示 {rm_n} 只"
            self.statusBar().showMessage(msg, 6000)

    def _update_window_title(self):
        if TB_OK:
            desc = "、".join(g for g in TB.GROUPS if g in self.bl_active) or "无"
            self.setWindowTitle(f"持仓 / 多组共振 / 转折   ｜ 黑名单屏蔽：{desc}")
        else:
            self.setWindowTitle("持仓 / 多组共振 / 转折")

