            b.setFocusPolicy(Qt.FocusPolicy.NoFocus)
            b.setCursor(QCursor(Qt.CursorShape.PointingHandCursor))
            b.setToolTip(tip)
            b.clicked.connect(lambda _=False, f=slot: f())
            b.setEnabled(TB_OK)
            bar.addWidget(b)
        return bar

    def _update_bl_bar(self):
        if not TB_OK or not hasattr(self, 'bl_info_label'):
            return
        data = TB.load()
        for g, cb in self.bl_checks.items():
            tags = data.get(g, [])
            cb.blockSignals(True)
            cb.setChecked(g in self.bl_active)
            cb.setText(f"{g} ({len(tags)})")
            cb.blockSignals(False)
            cb.setToolTip(f"「{g}」黑名单 Tag：\n{preview_tags(tags, 60)}")

        parts = []
        if self.bl_active:
            parts.append(f"已隐藏 {len(self.hidden_info)} 只")
        else:
            parts.append("当前未屏蔽（带黑名单 Tag 的卡片以 ⛔ 标出）")
        err = TB.last_error()
        if err:
            parts.append("⚠ 黑名单文件解析失败，沿用上次内容")
        self.bl_info_label.setText("   ".join(parts))

        lines = []
        for sym in sorted(self.hidden_info)[:80]:
            hits = self.hidden_info[sym]
            lines.append(f"{sym}：" + "、".join(f"{t}[{g}]" for t, g in hits))
        if len(self.hidden_info) > 80:
            lines.append(f"… 共 {len(self.hidden_info)} 只")
        if err:
            lines.insert(0, f"解析错误：{err}\n")
        self.bl_info_label.setToolTip("\n".join(lines) or "无")

