    def _update_hold_header(self):
        arrow = '↓' if self.hold_sort_desc else '↑'
        label = HOLD_SORT_LABEL.get(self.hold_sort_mode, self.hold_sort_mode)
        ts = self.positions_meta.get('updated_at_str', '')
