            let triggerURLs: Set<String> = onReachEnd == nil
                ? [] : Set(items.suffix(Self.prefetchDistance).map(\.url))
            LazyVGrid(columns: columns, spacing: 12) {
                ForEach(items) { item in
                    NavigationLink {
