                    let subscribed = authManager.isSubscribed
                    let noQuota = quotaManager.remaining <= 0

                    LazyVGrid(columns: [GridItem(.adaptive(minimum: 80), spacing: 10)], spacing: 10) {
                        ForEach(sortedEps, id: \.url) { episode in
