    private func retryCurrent() {
        resolveError = nil
        if let local = localURL(forOriginal: activeKey) {
            hasPlayable = true
            updateNowPlaying()
            engine.prepare(url: local, positionKey: activeKey, isLocal: true, resolver: nil)
            return
