TASK_TTL = 600
TASK_LEASE = 90
AGENT_ALIVE_SEC = 8

_TASKS = OrderedDict()
_TASK_LOCK = threading.Lock()
_TASK_SEQ = [0]
_LAST_AGENT_POLL = [0.0]

