def _qt_loop_running():
    """当前线程是否已处于 Qt 事件循环中"""
    app = QApplication.instance()
    if app is None:
        return False
    try:
        return QThread.currentThread().loopLevel() > 0
    except Exception:
        # 兜底：有可见的顶层窗口，基本可以认为是嵌入在 GUI 程序里
        try:
            return any(w.isVisible() for w in QApplication.topLevelWidgets())
