        return _EARNING_RELEASE_CACHE["data"]
    result = {}
    for file_path in files:
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    parts = [p.strip() for p in line.split(':')]
                    if len(parts) >= 3:
                        sym, date_str = parts[0], parts[2]
                        if sym not in result:
