def _file_sig(*paths):
    """文件修改时间签名，用作缓存失效键"""
    sig = []
    for p in paths:
        try:
            sig.append(os.path.getmtime(p))
        except OSError:
            sig.append(0.0)
    return tuple(sig)


def _db_sig(db_path):
    # WAL 模式下写入先落到 -wal 文件，所以两者都要看
    return _file_sig(db_path, db_path + "-wal")


def _to_bool(v):
    if isinstance(v, str):
        return v.strip().lower() in ("1", "true", "yes", "y")
    return bool(v)


def _qt_loop_running():
    """当前线程是否已处于 Qt 事件循环中"""
    app = QApplication.instance()
    if app is None:
        return False
    try:
        return QThread.currentThread().loopLevel() > 0
    except Exception:
        # 兜底：有可见的顶层窗口，基本可以认为是嵌入在 GUI 程序里
        try:
            return any(w.isVisible() for w in QApplication.topLevelWidgets())
        except Exception:
            return False


