def _file_sig(*paths):
    """文件修改时间签名，用作缓存失效键"""
    sig = []
    for p in paths:
        try:
            sig.append(os.path.getmtime(p))
        except OSError:
            sig.append(0.0)
    return tuple(sig)


def _db_sig(db_path):
