class BlacklistChoiceDialog(QDialog):
    def __init__(self, active=None, parent=None, startup=True):
        super().__init__(parent)
        self.setWindowTitle("Check_Group · Tag 黑名单屏蔽")
        self.setMinimumWidth(480)
        data = TB.load() if TB_OK else {}
        active = set(TB.DEFAULT_ACTIVE if (TB_OK and active is None) else (active or ()))

        lay = QVBoxLayout(self)
        lay.setContentsMargins(18, 16, 18, 14)
        lay.setSpacing(8)
        head = QLabel("本次要屏蔽哪些黑名单分组？\n（只影响「转折 / 共振」，「持仓」始终完整显示）")
        head.setObjectName("DlgHead")
        lay.addWidget(head)

        self.checks = {}
        for i, g in enumerate(TB.GROUPS if TB_OK else ()):
            tags = data.get(g, [])
            cb = QCheckBox(f"{i + 1}.  {g}   （{len(tags)} 个 Tag）")
            cb.setChecked(g in active)
            lay.addWidget(cb)
            pv = QLabel(preview_tags(tags))
            pv.setWordWrap(True)
            pv.setObjectName("DlgPreview")
            lay.addWidget(pv)
            self.checks[g] = cb

        hint = QLabel("Enter 确认 ｜ 数字键 1 / 2 切换 ｜ 空格切换当前项 ｜ "
                      + ("Esc 退出程序" if startup else "Esc 取消"))
        hint.setObjectName("DlgHint")
        lay.addWidget(hint)

        btns = QDialogButtonBox(QDialogButtonBox.StandardButton.Ok |
                                QDialogButtonBox.StandardButton.Cancel)
        ok_btn = btns.button(QDialogButtonBox.StandardButton.Ok)
        ok_btn.setText("打开列表" if startup else "应用")
        ok_btn.setDefault(True)
        ok_btn.setAutoDefault(True)
        btns.button(QDialogButtonBox.StandardButton.Cancel).setText("退出" if startup else "取消")
        btns.accepted.connect(self.accept)
        btns.rejected.connect(self.reject)
        lay.addWidget(btns)
        self.setStyleSheet(DIALOG_QSS)

    def keyPressEvent(self, e):
        k = e.key()
        cbs = list(self.checks.values())
        if k == Qt.Key.Key_1 and len(cbs) > 0:
            cbs[0].toggle(); return
        if k == Qt.Key.Key_2 and len(cbs) > 1:
            cbs[1].toggle(); return
        if k in (Qt.Key.Key_Return, Qt.Key.Key_Enter):
            self.accept(); return
        super().keyPressEvent(e)

    def showEvent(self, e):
        super().showEvent(e)
        self.raise_()
        self.activateWindow()

    def selected(self):
        return {g for g, cb in self.checks.items() if cb.isChecked()}


