    def _build_blacklist_bar(self):
        bar = QHBoxLayout()
        bar.setContentsMargins(10, 0, 10, 4)
        bar.setSpacing(12)
        title = QLabel("⛔ 黑名单屏蔽（不影响持仓）：")
        title.setObjectName("BLTitle")
        bar.addWidget(title)

        self.bl_checks = {}
        for g in (TB.GROUPS if TB_OK else ()):
            cb = QCheckBox(g)
            cb.setObjectName("BLCheck")
            cb.setChecked(g in self.bl_active)
            cb.setFocusPolicy(Qt.FocusPolicy.NoFocus)
            cb.toggled.connect(self._on_bl_check_toggled)
            self.bl_checks[g] = cb
            bar.addWidget(cb)

        self.bl_info_label = QLabel("" if TB_OK else "tag_blacklist.py 未加载，黑名单功能不可用")
        self.bl_info_label.setObjectName("BLInfo")
        bar.addWidget(self.bl_info_label)
        bar.addStretch(1)

        for text, slot, tip in (
                ("⚙ 设置 (B)", self.open_blacklist_settings, "打开勾选对话框"),
                ("📝 编辑黑名单文件", self.open_blacklist_file, "用文本编辑器打开 Tag_Blacklist.json"),
                ("↻ 重新读取", lambda: self._poll_external_changes(force=True),
                 "强制重新读取黑名单与 description.json")):
            b = QPushButton(text)
            b.setObjectName("SortBtn")
            b.setFocusPolicy(Qt.FocusPolicy.NoFocus)
            b.setCursor(QCursor(Qt.CursorShape.PointingHandCursor))
            b.setToolTip(tip)
            b.clicked.connect(lambda _=False, f=slot: f())
            b.setEnabled(TB_OK)
            bar.addWidget(b)
        return bar

    def _update_bl_bar(self):
        if not TB_OK or not hasattr(self, 'bl_info_label'):
            return
        data = TB.load()
        for g, cb in self.bl_checks.items():
            tags = data.get(g, [])
            cb.blockSignals(True)
            cb.setChecked(g in self.bl_active)
            cb.setText(f"{g} ({len(tags)})")
            cb.blockSignals(False)
            cb.setToolTip(f"「{g}」黑名单 Tag：\n{preview_tags(tags, 60)}")

        parts = []
        if self.bl_active:
            parts.append(f"已隐藏 {len(self.hidden_info)} 只")
        else:
            parts.append("当前未屏蔽（带黑名单 Tag 的卡片以 ⛔ 标出）")
        err = TB.last_error()
        if err:
            parts.append("⚠ 黑名单文件解析失败，沿用上次内容")
        self.bl_info_label.setText("   ".join(parts))

        lines = []
        for sym in sorted(self.hidden_info)[:80]:
            hits = self.hidden_info[sym]
            lines.append(f"{sym}：" + "、".join(f"{t}[{g}]" for t, g in hits))
        if len(self.hidden_info) > 80:
            lines.append(f"… 共 {len(self.hidden_info)} 只")
        if err:
            lines.insert(0, f"解析错误：{err}\n")
        self.bl_info_label.setToolTip("\n".join(lines) or "无")

