            "Reso_L0":  ("#111111", "#D8DEE9", "#3A3A3A"),
            "Reso_L1":  ("#10222A", "#D8DEE9", "#88C0D0"),
            "Reso_L2":  ("#2C2411", "#F2E3B4", "#EBCB8B"),
