                "padding:3px 4px; text-align:center; }\n"
                "QPushButton#SortBtnOn:hover { background-color:#5E81AC; }\n")

        qss += ("QLabel#BLTitle { color:#BF616A; font-size:14px; font-weight:bold; }\n"
                "QLabel#BLInfo { color:#9AA5B1; font-size:13px; }\n"
