def _qint(qs, key, default):
    try:
        return int(qs.get(key, [default])[0])
    except Exception:
        return default


class StockRequestHandler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def _cors(self):
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "Content-Type")
        self.send_header("Access-Control-Max-Age", "86400")
        self.send_header("Access-Control-Allow-Private-Network", "true")

    def _reply(self, status, obj):
        body = json.dumps(obj, ensure_ascii=False).encode("utf-8")
        self.send_response(status)
        self._cors()
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        try:
            self.wfile.write(body)
        except Exception:
            pass

    def _read_json_body(self):
        try:
            length = int(self.headers.get("Content-Length", 0) or 0)
        except ValueError:
            length = 0
        if length <= 0:
            return {}
        raw = self.rfile.read(length)
        if not raw:
            return {}
        return json.loads(raw.decode("utf-8"))

    def _handle_symbol_task(self, action):
        """/wl_add 与 /wl_remove 共用：激活 watchlist Tab → 排队（同 symbol+分组去重）→ 可选阻塞等待结果"""
        try:
            body = self._read_json_body()
            symbol = str(body.get("symbol", "")).strip().upper()
            group = str(body.get("group", "")).strip()
            wait = float(body.get("wait", 0) or 0)
            restore = bool(body.get("restore", True))
            if not symbol:
                self._reply(400, {"status": "error", "ok": False, "message": "no symbol"})
                return
            if action == "remove" and not group:
                self._reply(400, {"status": "error", "ok": False, "message": "删除必须指定分组"})
                return
            tab = ensure_watchlist_tab()
            _log(f"[任务] 激活 Watchlist 页面 -> {tab}")
            t = find_active_task(action, symbol, group)
            if t:
                _log(f"[任务] 复用已排队的 {action} {symbol}@{group} id={t['id']}")
            else:
                t = new_task(action, symbol, group, {"restore": restore})
                _log(f"[任务] 排队 {action} {symbol} {'→' if action == 'add' else '✕'} 「{group or '当前分组'}」 id={t['id']}")
            if wait > 0:
                t["event"].wait(min(wait, 180))
            res = t.get("result")
            if res:
                out = {"status": "ok", "id": t["id"], "tab": tab, "action": action}
                out.update(res)
                self._reply(200, out)
            else:
                self._reply(200, {
                    "status": "pending", "id": t["id"], "tab": tab, "ok": False, "action": action,
                    "message": "任务已排队、页面已激活，但未在等待时间内完成（检查 watchlist 页面是否登录/网络是否通畅）"})
        except Exception as e:
            _log(f"/wl_{action} 失败: {e}")
            self._reply(500, {"status": "error", "ok": False, "message": str(e)})

    def do_OPTIONS(self):
        self.send_response(204)
        self._cors()
        self.send_header("Content-Length", "0")
        self.end_headers()

    def do_POST(self):
        path = urlparse(self.path).path

        if path == "/sync_positions":
            try:
                body = self._read_json_body()
                incoming = body.get("positions", body) if isinstance(body.get("positions"), dict) else body
                overwrite = bool(body.get("overwrite", False))
                n, total = save_positions(incoming, overwrite=overwrite)
                self._reply(200, {"status": "ok", "saved": n, "total": total, "overwrite": overwrite})
            except Exception as e:
                self._reply(500, {"status": "error", "message": str(e)})
            return

        if path == "/sync_orders":
            try:
                body = self._read_json_body()
                incoming = body.get("orders") if isinstance(body.get("orders"), dict) else body
                verbose = body.get("verbose", None)
                added, updated, total, shrunk = save_orders(incoming, verbose=verbose)
                self._reply(200, {"status": "ok", "added": added, "updated": updated,
                                  "total": total, "shrunk": shrunk,
                                  "bytes": _file_size(ORDERS_JSON_PATH)})
            except Exception as e:
                self._reply(500, {"status": "error", "message": str(e)})
            return

        if path == "/compact_orders":
            try:
                body = self._read_json_body()
                r = compact_orders(bool(body.get("verbose", False)))
                self._reply(200, r)
            except Exception as e:
                self._reply(500, {"status": "error", "message": str(e)})
            return

        if path == "/compact_positions":
            try:
                body = self._read_json_body()
                self._reply(200, compact_positions(bool(body.get("verbose", False))))
            except Exception as e:
                self._reply(500, {"status": "error", "message": str(e)})
            return

        if path == "/sync_watchlist":
            try:
                body = self._read_json_body()
                incoming = body.get("quotes") if isinstance(body.get("quotes"), dict) else body
                overwrite = bool(body.get("overwrite", True))
                n, total, mode = save_watchlist(incoming, overwrite=overwrite)
                self._reply(200, {"status": "ok", "saved": n, "total": total, "mode": mode})
            except Exception as e:
                self._reply(500, {"status": "error", "message": str(e)})
            return

        if path in ("/wl_add", "/wl_remove"):
            self._handle_symbol_task("add" if path == "/wl_add" else "remove")
            return

        if path == "/wl_membership":
            try:
                body = self._read_json_body()
                r = save_membership_snapshot(body.get("group"), body.get("symbols") or [],
                                             complete=bool(body.get("complete", True)),
                                             source=str(body.get("source", "")),
                                             page_groups=body.get("page_groups"))
                self._reply(200, r)
            except Exception as e:
                self._reply(500, {"status": "error", "message": str(e)})
            return

        if path == "/wl_membership_event":
            try:
                body = self._read_json_body()
                r = apply_membership_event(body.get("group"), body.get("symbol"),
                                           str(body.get("op", "")), str(body.get("source", "")))
                self._reply(200, r)
            except Exception as e:
                self._reply(500, {"status": "error", "message": str(e)})
            return

        # ★ 全量扫描所有分组的归属（图表 M 键 / 其它脚本）
        if path == "/wl_scan_groups":
            try:
                body = self._read_json_body()
                groups = body.get("groups")
                groups = [str(x).strip() for x in groups if str(x).strip()] if isinstance(groups, list) else None
                wait = float(body.get("wait", 0) or 0)
                tab = ensure_watchlist_tab()
                t = find_active_task("scan_groups")
                if t:
                    _log(f"[任务] 已有扫描任务 {t['id']} 在进行，复用")
                else:
                    t = new_task("scan_groups", "", "", {"groups": groups, "restore": True,
                                                         "lease": 900, "ttl": 1500})
                    _log(f"[任务] 排队 scan_groups {groups or '(页面全部分组)'} id={t['id']}")
                if wait > 0:
                    t["event"].wait(min(wait, 900))
                res = t.get("result")
                if res:
                    out = {"status": "ok", "id": t["id"], "tab": tab}
                    out.update(res)
                    self._reply(200, out)
                else:
                    self._reply(200, {"status": "pending", "id": t["id"], "tab": tab, "ok": False,
                                      "message": "扫描任务已排队但未在等待时间内完成（稍后图表会自动刷新）"})
            except Exception as e:
                self._reply(500, {"status": "error", "ok": False, "message": str(e)})
            return

        if path == "/wl_task_result":
            try:
                body = self._read_json_body()
                tid = str(body.get("id"))
                reported_ok = bool(body.get("ok"))
                with _TASK_LOCK:
                    t = _TASKS.get(tid)
                    info = (t.get("action"), t.get("symbol"), t.get("group")) if t else (None, None, None)
                # ★ 先记账（F 键添加成功 / 已存在 都说明该 symbol 在该分组），再唤醒等待方
                if reported_ok and info[0] == "add":
                    d = body.get("data") or {}
                    grp = d.get("group") or info[2]
                    sym = d.get("symbol") or info[1]
                    if grp and sym:
                        try:
                            apply_membership_event(grp, sym, "add", "agent_add")
                        except Exception as e:
                            _log(f"[归属] 记账失败: {e}")
                if reported_ok and info[0] == "remove":
                    d = body.get("data") or {}
                    grp = d.get("group") or info[2]
                    sym = d.get("symbol") or info[1]
                    if grp and sym:
                        try:
                            apply_membership_event(grp, sym, "remove", "agent_remove")
                        except Exception as e:
                            _log(f"[归属] 删除记账失败: {e}")
                ok = finish_task(tid, reported_ok, str(body.get("message", "")), body.get("data"))
                _log(f"[任务] 回报 id={tid} ok={reported_ok} msg={str(body.get('message',''))[:90]}")
                self._reply(200, {"status": "ok" if ok else "unknown_task"})
            except Exception as e:
                self._reply(500, {"status": "error", "message": str(e)})
            return

        if path == "/plot":
            try:
                payload = self._read_json_body()
                symbol = str(payload.get("symbol", "")).strip().upper()
                positions = payload.get("positions") or {}
                saved, total = (0, 0)
                if positions:
                    saved, total = save_positions(positions)
                if not symbol:
                    self._reply(400, {"status": "error", "message": "no symbol"})
                    return
                ok, err = launch_chart(symbol)
                if ok:
                    self._reply(200, {"status": "ok", "symbol": symbol, "saved": saved, "total": total})
                else:
                    self._reply(500, {"status": "error", "message": err})
            except Exception as e:
                self._reply(500, {"status": "error", "message": str(e)})
            return

        self._reply(404, {"status": "error", "message": "not found"})

    def do_GET(self):
        parsed = urlparse(self.path)
        path = parsed.path
        qs = parse_qs(parsed.query)

        if path == "/ping":
            self._reply(200, {
                "status": "ok", "port": PORT, "python": PYTHON_EXEC,
                "chart_script_exists": os.path.exists(STOCK_CHART_PY),
                "wl_groups": WATCHLIST_GROUPS,
                "membership_exists": os.path.exists(WL_MEMBERSHIP_JSON_PATH),
                "membership_bytes": _file_size(WL_MEMBERSHIP_JSON_PATH),
                "wl_tasks_pending": pending_count(),
                "orders_bytes": _file_size(ORDERS_JSON_PATH),
                "orders_schema_default": "full_v1" if ORDER_VERBOSE_DEFAULT else "lean_v1",
                "earnings_release": EARNINGS_RELEASE_PATH,
                "earnings_release_exists": os.path.exists(EARNINGS_RELEASE_PATH),
                "sectors_source_enabled": ENABLE_SECTORS_SOURCE,
                "positions_bytes": _file_size(POSITIONS_JSON_PATH),
                "positions_bak_exists": os.path.exists(POSITIONS_JSON_PATH + ".bak"),
                "agent_last_poll_ago": (round(time.time() - _LAST_AGENT_POLL[0], 1)
                                        if _LAST_AGENT_POLL[0] else None),
            })
            return

        if path == "/wl_groups":
            self._reply(200, {"status": "ok", "groups": WATCHLIST_GROUPS, "url": WATCHLIST_URL})
            return

        if path == "/wl_tasks":
            _LAST_AGENT_POLL[0] = time.time()
            tasks = take_tasks(_qint(qs, "max", 3))
            self._reply(200, {"status": "ok", "tasks": tasks, "server_time": time.time()})
            return

        if path == "/wl_task":
            tid = qs.get("id", [""])[0]
            with _TASK_LOCK:
                t = _TASKS.get(tid)
                pub = _task_public(t) if t else None
            self._reply(200, pub or {"status": "error", "message": "unknown task"})
            return

        if path == "/wl_source":
            try:
                src = (qs.get("src", [DEFAULT_WL_SOURCE])[0] or DEFAULT_WL_SOURCE)
                fb = qs.get("fallback", ["0"])[0] == "1"
                self._reply(200, build_wl_source(src, back=_qint(qs, "back", 1),
                                                 ahead=_qint(qs, "ahead", 0), fallback=fb))
            except Exception as e:
                self._reply(500, {"status": "error", "message": str(e)})
            return

        if path == "/positions":
            self._reply(200, _load_json(POSITIONS_JSON_PATH))
            return

        if path == "/orders":
            self._reply(200, _load_json(ORDERS_JSON_PATH))
            return

        if path == "/wl_membership":
            self._reply(200, _load_json(WL_MEMBERSHIP_JSON_PATH))
            return

        if path == "/watchlist":
            self._reply(200, _load_json(WATCHLIST_JSON_PATH))
            return

        self._reply(404, {"status": "error", "message": "not found"})

    def log_message(self, fmt, *args):
        try:
            line = fmt % args
        except Exception:
            line = str(fmt)
        if "/wl_tasks" in line:
            return
        sys.stderr.write(f"[BridgeServer] {line}\n")


if __name__ == "__main__":
    _er = load_earnings_symbols()
    print("=" * 72)
    print(f"  Firstrade 本地桥接服务已启动: http://127.0.0.1:{PORT}")
    print(f"  远程添加支持全自动寻找与切换标签页")
    print("=" * 72, flush=True)
    server = ThreadingHTTPServer(("127.0.0.1", PORT), StockRequestHandler)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\n服务已停止。")
        server.server_close()

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
ft_quotes.py —— Firstrade 本地数据读取层（Chart_input.py）

数据来源（均由 Chrome 插件 + bridge_server.py 落盘）:
    Modules/firstrade_positions.json   持仓快照（覆盖式）
    Modules/firstrade_watchlist.json   自选股「变更%」快照（覆盖式，1800+ 只）

显示优先级（build_market_items）:
    1) 该 symbol 在持仓里  -> 显示 成本 / 损益 / 日 / 总 / 仓位
    2) 不在持仓、但在自选股 -> 显示 盘前变更% / 现价
    3) 都没有              -> 视 FT_SHOW_MISS 决定是否显示灰色占位
"""
import os
import re
import json
import time

USER_HOME = os.path.expanduser("~")
BASE_CODING_DIR = os.path.join(USER_HOME, "Coding")
MODULES_DIR = os.path.join(BASE_CODING_DIR, "Financial_System", "Modules")

FIRSTRADE_POSITIONS_FILE = os.path.join(MODULES_DIR, "firstrade_positions.json")
FIRSTRADE_WATCHLIST_FILE = os.path.join(MODULES_DIR, "firstrade_watchlist.json")

FT_DEBUG = os.environ.get("FT_DEBUG", "") == "1"
FT_SHOW_MISS = os.environ.get("FT_SHOW_MISS", "1") == "1"

# 自选股数据超过该小时数就打「N天前」标记
FT_STALE_HOURS = float(os.environ.get("FT_STALE_HOURS", "20"))

_CACHE = {}          # path -> (mtime, data)


# ----------------------------------------------------------------------
# 基础工具
# ----------------------------------------------------------------------
def _ft_norm_sym(s):
    """AAPL / brk.b / BRK-B 统一成大写且以 '-' 为分隔的形式"""
    return str(s).strip().upper().replace('.', '-')


def _norm_key(s):
    """比较用：去掉一切分隔符 BRK.B / BRK-B / BRKB -> BRKB"""
    return re.sub(r'[^A-Z0-9]', '', str(s).strip().upper())


def _load_json_cached(path):
    """按 mtime 缓存，避免 matplotlib 频繁重画时反复读盘"""
    try:
        mtime = os.path.getmtime(path) if os.path.exists(path) else 0.0
    except Exception:
        mtime = 0.0
    ent = _CACHE.get(path)
    if ent and ent[0] == mtime:
        return ent[1]
    data = {}
    if mtime:
        try:
            with open(path, 'r', encoding='utf-8') as f:
                loaded = json.load(f)
            if isinstance(loaded, dict):
                data = loaded
        except Exception as e:
            print(f"[FT] 读取 {os.path.basename(path)} 失败: {e}")
    _CACHE[path] = (mtime, data)
    return data


def _num(s):
    try:
        m = re.search(r'[-+]?\d[\d,]*\.?\d*', str(s).replace(' ', ''))
        return float(m.group(0).replace(',', '')) if m else None
    except Exception:
        return None


def _fmt_money(s):
    v = _num(s)
    if v is None:
        return str(s)
    if abs(v) >= 1e6:
        return f"{v/1e6:.2f}M"
    if abs(v) >= 1e3:
        return f"{v/1e3:.1f}K"
    return f"{v:.0f}"


def _fmt_gainloss_amount(s):
    """损益金额格式化：自动带正负号，并兼顾大额缩写"""
    v = _num(s)
    if v is None:
        return str(s)
    if abs(v) >= 1e6:
        return f"{v/1e6:+.2f}M"
    if abs(v) >= 1e3:
        return f"{v/1e3:+.1f}K"
    return f"{v:+.2f}"


def _age_hours(ts):
    """兼容秒 / 毫秒时间戳"""
    try:
        t = float(ts)
    except Exception:
        return None
    if t <= 0:
        return None
    if t > 1e11:          # 毫秒
        t /= 1000.0
    return (time.time() - t) / 3600.0


def _sign_color(s, theme):
    v = _num(s)
    if v is None:
        return theme['text_bright']
    if v > 0:
        return theme['accent_red']        # 红涨
    if v < 0:
        return theme['accent_green']      # 绿跌
    return theme['text_bright']


# ----------------------------------------------------------------------
# 持仓
# ----------------------------------------------------------------------
def get_firstrade_position(symbol):
    """读取插件回传的真实持仓数据，返回 dict 或 None"""
    if not symbol:
        return None
    data = _load_json_cached(FIRSTRADE_POSITIONS_FILE)
    if not data:
        if FT_DEBUG:
            print(f"[FT] 持仓文件为空或不存在: {FIRSTRADE_POSITIONS_FILE}")
        return None
    meta_ts = (data.get('_meta') or {}).get('updated_at')
    target = _norm_key(symbol)
    for k, v in data.items():
        if str(k).startswith('_') or not isinstance(v, dict):
            continue
        if _norm_key(k) == target:
            out = dict(v)
            out.setdefault('symbol', str(k).upper())
            if not out.get('updated_at'):        # ★ 逐条 updated_at 已取消，从 _meta 回填
                out['updated_at'] = meta_ts
            if FT_DEBUG:
                print(f"[FT] 命中持仓 {k}: {out}")
            return out
    if FT_DEBUG:
        keys = [k for k in data.keys() if not str(k).startswith('_')]
        print(f"[FT] 持仓未找到 {symbol}（共 {len(keys)} 条）: {keys[:25]}")
    return None


# ----------------------------------------------------------------------
# 自选股行情（变更%）
# ----------------------------------------------------------------------
def get_watchlist_quote(symbol):
    """返回 {'symbol','change_pct','change_pct_num','last','updated_at'} 或 None"""
    if not symbol:
        return None
    data = _load_json_cached(FIRSTRADE_WATCHLIST_FILE)
    if not data:
        return None
    quotes = data.get('quotes')
    if not isinstance(quotes, dict):
        quotes = {k: v for k, v in data.items()
                  if isinstance(v, dict) and not str(k).startswith('_')}
    target = _norm_key(symbol)
    meta_ts = (data.get('_meta') or {}).get('updated_at')
    for k, v in quotes.items():
        if not isinstance(v, dict):
            continue
        if _norm_key(k) == target:
            out = dict(v)
            out.setdefault('symbol', str(k).upper())
            if not out.get('updated_at'):
                out['updated_at'] = meta_ts
            if FT_DEBUG:
                print(f"[FT] 命中自选股行情 {k}: {out}")
            return out
    if FT_DEBUG:
        print(f"[FT] 自选股行情未找到 {symbol}（共 {len(quotes)} 条）")
    return None


# ----------------------------------------------------------------------
# 供图表副标题使用：[(文本, 颜色, 粗细), ...]
# ----------------------------------------------------------------------
def _items_from_position(pos, theme):
    raw = pos.get('raw') or {}

    def _pick(*keys):
        for k in keys:
            v = pos.get(k)
            if v not in (None, '', '--'):
                return str(v)
        for k in keys:
            v = raw.get(k)
            if v not in (None, '', '--'):
                return str(v)
        return None

    cost_val = _pick('cost', 'totalCost')

    # 优先获取金额型损益，若从 raw.gainloss 取，需确认不是百分比字符串
    gl_amt_val = _pick('gainloss_amount')
    if not gl_amt_val:
        raw_gl = raw.get('gainloss')
        if raw_gl not in (None, '', '--') and not str(raw_gl).strip().endswith('%'):
            gl_amt_val = str(raw_gl)

    day_val = _pick('day_change', 'changePercent')
    gl_val = _pick('gainloss', 'gainlossPercent')
    alloc_val = _pick('allocation', 'allocationPercent')

    items = []
    if cost_val:
        items.append((f"成本 {_fmt_money(cost_val)}", theme['accent_yellow'], 'bold'))
    if gl_amt_val:
        items.append((f"损益 {_fmt_gainloss_amount(gl_amt_val)}", _sign_color(gl_amt_val, theme), 'bold'))
    if day_val:
        items.append((f"日{day_val}", _sign_color(day_val, theme), 'bold'))
    if gl_val:
        items.append((f"总{gl_val}", _sign_color(gl_val, theme), 'bold'))
    if alloc_val:
        items.append((f"仓{alloc_val}", theme['accent_cyan'], 'normal'))

    age = _age_hours(pos.get('updated_at'))
    if age is not None and age > FT_STALE_HOURS:
        items.append((f"({age/24:.0f}天前)", theme['border'], 'normal'))
    return items


def _items_from_watchlist(q, theme):
    txt = q.get('change_pct')
    if txt in (None, '', '--'):
        n = q.get('change_pct_num')
        txt = f"{float(n):+.2f}%" if isinstance(n, (int, float)) else None
    if not txt:
        return []

    items = [(f"盘前 {txt}", _sign_color(txt, theme), 'bold')]
    last = q.get('last')
    if last not in (None, '', '--'):
        items.append((f"现价 {last}", theme['text_light'], 'normal'))

    age = _age_hours(q.get('updated_at'))
    if age is not None and age > FT_STALE_HOURS:
        items.append((f"({age/24:.0f}天前)", theme['border'], 'normal'))
    return items


def build_market_items(symbol, theme, show_miss=None):
    """
    图表副标题左侧一行的内容。
    持仓优先；无持仓则用自选股「变更%」；都没有按 show_miss 决定占位。
    """
    if show_miss is None:
        show_miss = FT_SHOW_MISS

    pos = get_firstrade_position(symbol)
    if pos:
        items = _items_from_position(pos, theme)
        if items:
            return items

    q = get_watchlist_quote(symbol)
    if q:
        items = _items_from_watchlist(q, theme)
        if items:
            return items

    if show_miss:
        return [("持仓/自选: 无数据", theme['border'], 'normal')]
    return []

# ----------------------------------------------------------------------
# 供 Check_Group.py 使用：整份持仓 + 数值解析 + 格式化
# ----------------------------------------------------------------------
def load_all_positions():
    """返回 (positions: {SYMBOL: rec}, meta: dict)；symbol 统一为大写 '-' 形式"""
    data = _load_json_cached(FIRSTRADE_POSITIONS_FILE)
    meta = data.get('_meta') or {}
    out = {}
    for k, v in data.items():
        if str(k).startswith('_') or not isinstance(v, dict):
            continue
        sym = _ft_norm_sym(v.get('symbol') or k)
        if not sym:
            continue
        rec = dict(v)
        rec['symbol'] = sym
        if not rec.get('updated_at'):
            rec['updated_at'] = meta.get('updated_at')
        out[sym] = rec
    return out, meta


def position_num(rec, *keys):
    """按优先级从记录里取第一个可解析成数字的字段（'+7.16%' -> 7.16, '6,000.00' -> 6000.0）"""
    if not isinstance(rec, dict):
        return None
    for k in keys:
        v = rec.get(k)
        if v in (None, '', '--'):
            continue
        n = _num(v)
        if n is not None:
            return n
    return None


def fmt_money(s):
    """6,000.00 -> 6.0K / 1,234,567 -> 1.23M"""
    return _fmt_money(s)


def fmt_signed(s):
    return _fmt_gainloss_amount(s)

# ----------------------------------------------------------------------
# 自选股「分组归属」：该 symbol 在 Firstrade 哪些 watchlist 分组里
#   数据：Modules/firstrade_wl_membership.json（bridge_server.py 写入）
# ----------------------------------------------------------------------
FIRSTRADE_WL_MEMBERSHIP_FILE = os.path.join(MODULES_DIR, "firstrade_wl_membership.json")
FT_MEMBER_STALE_HOURS = float(os.environ.get("FT_MEMBER_STALE_HOURS", "72"))
_MEMBER_INDEX = {"mtime": None, "index": {}, "order": [], "groups": {}}


def membership_signature():
    """文件 mtime，图表用它判断是否需要重画归属行"""
    try:
        return os.path.getmtime(FIRSTRADE_WL_MEMBERSHIP_FILE) if os.path.exists(FIRSTRADE_WL_MEMBERSHIP_FILE) else 0.0
    except Exception:
        return 0.0


def _membership_index():
    data = _load_json_cached(FIRSTRADE_WL_MEMBERSHIP_FILE)
    mtime = (_CACHE.get(FIRSTRADE_WL_MEMBERSHIP_FILE) or (None,))[0]
    if _MEMBER_INDEX["mtime"] is not None and _MEMBER_INDEX["mtime"] == mtime:
        return _MEMBER_INDEX
    groups = data.get('groups') if isinstance(data.get('groups'), dict) else {}
    idx = {}
    for g, rec in groups.items():
        if not isinstance(rec, dict):
            continue
        for s in rec.get('symbols') or []:
            idx.setdefault(_norm_key(s), []).append(g)
    page = [str(x) for x in (data.get('page_groups') or []) if str(x) in groups]
    order = page + sorted(g for g in groups if g not in page)
    _MEMBER_INDEX.update({"mtime": mtime, "index": idx, "order": order,
                          "groups": {g: groups[g] for g in order if isinstance(groups[g], dict)}})
    return _MEMBER_INDEX


def get_watchlist_membership(symbol):
    """返回 {'groups': [所在分组], 'unsure': [未完整扫描且未命中的分组], 'oldest_age_h': float}
       无任何归属数据时返回 None"""
    if not symbol:
        return None
    ix = _membership_index()
    if not ix["groups"]:
        return None
    hit = set(ix["index"].get(_norm_key(symbol), []))
    inside = [g for g in ix["order"] if g in hit]
    unsure = [g for g in ix["order"] if g not in hit and not ix["groups"].get(g, {}).get('complete')]
    ages = [_age_hours(rec.get('updated_at')) for rec in ix["groups"].values()]
    ages = [a for a in ages if a is not None]
    if FT_DEBUG:
        print(f"[FT] 分组归属 {symbol}: {inside} 未全扫 {unsure}")
    return {"groups": inside, "unsure": unsure, "oldest_age_h": max(ages) if ages else None}


def _group_color(name, theme):
    n = str(name)
    low = n.lower()
    if 'short' in low:
        return theme['accent_purple']
    if '卖' in n:
        return theme['accent_green']
    if '买' in n:
        return theme['accent_red']
    if low == 'watch':
        return theme['accent_cyan']
    if n.upper() == 'ALL':
        return theme['accent_yellow']
    return theme['accent_orange']


def build_membership_items(symbol, theme):
    """图表第三行：[(文本, 颜色, 粗细), ...]"""
    m = get_watchlist_membership(symbol)
    if m is None:
        return [("自选: 未同步(按M扫描)", theme['border'], 'normal')]
    items = []
    if m['groups']:
        items.append(("自选", theme['text_light'], 'normal'))
        for g in m['groups']:
            items.append((f"[{g}]", _group_color(g, theme), 'bold'))
            # 第 4 个元素 = 可点击动作：Chart_input 渲染成红色小按钮，点击后从该分组删除
            items.append(("×", theme['accent_red'], 'bold', ('wl_remove', g)))
    else:
        items.append(("自选: 未加入", theme['border'], 'normal'))
    if m['unsure']:
        tail = '/'.join(m['unsure'][:3]) + ('…' if len(m['unsure']) > 3 else '')
        items.append((f"(未全扫:{tail})", theme['border'], 'normal'))
    age = m.get('oldest_age_h')
    if age is not None and age > FT_MEMBER_STALE_HOURS:
        items.append((f"(最旧{age/24:.0f}天前,按M刷新)", theme['border'], 'normal'))
    return items

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Firstrade 买入/卖出痕迹读取与聚合（供 Chart_input.py）

数据来源: ~/Coding/Financial_System/Modules/firstrade_orders.json

★ 同时兼容两种 schema：
  LEAN (v6+，默认，体积小 90%)
    { "symbol":"KRMN","side":"buy","date":"2026-09-10",
      "amount":1000,"price":34.79,"st":"F" }
      st: F=已成交 C=取消/拒绝 P=待成交 X=未知
  FULL (旧版，含 raw / datetime / status 等)

环境变量:
  FT_TRADE_DEBUG=1        打印调试信息
  FT_ORDER_INCLUDE_ALL=1  连"已取消/已拒绝"的订单也画出来（默认剔除）
  FT_ORDER_ONLY_FILLED=1  只画已成交(st=F)，挂单/未知一律不画
"""
import os
import re
import json
from datetime import datetime

USER_HOME = os.path.expanduser("~")
BASE_CODING_DIR = os.path.join(USER_HOME, "Coding")
ORDERS_FILE = os.path.join(BASE_CODING_DIR, "Financial_System", "Modules", "firstrade_orders.json")

# 图上颜色/形状
BUY_COLOR = '#5E81AC'      # 蓝色 ▲ 买入
SELL_COLOR = '#D08770'     # 橙色 ▼ 卖出
BUY_MARKER = '^'
SELL_MARKER = 'v'

FT_TRADE_DEBUG = os.environ.get("FT_TRADE_DEBUG", "") == "1"
FT_ORDER_INCLUDE_ALL = os.environ.get("FT_ORDER_INCLUDE_ALL", "") == "1"
FT_ORDER_ONLY_FILLED = os.environ.get("FT_ORDER_ONLY_FILLED", "") == "1"

_FILL_RE = re.compile(r"已成交|已执行|成交|filled|executed|partial", re.I)
_CANCEL_RE = re.compile(r"取消|撤销|撤单|拒绝|失效|过期|无效|作废|cancel|reject|expire|void", re.I)
_PEND_RE = re.compile(r"待|挂单|未成交|排队|已提交|open|pending|queued|working|accept", re.I)

_ST_LABEL = {'F': '已成交', 'C': '已取消', 'P': '待成交', 'X': ''}

_CACHE = {"mtime": None, "map": None}


# ----------------------------------------------------------------------
def _norm_sym(s):
    return str(s).strip().upper().replace('.', '-')


def _to_float(v):
    if v is None:
        return None
    if isinstance(v, (int, float)):
        return float(v)
    m = re.search(r'-?\d[\d,]*\.?\d*', str(v).replace(' ', ''))
    return float(m.group(0).replace(',', '')) if m else None


def _to_date(s):
    if not s:
        return None
    head = str(s).split(',')[0].strip()
    for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y/%m/%d", "%m/%d/%y"):
        try:
            return datetime.strptime(head, fmt).date()
        except ValueError:
            continue
    return None


def _status_code(o):
    """LEAN 用 st 字段；FULL 回落到文本正则"""
    st = o.get('st') or o.get('status_code')
    if isinstance(st, str) and st.strip():
        c = st.strip()[:1].upper()
        if c in ('F', 'C', 'P', 'X'):
            return c
    raw = o.get('raw') if isinstance(o.get('raw'), dict) else {}
    txt = "{} {} {}".format(o.get('status', ''), o.get('status_text', ''),
                            raw.get('statusCategory', ''))
    if _FILL_RE.search(txt):
        return 'F'
    if _CANCEL_RE.search(txt):
        return 'C'
    if _PEND_RE.search(txt):
        return 'P'
    return 'X'


def _is_effective(order):
    if FT_ORDER_INCLUDE_ALL:
        return True
    code = _status_code(order)
    if FT_ORDER_ONLY_FILLED:
        return code == 'F'
    return code != 'C'


def _load_orders_raw():
    if not os.path.exists(ORDERS_FILE):
        if FT_TRADE_DEBUG:
            print(f"[FT-TRADE] 订单文件不存在: {ORDERS_FILE}")
        return {}
    try:
        with open(ORDERS_FILE, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except Exception as e:
        print(f"[FT-TRADE] 读取订单文件失败: {e}")
        return {}
    if not isinstance(data, dict):
        return {}
    orders = data.get('orders')
    if isinstance(orders, dict):
        return orders
    return {k: v for k, v in data.items()
            if isinstance(v, dict) and not str(k).startswith('_')}


# ----------------------------------------------------------------------
def load_trade_map(force=False):
    """返回 { 'AAPL': { date: {'buy': agg, 'sell': agg} } }
       agg = {'amount': float|None, 'quantity': float, 'count': int, 'items': [...]}"""
    try:
        mtime = os.path.getmtime(ORDERS_FILE) if os.path.exists(ORDERS_FILE) else 0
    except OSError:
        mtime = 0
    if (not force) and _CACHE["map"] is not None and _CACHE["mtime"] == mtime:
        return _CACHE["map"]

    out = {}
    skipped = 0
    for _key, o in _load_orders_raw().items():
        if not isinstance(o, dict):
            continue
        if not _is_effective(o):
            skipped += 1
            continue

        sym = _norm_sym(o.get('symbol', ''))
        d = _to_date(o.get('date') or o.get('datetime') or o.get('updated'))
        side = str(o.get('side', '')).strip().lower()
        if side not in ('buy', 'sell'):
            t = str(o.get('side_text') or o.get('transaction') or '')
            if re.search(r'买|buy|bought', t, re.I):
                side = 'buy'
            elif re.search(r'卖|sell|sold', t, re.I):
                side = 'sell'
            else:
                continue
        if not sym or d is None:
            continue

        amount = _to_float(o.get('amount'))
        qty = _to_float(o.get('quantity') if o.get('quantity') is not None else o.get('qty'))
        price = _to_float(o.get('price'))
        if amount is None and qty and price:
            amount = qty * price

        code = _status_code(o)
        node = out.setdefault(sym, {}).setdefault(d, {})
        agg = node.setdefault(side, {'amount': None, 'quantity': 0.0, 'count': 0, 'items': []})
        if amount is not None:
            agg['amount'] = (agg['amount'] or 0.0) + amount
        if qty:
            agg['quantity'] += qty
        agg['count'] += 1
        agg['items'].append({
            'time': str(o.get('datetime') or o.get('date') or ''),
            'quantity': qty,
            'amount': amount,
            'price': price,
            'status': str(o.get('status') or _ST_LABEL.get(code, '')),
            'price_type': str(o.get('price_type', '')),
            'source': str(o.get('amount_source', '')),
        })

    for sym in out:
        for d in out[sym]:
            for side in out[sym][d]:
                out[sym][d][side]['items'].sort(key=lambda x: x.get('time') or '')

    if FT_TRADE_DEBUG:
        print(f"[FT-TRADE] 载入 {sum(len(v) for v in out.values())} 个交易日，"
              f"覆盖 {len(out)} 只标的，剔除无效 {skipped} 笔")

    _CACHE["mtime"] = mtime
    _CACHE["map"] = out
    return out


def get_trades_for_symbol(symbol):
    """返回 { date: {'buy': agg, 'sell': agg} }；兼容 BRK.B / BRK-B"""
    if not symbol:
        return {}
    return load_trade_map().get(_norm_sym(symbol), {})


# ----------------------------------------------------------------------
def fmt_money(v):
    if v is None:
        return '--'
    a = abs(v)
    if a >= 1e6:
        return f"${v/1e6:.2f}M"
    if a >= 1e3:
        return f"${v/1e3:.1f}K"
    return f"${v:.0f}"


def short_trade_label(side, agg, close_price=None):
    """一行短标签，给 hover 汇总用：'买入 $3.1K'"""
    amount = agg.get('amount')
    est = False
    if amount is None and agg.get('quantity') and close_price:
        amount = float(agg['quantity']) * float(close_price)
        est = True
    label = '买入' if side == 'buy' else '卖出'
    return f"{label} {fmt_money(amount)}{'(估)' if est else ''}"


def build_marker_text(side, d, agg, close_price=None):
    """浮框完整文案"""
    label = '买入' if side == 'buy' else '卖出'
    amount = agg.get('amount')
    est = False
    if amount is None and agg.get('quantity') and close_price:
        amount = float(agg['quantity']) * float(close_price)
        est = True

    day = d.isoformat() if hasattr(d, 'isoformat') else str(d)
    lines = [f"● {label}  {day}"]

    money = fmt_money(amount) + ('(按收盘价估算)' if est else '')
    qty = agg.get('quantity') or 0
    lines.append(f"{money}" + (f"  /  {qty:.0f}股" if qty else ""))

    cnt = agg.get('count', 1)
    if cnt > 1:
        lines.append(f"当日共 {cnt} 笔")
        for it in agg.get('items', [])[:5]:
            bits = []
            if it.get('quantity'):
                bits.append(f"{it['quantity']:.0f}股")
            if it.get('amount') is not None:
                bits.append(fmt_money(it['amount']))
            if it.get('price'):
                bits.append(f"@{it['price']:.2f}")
            if it.get('status'):
                bits.append(str(it['status']))
            if bits:
                lines.append("  · " + " ".join(bits))
    else:
        it = (agg.get('items') or [{}])[0]
        bits = []
        if it.get('price'):
            bits.append(f"@{it['price']:.2f}")
        if it.get('status'):
            bits.append(str(it['status']))
        if bits:
            lines.append("  · " + " ".join(bits))
    return "\n".join(lines)

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
ft_watchlist_add.py —— Python 侧「一键把 symbol 加入 Firstrade 自选股分组」客户端
自动寻找与唤醒 Chrome /app/watchlist 页面，保证后台添加绝对通畅。
"""
import os
import re
import sys
import json
import threading
import subprocess
from urllib import request

BRIDGE_BASE = os.environ.get("FT_BRIDGE", "http://127.0.0.1:18888")

USER_HOME = os.path.expanduser("~")
MODULES_DIR = os.path.join(USER_HOME, "Coding", "Financial_System", "Modules")
GROUPS_FILE = os.path.join(MODULES_DIR, "ft_watchlist_groups.json")
LAST_FILE = os.path.join(MODULES_DIR, "ft_watchlist_last_group.txt")

DEFAULT_GROUPS = ["买", "买买", "买买买", "卖卖卖", "Short", "Watch", "ALL"]


def watchlist_groups():
    try:
        if os.path.exists(GROUPS_FILE):
            with open(GROUPS_FILE, "r", encoding="utf-8") as f:
                data = json.load(f)
            arr = data.get("groups") if isinstance(data, dict) else data
            arr = [str(x).strip() for x in (arr or []) if str(x).strip()]
            if arr:
                return arr
    except Exception as e:
        print(f"[FT-WL] 读取 {GROUPS_FILE} 失败: {e}")
    env = os.environ.get("FT_WL_GROUPS", "").strip()
    if env:
        arr = [s.strip() for s in re.split(r"[,\s;]+", env) if s.strip()]
        if arr:
            return arr
    return list(DEFAULT_GROUPS)


def last_group():
    try:
        if os.path.exists(LAST_FILE):
            with open(LAST_FILE, "r", encoding="utf-8") as f:
                g = f.read().strip()
            if g:
                return g
    except Exception:
        pass
    return ""


def save_last_group(group):
    try:
        os.makedirs(MODULES_DIR, exist_ok=True)
        with open(LAST_FILE, "w", encoding="utf-8") as f:
            f.write(str(group or "").strip())
    except Exception:
        pass


def _post(path, payload, timeout=20):
    url = BRIDGE_BASE.rstrip("/") + path
    data = json.dumps(payload, ensure_ascii=False).encode("utf-8")
    req = request.Request(url, data=data,
                          headers={"Content-Type": "application/json"}, method="POST")
    with request.urlopen(req, timeout=timeout) as r:
        return json.loads(r.read().decode("utf-8"))


def _get(path, timeout=5):
    url = BRIDGE_BASE.rstrip("/") + path
    with request.urlopen(url, timeout=timeout) as r:
        return json.loads(r.read().decode("utf-8"))


def ping():
    try:
        return _get("/ping", timeout=3)
    except Exception:
        return None


def _symbol_task(path, action, symbol, group, wait, restore):
    symbol = str(symbol or "").strip().upper()
    group = str(group or "").strip()
    out = {"ok": False, "symbol": symbol, "group": group, "action": action, "message": ""}
    if not symbol:
        out["message"] = "symbol 为空"
        return out
    if action == "remove" and not group:
        out["message"] = "删除必须指定分组"
        return out
    try:
        r = _post(path, {"symbol": symbol, "group": group,
                         "wait": max(1, int(wait)), "restore": bool(restore)},
                  timeout=int(wait) + 20)
    except Exception as e:
        out["message"] = (f"连不上本地桥接服务 {BRIDGE_BASE}：{e}\n"
                          f"请先在终端运行 bridge_server.py")
        return out
    out["ok"] = bool(r.get("ok"))
    out["message"] = r.get("message") or (("已加入" if action == "add" else "已删除")
                                          if out["ok"] else "未收到浏览器回报")
    out["raw"] = r
    return out


def _run_async(fn, on_done, *args, **kw):
    def _run():
        res = fn(*args, **kw)
        if callable(on_done):
            try:
                on_done(res)
            except Exception as e:
                print(f"[FT-WL] on_done 回调异常: {e}")
    th = threading.Thread(target=_run, daemon=True)
    th.start()
    return th


def add_symbol(symbol, group, wait=45, restore=True):
    """阻塞式：把 symbol 加进 group（自动唤醒 Chrome 里的 Watchlist 页面）"""
    return _symbol_task("/wl_add", "add", symbol, group, wait, restore)


def add_symbol_async(symbol, group, on_done=None, wait=45, restore=True):
    return _run_async(add_symbol, on_done, symbol, group, wait=wait, restore=restore)


def remove_symbol(symbol, group, wait=90, restore=True):
    """阻塞式：把 symbol 从 group 删除（浏览器自动切分组 → 三点菜单 → 删除）"""
    return _symbol_task("/wl_remove", "remove", symbol, group, wait, restore)


def remove_symbol_async(symbol, group, on_done=None, wait=90, restore=True):
    return _run_async(remove_symbol, on_done, symbol, group, wait=wait, restore=restore)

def scan_groups(groups=None, wait=300):
    """阻塞式：让浏览器逐个分组扫描归属，结果写入 firstrade_wl_membership.json"""
    out = {"ok": False, "symbol": "", "group": "全部分组", "message": ""}
    payload = {"wait": max(1, int(wait))}
    if groups:
        payload["groups"] = [str(g) for g in groups if str(g).strip()]
    try:
        r = _post("/wl_scan_groups", payload, timeout=int(wait) + 20)
    except Exception as e:
        out["message"] = f"连不上本地桥接服务 {BRIDGE_BASE}：{e}\n请先在终端运行 bridge_server.py"
        return out
    out["ok"] = bool(r.get("ok"))
    out["message"] = r.get("message") or ("分组归属已刷新" if out["ok"] else "未收到浏览器回报")
    out["raw"] = r
    return out


def scan_groups_async(on_done=None, groups=None, wait=300):
    def _run():
        res = scan_groups(groups=groups, wait=wait)
        if callable(on_done):
            try:
                on_done(res)
            except Exception as e:
                print(f"[FT-WL] on_done 回调异常: {e}")
    th = threading.Thread(target=_run, daemon=True)
    th.start()
    return th


def notify_mac(title, text, subtitle=None):
    if sys.platform != "darwin":
        return
    def esc(s):
        return str(s).replace("\\", "\\\\").replace('"', '\\"').replace("\n", " ")
    parts = [f'display notification "{esc(text)}" with title "{esc(title)}"']
    if subtitle:
        parts.append(f'subtitle "{esc(subtitle)}"')
    try:
        subprocess.Popen(["osascript", "-e", " ".join(parts)])
    except Exception:
        pass


def choose_group_dialog(symbol, groups=None, parent=None, title=None):
    try:
        from PyQt6.QtWidgets import (QApplication, QDialog, QVBoxLayout,
                                     QLabel, QPushButton)
        from PyQt6.QtGui import QFont
        from PyQt6.QtCore import Qt
    except Exception as e:
        print(f"[FT-WL] 无法加载 PyQt6，无法弹出选择框: {e}")
        return None

    groups = groups or watchlist_groups()
    if not groups:
        return None

    app = QApplication.instance()
    if app is None:
        app = QApplication(sys.argv)

    prev = last_group()

    class _Chooser(QDialog):
        def __init__(self):
            super().__init__(parent)
            self.picked = None
            self.setWindowTitle(title or f"把 {symbol} 加入自选股分组")
            self.setWindowFlag(Qt.WindowType.WindowStaysOnTopHint, True)
            lay = QVBoxLayout(self)
            lay.setContentsMargins(18, 16, 18, 16)
            lay.setSpacing(8)

            head = QLabel(f"{symbol}  →  选择目标分组")
            head.setFont(QFont("Arial Unicode MS", 16, QFont.Weight.Bold))
            head.setAlignment(Qt.AlignmentFlag.AlignCenter)
            lay.addWidget(head)

            for i, g in enumerate(groups[:9], start=1):
                mark = "  ←上次" if g == prev else ""
                b = QPushButton(f"{i}.  {g}{mark}")
                b.setFont(QFont("Arial Unicode MS", 15))
                b.setMinimumHeight(38)
                b.clicked.connect(lambda _=False, gg=g: self._pick(gg))
                if g == prev:
                    b.setDefault(True)
                    b.setFocus()
                lay.addWidget(b)

            tip = QLabel("按 1~9 直接选择 ｜ Esc 取消")
            tip.setAlignment(Qt.AlignmentFlag.AlignCenter)
            tip.setStyleSheet("color:#81A1C1; font-size:12px;")
            lay.addWidget(tip)

            self.setStyleSheet("""
                QDialog { background-color:#2E3440; }
                QLabel { color:#ECEFF4; }
                QPushButton {
                    background-color:#3B4252; color:#ECEFF4;
                    border:1px solid #4C566A; border-radius:6px;
                    padding:6px 12px; text-align:left;
                }
                QPushButton:hover { background-color:#4C566A; }
                QPushButton:default { border:2px solid #88C0D0; }
            """)

        def _pick(self, g):
            self.picked = g
            self.accept()

        def keyPressEvent(self, e):
            k = e.key()
            if k == Qt.Key.Key_Escape:
                self.picked = None
                self.reject()
                return
            if Qt.Key.Key_1 <= k <= Qt.Key.Key_9:
                idx = k - Qt.Key.Key_1
                if idx < len(groups):
                    self._pick(groups[idx])
                    return
            super().keyPressEvent(e)

    dlg = _Chooser()
    dlg.exec()
    return dlg.picked


if __name__ == "__main__":
    sym = (sys.argv[1] if len(sys.argv) > 1 else "AAPL").upper()
    grp = sys.argv[2] if len(sys.argv) > 2 else watchlist_groups()[0]
    print(f"桥接状态: {'OK' if ping() else '不可用'}")
    print(f"提交: {sym} -> {grp}")
    print(add_symbol(sym, grp, wait=45))

