/* ============================================================================
 * Firstrade 助手 content script v5.2 (去除 Popover 浮窗，纯点击响应)
 *  1) Tag 徽章 + 一键看图（纯展示）
 *  2) 持仓抓取：仅 /app/positions      —— 开关 ftAutoPositions
 *  3) 订单痕迹：仅 /app/order-status    —— 开关 ftAutoOrders
 *     ★ 订单 LEAN schema：只回传 date/symbol/side/quantity/amount/price/st
 *       体积比老版本降约 90%；勾选 ftOrderVerbose 可恢复完整字段
 *  ★ 自选股（/app/watchlist）的抓取与批量补齐由 watchlist.js 负责
 *  ★ 三个自动开关互相独立，默认全部关闭
 * ==========================================================================*/
(() => {
  if (window.__FT_TAG_HELPER_V5__) return;
  window.__FT_TAG_HELPER_V5__ = true;

  const LOG_PREFIX = '[FT]';
  let DEBUG = false;
  let AUTO_POSITIONS = false;     // ★ 独立开关
  let AUTO_ORDERS = false;        // ★ 独立开关
  let ORDER_VERBOSE = false;      // ★ 订单是否保存完整字段（默认精简）
  let stockTagMap = {};
  let maxTags = 2;

  const log = (...a) => { if (DEBUG) console.log(LOG_PREFIX, ...a); };
  const sleep = (ms) => new Promise(r => setTimeout(r, ms));

  /* ==================== 0. 页面闸门（双重校验） ==================== */
  const PAGE_RULES = [
    { key: 'positions', re: /\/positions?(\/|$|\?|#)/i },
    { key: 'orders', re: /\/order-status/i },
    { key: 'watchlist', re: /\/watchlist/i }
  ];

  function detectPage() {
    const p = (location.pathname || '').toLowerCase();
    for (const r of PAGE_RULES) if (r.re.test(p)) return r.key;
    return null;
  }
  let PAGE = detectPage();

  const POSITION_COL_HINTS = ['allocationPercent', 'marketValue', 'gainlossPercent',
    'totalCost', 'changePercent', 'quantity', 'averageCost'];

  function colIdSet() {
    const s = new Set();
    document.querySelectorAll('[col-id]').forEach(el => s.add(el.getAttribute('col-id')));
    return s;
  }

  function gridLooksLike(kind) {
    const s = colIdSet();
    if (!s.has('symbol')) return false;
    if (kind === 'positions') {
      if (s.has('transaction') || s.has('statusCategory') || s.has('durationType')) return false;
      return POSITION_COL_HINTS.filter(c => s.has(c)).length >= 2;
    }
    if (kind === 'orders') {
      if (!s.has('transaction')) return false;
      return s.has('statusCategory') || s.has('limitPrice') || s.has('durationType');
    }
    return false;
  }

  const canScrapePositions = () => PAGE === 'positions' && gridLooksLike('positions');
  const canScrapeOrders = () => PAGE === 'orders' && gridLooksLike('orders');

  /* 自选股自动化进行中 → 暂停一切 DOM 注入，减少干扰 */
  const automationBusy = () => window.__FT_AUTOMATION__ === true;

  /* ==================== 1. 缓存与通用工具 ==================== */
  const positionCache = Object.create(null);
  const orderCache = Object.create(null);
  let lastSentSig = '';
  let lastOrderSig = '';
  let syncTimer = null;
  let orderSyncTimer = null;

  /* ★ 白名单：只有这里列出的列才会落盘（顶层别名字段即最终 schema） */
  const COL_ALIAS = {
    quantity: 'quantity',
    changePercent: 'day_change',
    change: 'day_change_amount',
    gainlossPercent: 'gainloss',
    gainloss: 'gainloss_amount',
    totalCost: 'cost',
    allocationPercent: 'allocation',
    marketValue: 'market_value',
    price: 'last_price',
    lastPrice: 'last_price',
    averageCost: 'avg_cost',
    avgCost: 'avg_cost'
  };

  /* ★ 黑名单：这些列里是内嵌图表/样式表文本，体积大且无用 */
  const POSITION_COL_BLACKLIST = new Set(
    ['dayTrend', 'trend', 'chart', 'sparkline', 'actions', 'menu']);
  const MAX_CELL_LEN = 40;    // 超过这个长度的单元格文本一律视为噪音

  /* 持仓内容级签名（用于判断是否有变化） */
  function posSig(p) {
    if (!p) return '';
    return [p.cost, p.day_change, p.gainloss, p.gainloss_amount,
    p.quantity, p.market_value, p.allocation, p.avg_cost].join('|');
  }

  function safeSendMessage(msg) {
    return new Promise((resolve) => {
      try {
        chrome.runtime.sendMessage(msg, (resp) => {
          if (chrome.runtime.lastError) {
            resolve({ ok: false, error: chrome.runtime.lastError.message });
            return;
          }
          resolve(resp || { ok: false, error: 'no response' });
        });
      } catch (e) { resolve({ ok: false, error: String(e) }); }
    });
  }

  function cleanText(el) {
    let t = (el.innerText || el.textContent || '');
    return t.replace(/\u00a0/g, ' ')
      .replace(/\s+/g, ' ')
      .replace(/(\d),\s+(\d)/g, '$1,$2')
      .trim();
  }

  const toNum = (s) => {
    if (s === null || s === undefined) return null;
    const m = String(s).replace(/\s/g, '').match(/-?\d[\d,]*\.?\d*/);
    return m ? parseFloat(m[0].replace(/,/g, '')) : null;
  };

  const pad2 = (n) => String(parseInt(n, 10)).padStart(2, '0');

  function parseUpdatedDate(txt) {
    if (!txt) return '';
    const head = String(txt).split(',')[0].trim();
    let m = head.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
    if (m) return `${m[3]}-${pad2(m[1])}-${pad2(m[2])}`;
    m = head.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
    if (m) return `${m[1]}-${pad2(m[2])}-${pad2(m[3])}`;
    m = head.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2})$/);
    if (m) return `20${m[3]}-${pad2(m[1])}-${pad2(m[2])}`;
    return '';
  }

  function symbolFromRowId(rowId) {
    if (!rowId) return '';
    const raw = String(rowId).split('|')[0].trim().toUpperCase();
    if (!/^[A-Z][A-Z0-9.\-]{0,9}$/.test(raw)) return '';
    return raw;
  }

  function extractSymbol(el) {
    let t = (el.textContent || '').trim().toUpperCase();
    if (!t) return '';
    t = t.split(/[\s\n\r\t/(]/)[0];
    return t.replace(/[^A-Z0-9.\-]/g, '');
  }

  function symbolFromCell(cell) {
    const tagged = cell.querySelector('[data-ft-symbol]');
    if (tagged && tagged.dataset.ftSymbol) return tagged.dataset.ftSymbol;
    const btn = cell.querySelector('button[data-tooltip-trigger]') ||
      cell.querySelector('button') ||
      cell.querySelector('[data-ref="eValue"]');
    if (!btn) return '';
    const clone = btn.cloneNode(true);
    clone.querySelectorAll('.ft-custom-tag-container').forEach(n => n.remove());
    return extractSymbol(clone);
  }

  /* ==================== 2. 右下角提示 Toast ==================== */
  function flashToast(text) {
    let el = document.getElementById('ft-toast');
    if (!el) { el = document.createElement('div'); el.id = 'ft-toast'; document.body.appendChild(el); }
    el.textContent = text;
    el.classList.add('ft-toast-show');
    clearTimeout(el._t);
    el._t = setTimeout(() => el.classList.remove('ft-toast-show'), 2400);
  }
  window.__FT_TOAST__ = flashToast;      // 供 watchlist.js 复用

  /* ==================== 3. 拉起本机 Python 图表 ==================== */
  async function triggerLocalChart(symbol) {
    if (!symbol) return;
    const resp = await safeSendMessage({ action: 'FT_PLOT', symbol, payload: {} });
    if (!resp.ok) {
      console.warn(`${LOG_PREFIX} 无法连接本地桥接服务(bridge_server.py 是否在运行?)：`, resp.error);
      flashToast(`❌ 桥接失败: ${resp.error}`);
    } else {
      log('图表已启动:', resp.data);
      flashToast(`📈 ${symbol} 已发送`);
    }
  }

  /* ==================== 4. 持仓抓取（仅 positions 页） ==================== */
  function scrapeGridData() {
    if (!canScrapePositions()) return 0;

    const rows = document.querySelectorAll('[row-id]');
    if (!rows.length) return 0;
    const buf = Object.create(null);

    rows.forEach((row) => {
      if (row.closest('.ag-floating-top, .ag-floating-bottom')) return;
      const sym = symbolFromRowId(row.getAttribute('row-id'));
      if (!sym) return;
      const rec = buf[sym] || (buf[sym] = { symbol: sym });
      row.querySelectorAll('[col-id]').forEach((cell) => {
        const col = cell.getAttribute('col-id');
        if (!col || col === 'symbol') return;
        if (POSITION_COL_BLACKLIST.has(col)) return;   // ★ 干掉 dayTrend 之类
        const alias = COL_ALIAS[col];
        if (!alias) return;                            // ★ 白名单之外一律不要
        const txt = cleanText(cell);
        if (!txt || txt === '--' || txt.length > MAX_CELL_LEN) return;
        rec[alias] = txt;
      });
    });

    let changed = 0;
    Object.keys(buf).forEach((sym) => {
      const rec = buf[sym];
      if (!(rec.cost || rec.day_change || rec.gainloss || rec.quantity)) return;
      const old = positionCache[sym];
      const merged = Object.assign({}, old || {}, rec);
      delete merged.raw;          // ★ 清掉历史遗留
      delete merged.updated_at;   // ★ 时间戳统一由文件 _meta 记录
      const oldSig = posSig(old);
      const newSig = posSig(merged);
      positionCache[sym] = merged;
      if (oldSig !== newSig) changed++;
    });

    if (changed > 0) {
      log('持仓抓取更新', changed, '条，累计', Object.keys(positionCache).length);
      if (AUTO_POSITIONS) debounceSync();
    }
    return Object.keys(buf).length;
  }

  function signature() {
    return Object.keys(positionCache).sort()
      .map(k => `${k}:${posSig(positionCache[k])}`).join(';');
  }

  function buildPayload() {
    const out = {};
    Object.keys(positionCache).forEach(k => { out[k] = positionCache[k]; });
    return out;
  }

  function debounceSync(delay = 1200) {
    clearTimeout(syncTimer);
    syncTimer = setTimeout(() => { flushPositions(); }, delay);
  }

  async function flushPositions(force = false, overwrite = false) {
    const payload = buildPayload();
    if (!Object.keys(payload).length && !overwrite) return { ok: false, error: 'cache empty' };
    const sig = signature();
    if (!force && !overwrite && sig === lastSentSig) return { ok: true, data: { status: 'unchanged' } };
    const resp = await safeSendMessage({ action: 'FT_SYNC', payload, overwrite });
    if (resp.ok) { lastSentSig = sig; log('持仓已同步:', resp.data); }
    else log('持仓同步失败:', resp.error);
    return resp;
  }

  async function fullScan() {
    if (!canScrapePositions()) {
      return { ok: false, error: `当前页面不是持仓页（PAGE=${PAGE}），已拒绝抓取` };
    }
    for (const sym of Object.keys(positionCache)) delete positionCache[sym];
    lastSentSig = '';

    const vp = document.querySelector('.ag-body-viewport');
    scrapeGridData();
    if (!vp) return flushPositions(true, true);

    const original = vp.scrollTop;
    const step = Math.max(150, vp.clientHeight - 60);
    let guard = 0;
    vp.scrollTop = 0;
    await sleep(250);
    scrapeGridData();
    while (guard++ < 400) {
      if (vp.scrollTop + vp.clientHeight >= vp.scrollHeight - 2) break;
      vp.scrollTop = vp.scrollTop + step;
      await sleep(200);
      scrapeGridData();
    }
    await sleep(250);
    scrapeGridData();
    vp.scrollTop = original;
    await sleep(150);

    const r = await flushPositions(true, true);
    flashToast(`✅ 已全量刷新并保存 ${Object.keys(positionCache).length} 只持仓`);
    return r;
  }

  /* ==================== 5. 订单痕迹抓取（仅 order-status 页，LEAN） ==================== */
  const ORDER_FIELD_COLS = {
    updated: ['updated', 'updatedTime', 'updateTime', 'time', 'date'],
    side: ['transaction', 'action', 'side'],
    qty: ['0', 'quantity', 'qty', 'amount', 'dollarAmount', 'orderAmount'],
    priceType: ['priceType'],
    price: ['limitPrice', 'price', 'stopPrice'],
    duration: ['durationType'],
    instruction: ['instructionType'],
    status: ['statusCategory', 'status', 'orderStatus']
  };

  /* 状态 → 单字符码：F 已成交 / C 取消拒绝 / P 待成交 / X 未知 */
  const ST_FILLED = /已成交|已执行|成交|filled|executed|partial/i;
  const ST_CANCEL = /取消|撤销|撤单|拒绝|失效|过期|无效|作废|cancel|reject|expire|void/i;
  const ST_PENDING = /待|挂单|未成交|排队|已提交|open|pending|queued|working|accept/i;

  function statusCode(txt) {
    const s = String(txt || '');
    if (!s) return 'X';
    if (ST_FILLED.test(s)) return 'F';     // 「部分成交后取消」优先算有成交
    if (ST_CANCEL.test(s)) return 'C';
    if (ST_PENDING.test(s)) return 'P';
    return 'X';
  }

  function pickCol(raw, keys) {
    for (const k of keys) {
      if (raw[k] !== undefined && raw[k] !== null && raw[k] !== '') return raw[k];
    }
    return '';
  }

  function orderSig(o) {
    if (!o) return '';
    return [o.date, o.side, o.quantity, o.amount, o.price, o.st].join('|');
  }

  function normalizeOrder(rec) {
    const raw = rec.raw || {};
    const updatedTxt = pickCol(raw, ORDER_FIELD_COLS.updated);
    const date = parseUpdatedDate(updatedTxt);
    const sideTxt = pickCol(raw, ORDER_FIELD_COLS.side);
    let side = '';
    if (/买|buy|bought/i.test(sideTxt)) side = 'buy';
    else if (/卖|sell|sold/i.test(sideTxt)) side = 'sell';

    const sym = rec.symbol || '';
    if (!sym || !date || !side) return false;

    let qtyTxt = pickCol(raw, ORDER_FIELD_COLS.qty);
    if (!qtyTxt && raw['@3']) qtyTxt = raw['@3'];
    const isDollar = /\$/.test(qtyTxt);
    const qtyNum = toNum(qtyTxt);
    const price = toNum(pickCol(raw, ORDER_FIELD_COLS.price));
    const statusTxt = pickCol(raw, ORDER_FIELD_COLS.status);

    let amount = null, quantity = null, source = 'unknown';
    if (isDollar && qtyNum !== null) { amount = qtyNum; source = 'dollar'; }
    else if (qtyNum !== null) {
      quantity = qtyNum;
      if (price !== null && price > 0) { amount = qtyNum * price; source = 'qty*price'; }
      else source = 'qty_only';
    }

    const key = rec.row_id ? String(rec.row_id)
      : `${date}|${sym}|${side}|${qtyTxt}|${price}`;

    /* ---------- LEAN：只保留图表真正需要的字段 ---------- */
    const out = { symbol: sym, side: side, date: date, st: statusCode(statusTxt) };
    if (quantity !== null) out.quantity = quantity;
    if (amount !== null) out.amount = Math.round(amount * 100) / 100;
    if (price !== null) out.price = price;

    /* ---------- 可选：完整字段（默认关闭，体积大 ~10 倍） ---------- */
    if (ORDER_VERBOSE) {
      out.order_id = rec.row_id || '';
      out.side_text = sideTxt;
      out.datetime = updatedTxt;
      out.status = statusTxt;
      out.amount_source = source;
      out.quantity_text = qtyTxt;
      out.price_type = pickCol(raw, ORDER_FIELD_COLS.priceType);
      out.duration = pickCol(raw, ORDER_FIELD_COLS.duration);
      out.instruction = pickCol(raw, ORDER_FIELD_COLS.instruction);
      out.raw = raw;
    }

    const old = orderCache[key];
    orderCache[key] = out;                 // 直接替换，避免旧胖字段残留
    return !old || orderSig(old) !== orderSig(out);
  }

  function scrapeOrderGrid() {
    if (!canScrapeOrders()) return 0;
    const rows = document.querySelectorAll('[row-id]');
    if (!rows.length) return 0;

    const buf = Object.create(null);
    rows.forEach((row) => {
      if (row.closest('.ag-floating-top, .ag-floating-bottom')) return;
      const rid = row.getAttribute('row-id');
      if (!rid) return;
      const rec = buf[rid] || (buf[rid] = { row_id: rid, raw: {} });
      row.querySelectorAll('[col-id]').forEach((cell) => {
        const col = cell.getAttribute('col-id');
        if (!col) return;
        if (col === 'symbol') {
          const sym = symbolFromCell(cell);
          if (sym) rec.symbol = sym;
          return;
        }
        const txt = cleanText(cell);
        if (!txt) return;
        rec.raw[col] = txt;
        const ci = cell.getAttribute('aria-colindex');
        if (ci) rec.raw['@' + ci] = txt;
      });
    });

    let changed = 0;
    Object.keys(buf).forEach((rid) => { if (normalizeOrder(buf[rid])) changed++; });
    if (changed > 0) {
      log('订单抓取更新', changed, '条，累计', Object.keys(orderCache).length);
      if (AUTO_ORDERS) debounceOrderSync();
    }
    return Object.keys(buf).length;
  }

  function debounceOrderSync(delay = 1500) {
    clearTimeout(orderSyncTimer);
    orderSyncTimer = setTimeout(() => { flushOrders(); }, delay);
  }

  async function flushOrders(force = false) {
    const payload = {};
    Object.keys(orderCache).forEach(k => { payload[k] = orderCache[k]; });
    const n = Object.keys(payload).length;
    if (!n) return { ok: false, error: 'order cache empty' };
    const sig = Object.keys(payload).sort()
      .map(k => k + ':' + orderSig(payload[k])).join(';');
    if (!force && sig === lastOrderSig) return { ok: true, data: { status: 'unchanged' } };
    const resp = await safeSendMessage({
      action: 'FT_SYNC_ORDERS', payload, verbose: ORDER_VERBOSE
    });
    if (resp.ok) { lastOrderSig = sig; log('订单已追加:', resp.data); }
    else log('订单同步失败:', resp.error);
    return resp;
  }

  async function fullScanOrders() {
    if (!canScrapeOrders()) {
      return { ok: false, error: `当前页面不是订单页（PAGE=${PAGE}），已拒绝抓取` };
    }
    const vp = document.querySelector('.ag-body-viewport');
    scrapeOrderGrid();
    if (vp) {
      const original = vp.scrollTop;
      const step = Math.max(150, vp.clientHeight - 60);
      let guard = 0;
      vp.scrollTop = 0;
      await sleep(250);
      scrapeOrderGrid();
      while (guard++ < 400) {
        if (vp.scrollTop + vp.clientHeight >= vp.scrollHeight - 2) break;
        vp.scrollTop = vp.scrollTop + step;
        await sleep(200);
        scrapeOrderGrid();
      }
      await sleep(250);
      scrapeOrderGrid();
      vp.scrollTop = original;
      await sleep(150);
    }
    const r = await flushOrders(true);
    flashToast(`✅ 已抓取 ${Object.keys(orderCache).length} 笔订单（${ORDER_VERBOSE ? '完整' : '精简'}追加写入）`);
    return r;
  }

  /* ==================== 6. 标签匹配与注入（纯展示，仅点击看图） ==================== */
  function getTagsForSymbol(symbol) {
    if (!symbol) return [];
    if (stockTagMap[symbol]) return stockTagMap[symbol];
    if (symbol.includes('.')) {
      const alt = symbol.replace(/\./g, '-');
      if (stockTagMap[alt]) return stockTagMap[alt];
    }
    if (symbol.includes('-')) {
      const alt = symbol.replace(/-/g, '.');
      if (stockTagMap[alt]) return stockTagMap[alt];
    }
    return [];
  }

  function loadSettings() {
    chrome.storage.local.get(
      ['stockData', 'maxTags', 'ftDebug', 'ftAutoPositions', 'ftAutoOrders',
        'ftAutoScrape', 'ftOrderVerbose'],
      (res) => {
        stockTagMap = res.stockData || {};
        maxTags = res.maxTags || 2;
        DEBUG = !!res.ftDebug;
        ORDER_VERBOSE = res.ftOrderVerbose === true;
        const legacy = res.ftAutoScrape === true;
        AUTO_POSITIONS = res.ftAutoPositions === undefined ? legacy : res.ftAutoPositions === true;
        AUTO_ORDERS = res.ftAutoOrders === undefined ? legacy : res.ftAutoOrders === true;
        log('设置已加载 AUTO_POSITIONS=', AUTO_POSITIONS, 'AUTO_ORDERS=', AUTO_ORDERS,
          'ORDER_VERBOSE=', ORDER_VERBOSE, 'PAGE=', PAGE);
        clearAllTags();
        scheduleInject();
      });
  }

  chrome.storage.onChanged.addListener((changes, area) => {
    if (area !== 'local') return;
    if (changes.stockData || changes.maxTags || changes.ftDebug || changes.ftOrderVerbose ||
      changes.ftAutoPositions || changes.ftAutoOrders || changes.ftAutoScrape) loadSettings();
  });

  function clearAllTags() {
    document.querySelectorAll('.ft-custom-tag-container').forEach(el => el.remove());
  }

  function buildTagContainer(symbol, tags) {
    const box = document.createElement('span');
    box.className = 'ft-custom-tag-container';
    box.dataset.ftSymbol = symbol;

    if (tags && tags.length) {
      const shown = tags.slice(0, maxTags);
      shown.forEach((txt) => {
        const s = document.createElement('span');
        s.className = 'ft-custom-tag-badge';
        s.textContent = txt;
        box.appendChild(s);
      });
      if (tags.length > shown.length) {
        const more = document.createElement('span');
        more.className = 'ft-custom-tag-badge ft-custom-tag-more';
        more.textContent = `+${tags.length - shown.length}`;
        box.appendChild(more);
      }
    } else {
      const only = document.createElement('span');
      only.className = 'ft-custom-tag-badge ft-custom-tag-chart';
      only.textContent = '📈';
      box.appendChild(only);
    }

    // ★ 关键：移除了 mouseenter 和 mouseleave 浮窗监听，仅保留点击看图
    box.addEventListener('click', (e) => {
      e.stopPropagation(); e.preventDefault();
      triggerLocalChart(symbol);
    });
    return box;
  }

  function injectTags() {
    if (automationBusy()) return;           // ★ 自动化进行中，不注入

    const cells = document.querySelectorAll('[col-id="symbol"]');
    cells.forEach((cell) => {
      if (cell.closest('.ag-header')) return;
      const anchor =
        cell.querySelector('button[data-tooltip-trigger]') ||
        cell.querySelector('button') ||
        cell.querySelector('[data-ref="eValue"]');
      if (!anchor) return;

      const row = cell.closest('[row-id]');
      const symbol = (row && symbolFromRowId(row.getAttribute('row-id'))) || symbolFromCell(cell);
      if (!symbol) return;

      anchor.dataset.ftSymbol = symbol;
      const existing = cell.querySelector('.ft-custom-tag-container');
      if (existing && existing.dataset.ftSymbol === symbol) return;
      if (existing) existing.remove();
      anchor.insertAdjacentElement('afterend', buildTagContainer(symbol, getTagsForSymbol(symbol)));
    });

    if (AUTO_POSITIONS && PAGE === 'positions') scrapeGridData();
    if (AUTO_ORDERS && PAGE === 'orders') scrapeOrderGrid();
  }

  /* ==================== 7. 调度 ==================== */
  let timer = null;
  function scheduleInject(delay = 80) {
    if (timer) return;
    timer = setTimeout(() => { timer = null; try { injectTags(); } catch (e) { log(e); } }, delay);
  }

  function isOurNode(node) {
    if (!node || node.nodeType !== 1) return false;
    return !!(
      (node.classList && node.classList.contains('ft-custom-tag-container')) ||
      node.id === 'ft-toast' || node.id === 'ft-wl-hud' || node.id === 'ft-trade-layer' ||
      (node.closest && (node.closest('#ft-wl-hud') || node.closest('#ft-trade-layer')))
    );
  }

  const observer = new MutationObserver((records) => {
    for (const r of records) {
      if (isOurNode(r.target)) continue;
      scheduleInject();
      return;
    }
  });
  observer.observe(document.documentElement, { childList: true, subtree: true });

  document.addEventListener('scroll', () => scheduleInject(20), true);
  window.addEventListener('resize', () => scheduleInject(100));
  setInterval(() => scheduleInject(0), 2000);

  /* 定期兜底同步：仅在对应开关打开时才动作 */
  setInterval(() => {
    if (automationBusy()) return;
    if (AUTO_POSITIONS && PAGE === 'positions') { scrapeGridData(); flushPositions(); }
    if (AUTO_ORDERS && PAGE === 'orders') { scrapeOrderGrid(); flushOrders(); }
  }, 30000);

  /* SPA 路由变化 → 重新判定页面 */
  let lastHref = location.href;
  setInterval(() => {
    if (location.href === lastHref) return;
    lastHref = location.href;
    PAGE = detectPage();
    log('路由变化 ->', location.pathname, 'PAGE =', PAGE);
    clearAllTags();
    scheduleInject(150);
  }, 800);

  /* ==================== 8. 与 popup 通信 ==================== */
  chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
    if (!msg || !msg.action) return;

    if (msg.action === 'refreshTags') { loadSettings(); sendResponse({ ok: true }); return; }

    /* ★ 后台自动导航用：判断页面是否已就绪 / 是否未登录 */
    if (msg.action === 'FT_PAGE_READY') {
      PAGE = detectPage();
      const pw = Array.from(document.querySelectorAll('input[type="password"]'))
        .some(el => el.offsetParent !== null);
      const rows = Array.from(document.querySelectorAll('[row-id]'))
        .filter(r => !r.closest('.ag-floating-top, .ag-floating-bottom')).length;
      const overlay = !!document.querySelector('.ag-overlay-no-rows-wrapper, .ag-overlay-no-rows-center');
      let looks = false, ready = false;
      if (PAGE === 'positions' || PAGE === 'orders') {
        looks = gridLooksLike(PAGE);
        ready = looks && (rows > 0 || overlay);
      } else if (PAGE === 'watchlist') {
        const api = window.__FT_WL_API__;
        looks = !!(api && (document.querySelector('[role="grid"], .ag-root') || api.groupName()));
        ready = !!(looks && api.groupName() && (rows > 0 || (api.gridSaysEmpty && api.gridSaysEmpty())));
      }
      sendResponse({
        ok: true, page: PAGE || 'other', path: location.pathname,
        looks, ready, rows, loggedOut: pw && !looks, busy: automationBusy()
      });
      return;
    }

    if (msg.action === 'FT_STATUS') {
      sendResponse({
        ok: true,
        page: PAGE || 'other',
        path: location.pathname,
        autoPositions: AUTO_POSITIONS,
        autoOrders: AUTO_ORDERS,
        orderVerbose: ORDER_VERBOSE,
        canPositions: canScrapePositions(),
        canOrders: canScrapeOrders(),
        positions: Object.keys(positionCache).length,
        orders: Object.keys(orderCache).length
      });
      return;
    }

    if (msg.action === 'FT_DUMP') {
      sendResponse({ ok: true, count: Object.keys(positionCache).length, data: positionCache });
      return;
    }

    if (msg.action === 'FT_DUMP_ORDERS') {
      sendResponse({ ok: true, count: Object.keys(orderCache).length, data: orderCache });
      return;
    }

    if (msg.action === 'FT_SYNC_ALL') {
      fullScan().then(r => sendResponse({ ok: true, count: Object.keys(positionCache).length, server: r }))
        .catch(e => sendResponse({ ok: false, error: String(e) }));
      return true;
    }

    if (msg.action === 'FT_SCAN_ORDERS') {
      fullScanOrders().then(r => sendResponse({ ok: true, count: Object.keys(orderCache).length, server: r }))
        .catch(e => sendResponse({ ok: false, error: String(e) }));
      return true;
    }
  });

  loadSettings();
  console.log(LOG_PREFIX, `Content Script v5.2 就绪（已移除悬浮浮窗，保留点击直开图表）`);
})();

/* ============================================================================
 * Firstrade 快速交易层  ft_trade.js  v1        仅在 /app/watchlist 生效
 *   点击股票代码 → 弹出交易层 → 自动驱动页面底部「交易」快速下单面板
 *   规则：当前/所在分组 ∈ 买/买买/买买买 → 买进（金额档 / 自定义金额）
 *         当前/所在分组 ∈ 卖卖卖          → 卖出（股数：positions JSON 的 quantity 一键全卖 / 自定义）
 *         其它                            → 由用户选择
 *   成交后：从勾选的分组删除该代码（Earning / Wrong 永不自动删）
 *   安全：同一时间只跑一笔；「下单」只点一次；预演模式只填表；全程审计日志
 * ==========================================================================*/
(() => {
  if (window.__FT_TRADE_V1__) return;
  window.__FT_TRADE_V1__ = true;

  const LOG = '[FT-TRADE]';
  const BUY_GROUPS = ['买', '买买', '买买买'];
  const SELL_GROUPS = ['卖卖卖'];
  const PROTECTED = ['Earning', 'Wrong'];
  const ROW_EXCLUDE = '.ag-floating-top, .ag-floating-bottom, #app-quote-bar, header, #app-header';

  const S = { enabled: true, dry: false, removeAfter: true, presets: [1000, 2000, 3000], debug: false };
  let running = false;
  let abortFlag = false;

  const sleep = (ms) => new Promise(r => setTimeout(r, ms));
  const log = (...a) => { if (S.debug) console.log(LOG, ...a); };
  const isWatchlistPage = () => /\/watchlist/i.test(location.pathname || '');
  const api = () => window.__FT_WL_API__ || null;
  const toast = (t) => { try { (window.__FT_TOAST__ || console.log)(t); } catch (e) { } };
  const normKey = (s) => String(s || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  const normGroup = (s) => String(s || '').replace(/[（(][^）)]*[）)]\s*$/g, '').replace(/\s+/g, '').toUpperCase();
  const cleanGroupName = (s) => String(s || '').replace(/\u00a0/g, ' ').replace(/[（(]\s*\d+\s*[）)]\s*$/, '').trim();
  const inList = (g, list) => list.some(x => normGroup(x) === normGroup(g));
  const $id = (id) => document.getElementById(id);
  const esc = (s) => String(s === undefined || s === null ? '' : s)
    .replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

  function isVisible(el) {
    if (!el) return false;
    const st = getComputedStyle(el);
    if (st.visibility === 'hidden' || st.display === 'none' || st.opacity === '0') return false;
    if (st.display === 'contents') return true;
    const r = el.getBoundingClientRect();
    return !!(r.width || r.height);
  }
  function cleanText(el) {
    const t = (el && (el.innerText || el.textContent)) || '';
    return t.replace(/\u00a0/g, ' ').replace(/\s+/g, ' ').trim();
  }
  async function waitFor(fn, timeout = 4000, interval = 100) {
    const t0 = Date.now();
    for (; ;) {
      let v = null;
      try { v = fn(); } catch (e) { v = null; }
      if (v) return v;
      if (Date.now() - t0 > timeout) return null;
      await sleep(interval);
    }
  }
  function bg(msg) {
    return new Promise((resolve) => {
      try {
        chrome.runtime.sendMessage(msg, (resp) => {
          if (chrome.runtime.lastError) { resolve({ ok: false, error: chrome.runtime.lastError.message }); return; }
          resolve(resp || { ok: false, error: 'no response' });
        });
      } catch (e) { resolve({ ok: false, error: String(e) }); }
    });
  }
  function setNativeValue(el, value) {
    const proto = Object.getPrototypeOf(el);
    const desc = Object.getOwnPropertyDescriptor(proto, 'value') ||
      Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value');
    if (desc && desc.set) desc.set.call(el, value); else el.value = value;
    el.dispatchEvent(new Event('input', { bubbles: true }));
    el.dispatchEvent(new Event('change', { bubbles: true }));
  }
  function sendKey(el, key, keyCode) {
    const opt = { bubbles: true, cancelable: true, key, code: key, keyCode, which: keyCode };
    el.dispatchEvent(new KeyboardEvent('keydown', opt));
    el.dispatchEvent(new KeyboardEvent('keyup', opt));
  }
  function fireMouseSeq(el) {
    const r = el.getBoundingClientRect();
    const opt = {
      bubbles: true, cancelable: true, view: window,
      clientX: r.left + Math.max(2, r.width / 2), clientY: r.top + Math.max(2, r.height / 2),
      button: 0, buttons: 1, pointerId: 1, isPrimary: true, pointerType: 'mouse'
    };
    try { el.dispatchEvent(new PointerEvent('pointerover', opt)); } catch (e) { }
    try { el.dispatchEvent(new PointerEvent('pointerenter', opt)); } catch (e) { }
    el.dispatchEvent(new MouseEvent('mouseover', opt));
    el.dispatchEvent(new MouseEvent('mousemove', opt));
    try { el.dispatchEvent(new PointerEvent('pointerdown', opt)); } catch (e) { }
    el.dispatchEvent(new MouseEvent('mousedown', opt));
    try { el.dispatchEvent(new PointerEvent('pointerup', Object.assign({}, opt, { buttons: 0 }))); } catch (e) { }
    el.dispatchEvent(new MouseEvent('mouseup', Object.assign({}, opt, { buttons: 0 })));
    el.dispatchEvent(new MouseEvent('click', Object.assign({}, opt, { buttons: 0 })));
  }
  function symbolFromRowId(rowId) {
    if (!rowId) return '';
    const raw = String(rowId).split('|')[0].trim().toUpperCase();
    return /^[A-Z][A-Z0-9.\-]{0,9}$/.test(raw) ? raw : '';
  }
  function candidateForms(sym) {
    const s = String(sym).trim().toUpperCase();
    const out = [];
    if (s.includes('-')) out.push(s.replace(/-/g, '.'));
    out.push(s);
    if (s.includes('.')) out.push(s.replace(/\./g, '-'));
    return Array.from(new Set(out));
  }

  /* ==========================================================================
   *                  页面「快速交易」面板 DOM 驱动
   * ========================================================================*/
  function tradeRoot() {
    const inp = $id('quick-trade-symbol-search');
    if (!inp || !isVisible(inp)) return null;
    return inp.closest('[data-popover-content]') || inp.closest('article') || inp.closest('div.fixed') || null;
  }
  function tradeButton() {
    const b = $id('quick-trade-quote-bar');
    if (b && isVisible(b)) return b;
    const bar = $id('app-quote-bar');
    if (!bar) return null;
    return Array.from(bar.querySelectorAll('button')).find(x => isVisible(x) && cleanText(x) === '交易') || null;
  }
  async function openPanel() {
    if (tradeRoot()) return { ok: true, reused: true };
    for (let i = 0; i < 2; i++) {
      const b = tradeButton();
      if (!b) return { ok: false, error: '找不到页面底部报价条上的「交易」按钮 (#quick-trade-quote-bar)' };
      fireMouseSeq(b);
      const r = await waitFor(tradeRoot, 5000, 120);
      if (r) { await sleep(350); return { ok: true }; }
    }
    return { ok: false, error: '点击「交易」后未出现快速交易面板' };
  }
  async function closeTradePanel() {
    for (let i = 0; i < 3 && tradeRoot(); i++) {
      const root = tradeRoot();
      const hdr = root.querySelector('header');
      const btns = hdr ? Array.from(hdr.querySelectorAll('button')).filter(isVisible) : [];
      const x = btns.find(b => /关闭|close|×|✕/i.test((b.getAttribute('aria-label') || '') + (b.title || '') + cleanText(b)));
      if (x) fireMouseSeq(x);
      else { sendKey(root, 'Escape', 27); sendKey(document.body, 'Escape', 27); }
      await waitFor(() => !tradeRoot(), 1500, 100);
    }
    if (tradeRoot()) {
      const b = tradeButton();
      if (b) { fireMouseSeq(b); await waitFor(() => !tradeRoot(), 1500, 100); }
    }
    return !tradeRoot();
  }
  async function ensureStocksTab() {
    const r = tradeRoot();
    if (!r) return;
    const tab = r.querySelector('[role="tab"][data-value="stocks"], [data-tabs-trigger][data-value="stocks"], button[data-value="stocks"]');
    if (tab && tab.getAttribute('aria-selected') !== 'true' && tab.getAttribute('data-state') !== 'active') {
      fireMouseSeq(tab);
      await sleep(400);
    }
  }

  /* ---------- 代码选择 ---------- */
  function comboItems() {
    const sel = '[data-combobox-content] [data-combobox-item], [role="listbox"] [role="option"], [data-combobox-item]';
    return Array.from(document.querySelectorAll(sel)).filter(el => isVisible(el) &&
      !el.closest('[data-command-root]') && !el.closest('[data-select-content]') && !el.closest('#ft-trade-layer'));
  }
  function itemMatches(el, k) {
    if (normKey(el.getAttribute('data-value')) === k || normKey(el.getAttribute('data-label')) === k) return true;
    const first = (cleanText(el).split(/\s+/)[0] || '');
    if (normKey(first) === k) return true;
    return Array.from(el.querySelectorAll('span, div, p, strong, b')).some(x => normKey(cleanText(x)) === k);
  }
  function symbolConfirmed(k) {
    const root = tradeRoot();
    if (!root) return false;
    const i = $id('quick-trade-symbol-search');
    if (i && normKey(i.value) === k) return true;
    const info = root.querySelector('p[class*="pl-8"]');
    if (info) {
      const toks = cleanText(info).toUpperCase().split(/[^A-Z0-9.\-]+/);
      if (toks.some(t => normKey(t) === k)) return true;
    }
    return false;
  }
  async function pickSymbol(sym) {
    let lastErr = '';
    for (const f of candidateForms(sym)) {
      const inp = $id('quick-trade-symbol-search');
      if (!inp) return { ok: false, error: '找不到交易面板的代码输入框' };
      const k = normKey(f);
      inp.focus();
      setNativeValue(inp, '');
      await sleep(80);
      setNativeValue(inp, f);
      inp.dispatchEvent(new KeyboardEvent('keyup', { bubbles: true, key: f.slice(-1) }));
      const hit = await waitFor(() => comboItems().find(el => itemMatches(el, k)) || null, 6000, 120);
      if (!hit) { lastErr = `联想列表里没有精确匹配 ${f}`; continue; }
      fireMouseSeq(hit);
      const ok = await waitFor(() => symbolConfirmed(k), 4000, 120);
      if (ok) { await sleep(350); return { ok: true, form: f }; }
      lastErr = `点选 ${f} 后未在面板上确认到该代码`;
    }
    return { ok: false, error: lastErr || '无法选择代码' };
  }

  /* ---------- 下拉框（交易类型 / 订单类型） ---------- */
  function openSelectItems() {
    return Array.from(document.querySelectorAll('[data-select-content] [data-select-item], [role="listbox"] [data-select-item]'))
      .filter(isVisible);
  }
  const trig = (id) => { const r = tradeRoot(); return (r && r.querySelector('#' + id)) || null; };
  async function chooseSelect(id, label) {
    const t = trig(id);
    if (!t) return { ok: false, missing: true, error: `找不到下拉框 #${id}` };
    if (cleanText(t) === label) return { ok: true, already: true };
    if (t.disabled) return { ok: false, error: `下拉框 #${id} 不可用（当前「${cleanText(t)}」）` };
    for (let a = 0; a < 3; a++) {
      fireMouseSeq(trig(id) || t);
      const items = await waitFor(() => { const it = openSelectItems(); return it.length ? it : null; }, 3000, 100);
      if (!items) { sendKey(t, 'Escape', 27); await sleep(300); continue; }
      const hit = items.find(i => (i.getAttribute('data-label') || '').trim() === label) ||
        items.find(i => cleanText(i) === label);
      if (!hit) {
        const names = items.map(i => i.getAttribute('data-label') || cleanText(i));
        sendKey(t, 'Escape', 27);
        return { ok: false, error: `下拉框里没有「${label}」（可选：${names.join(' / ')}）` };
      }
      fireMouseSeq(hit);
      const ok = await waitFor(() => { const x = trig(id); return x && cleanText(x) === label; }, 3000, 100);
      if (ok) { await sleep(250); return { ok: true }; }
      await sleep(400);
    }
    return { ok: false, error: `无法把 #${id} 设为「${label}」` };
  }

  /* ---------- 股数 / 金额 ---------- */
  function qtyFieldset() {
    const r = tradeRoot();
    if (!r) return null;
    const lb = r.querySelector('label[for="quick-trade-form-quantity-amount"]');
    return lb ? lb.closest('fieldset') : null;
  }
  function qtyInput() {
    const fs = qtyFieldset();
    if (fs) {
      const i = Array.from(fs.querySelectorAll('input')).find(isVisible);
      if (i) return i;
    }
    const byId = $id('quick-trade-form-quantity-amount');
    return byId && isVisible(byId) ? byId : null;
  }
  const qtyTypeBtn = () => { const r = tradeRoot(); return r && r.querySelector('#quick-trade-form-quantity-type'); };
  function qtyMode() {
    const fs = qtyFieldset();
    if (fs && Array.from(fs.querySelectorAll('span')).some(s => cleanText(s) === '$')) return '金额';
    if (fs && fs.querySelector('#quick-trade-form-quantity-amount')) return '股数';
    const b = qtyTypeBtn();
    const t = b ? (b.getAttribute('title') || '').trim() : '';
    return (t === '金额' || t === '股数') ? t : '';
  }
  async function setQtyMode(want) {
    for (let a = 0; a < 3; a++) {
      if (qtyMode() === want) return { ok: true };
      const b = qtyTypeBtn();
      if (!b) return { ok: false, error: '找不到「股数/金额」切换按钮 (#quick-trade-form-quantity-type)' };
      fireMouseSeq(b);
      await waitFor(() => qtyMode() === want, 1500, 100);
    }
    return qtyMode() === want ? { ok: true } : { ok: false, error: `无法切换到「${want}」（当前 ${qtyMode() || '未知'}）` };
  }
  function qtyMatches(val) {
    const i = qtyInput();
    return !!i && Math.abs(parseFloat(i.value) - Number(val)) < 1e-6;
  }
  async function fillQty(val) {
    const i = await waitFor(qtyInput, 2500, 100);
    if (!i) return { ok: false, error: '找不到数量/金额输入框' };
    i.focus();
    setNativeValue(i, '');
    await sleep(60);
    setNativeValue(i, String(val));
    i.dispatchEvent(new KeyboardEvent('keyup', { bubbles: true, key: '0' }));
    i.dispatchEvent(new FocusEvent('focusout', { bubbles: true }));
    i.dispatchEvent(new Event('blur'));
    await sleep(250);
    if (!qtyMatches(val)) { const now = qtyInput(); return { ok: false, error: `写入失败（期望 ${val}，实际 ${now ? now.value : '-'}）` }; }
    return { ok: true };
  }

  /* ---------- 下单 & 结果识别 ---------- */
  const OK_RE = /成功|已提交|已送出|已下单|已接收|已受理|已委托|订单号|委托号|submitted|placed|received|success|accepted/i;
  const ERR_RE = /失败|错误|不足|拒绝|无效|不允许|无法|超出|error|fail|insufficient|reject|invalid|not allowed|exceed/i;
  const CONFIRM_RE = /^(确认|确定|确认下单|确认交易|确认订单|提交|提交订单|发送订单|送出|Confirm|Submit|Place Order|Send Order)$/i;

  function submitButton() {
    const r = tradeRoot();
    if (!r) return null;
    const f = r.querySelector('footer') || r;
    return Array.from(f.querySelectorAll('button')).find(b => isVisible(b) && cleanText(b) === '下单') || null;
  }
  const notifText = () => { const s = document.querySelector('section[aria-label^="Notifications"]'); return s ? cleanText(s) : ''; };
  function panelErrorText() {
    const r = tradeRoot();
    if (!r) return '';
    const errs = Array.from(r.querySelectorAll('[role="alert"], [aria-invalid="true"], [data-form-error], .text-error'))
      .filter(isVisible).map(cleanText).filter(Boolean);
    return errs.join('；').slice(0, 160) || '无明确提示';
  }
  function confirmCandidates() {
    const scopes = [tradeRoot()].concat(Array.from(document.querySelectorAll(
      '[role="dialog"], [role="alertdialog"], [data-dialog-content], [data-alert-dialog-content]')))
      .filter(el => el && isVisible(el) && !el.closest('#ft-trade-layer'));
    const out = [];
    scopes.forEach(s => s.querySelectorAll('button').forEach(b => {
      if (isVisible(b) && !b.disabled && CONFIRM_RE.test(cleanText(b))) out.push(b);
    }));
    return out;
  }
  const newWords = (now, before) => now.split(' ').filter(w => w && !before.includes(w)).join(' ');

  async function submitAndWatch(say) {
    const btn = await waitFor(() => {
      const b = submitButton();
      return b && !b.disabled && b.getAttribute('aria-disabled') !== 'true' ? b : null;
    }, 5000, 120);
    if (!btn) {
      const b = submitButton();
      return { status: 'error', message: b ? `「下单」按钮不可点（表单校验未通过：${panelErrorText()}）` : '找不到「下单」按钮' };
    }
    const n0 = notifText();
    const p0 = tradeRoot() ? cleanText(tradeRoot()) : '';
    const clicked = new Set([btn]);
    fireMouseSeq(btn);                               // ★ 「下单」只点这一次
    const t0 = Date.now();
    while (Date.now() - t0 < 20000) {
      await sleep(250);
      const cands = confirmCandidates().filter(b => !clicked.has(b));
      if (cands.length) {
        clicked.add(cands[0]);
        if (say) say(`↳ 出现确认按钮「${cleanText(cands[0])}」，自动确认`);
        fireMouseSeq(cands[0]);
        continue;
      }
      const n1 = notifText();
      const nNew = n1 !== n0 ? newWords(n1, n0) : '';
      if (nNew) {
        if (ERR_RE.test(nNew)) return { status: 'error', message: '下单失败：' + nNew.slice(0, 160) };
        if (OK_RE.test(nNew)) return { status: 'ok', message: '下单成功：' + nNew.slice(0, 120) };
      }
      const root = tradeRoot();
      if (!root) return { status: 'assumed', message: '交易面板已关闭（视为已提交，请到订单页核对）' };
      const pNew = newWords(cleanText(root), p0);
      if (pNew) {
        if (ERR_RE.test(pNew)) return { status: 'error', message: '下单失败：' + pNew.slice(0, 160) };
        if (OK_RE.test(pNew)) return { status: 'ok', message: '下单成功：' + pNew.slice(0, 120) };
      }
    }
    return { status: 'unknown', message: '20 秒内未看到成功/失败提示（未移出分组，请到订单页核对）' };
  }

  /* ---------- 成交后移出分组 ---------- */
  async function removeFromGroups(sym, groups, say) {
    const a = api();
    const origin = a.groupName();
    const removed = [], failed = [];
    a.clearStopFlags();
    for (const g of groups) {
      try {
        if (normGroup(a.groupName()) !== normGroup(g)) {
          if (say) say(`↳ 切换到「${g}」…`);
          const sr = await a.switchGroup(g);
          if (!sr.ok) { failed.push({ group: g, error: sr.error }); continue; }
          await a.waitGridSettled(4000);
        }
        const r = await a.deleteSymbol(sym);
        if (r.status === 'removed' || r.status === 'missing') {
          removed.push(g);
          if (say) say(`↳ 已从「${g}」移除 ${sym}${r.status === 'missing' ? '（本就不在）' : ''}`);
          try { window.__FT_WL_MEMBER__ && window.__FT_WL_MEMBER__.event(g, sym, 'remove', 'trade_remove'); } catch (e) { }
        } else {
          failed.push({ group: g, error: r.error || r.status });
          if (say) say(`↳ ❌ 从「${g}」移除失败：${r.error || r.status}`);
        }
      } catch (e) { failed.push({ group: g, error: String((e && e.message) || e) }); }
    }
    try {
      if (origin && normGroup(a.groupName()) !== normGroup(origin)) await a.switchGroup(origin);
    } catch (e) { }
    return { removed, failed };
  }

  /* ---------- 主流程 ---------- */
  async function execute(opts) {
    const o = opts || {};
    const sym = String(o.symbol || '').trim().toUpperCase();
    const side = o.side === 'sell' ? 'sell' : (o.side === 'buy' ? 'buy' : '');
    const amount = Number(o.amount), qty = Number(o.qty);
    const groups = (Array.isArray(o.removeGroups) ? o.removeGroups : []).filter(g => !inList(g, PROTECTED));
    const dry = S.dry || !!o.dry;
    const say = (t) => { log(t); if (typeof o.onLog === 'function') { try { o.onLog(t); } catch (e) { } } };
    const res = {
      ok: false, symbol: sym, side, amount: side === 'buy' ? amount : null, qty: side === 'sell' ? qty : null,
      status: '', message: '', removed: [], removeFailed: [], dry, source: o.source || 'layer'
    };
    const fail = (m) => Object.assign(res, { message: m });

    if (running) return fail('已有一笔交易在执行中');
    const a = api();
    if (!isWatchlistPage() || !a) return fail('请在 /app/watchlist 页面使用（watchlist.js 未就绪）');
    if (a.isBusy()) return fail('自选股同步/行情抓取进行中，请稍后再交易');
    if (!sym || !side) return fail('缺少代码或买卖方向');
    if (side === 'buy' && !(amount > 0)) return fail('买入金额必须大于 0');
    if (side === 'sell' && !(qty > 0)) return fail('卖出股数必须大于 0');

    running = true; abortFlag = false;
    try { a.setTradeBusy(true); } catch (e) { }
    const chk = () => { if (abortFlag) throw new Error('已取消（尚未点击「下单」）'); };
    const must = (r, step) => { if (!r || !r.ok) throw new Error(`${step}：${(r && r.error) || '失败'}`); return r; };
    try {
      a.clearStopFlags(); a.cleanNavSearch();
      say('① 打开快速交易面板…'); must(await openPanel(), '打开交易面板'); chk();
      await ensureStocksTab();
      say(`② 选择代码 ${sym}…`); must(await pickSymbol(sym), '选择代码'); chk();
      const txLabel = side === 'buy' ? '买进' : '卖出';
      say(`③ 交易类型 → ${txLabel}`); must(await chooseSelect('quick-trade-form-transaction', txLabel), '交易类型'); chk();
      await sleep(300);
      const mode = side === 'buy' ? '金额' : '股数';
      say(`④ 数量方式 → ${mode}`); must(await setQtyMode(mode), '数量方式'); chk();
      const val = side === 'buy' ? amount : qty;
      say(`⑤ 填写 ${side === 'buy' ? '$' + val : val + ' 股'}`); must(await fillQty(val), '填写数量'); chk();
      if (trig('quick-trade-form-order-type')) {
        say('⑥ 订单类型 → 市价'); must(await chooseSelect('quick-trade-form-order-type', '市价'), '订单类型');
      } else say('⑥ 未出现订单类型下拉框（金额单通常固定市价），跳过');
      await sleep(250);
      if (!qtyMatches(val)) { say('数量框被重置，重新填写…'); must(await fillQty(val), '重新填写数量'); }
      chk();
      if (dry) {
        res.ok = true; res.status = 'dry';
        res.message = '🧪 预演模式：表单已全部填好，未点击「下单」，请在页面上核对';
        say(res.message);
        return res;
      }
      say('⑦ 点击「下单」…');
      const sw = await submitAndWatch(say);
      res.status = sw.status; res.message = sw.message;
      if (sw.status !== 'ok' && sw.status !== 'assumed') throw new Error(sw.message);
      res.ok = true;
      say((sw.status === 'ok' ? '✅ ' : '⚠️ ') + sw.message);
      if (groups.length) {
        say(`⑧ 从分组移除：${groups.join(' / ')}`);
        await closeTradePanel();
        const rr = await removeFromGroups(sym, groups, say);
        res.removed = rr.removed; res.removeFailed = rr.failed;
      }
    } catch (e) {
      res.ok = false;
      res.error = String((e && e.message) || e);
      if (!res.status) res.message = res.error;
    } finally {
      running = false;
      try { a.setTradeBusy(false); } catch (e) { }
      bg({ action: 'FT_TRADE_LOG', payload: Object.assign({ ts: Date.now(), page_group: cleanGroupName(a.groupName()) }, res) });
    }
    return res;
  }

  /* ==========================================================================
   *                       上下文（分组归属 / 持仓）
   * ========================================================================*/
  async function loadContext(sym) {
    const a = api();
    const current = a ? cleanGroupName(a.groupName()) : '';
    const [mem, pos] = await Promise.all([bg({ action: 'FT_SERVER_MEMBERSHIP' }), bg({ action: 'FT_SERVER_POSITIONS' })]);
    const k = normKey(sym);
    const groups = [];
    const gmap = (mem && mem.ok && mem.data && mem.data.groups) || {};
    Object.keys(gmap).forEach(g => {
      const syms = (gmap[g] && gmap[g].symbols) || [];
      if (syms.some(s => normKey(s) === k)) groups.push(g);
    });
    let position = null, posMeta = null;
    if (pos && pos.ok && pos.data) {
      posMeta = pos.data._meta || null;
      for (const key of Object.keys(pos.data)) {
        if (key.startsWith('_')) continue;
        if (normKey(key) === k) { position = pos.data[key]; break; }
      }
    }
    return { symbol: sym, current, groups, position, posMeta, bridgeOk: !!((mem && mem.ok) || (pos && pos.ok)) };
  }
  function allGroups(c, includeCurrent) {
    const s = c.groups.slice();
    if (includeCurrent && c.current && !s.some(g => normGroup(g) === normGroup(c.current))) s.unshift(c.current);
    return s;
  }
  const removable = (groups) => groups.filter(g => !inList(g, PROTECTED));
  function positionQty(p) {
    if (!p) return 0;
    const n = parseFloat(String(p.quantity === undefined ? '' : p.quantity).replace(/,/g, ''));
    return Number.isFinite(n) && n > 0

