def _log(msg):
    print(f"[ChartBridge] {msg}", flush=True)


def _atomic_write(path, obj, backup=False):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    if backup and os.path.exists(path):
        try:
            shutil.copy2(path, path + ".bak")
        except Exception as e:
            _log(f"备份失败(忽略): {e}")
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(obj, f, ensure_ascii=False, indent=1)
    os.replace(tmp, path)


def _load_json(path):
    if not os.path.exists(path):
        return {}
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, dict) else {}
    except Exception as e:
        _log(f"读取 {os.path.basename(path)} 失败: {e}")
        return {}


def _file_size(path):
    try:
        return os.path.getsize(path)
    except Exception:
        return 0


def _gc_tasks_locked():
    now = time.time()
    for tid in list(_TASKS.keys()):
        t = _TASKS[tid]
        lease = float(t.get("lease") or TASK_LEASE)
        ttl = float(t.get("ttl") or TASK_TTL)
        if t["status"] == "taken" and (now - t["taken_at"]) > lease:
            t["status"] = "pending"
            _log(f"[任务] {tid} 租约超时，重新排队")
        if (now - t["created_at"]) > ttl:
            _TASKS.pop(tid, None)


def _task_public(t):
    return {k: v for k, v in t.items() if k != "event"}


def new_task(action, symbol, group, extra=None):
    with _TASK_LOCK:
        _TASK_SEQ[0] += 1
        tid = "t%d_%d" % (int(time.time() * 1000), _TASK_SEQ[0])
        t = {
            "id": tid, "action": action, "symbol": symbol, "group": group,
            "status": "pending", "created_at": time.time(), "taken_at": 0.0,
            "result": None, "event": threading.Event(),
        }
        if extra:
            t.update(extra)
        _TASKS[tid] = t
        _gc_tasks_locked()
    return t


def take_tasks(limit=3):
    out = []
    with _TASK_LOCK:
        _gc_tasks_locked()
        for t in _TASKS.values():
            if t["status"] != "pending":
                continue
            t["status"] = "taken"
            t["taken_at"] = time.time()
            out.append({"id": t["id"], "action": t["action"],
                        "symbol": t["symbol"], "group": t["group"],
                        "groups": t.get("groups"),
                        "restore": bool(t.get("restore", True))})
            if len(out) >= max(1, limit):
                break
    return out

def find_active_task(action, symbol=None, group=None):
    with _TASK_LOCK:
        _gc_tasks_locked()
        for t in _TASKS.values():
            if t["action"] != action or t["status"] not in ("pending", "taken"):
                continue
            if symbol is not None and _sym_key(t.get("symbol")) != _sym_key(symbol):
                continue
            if group is not None and _clean_group(t.get("group")) != _clean_group(group):
                continue
            return t
    return None

def finish_task(tid, ok, message, data=None):
    with _TASK_LOCK:
        t = _TASKS.get(str(tid))
        if not t:
            return False
        t["status"] = "done" if ok else "error"
        t["result"] = {"ok": bool(ok), "message": message or "",
                       "data": data or {}, "finished_at": time.time()}
        t["event"].set()
    return True


def pending_count():
    with _TASK_LOCK:
        return sum(1 for t in _TASKS.values() if t["status"] in ("pending", "taken"))


