def load_all_earnings_dates_scanner(db_path, earnings_files):
    """
    从数据库 Earning 表和文本文件中获取所有财报日期。
    返回字典: {'AAPL': {'2024-08-01', '2024-11-01'}, 'BOOT': {'2026-02-05'}, ...}
    使用 set 存储日期，防止遗漏和方便快速查找。
    """
    from collections import defaultdict
    earnings_map = defaultdict(set)

    # 1. 核心：从数据库 Earning 表读取所有历史财报日期
    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
        # 获取所有已记录的财报日期，而不仅仅是 MAX
        query = "SELECT name, date FROM Earning"
        cursor.execute(query)
        for name, date_str in cursor.fetchall():
            if name and date_str:
                # 确保日期格式统一为 YYYY-MM-DD
                clean_date = date_str.strip()
                earnings_map[name].add(clean_date)
        conn.close()
        print(f"从数据库加载了 {len(earnings_map)} 只股票的历史财报记录。")
    except Exception as e:
        print(f"读取数据库 Earning 表失败: {e}")

    # 2. 补充：从文本文件读取 (获取尚未同步进数据库的最新/未来财报)
    for filepath in earnings_files:
        if os.path.exists(filepath):
            try:
                with open(filepath, 'r', encoding='utf-8') as f:
                    for line in f:
                        parts = [p.strip() for p in line.split(':')]
                        if len(parts) >= 3:
                            symbol = parts[0]
                            date_str = parts[-1] 
                            # 简单的正则校验 YYYY-MM-DD
                            if re.match(r'\d{4}-\d{2}-\d{2}', date_str):
                                earnings_map[symbol].add(date_str)
            except Exception as e:
                print(f"读取财报文件 {filepath} 失败: {e}")

    return earnings_map

def run_volume_high_scanner():
    """Volume Scanner: 基于 Turnover 比较 + 修正后的 STRANGE 策略"""
    print("\n" + "="*50)
    print("STEP 3: 执行 Volume_High_Scanner 逻辑 (Turnover 模式 + STRANGE)")
    print("="*50)

    # 配置路径
    DB_PATH = os.path.join(BASE_CODING_DIR, 'Database/Finance.db')
    SECTORS_ALL_PATH = os.path.join(BASE_CODING_DIR, 'Financial_System/Modules/Sectors_All.json')
    COMPARE_ALL_PATH = os.path.join(BASE_CODING_DIR, 'News/backup/Compare_All.txt')
    DESCRIPTION_PATH = os.path.join(BASE_CODING_DIR, 'Financial_System/Modules/description.json')
    BLACKLIST_PATH = os.path.join(BASE_CODING_DIR, 'Financial_System/Modules/blacklist.json')

    # 财报文件列表 (引用 ConfigCompare 中的定义)
    EARNINGS_FILES = ConfigCompare.EARNINGS_FILES

    OUTPUT_FILENAME = f'{LOOKBACK_YEARS}Y_volume_high.txt'
    OUTPUT_FILE = os.path.join(BASE_CODING_DIR, f'News/{OUTPUT_FILENAME}')

    TARGET_SECTORS = [
        "Basic_Materials", "Communication_Services", "Consumer_Cyclical",
        "Consumer_Defensive", "Energy", "Financial_Services", "Healthcare",
        "Industrials", "Real_Estate", "Technology", "Utilities"
    ]
    ETF_SECTOR = "ETFs"

    # 1. 加载基础数据
    sectors_data = load_json_scanner(SECTORS_ALL_PATH)
    compare_map = load_compare_info_scanner(COMPARE_ALL_PATH)
    tags_map = load_tags_scanner(DESCRIPTION_PATH)
    blacklist = get_blacklist_scanner(BLACKLIST_PATH)

    # 加载所有财报日期集合
    all_earnings_sets = load_all_earnings_dates_scanner(DB_PATH, EARNINGS_FILES)

    # 【新增】构建 symbol 到表名的反查映射字典
    symbol_to_table = {}
    for table_name, symbols in sectors_data.items():
        for sym in symbols:
            symbol_to_table[sym] = table_name

    pos_results = [] 
    neg_results = []
    strange_results = []  # 新增
    skipped_by_earnings = 0

    # 2. 连接数据库
    try:
        conn = sqlite3.connect(DB_PATH)
        cursor = conn.cursor()
    except Exception as e:
        print(f"无法连接数据库: {e}")
        return

    # -------------------------------------------------------------------------
    # 【修正后】STRANGE 策略：扫描两次财报下跌 + 最新财报日当天跌 + 最新价反弹超20%
    # -------------------------------------------------------------------------
    print("\n开始扫描 STRANGE 策略股票...")
    for symbol, table_name in symbol_to_table.items():
        # 仅扫描普通股票板块，排除 ETFs、Bonds 等
        if table_name not in TARGET_SECTORS:
            continue
        if symbol in blacklist:
            continue

        try:
            # 1. 获取该股票在 Earning 表中的记录（按日期倒序）
            # 注意：这里的 price 字段是财报当天的涨跌幅百分比
            cursor.execute("""
                SELECT date, price FROM Earning 
                WHERE name = ? 
                ORDER BY date DESC LIMIT 2
            """, (symbol,))
            earnings_rows = cursor.fetchall()

            if len(earnings_rows) < 2:
                continue  # 至少需要两次财报数据

            latest_earn_date, latest_earn_change = earnings_rows[0]
            prev_earn_date, prev_earn_change = earnings_rows[1]

            # 规则 1：最新财报当天的涨跌幅（Earning 表里的 price）必须为负值
            if latest_earn_change >= 0:
                continue

            # 2. 去该 symbol 实际所在的板块表中，反查这两次财报日期的真实收盘价（price 字段）
            cursor.execute(f"""
                SELECT price FROM "{table_name}" 
                WHERE name = ? AND date = ?
            """, (symbol, latest_earn_date))
            latest_close_row = cursor.fetchone()

            cursor.execute(f"""
                SELECT price FROM "{table_name}" 
                WHERE name = ? AND date = ?
            """, (symbol, prev_earn_date))
            prev_close_row = cursor.fetchone()

            # 如果查不到对应的收盘价，跳过
            if not latest_close_row or not prev_close_row:
                continue

            latest_earn_close_price = latest_close_row[0]
            prev_earn_close_price = prev_close_row[0]

            if latest_earn_close_price is None or prev_earn_close_price is None:
                continue

            # 规则 2：两次财报的收盘价是持续下跌的（最新财报收盘价 < 上一期财报收盘价）
            if latest_earn_close_price >= prev_earn_close_price:
                continue

            # 3. 获取该股票当前最新的收盘价
            cursor.execute(f"""
                SELECT price FROM "{table_name}" 
                WHERE name = ? 
                ORDER BY date DESC LIMIT 1
            """, (symbol,))
            current_price_row = cursor.fetchone()
            if not current_price_row or current_price_row[0] is None:
                continue
            current_close = current_price_row[0]

            # 规则 3：最新收盘价比最新财报收盘价反弹超 20%
            if latest_earn_close_price <= 0:
                continue  # 避免除以 0 或异常负价格

            gain_pct = (current_close - latest_earn_close_price) / latest_earn_close_price
            if gain_pct >= 0.20:
                # 组装输出行
                info_str = compare_map.get(symbol, "")
                tags_str = tags_map.get(symbol, "")
                line = f"{table_name} {symbol} {info_str} {tags_str}".replace("  ", " ").strip()
                strange_results.append(line)
                print(f"[STRANGE 命中] {symbol}: 财报日收盘价从 {prev_earn_close_price:.2f} 跌至 {latest_earn_close_price:.2f} (当天跌幅 {latest_earn_change}%)，当前反弹至 {current_close:.2f} (+{gain_pct*100:.2f}%)")

        except Exception as e:
            # print(f"STRANGE 扫描 {symbol} 出错: {e}") # 调试用
            continue

    # -------------------------------------------------------------------------
    # 原来的 UP/DOWN 逻辑（不变）
    # -------------------------------------------------------------------------
    all_scan_sectors = TARGET_SECTORS + [ETF_SECTOR]
    for table_name in all_scan_sectors:
        if table_name not in sectors_data:
            continue
        symbols = sectors_data[table_name]
        print(f"正在扫描成交量: {table_name}...")

        for name in symbols:
            if name in blacklist:
                continue

            try:
                # A. 获取最近 2 天的数据，用于计算当天的 Turnover 和判断涨跌
                query_recent = f"SELECT date, price, volume FROM {table_name} WHERE name = ? ORDER BY date DESC LIMIT 2"
                cursor.execute(query_recent, (name,))
                rows = cursor.fetchall()

                if len(rows) < 2: continue

                latest_date_str, latest_price, latest_volume = rows[0]
                prev_price = rows[1][1]

                if latest_volume is None or latest_price is None or latest_volume <= 0: 
                    continue

                # 计算当天的成交额 (Turnover)
                latest_turnover = float(latest_price) * float(latest_volume)

                # B. 财报日过滤
                if name in all_earnings_sets:
                    if latest_date_str in all_earnings_sets[name]:
                        skipped_by_earnings += 1
                        # print(f"跳过财报日股票: {name} ({latest_date_str})") # 调试用
                        continue

                # C. 计算回溯日期
                latest_date_obj = datetime.strptime(latest_date_str, "%Y-%m-%d")
                # 减去 LOOKBACK_YEARS
                start_date_obj = latest_date_obj - relativedelta(years=int(LOOKBACK_YEARS), 
                                                                months=int((LOOKBACK_YEARS % 1) * 12))
                start_date = start_date_obj.strftime("%Y-%m-%d")

                # D. 获取过去 N 年的成交额排行（不含当天）
                # 在 SQL 中直接计算 price * volume 并排序
                query_hist = f"""
                    SELECT (price * volume) as turnover FROM {table_name} 
                    WHERE name = ? AND date >= ? AND date < ? 
                    AND price IS NOT NULL AND volume IS NOT NULL
                    ORDER BY turnover DESC LIMIT 2
                """
                cursor.execute(query_hist, (name, start_date, latest_date_str))
                hist_turnovers = [r[0] for r in cursor.fetchall()]

                if not hist_turnovers: continue 

                max_turnover_1 = float(hist_turnovers[0]) 
                max_turnover_2 = float(hist_turnovers[1]) if len(hist_turnovers) > 1 else max_turnover_1 

                # E. 判定逻辑 (使用 Turnover 替代 Volume)
                is_pos = (latest_price >= prev_price)
                qualified = False

                if is_pos:
                    # 价格上涨或持平：成交额是全期前两名
                    if latest_turnover >= max_turnover_2:
                        qualified = True
                else:
                    # 价格下跌：成交额是全期第一名
                    if latest_turnover >= max_turnover_1:
                        qualified = True

                if qualified:
                    turnover_display = format_turnover_scanner(latest_turnover)
                    info_str = compare_map.get(name, "")
                    tags_str = tags_map.get(name, "")
                    # 格式化输出
                    line = f"{table_name} {name} {info_str} {turnover_display} {tags_str}".replace("  ", " ").strip()

                    if is_pos:
                        pos_results.append(line)
                    else:
                        neg_results.append(line)

            except Exception as e:
                # print(f"Error processing {name}: {e}") # 调试时取消注释
                continue

    conn.close()

    # -------------------------------------------------------------------------
    # 输出文件：UP + DOWN + STRANGE
    # -------------------------------------------------------------------------
    try:
        os.makedirs(os.path.dirname(OUTPUT_FILE), exist_ok=True)
        with open(OUTPUT_FILE, 'w', encoding='utf-8') as f:
            if pos_results:
                f.write("========== UP ==========\n")
                f.write('\n'.join(pos_results) + '\n\n')

            if neg_results:
                f.write("========== DOWN ==========\n")
                f.write('\n'.join(neg_results) + '\n\n')

            # 输出 STRANGE
            if strange_results:
                f.write("========== STRANGE ==========\n")
                f.write('\n'.join(strange_results) + '\n')

        print(f"\n成功生成: {OUTPUT_FILENAME}")
        print(f"UP: {len(pos_results)} | DOWN: {len(neg_results)} | STRANGE: {len(strange_results)} | 财报跳过: {skipped_by_earnings}")
    except Exception as e:
        print(f"写入文件失败: {e}")

# ==============================================================================
# 主入口
# ==============================================================================
if __name__ == "__main__":
    print("************************************************************************")
    print(f"FULL SYSTEM START: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
    print("************************************************************************")

    # 执行第一部分 (Compare)
    execute_compare_process()

    # 执行第二部分 (Analyse)
    execute_analyse_process()

    # 执行第三部分 (Volume Scanner)
    run_volume_high_scanner()

    print("\n************************************************************************")
    print("所有任务执行完毕 (Compare + Analyse + VolumeScanner)。")
    print("************************************************************************")

