function mkSetter(el, okColor) {
  return (text, isError) => { el.style.color = isError ? '#b91c1c' : okColor; el.innerText = text; };
}
const setStatus = mkSetter(statusEl, '#059669');
const setBridge = mkSetter(bridgeEl, '#059669');
