    `★ 待添加：${r.missing} 只｜★ 多余(严格同步会删)：${r.extraCount} 只\n` +
    (r.srcCount === 0 ? '⚠ 数据源目标日期无数据（不回退）\n' : '') +
    (r.sample && r.sample.length ? `待加示例：${r.sample.join(', ')}\n` : '') +
    (r.extraSample && r.extraSample.length ? `多余示例：${r.extraSample.join(', ')}` : '');
