    job: '自选股同步(对账)',
    scan: '自选股行情抓取',
    diff: '差集比对',
    test: '单只操作自检',
    task: '🤖 远程添加(来自 Python)'
  };
  const PHASE_LABEL = {
    idle: '待开始', group: '切换分组', diff: '比对中',
    clear: '删除中', add: '添加中', verify: '复核中'
  };

  function buildHud() {
    hudEl = document.createElement('div');
    hudEl.id = 'ft-wl-hud';
    hudEl.innerHTML = `
      <div class="ft-wl-head">
        <span class="ft-wl-title">自选股同步(对账)</span>
        <span class="ft-wl-x" title="隐藏面板">✕</span>
      </div>
      <div class="ft-wl-line ft-wl-job-only" id="ft-wl-group">分组: --</div>
      <div class="ft-wl-line ft-wl-job-only" id="ft-wl-sub"
           style="color:#81A1C1 !important;font-size:11px !important;">--</div>
      <div class="ft-wl-bar ft-wl-job-only"><i id="ft-wl-bar-i"></i></div>
      <div class="ft-wl-line ft-wl-job-only" id="ft-wl-stat">等待开始</div>
      <div class="ft-wl-line ft-wl-cur" id="ft-wl-cur"></div>
      <div class="ft-wl-btns ft-wl-job-only">
        <button id="ft-wl-pause">暂停</button>
        <button id="ft-wl-stop">停止</button>
        <button id="ft-wl-copy">复制失败</button>
      </div>
      <div class="ft-wl-btns ft-wl-scan-only">
        <button id="ft-wl-scan-stop">停止抓取</button>
      </div>`;
    document.body.appendChild(hudEl);
    hudEl.querySelector('.ft-wl-x').addEventListener('click', () => { hudEl.style.display = 'none'; });
    hudEl.querySelector('#ft-wl-pause').addEventListener('click', () => togglePause());
    hudEl.querySelector('#ft-wl-stop').addEventListener('click', () => stopJob());
    hudEl.querySelector('#ft-wl-copy').addEventListener('click', () => copyFailed());
    hudEl.querySelector('#ft-wl-scan-stop').addEventListener('click', () => {
      scanState.abort = true;
      renderScan('⏹ 正在中止抓取…');
    });
    return hudEl;
  }

  function setHudMode(mode) {
    if (!mode) return;
    hudMode = (mode === 'job') ? 'job' : 'scan';
    hudEl.classList.toggle('ft-wl-scan', hudMode !== 'job');
    hudEl.querySelector('.ft-wl-title').textContent = HUD_TITLE[mode] || HUD_TITLE[hudMode];
  }

  function ensureHud(mode) {
    if (!hudEl || !document.body.contains(hudEl)) buildHud();
    if (mode) setHudMode(mode);
    hudEl.style.display = 'block';
    return hudEl;
  }

  function etaText(done, total, startedAt) {
    if (!startedAt || done <= 0 || !total || done >= total) return '';
    const per = (Date.now() - startedAt) / done;
    const left = Math.round(per * (total - done) / 1000);
    if (left <= 0) return '';
    return left < 90 ? `  剩~${left}s` : `  剩~${Math.round(left / 60)}min`;
  }

  function renderHud(extra) {
    const el = ensureHud('job');
    const clearing = job.phase === 'clear';
    el.classList.toggle('ft-wl-danger', clearing);
    el.querySelector('.ft-wl-title').textContent = clearing ? '⚠️ 正在删除自选股标的' : HUD_TITLE.job;

    let total, done, stat;
    if (clearing) {
      total = job.clearTotal || 0;
      done = job.cleared || 0;
      stat = `已删 ${done}/${total}  失败 ${job.clearFailed.length}` +
        etaText(done, total, job.clearStartedAt) + (job.paused ? '  ⏸已暂停' : '');
    } else {
      total = job.total || 0;
      done = job.done || 0;
      const p = total ? Math.min(100, Math.round(done / total * 100)) : 0;
      stat = `${done}/${total} (${p}%)  成功 ${job.added}  失败 ${job.failed.length}` +
        etaText(done, total, job.addStartedAt) + (job.paused ? '  ⏸已暂停' : '');
    }
    const pct = total ? Math.min(100, Math.round(done / total * 100)) : 0;

    el.querySelector('#ft-wl-group').textContent =
      `分组: ${job.group || '--'}｜${PHASE_LABEL[job.phase] || job.phase}` +
      (clearing ? '' : `｜第 ${job.pass || 1} 趟`);
    el.querySelector('#ft-wl-sub').textContent =
      `目标「${job.targetGroup || '-'}」｜源 ${SRC_LABEL[SRC.mode] || SRC.mode}` +
      `｜待删 ${job.removeQueue.length}｜待加 ${job.queue.length}` +
      `｜严格同步 ${job.strictSync ? '开' : '关'}`;
    el.querySelector('#ft-wl-bar-i').style.width = pct + '%';
    el.querySelector('#ft-wl-stat').textContent = stat;
    el.querySelector('#ft-wl-cur').textContent = extra || (job.current ? `当前: ${job.current}` : '');
    el.querySelector('#ft-wl-pause').textContent = job.paused ? '继续' : '暂停';
  }

  function renderScan(text, mode) {
    const el = ensureHud(mode || (hudMode === 'job' ? 'scan' : hudMode));
    el.classList.remove('ft-wl-danger');
    el.querySelector('#ft-wl-cur').textContent = text || '';
  }

  function hudInfo(text) {
    if (hudMode === 'job') renderHud(text);
    else renderScan(text);
  }

  function copyFailed() {
    const all = job.failed.map(f => `ADD\t${f.symbol}\t${f.error}`)
      .concat(job.clearFailed.map(f => `DEL\t${f.symbol}\t${f.error}`));
    const txt = all.join('\n');
    navigator.clipboard.writeText(txt || '(无失败项)').then(
      () => toast('📋 失败清单已复制'),
      () => console.log(LOG, '失败清单:\n' + txt));
  }

  /* ================= 任务状态机 ================= */
  const job = {
    running: false, paused: false, stop: false, finishing: false,
    phase: 'idle', clearFirst: false, clearOnly: false,
    strictSync: true, targetGroup: 'Earning', originGroup: '',
    group: '', pass: 1, total: 0, done: 0, added: 0,
    failed: [], queue: [], current: '', lastError: '',
    cleared: 0, clearTotal: 0, clearFailed: [], clearSkip: new Set(),
    removeQueue: [], backedUp: false,
    clearStartedAt: 0, addStartedAt: 0,
    startedAt: 0, sinceReload: 0, sinceReopen: 0,
    srcFrom: '', srcCount: 0, haveCount: 0,
    multi: null, skipQuotes: false
  };

  const scanState = { running: false, abort: false };

  function syncBusy() {
    window.__FT_AUTOMATION__ = !!(job.running || job.finishing || scanState.running ||
      window.__FT_AGENT_BUSY__ || window.__FT_TRADE_BUSY__);
  }

  async function persist(autoResume) {
    await storeSet({
      [JOB_KEY]: {
        v: 10, phase: job.phase, clearFirst: job.clearFirst, clearOnly: job.clearOnly,
        strictSync: job.strictSync, targetGroup: job.targetGroup, originGroup: job.originGroup,
        group: job.group, pass: job.pass, total: job.total, done: job.done,
        added: job.added, failed: job.failed, queue: job.queue, src: SRC.mode,
        cleared: job.cleared, clearTotal: job.clearTotal, clearFailed: job.clearFailed,
        removeQueue: job.removeQueue, backedUp: job.backedUp, skipQuotes: job.skipQuotes,
        autoResume: !!autoResume && !job.multi,          // ★ 多分组清空不做断点续跑
        ts: Date.now()
      }
    });
  }

  function togglePause() { job.paused = !job.paused; renderHud(); }
  function stopJob() {
    job.stop = true; job.paused = false;
    scanState.abort = true;
    renderHud('正在停止…');
  }

  /* ---------------- 数据源 ---------------- */
  async function manualList() {
    const st = await storeGet([MANUAL_KEY]);
    const arr = st[MANUAL_KEY];
    return Array.isArray(arr) ? arr.filter(Boolean) : [];
  }

  async function getSourceSymbols() {
    if (SRC.mode === 'manual') {
      const m = await manualList();
      if (m.length) return { symbols: m.slice(), from: '本地备用清单', detail: null };
      throw new Error('本地备用清单为空（popup 里保存一份，或切回财报日历）');
    }

    const r = await bg({ action: 'FT_WL_SOURCE', src: SRC.mode, back: SRC.back, ahead: SRC.ahead });
    /* ★ 不再「退而求其次」改用本地清单：严格同步按错误数据源对账会误删 */
    if (!r.ok || !r.data) {
      throw new Error('桥接服务不可用（' + (r.error || '无响应') + '）。为防止按错误清单增删已中止；' +
        '请先运行 bridge_server.py，或在 popup 把数据源切到「本地备用清单」');
    }
    const d = r.data;
    if (d.status === 'disabled') throw new Error(d.message || `数据源 ${SRC.mode} 已在 bridge_server.py 中停用`);
    if (d.status === 'error') throw new Error(d.message || '数据源返回错误');
    if (!Array.isArray(d.symbols)) throw new Error('数据源返回格式异常（缺少 symbols）');
    return {
      symbols: d.symbols.slice(), from: d.from || SRC.mode,
      detail: d.dates || null, empty: d.symbols.length === 0
    };
  }

  /* ★ 双向差集 */
  async function computeDiff() {
    const src = await getSourceSymbols();
    hudInfo(`来源 ${src.from}：${src.symbols.length} 只，正在抓取「${groupName()}」全表…`);
    const have = await collectWatchlist(n => hudInfo(`已读取 ${n} 只…`));
    const haveSymbols = Object.keys(have);
    const haveSet = new Set(haveSymbols.map(normKey));
    const srcSet = new Set(src.symbols.map(normKey));
    const missing = src.symbols.filter(s => !haveSet.has(normKey(s)));
    const extra = haveSymbols.filter(s => !srcSet.has(normKey(s)));
    return {
      srcFrom: src.from, srcCount: src.symbols.length, srcDetail: src.detail,
      srcSymbols: src.symbols, haveCount: haveSymbols.length, haveSymbols,
      missing, extra
    };
  }

  /* ================= 一键 pipeline ================= */
  function resetJob(opts) {
    opts = opts || {};
    job.running = true; job.paused = false; job.stop = false; job.finishing = false;
    job.phase = 'idle';
    job.clearFirst = !!opts.clearFirst;
    job.clearOnly = !!opts.clearOnly;
    job.strictSync = (opts.strictSync !== undefined) ? !!opts.strictSync : !!TARGET.strictSync;
    job.targetGroup = (opts.targetGroup || TARGET.group || '').trim();
    job.originGroup = groupName();
    job.group = job.originGroup;
    job.pass = 1; job.total = 0; job.done = 0; job.added = 0;
    job.failed = []; job.queue = []; job.current = ''; job.lastError = '';
    job.cleared = 0; job.clearTotal = 0; job.clearFailed = []; job.clearSkip = new Set();
    job.removeQueue = []; job.backedUp = false;
    job.clearStartedAt = 0; job.addStartedAt = 0;
    job.startedAt = Date.now(); job.sinceReload = 0; job.sinceReopen = 0;
    job.srcFrom = ''; job.srcCount = 0; job.haveCount = 0;
    job.multi = null;
    job.skipQuotes = !!opts.skipQuotes;
    RUN = Object.assign({}, CFG);
    scanState.abort = false;
    syncBusy();
  }

  async function startJob(opts) {
    opts = opts || {};
    if (!isWatchlistPage()) return { ok: false, error: '当前不在 /app/watchlist 页面' };
    if (job.running || job.finishing) return { ok: false, error: '任务已在运行中' };
    if (window.__FT_TRADE_BUSY__) return { ok: false, error: '快速交易进行中，请稍后' };
    if (scanState.running) return { ok: false, error: '行情抓取进行中，请稍后再启动' };

    const pageReady = document.querySelector('.ag-root, [role="grid"], .ag-body-viewport, main, [data-select-trigger]');
    if (!pageReady && !findAddButton()) {
      return { ok: false, error: '未识别到自选股页面元素，请等页面加载完成后重试' };
    }

    resetJob(opts);
    cleanNavSearch();
    ensureHud('job');
    renderHud('正在启动…');

    runPipeline({}).catch(e => {
      job.lastError = String((e && e.message) || e);
      renderHud('❌ ' + job.lastError);
      finishJob();
    });

    return {
      ok: true, started: true, group: job.group,
      targetGroup: job.targetGroup, strictSync: job.strictSync,
      clearFirst: job.clearFirst, clearOnly: job.clearOnly,
      rows: dataRowsTotal()
    };
  }

  async function runPipeline(opts) {
    opts = opts || {};

    /* ---------- 阶段 0：切到目标分组 ---------- */
    job.phase = 'group';
    if (!job.originGroup) job.originGroup = groupName();
    const want = job.targetGroup;
    if (want && normGroup(groupName()) !== normGroup(want)) {
      renderHud(`正在从「${job.originGroup || '?'}」切换到目标分组「${want}」…`);
      const sr = await switchGroup(want);
      if (!sr.ok) {
        job.lastError = sr.error || '切换分组失败';
        renderHud('❌ ' + job.lastError);
        toast('❌ ' + job.lastError);
        return finishJob();
      }
      await waitGridSettled();
    }
    job.group = groupName() || want;
    if (job.stop) return finishJob();

    if (!job.clearOnly) {
      const addBtn = await waitFor(findAddButton, 6000, 200);
      if (!addBtn) {
        job.lastError = `分组「${job.group}」里找不到「添加自选股」按钮（该分组可能不支持添加）`;
        renderHud('❌ ' + job.lastError);
        toast('❌ ' + job.lastError);
        return finishJob();
      }
    }
    renderHud(`已定位到分组「${job.group}」（表内 ${dataRowsTotal()} 只）`);
    await sleep(300);

    /* ---------- 阶段 1：比对（源 ↔ 现有），双向差集 ---------- */
    if (opts.resume && (job.queue.length || job.removeQueue.length)) {
      prepareRun(job.queue.length);
      renderHud(`续跑：待删 ${job.removeQueue.length}｜待加 ${job.queue.length}`);
    } else {
      job.phase = 'diff';
      renderHud('正在读取数据源并比对差集…');
      const d = await computeDiff();
      if (job.stop) return finishJob();
      job.srcFrom = d.srcFrom; job.srcCount = d.srcCount; job.haveCount = d.haveCount;

      if (job.clearOnly) {
        job.queue = [];
        job.removeQueue = d.haveSymbols.slice();
      } else if (job.clearFirst) {
        job.queue = d.srcSymbols.slice();
        job.removeQueue = d.haveSymbols.slice();
      } else {
        job.queue = d.missing.slice();
        job.removeQueue = job.strictSync ? d.extra.slice() : [];
      }
      job.total = job.queue.length;
      prepareRun(job.total);
      renderHud(`源 ${d.srcFrom}: ${d.srcCount} 只｜「${job.group}」现有 ${d.haveCount}` +
        `｜待删 ${job.removeQueue.length}｜待加 ${job.total}`);
      await sleep(700);
      if (d.srcCount === 0 && job.removeQueue.length) {
        const warn = `⚠ 数据源在目标日期无数据（不回退到最近财报日）→ 将从「${job.group}」删除全部 ${job.removeQueue.length} 只`;
        toast(warn);
        renderHud(warn);
        await sleep(1500);
      }

      if (!job.removeQueue.length && !job.queue.length) {
        toast(`✅ 分组「${job.group}」已与数据源完全一致，无需任何改动`);
        renderHud(`✅ 已一致：${d.haveCount} 只，未做任何点击`);
        return finishJob();
      }
    }

    /* ---------- 阶段 2：删除（多余 / 全清） ---------- */
    if (job.removeQueue.length && !job.stop) {
      if (!job.backedUp) {
        try { await backupCurrentList(); job.backedUp = true; }
        catch (e) { log('备份失败（继续执行）', e); }
      }
      if (job.stop) return finishJob();

      const wipeAll = (job.clearFirst || job.clearOnly);
      const r = wipeAll ? await runClearAllPhase() : await runRemovePhase(job.removeQueue);
      if (r === 'reload') return;
      if (r === 'stopped') return finishJob();
      renderHud(`✅ 删除阶段完成：删除 ${job.cleared} 只，失败 ${job.clearFailed.length}`);
      await sleep(700);
    }
    if (job.clearOnly || job.stop) return finishJob();

    if (!job.queue.length) {
      renderHud('无需添加，进入复核…');
    }

    /* ---------- 阶段 3：批量添加 ---------- */
    job.phase = 'add';
    job.addStartedAt = job.addStartedAt || Date.now();
    if (job.queue.length) {
      try {
        const inp = await ensureInput();
        assertSafeInput(inp);
        log('自检通过，输入框 =', inp.id || inp.placeholder);
        pressEscape();
        await sleep(200);
      } catch (e) {
        job.lastError = '输入框自检失败: ' + String((e && e.message) || e);
        renderHud('❌ ' + job.lastError);
        return finishJob();
      }
    }

    await persist(true);
    const r = await runAddLoop();
    if (r === 'reload') return;
    return finishJob();
  }

  async function runAddLoop() {
    let consecutiveFail = 0;

    for (; ;) {
      job.phase = 'add';
      while (job.queue.length && !job.stop) {
        while (job.paused && !job.stop) { renderHud(); await sleep(400); }
        if (job.stop) break;
        if (!(await guardGroup())) continue;

        const sym = job.queue[0];
        job.current = sym;
        renderHud();

        const r = await addOneSymbol(sym);
        if (r.status === 'aborted') break;

        job.queue.shift();
        job.done++;
        job.sinceReload++;
        job.sinceReopen++;

        if (r.status === 'added') { job.added++; consecutiveFail = 0; }
        else {
          job.failed.push({ symbol: sym, error: r.error || '未知' });
          job.lastError = r.error || '';
          consecutiveFail++;
        }
        renderHud();

        if (job.done % RUN.checkpointEvery === 0) await persist(true);

        if (consecutiveFail >= RUN.consecutiveFailAbort) {
          job.paused = true;
          consecutiveFail = 0;
          renderHud(`⚠ 连续失败过多（最后: ${job.lastError}），已自动暂停，请人工检查`);
          await persist(true);
        }

        if (RUN.reopenPanelEvery > 0 && job.sinceReopen >= RUN.reopenPanelEvery) {
          job.sinceReopen = 0;
          try { pressEscape(); } catch (e) { }
          await sleep(450);
        }

        if (RUN.reloadEvery > 0 && job.sinceReload >= RUN.reloadEvery && job.queue.length) {
          renderHud('页面即将刷新以释放内存，随后自动续跑…');
          await persist(true);
          await sleep(900);
          location.reload();
          return 'reload';
        }

        await sleep(RUN.perSymbolDelay + Math.random() * RUN.jitter);
      }

      try { pressEscape(); } catch (e) { }
      cleanNavSearch();

      if (job.stop || job.pass >= RUN.maxPasses) break;

      /* ---------- 阶段 4：复核（缺的补加，多的补删） ---------- */
      job.phase = 'verify';
      renderHud('本趟结束，正在复核分组与数据源是否一致…');
      try {
        if (!(await guardGroup())) continue;
        const d = await computeDiff();
        const extra = job.strictSync ? d.extra : [];
        if (!d.missing.length && !extra.length) {
          renderHud('✅ 复核通过：分组与数据源一致');
          break;
        }
        job.pass++;
        if (extra.length) {
          renderHud(`复核发现 ${extra.length} 只多余，正在删除…`);
          const rr = await runRemovePhase(extra, true);
          if (rr === 'stopped') break;
        }
        if (!d.missing.length) {
          if (job.pass >= RUN.maxPasses) break;
          continue;
        }
        job.queue = d.missing.slice();
        job.total = job.done + job.queue.length;
        job.sinceReload = 0;
        await persist(true);
        renderHud(`第 ${job.pass} 趟：仍缺 ${job.queue.length} 只`);
      } catch (e) { log('复核失败', e); break; }
    }
    return 'done';
  }

  async function finishJob() {
    job.finishing = true;
    job.running = false;
    job.current = '';
    job.phase = 'idle';
    syncBusy();
    try {
      await persist(false);
      const bits = [];
      if (job.multi) bits.push(`清空分组 ${job.multi.join('/')}`);
      if (job.cleared > 0 || job.clearFailed.length) bits.push(`删除 ${job.cleared}（失败 ${job.clearFailed.length}）`);
      if (!job.clearOnly) bits.push(`新增 ${job.added}（失败 ${job.failed.length}）`);
      const summary = bits.join(' ｜ ') || '无操作';
      renderHud(job.stop ? '⏹ 已手动停止：' + summary : `✅ 完成：${summary}`);
      toast(job.stop ? '⏹ 自选股任务已停止' : `✅ 自选股任务完成：${summary}`);

      if (!job.stop && !job.clearOnly && !job.skipQuotes) { try { await fullScanQuotes(true); } catch (e) { } }
      else if (!job.stop && job.clearOnly && !job.multi) { try { await collectWatchlist(); } catch (e) { } }

      try {
        if (TARGET.backToOrigin && job.originGroup && normGroup(groupName()) !== normGroup(job.originGroup)) {
          renderHud(`正在切回原分组「${job.originGroup}」…`);
          await switchGroup(job.originGroup);
          renderHud(`✅ ${summary}｜已切回「${job.originGroup}」`);
        }
      } catch (e) { log('切回原分组失败', e); }
    } finally {
      job.finishing = false;
      syncBusy();
    }
  }

  /* ================= ★ 一键清空除保留分组外的所有分组 ================= */
  const NOT_A_GROUP_RE = /新建|创建|管理|编辑|重命名|删除|new|create|manage|edit|rename|delete/i;
  const ALWAYS_KEEP = ['Earning', 'Wrong'];
  const stripCount = (s) => String(s || '').replace(/\u00a0/g, ' ').replace(/[（(]\s*\d+\s*[）)]\s*$/, '').trim();

  function snapshotEmpty(g) {
    try { const M = window.__FT_WL_MEMBER__; if (M && g) M.snapshot(g, [], true, 'clear_groups'); } catch (e) { }
  }
  function buildMultiBackup(b) {
    const all = [].concat(...Object.values(b));
    return { group: Object.keys(b).join(' + '), ts: Date.now(), count: all.length, src: 'clear_groups', symbols: all, groups: b };
  }

  async function startClearGroups(opts) {
    opts = opts || {};
    if (!isWatchlistPage()) return { ok: false, error: '当前不在 /app/watchlist 页面' };
    if (job.running || job.finishing) return { ok: false, error: '已有自选股任务在运行中' };
    if (scanState.running || window.__FT_AGENT_BUSY__ || window.__FT_TRADE_BUSY__) {
      return { ok: false, error: '行情抓取/远程任务/交易进行中，请稍后' };
    }
    const keep = Array.from(new Set(ALWAYS_KEEP.concat(Array.isArray(opts.keep) ? opts.keep : [])
      .map(s => String(s).trim()).filter(Boolean)));
    const keepN = new Set(keep.map(normGroup));
    const lr = await listGroupOptions();
    await sleep(300);
    if (!lr.ok) return { ok: false, error: '读不到页面分组列表：' + (lr.error || '下拉框没有选项') };
    const groups = Array.from(new Set((lr.options || []).map(stripCount).filter(Boolean)))
      .filter(n => !NOT_A_GROUP_RE.test(n) && !keepN.has(normGroup(n)));
    if (!groups.length) return { ok: true, started: false, keep, groups: [], message: '除保留分组外没有其它分组，无需清空' };

    resetJob({ clearOnly: true, targetGroup: groups[0], strictSync: false });
    job.multi = groups.slice();
    RUN.clearReloadEvery = 0;
    ensureHud('job');
    renderHud(`准备清空 ${groups.length} 个分组：${groups.join(' / ')}`);
    runMultiClear(groups, keep).catch(e => {
      job.lastError = String((e && e.message) || e);
      renderHud('❌ ' + job.lastError);
      finishJob();
    });
    return { ok: true, started: true, groups, keep };
  }

  async function runMultiClear(groups, keep) {
    for (let i = RUN.clearCountdown; i > 0 && !job.stop; i--) {
      renderHud(`⚠️ ${i} 秒后依次清空：${groups.join(' / ')}（保留 ${keep.join(' / ')}）…点「停止」可取消`);
      await sleep(1000);
    }
    const backups = {};
    for (let gi = 0; gi < groups.length && !job.stop; gi++) {
      const g = groups[gi];
      job.phase = 'group';
      job.targetGroup = g;
      renderHud(`(${gi + 1}/${groups.length}) 切换到「${g}」…`);
      const sr = await switchGroup(g);
      if (!sr.ok) {
        job.clearFailed.push({ symbol: `[${g}]`, error: sr.error || '切换失败' });
        job.lastError = sr.error || '';
        continue;
      }
      job.group = groupName() || g;
      await waitGridSettled();
      await sleep(300);
      if ((dataRowsTotal() || 0) === 0 && !firstDeletableRow()) { snapshotEmpty(job.group); continue; }
      try {
        renderHud(`(${gi + 1}/${groups.length}) 备份「${job.group}」…`);
        backups[job.group] = Object.keys(await collectWatchlist());
        await storeSet({ [BACKUP_KEY]: buildMultiBackup(backups) });
      } catch (e) { log('备份失败', e); }
      if (job.stop) break;
      const r = await runClearAllPhase(true);
      if (r === 'stopped') break;
      if ((dataRowsTotal() || 0) === 0) snapshotEmpty(job.group);
    }
    return finishJob();
  }

  async function resumeJob(saved) {
    resetJob({
      clearFirst: saved.clearFirst, clearOnly: saved.clearOnly,
      strictSync: saved.strictSync, targetGroup: saved.targetGroup || TARGET.group
    });
    job.originGroup = saved.originGroup || job.originGroup;
    job.group = saved.group || groupName();
    job.pass = saved.pass || 1;
    job.queue = saved.queue || [];
    job.removeQueue = saved.removeQueue || [];
    job.total = saved.total || job.queue.length;
    job.done = saved.done || 0;
    job.added = saved.added || 0;
    job.failed = saved.failed || [];
    job.cleared = saved.cleared || 0;
    job.clearTotal = saved.clearTotal || 0;
    job.clearFailed = saved.clearFailed || [];
    job.backedUp = !!saved.backedUp;
    cleanNavSearch();
    ensureHud('job');
    renderHud('已从上次进度续跑');
    runPipeline({ resume: true }).catch(e => {
      job.lastError = String((e && e.message) || e);
      renderHud('❌ ' + job.lastError);
      finishJob();
    });
  }

  /* ================= 变更% 快照（v11：区分「分组本来就空」与「页面/桥接异常」） ================= */
  async function fullScanQuotes(silent) {
    if (!isWatchlistPage()) return { ok: false, error: '当前不在 /app/watchlist 页面' };
    if (!silent) await waitFor(() => !job.finishing, 30000, 300);
    if (!silent && job.running) return { ok: false, error: '批量任务进行中，请先停止后再抓行情' };
    if (!silent && window.__FT_TRADE_BUSY__) return { ok: false, error: '快速交易进行中，请稍后' };
    if (scanState.running) return { ok: false, error: '已有抓取任务在进行中' };

    scanState.running = true;
    scanState.abort = false;
    syncBusy();
    const want = TARGET.group || 'Earning';
    const origin = groupName();
    let switched = false;
    const say = (t) => { if (!silent) renderScan(t, 'scan'); };
    try {
      if (normGroup(origin) !== normGroup(want)) {
        say(`正在切换到行情分组「${want}」…`);
        const sr = await switchGroup(want);
        if (!sr.ok) {
          const err = `页面异常：切换到「${want}」失败：${sr.error}（为防写入错误分组的数据，已中止）`;
          say('❌ ' + err);
          return { ok: false, error: err, pageError: true };
        }
        switched = !!sr.changed;
        await waitGridSettled();
      }
      const g = groupName();
      say(`正在全量抓取「${g}」的「变更%」…（请勿操作本标签页）`);
      let buf = await collectWatchlist(n => say(`「${g}」已抓 ${n} 只行情…`));
      let n = Object.keys(buf).length;
      if (scanState.abort) {
        say(`⏹ 已中止（已抓 ${n} 只，未写入本机）`);
        return { ok: false, error: '用户中止', count: n };
      }

      let empty = null;
      if (!n) {
        say(`「${g}」没读到任何行，正在判断是「分组本来就空」还是「页面异常」…`);
        const ce = await confirmGroupEmpty(want, 7000);
        if (ce.rowsAppeared) {
          buf = await collectWatchlist();
          n = Object.keys(buf).length;
        }
        if (!n) {
          if (!ce.empty) {
            const err = `页面异常：${ce.error || '无法确认分组为空'}（分组「${g || '?'}」，为防误清本机数据已中止，未写入）`;
            say('❌ ' + err);
            if (!silent) toast('❌ ' + err);
            return { ok: false, error: err, pageError: true, count: 0, group: g };
          }
          empty = await probeSourceCount();
        }
      }

      const resp = await bg({ action: 'FT_SYNC_WATCHLIST', payload: buf, overwrite: true, group: g });
      if (!resp.ok) {
        const err = `桥接异常：写入本机失败（${resp.error || '无响应'}），bridge_server.py 是否在运行？`;
        say('❌ ' + err);
        if (!silent) toast('❌ ' + err);
        return { ok: false, error: err, bridgeError: true, count: n, group: g, server: resp };
      }

      if (empty) {
        let message;
        if (empty.ok && empty.count === 0) {
          message = `分组「${g}」为空：数据源（${empty.from}）在目标日期没有符合条件的标的 → 已清空本机行情 JSON`;
        } else if (empty.ok) {
          message = `⚠ 分组「${g}」为空，但数据源有 ${empty.count} 只（一键同步可能未完成）→ 已按页面实际情况清空本机 JSON`;
        } else {
          message = `分组「${g}」为空（数据源核对失败：${empty.error}）→ 已按页面实际情况清空本机 JSON`;
        }
        say('✅ ' + message);
        if (!silent) toast('✅ ' + message.slice(0, 90));
        return {
          ok: true, count: 0, empty: true, srcOk: !!empty.ok,
          srcCount: empty.ok ? empty.count : null, message, server: resp, group: g
        };
      }

      say(`✅ 「${g}」已覆盖写入 ${n} 只行情`);
      if (!silent) toast(`✅ 已保存「${g}」${n} 只「变更%」`);
      return { ok: true, count: n, server: resp, group: g };
    } finally {
      if (switched && !silent && TARGET.backToOrigin && origin) {
        try { renderScan(`正在切回原分组「${origin}」…`); await switchGroup(origin); } catch (e) { }
      }
      scanState.running = false;
      syncBusy();
    }
  }

  let autoTimer = null;
  function autoTickSoon(delay = 2500) {
    if (!AUTO_WATCHLIST) return;
    clearTimeout(autoTimer);
    autoTimer = setTimeout(async () => {
      if (!AUTO_WATCHLIST || !isWatchlistPage() || job.running || scanState.running || window.__FT_AUTOMATION__) return;
      const g = groupName();
      if (!g || normGroup(g) !== normGroup(TARGET.group)) return;     // ★ 只在 Earning 分组时增量写
      const buf = scrapeRows(Object.create(null));
      if (!Object.keys(buf).length) return;
      const r = await bg({ action: 'FT_SYNC_WATCHLIST', payload: buf, overwrite: false, group: g });
      log('自动增量同步自选股', Object.keys(buf).length, r.ok ? 'ok' : r.error);
    }, delay);
  }

  /* ================= 设置 & 引导 ================= */
  function loadSettings() {
    chrome.storage.local.get(
      ['ftDebug', 'ftAutoWatchlist', 'ftWlCfg', 'ftWlSource', 'ftWlBack', 'ftWlAhead',
        'ftWlTargetGroup', 'ftWlStrictSync', 'ftWlRestoreGroup'],
      (res) => {
        DEBUG = !!res.ftDebug;
        AUTO_WATCHLIST = res.ftAutoWatchlist === true;
        if (res.ftWlCfg && typeof res.ftWlCfg === 'object') Object.assign(CFG, res.ftWlCfg);
        SRC.mode = res.ftWlSource || 'earnings';
        const b = parseInt(res.ftWlBack, 10);
        const a = parseInt(res.ftWlAhead, 10);
        SRC.back = Number.isFinite(b) ? Math.max(0, b) : 1;
        SRC.ahead = Number.isFinite(a) ? Math.max(0, a) : 0;
        let tg = (res.ftWlTargetGroup === undefined || res.ftWlTargetGroup === null ||
          String(res.ftWlTargetGroup).trim() === '') ? 'Earning' : String(res.ftWlTargetGroup).trim();
        if (normGroup(tg) === 'ALL') tg = 'Earning';          // ★ 旧设置迁移
        TARGET.group = tg;
        TARGET.strictSync = res.ftWlStrictSync !== false;
        TARGET.backToOrigin = res.ftWlRestoreGroup !== false;
        if (!job.running) RUN = Object.assign({}, CFG);
        log('设置: AUTO =', AUTO_WATCHLIST, 'SRC =', SRC, 'TARGET =', TARGET);
      });
  }
  chrome.storage.onChanged.addListener((c, area) => {
    if (area !== 'local') return;
    if (c.ftDebug || c.ftAutoWatchlist || c.ftWlCfg || c.ftWlSource || c.ftWlBack ||
      c.ftWlAhead || c.ftWlTargetGroup || c.ftWlStrictSync || c.ftWlRestoreGroup) loadSettings();
  });

  async function bootstrap() {
    loadSettings();
    if (!isWatchlistPage()) return;

    await waitFor(() => (document.querySelector('.ag-root, [role="grid"], main') &&
      (findAddButton() || document.querySelector('[role="grid"]'))), 25000, 400);

    const st = await storeGet([JOB_KEY]);
    const saved = st[JOB_KEY];
    const hasWork = saved && saved.autoResume &&
      ((Array.isArray(saved.queue) && saved.queue.length) ||
        (Array.isArray(saved.removeQueue) && saved.removeQueue.length) ||
        saved.phase === 'clear');
    if (hasWork) {
      ensureHud('job');
      job.group = saved.group; job.total = saved.total; job.done = saved.done;
      job.added = saved.added; job.failed = saved.failed || []; job.pass = saved.pass || 1;
      job.cleared = saved.cleared || 0; job.clearTotal = saved.clearTotal || 0;
      job.queue = saved.queue || []; job.removeQueue = saved.removeQueue || [];
      job.targetGroup = saved.targetGroup || TARGET.group;
      job.phase = saved.phase || 'add';
      const what = (saved.removeQueue && saved.removeQueue.length)
        ? `删除（剩 ${saved.removeQueue.length} 只）`
        : `添加（剩 ${(saved.queue || []).length} 只）`;
      for (let i = 5; i > 0; i--) {
        renderHud(`检测到未完成任务：${what}，目标分组「${job.targetGroup}」，${i} 秒后自动续跑…点「停止」可取消`);
        await sleep(1000);
        if (job.running) return;              // ★ 倒计时期间用户/后台已启动新任务 → 放弃续跑
        if (job.stop) {
          await storeSet({ [JOB_KEY]: Object.assign({}, saved, { autoResume: false }) });
          renderHud('⏹ 已取消续跑');
          job.stop = false;
          return;
        }
      }
      if (job.running) return;
      resumeJob(saved);
      return;
    }
    autoTickSoon(4000);
  }

  document.addEventListener('scroll', () => autoTickSoon(3000), true);
  setInterval(() => { if (!job.running && !scanState.running) autoTickSoon(1500); }, 60000);

  /* ================= 与 popup 通信 ================= */
  chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
    if (!msg || !msg.action || !String(msg.action).startsWith('FT_WL_')) return;

    if (msg.action === 'FT_WL_STATUS') {
      sendResponse({
        ok: true, page: isWatchlistPage(), path: location.pathname,
        group: groupName(), gridRows: gridRowCount(), dataRows: dataRowsTotal(),
        auto: AUTO_WATCHLIST,
        src: SRC.mode, srcBack: SRC.back, srcAhead: SRC.ahead,
        targetGroup: TARGET.group, strictSync: TARGET.strictSync,
        onTarget: normGroup(groupName()) === normGroup(TARGET.group),
        originGroup: job.originGroup,
        running: job.running, paused: job.paused, pass: job.pass,
        phase: job.phase, clearFirst: job.clearFirst, clearOnly: job.clearOnly,
        scanning: scanState.running,
        total: job.total, done: job.done, added: job.added,
        failed: job.failed.length, toAdd: job.queue.length, toRemove: job.removeQueue.length,
        cleared: job.cleared, clearTotal: job.clearTotal, clearFailed: job.clearFailed.length,
        srcFrom: job.srcFrom, srcCount: job.srcCount, haveCount: job.haveCount,
        finishing: job.finishing, multi: job.multi,
        lastError: job.lastError
      });
      return;
    }

    /* ★ 列出/切换分组（popup 的「检测/切换」按钮） */
    if (msg.action === 'FT_WL_GROUPS_PROBE') {
      (async () => {
        if (job.running || job.finishing) { sendResponse({ ok: false, error: '任务进行中，勿手动切分组' }); return; }
        const r = await listGroupOptions();
        let switched = null;
        if (msg.switchTo) {
          const sr = await switchGroup(msg.switchTo);
          switched = sr;
        }
        sendResponse({
          ok: true, current: groupName(), options: r.options || [],
          probeError: r.error || '', switched,
          dataRows: dataRowsTotal()
        });
      })();
      return true;
    }

    if (msg.action === 'FT_WL_PROBE') {
      (async () => {
        const btn = findAddButton();
        const del = firstDeletableRow();
        let info = {
          ok: true,
          addBtn: btn ? `${cleanText(btn).slice(0, 20)} (id=${btn.id || '-'}, state=${btn.getAttribute('data-state') || '-'})` : '未找到',
          popover: popoverRoots().length,
          input: '未打开/未找到',
          items: 0, itemSample: [],
          rows: gridRowCount(),
          dataRows: dataRowsTotal(),
          group: groupName(),
          topRow: del ? `${del.sym} (rowId=${del.rowId}, 菜单按钮 id=${del.btn.id || '-'})` : '未找到可删除行'
        };
        try {
          const inp = await ensureInput();
          info.input = `id=${inp.id || '-'} placeholder=${inp.placeholder || '-'} inPopover=${!!inp.closest('[data-popover-content]')} forbidden=${isForbiddenInput(inp)}`;
          await typeInto(inp, msg.symbol ? String(msg.symbol).toUpperCase() : 'LIN');
          const res = await waitForSuggestion(msg.symbol || 'LIN', 5000);
          const items = listItems();
          info.items = items.length;
          info.itemSample = items.slice(0, 5).map(itemValue);
          info.exact = res.exact;
          setNativeValue(inp, '');
          pressEscape();
        } catch (e) {
          info.error = String(e.message || e);
        }
        sendResponse(info);
      })();
      return true;
    }

    if (msg.action === 'FT_WL_PROBE_DEL') {
      (async () => {
        const tgt = msg.symbol ? await locateRow(String(msg.symbol).toUpperCase()) : firstDeletableRow();
        if (!tgt) { sendResponse({ ok: false, error: '未找到带三点菜单的目标行' }); return; }
        closeMenus(); await sleep(100);
        fireMouseSeq(tgt.btn);
        const item = await waitFor(findRemoveMenuItem, 2500, 100);
        const roots = menuRoots();
        const sample = roots.length
          ? Array.from(roots[roots.length - 1].querySelectorAll('[role="menuitem"],[data-dropdown-menu-item]'))
            .map(x => `${cleanText(x)}#${x.id || '-'}`).slice(0, 10)
          : [];
        closeMenus();
        sendResponse({
          ok: true, symbol: tgt.sym, rowId: tgt.rowId,
          menus: roots.length, menuItems: sample,
          removeFound: !!item, removeId: item ? (item.id || '-') : '-'
        });
      })();
      return true;
    }

    if (msg.action === 'FT_WL_TEST_ADD') {
      const sym = String(msg.symbol || '').trim().toUpperCase();
      if (!sym) { sendResponse({ ok: false, error: '未提供 symbol' }); return; }
      renderScan('测试添加 ' + sym + ' …', 'test');
      addOneSymbol(sym)
        .then(r => { renderScan('测试结果: ' + JSON.stringify(r)); sendResponse({ ok: true, result: r }); })
        .catch(e => sendResponse({ ok: false, error: String(e.message || e) }));
      return true;
    }

    if (msg.action === 'FT_WL_TEST_DEL') {
      if (job.running) { sendResponse({ ok: false, error: '批量任务进行中' }); return; }
      renderScan('测试删除…', 'test');
      const p = msg.symbol ? deleteSymbol(String(msg.symbol).toUpperCase()) : deleteTopRow(new Set());
      p.then(r => { renderScan('测试删除结果: ' + JSON.stringify(r)); sendResponse({ ok: true, result: r }); })
        .catch(e => sendResponse({ ok: false, error: String(e.message || e) }));
      return true;
    }

    if (msg.action === 'FT_WL_DIFF') {
      if (job.running) { sendResponse({ ok: false, error: '批量任务进行中，请先停止' }); return; }
      renderScan('正在比对差集…', 'diff');
      scanState.running = true; scanState.abort = false; syncBusy();
      computeDiff()
        .then(d => {
          renderScan(`来源 ${d.srcFrom}：${d.srcCount}｜现有 ${d.haveCount}｜待加 ${d.missing.length}｜多余 ${d.extra.length}`);
          sendResponse({
            ok: true, srcFrom: d.srcFrom, srcCount: d.srcCount, srcDetail: d.srcDetail,
            srcSymbols: d.srcSymbols.slice(0, 60),
            haveCount: d.haveCount, missing: d.missing.length,
            extraCount: d.extra.length, extraSample: d.extra.slice(0, 20),
            sample: d.missing.slice(0, 20), group: groupName(),
            targetGroup: TARGET.group, onTarget: normGroup(groupName()) === normGroup(TARGET.group)
          });
        })
        .catch(e => {
          renderScan('❌ ' + String(e.message || e));
          sendResponse({ ok: false, error: String(e.message || e) });
        })
        .finally(() => { scanState.running = false; syncBusy(); });
      return true;
    }

    if (msg.action === 'FT_WL_START') {
      startJob({
        clearFirst: !!msg.clearFirst, clearOnly: !!msg.clearOnly,
        strictSync: msg.strictSync, targetGroup: msg.targetGroup, skipQuotes: !!msg.skipQuotes
      }).then(r => sendResponse(r)).catch(e => sendResponse({ ok: false, error: String(e) }));
      return true;
    }

    if (msg.action === 'FT_WL_CLEAR_GROUPS') {
      startClearGroups({ keep: msg.keep }).then(r => sendResponse(r)).catch(e => sendResponse({ ok: false, error: String(e) }));
      return true;
    }

    if (msg.action === 'FT_WL_PAUSE') { togglePause(); sendResponse({ ok: true, paused: job.paused }); return; }
    if (msg.action === 'FT_WL_STOP') { stopJob(); scanState.abort = true; sendResponse({ ok: true }); return; }
    if (msg.action === 'FT_WL_FAILED') {
      sendResponse({ ok: true, list: job.failed, clearList: job.clearFailed });
      return;
    }
    if (msg.action === 'FT_WL_HUD') {
      ensureHud();
      if (hudMode === 'job') renderHud(); else renderScan();
      sendResponse({ ok: true, mode: hudMode, phase: job.phase });
      return;
    }

    if (msg.action === 'FT_WL_SCAN_QUOTES') {
      fullScanQuotes(false).then(r => sendResponse(r)).catch(e => sendResponse({ ok: false, error: String(e) }));
      return true;
    }
  });

  /* ================= 对外 API（wl_agent.js 复用） ================= */
  window.__FT_WL_API__ = {
    version: 10.1,
    isWatchlistPage, groupName, normGroup, switchGroup, listGroupOptions,
    waitGridSettled, gridRowCount, dataRowsTotal, gridSaysEmpty, normKey,
    collectWatchlist, addOneSymbol, deleteSymbol, hasSymbolInGrid, rowQuote, findRowQuote,
    cleanNavSearch, pressEscape, ensureHud, renderScan, toast,
    targetGroup: () => TARGET.group,
    isBusy: () => !!(job.running || job.finishing || scanState.running),
    clearStopFlags: () => { if (!job.running) job.stop = false; scanState.abort = false; },
    setExternalBusy: (v) => { window.__FT_AGENT_BUSY__ = !!v; syncBusy(); },
    setTradeBusy: (v) => { window.__FT_TRADE_BUSY__ = !!v; syncBusy(); }
  };

  bootstrap();
  console.log(LOG, `watchlist.js v10 就绪（isWatchlist=${isWatchlistPage()}，目标分组默认 ${TARGET.group}）`);
})();

/* ============================================================================
 * Firstrade 远程代理  wl_agent.js  v3     仅在 /app/watchlist 生效
 *   Python → bridge_server.py 任务队列 → 本脚本轮询领任务
 *   action: add / remove / trade / scan_groups / ★ quote（G 键取「变更%」）
 * ==========================================================================*/
(() => {
  if (window.__FT_WL_AGENT_V3__) return;
  window.__FT_WL_AGENT_V3__ = true;

  const LOG = '[FT-AGENT]';
  const POLL_MS = 2000;
  const FORBIDDEN = 'header, #app-header, nav, #app-quote-bar';
  const ROW_EXCLUDE = '.ag-floating-top, .ag-floating-bottom, #app-quote-bar, header, #app-header';
  const TEMP_GROUP = 'temp';
  const SRC_TXT = { positions: '持仓页', current: '当前分组', group: '自选分组', temp: '临时分组' };

  let ENABLED = true;
  let RESTORE = true;
  let DEBUG = false;
  let busy = false;

  const sleep = (ms) => new Promise(r => setTimeout(r, ms));
  const log = (...a) => { if (DEBUG) console.log(LOG, ...a); };
  const isWatchlistPage = () => /\/watchlist/i.test(location.pathname || '');
  const api = () => window.__FT_WL_API__ || null;
  const norm = (s) => String(s || '').replace(/\s+/g, '').trim();
  const toast = (t) => { try { (window.__FT_TOAST__ || console.log)(t); } catch (e) { } };

  function isVisible(el) {
    if (!el) return false;
    const st = getComputedStyle(el);
    if (st.visibility === 'hidden' || st.display === 'none' || st.opacity === '0') return false;
    if (st.display === 'contents') return true;
    const r = el.getBoundingClientRect();
    return !!(r.width || r.height);
  }
  function cleanText(el) {
    const t = (el && (el.innerText || el.textContent)) || '';
    return t.replace(/\u00a0/g, ' ').replace(/\s+/g, ' ').trim();
  }
  async function waitFor(fn, timeout = 4000, interval = 100) {
    const t0 = Date.now();
    for (; ;) {
      let v = null;
      try { v = fn(); } catch (e) { v = null; }
      if (v) return v;
      if (Date.now() - t0 > timeout) return null;
      await sleep(interval);
    }
  }
  function sendKey(el, key, keyCode) {
    const opt = { bubbles: true, cancelable: true, key, code: key, keyCode, which: keyCode };
    el.dispatchEvent(new KeyboardEvent('keydown', opt));
    el.dispatchEvent(new KeyboardEvent('keyup', opt));
  }
  function fireMouseSeq(el) {
    const r = el.getBoundingClientRect();
    const opt = {
      bubbles: true, cancelable: true, view: window,
      clientX: r.left + Math.max(2, r.width / 2), clientY: r.top + Math.max(2, r.height / 2),
      button: 0, buttons: 1, pointerId: 1, isPrimary: true, pointerType: 'mouse'
    };
    try { el.dispatchEvent(new PointerEvent('pointerover', opt)); } catch (e) { }
    try { el.dispatchEvent(new PointerEvent('pointerenter', opt)); } catch (e) { }
    el.dispatchEvent(new MouseEvent('mouseover', opt));
    el.dispatchEvent(new MouseEvent('mousemove', opt));
    try { el.dispatchEvent(new PointerEvent('pointerdown', opt)); } catch (e) { }
    el.dispatchEvent(new MouseEvent('mousedown', opt));
    try { el.dispatchEvent(new PointerEvent('pointerup', Object.assign({}, opt, { buttons: 0 }))); } catch (e) { }
    el.dispatchEvent(new MouseEvent('mouseup', Object.assign({}, opt, { buttons: 0 })));
    el.dispatchEvent(new MouseEvent('click', Object.assign({}, opt, { buttons: 0 })));
  }
  function bg(msg) {
    return new Promise((resolve) => {
      try {
        chrome.runtime.sendMessage(msg, (resp) => {
          if (chrome.runtime.lastError) { resolve({ ok: false, error: chrome.runtime.lastError.message }); return; }
          resolve(resp || { ok: false, error: 'no response' });
        });
      } catch (e) { resolve({ ok: false, error: String(e) }); }
    });
  }
  function symFromRowId(rowId) {
    if (!rowId) return '';
    const raw = String(rowId).split('|')[0].trim().toUpperCase();
    return /^[A-Z][A-Z0-9.\-]{0,9}$/.test(raw) ? raw : '';
  }

  function groupTrigger() {
    const all = Array.from(document.querySelectorAll('[data-select-trigger]'))
      .filter(el => isVisible(el) && !el.closest(FORBIDDEN));
    const inMain = all.filter(el => el.closest('main'));
    return inMain[0] || all[0] || null;
  }
  function currentGroup() {
    const a = api();
    if (a && a.groupName) { const g = a.groupName(); if (g) return g; }
    const t = groupTrigger();
    return t ? cleanText(t) : '';
  }
  const sameGroup = (x, y) => {
    const a = api();
    if (a && a.normGroup) return a.normGroup(x) === a.normGroup(y);
    return norm(x).toUpperCase() === norm(y).toUpperCase();
  };
  function selectOptions() {
    const roots = Array.from(document.querySelectorAll(
      '[data-select-content], [role="listbox"], [data-popover-content]'
    )).filter(el => isVisible(el) && !el.closest(FORBIDDEN));
    let items = [];
    roots.forEach(r => { items = items.concat(Array.from(r.querySelectorAll('[data-select-item], [role="option"]'))); });
    if (!items.length) {
      items = Array.from(document.querySelectorAll('[data-select-item], [role="option"]'))
        .filter(el => !el.closest(FORBIDDEN));
    }
    return items.filter(isVisible);
  }
  const optionLabel = (el) => norm(cleanText(el));

  function gridRowCount() {
    const a = api();
    if (a && a.gridRowCount) return a.gridRowCount();
    const gs = Array.from(document.querySelectorAll('[role="grid"][aria-rowcount]'))
      .filter(g => !g.closest(FORBIDDEN));
    let best = null;
    gs.forEach(g => {
      const n = parseInt(g.getAttribute('aria-rowcount'), 10);
      if (Number.isFinite(n) && (best === null || n > best)) best = n;
    });
    return best;
  }
  async function waitGridSettled(timeout = 8000) {
    const t0 = Date.now();
    let last = null, same = 0;
    while (Date.now() - t0 < timeout) {
      const n = gridRowCount();
      if (n !== null && n === last) { same++; if (same >= 3) return n; }
      else { same = 0; last = n; }
      await sleep(200);
    }
    return gridRowCount();
  }

  async function switchGroup(target) {
    const a = api();
    if (a && typeof a.switchGroup === 'function') return a.switchGroup(target);
    return switchGroupLocal(target);
  }
  async function switchGroupLocal(target) {
    const want = norm(target);
    if (!want) return { ok: false, error: '目标分组名为空' };
    if (norm(currentGroup()) === want) return { ok: true, changed: false };
    const trig = groupTrigger();
    if (!trig) return { ok: false, error: '页面上找不到分组选择器 [data-select-trigger]' };
    for (let attempt = 0; attempt < 3; attempt++) {
      if (trig.getAttribute('data-state') === 'open' || trig.getAttribute('aria-expanded') === 'true') {
        sendKey(trig, 'Escape', 27);
        await sleep(250);
      }
      fireMouseSeq(trig);
      const opts = await waitFor(() => { const o = selectOptions(); return o.length ? o : null; }, 3500, 120);
      if (!opts) { await sleep(450); continue; }
      const hit = opts.find(o => optionLabel(o) === want);
      if (!hit) {
        const names = opts.map(optionLabel).filter(Boolean);
        sendKey(trig, 'Escape', 27);
        return { ok: false, error: `分组「${target}」不存在（页面可选：${names.join(' / ') || '空'}）` };
      }
      fireMouseSeq(hit);
      try { hit.click(); } catch (e) { }
      const ok = await waitFor(() => norm(currentGroup()) === want, 7000, 160);
      if (ok) { await waitGridSettled(); return { ok: true, changed: true }; }
      sendKey(trig, 'Escape', 27);
      await sleep(500);
    }
    return { ok: false, error: `切换到分组「${target}」失败（重试 3 次）` };
  }

  async function alreadyHas(sym) {
    const a = api();
    if (!a || !a.collectWatchlist || !a.dataRowsTotal) return false;
    const rows = a.dataRowsTotal();
    if (rows === null || rows <= 0) return false;
    if (rows > 400) return false;
    const buf = await a.collectWatchlist();
    const t = a.normKey(sym);
    return Object.keys(buf).some(k => a.normKey(k) === t);
  }

  /* ★ 分组归属全量扫描任务（Python 图表 M 键） */
  async function handleScanTask(t) {
    const M = window.__FT_WL_MEMBER__;
    let ok = false, msg = '', data = {};
    if (!M) msg = 'wl_membership.js 未加载（请刷新 watchlist 页面）';
    else {
      try {
        const r = await M.scanAllGroups(Array.isArray(t.groups) ? t.groups : null);
        ok = !!r.ok;
        msg = r.message || r.error || '';
        data = { results: r.results || [], groups: r.groups || [] };
      } catch (e) { msg = String((e && e.message) || e); }
    }
    toast((ok ? '✅ ' : '❌ ') + msg);
    console.log(LOG, msg);
    await bg({ action: 'FT_WL_TASK_RESULT', payload: { id: t.id, ok, message: msg, data } });
  }

  async function reportTask(t, ok, msg, data, restore, origin) {
    const a = api();
    try {
      if (restore && origin && !sameGroup(currentGroup(), origin)) await switchGroup(origin);
    } catch (e) { log('切回原分组失败', e); }
    try { a.pressEscape(); a.cleanNavSearch(); } catch (e) { }
    const text = (ok ? '✅ ' : '❌ ') + msg;
    try { a.renderScan(text); } catch (e) { }
    toast(text);
    console.log(LOG, text);
    await bg({ action: 'FT_WL_TASK_RESULT', payload: { id: t.id, ok, message: msg, data } });
  }

  async function handleRemoveTask(t) {
    const a = api();
    const sym = String(t.symbol || '').trim().toUpperCase();
    const grp = String(t.group || '').trim();
    const restore = (t.restore === undefined) ? RESTORE : (!!t.restore && RESTORE);
    const origin = currentGroup();
    let ok = false, msg = '', status = '';
    try { a.ensureHud('task'); a.renderScan(`收到删除任务：${sym} ✕「${grp}」`, 'task'); } catch (e) { }
    try {
      if (!sym) throw new Error('symbol 为空');
      if (!grp) throw new Error('删除任务必须指定分组');
      if (typeof a.deleteSymbol !== 'function') throw new Error('watchlist.js 版本过旧（缺少 deleteSymbol），请刷新页面');
      a.clearStopFlags();
      a.cleanNavSearch();
      const sr = await switchGroup(grp);
      if (!sr.ok) throw new Error(sr.error);
      await waitGridSettled(4000);
      const r = await a.deleteSymbol(sym);
      status = (r && r.status) || '';
      if (status === 'removed') { ok = true; msg = `${sym} 已从「${grp}」删除`; }
      else if (status === 'missing') { ok = true; msg = `${sym} 本就不在「${grp}」中（已同步本机记录）`; }
      else msg = `${sym} 从「${grp}」删除失败：${(r && (r.error || r.status)) || '未知原因'}`;
    } catch (e) { ok = false; msg = String((e && e.message) || e); }
    await reportTask(t, ok, msg, { symbol: sym, group: grp, status }, restore, origin);
  }

  /* ★ 远程交易：at-most-once */
  async function handleTradeTask(t) {
    const T = window.__FT_TRADE__;
    const p = t.params || {};
    const st = await new Promise(r => chrome.storage.local.get(['ftTradeDoneIds'], r));
    const doneIds = Array.isArray(st.ftTradeDoneIds) ? st.ftTradeDoneIds : [];
    if (doneIds.includes(t.id)) {
      await bg({ action: 'FT_WL_TASK_RESULT', payload: { id: t.id, ok: false, message: '该交易任务已执行过（防重复下单，已忽略）' } });
      return;
    }
    await new Promise(r => chrome.storage.local.set({ ftTradeDoneIds: doneIds.concat([t.id]).slice(-300) }, r));
    let ok = false, msg = '', data = {};
    if (!T) msg = 'ft_trade.js 未加载（请刷新 watchlist 页面）';
    else {
      try {
        const r = await T.executeRemote({
          symbol: t.symbol, side: p.side, amount: p.amount, qty: p.qty,
          remove: p.remove !== false, dry: !!p.dry
        });
        ok = !!r.ok; msg = r.message || r.error || ''; data = r;
      } catch (e) { msg = String((e && e.message) || e); }
    }
    toast((ok ? '✅ ' : '❌ ') + msg);
    await bg({ action: 'FT_WL_TASK_RESULT', payload: { id: t.id, ok, message: msg, data } });
  }

  /* ==================== ★ G 键取「变更%」 ==================== */
  function visibleSyms() {
    const out = [], seen = new Set();
    document.querySelectorAll('[row-id]').forEach(r => {
      if (r.closest(ROW_EXCLUDE)) return;
      const s = symFromRowId(r.getAttribute('row-id'));
      if (s && !seen.has(s)) { seen.add(s); out.push(s); }
    });
    return out;
  }
  const quoteReady = (q) => !!(q && /%/.test(q.change_pct || ''));

  async function waitQuote(sym, timeout) {
    const a = api();
    const t0 = Date.now();
    let q = null;
    while (Date.now() - t0 < timeout) {
      q = a.rowQuote(sym) || q;
      if (quoteReady(q) && q.price > 0) return q;
      await sleep(250);
    }
    return q;
  }

  async function quoteInGroup(sym, grp) {
    const a = api();
    const sr = await switchGroup(grp);
    if (!sr.ok) throw new Error(sr.error || '切换失败');
    await waitGridSettled(4000);
    let q = await a.findRowQuote(sym, true);
    if (!q) throw new Error(`「${grp}」里没找到 ${sym}`);
    if (!quoteReady(q)) q = (await waitQuote(sym, 3000)) || q;
    return q;
  }

  async function quoteViaTemp(sym, grp, say) {
    const a = api();
    const sr = await switchGroup(grp);
    if (!sr.ok) throw new Error(`临时分组「${grp}」不可用：${sr.error}（请先在自选股页新建名为 ${grp} 的分组）`);
    await waitGridSettled(4000);
    const onTemp = () => sameGroup(currentGroup(), grp);
    let q = null;
    try {
      q = await a.findRowQuote(sym, false);
      if (!q) {
        say(`➕ 临时加入「${grp}」…`);
        const r = await a.addOneSymbol(sym);
        if (!r || r.status !== 'added') throw new Error(`临时添加失败：${(r && (r.error || r.status)) || '未知'}`);
        await waitGridSettled(3000);
      }
      say('⏳ 等待行情刷新…');
      q = await waitQuote(sym, 9000);
      if (!q) throw new Error('添加后没在表格里看到该股票');
    } finally {
      /* ★ 只在确认身处 temp 分组时才删，绝不误删其它分组 */
      if (onTemp()) {
        say('🧹 清理临时分组…');
        try { await a.deleteSymbol(sym); } catch (e) { }
        for (let i = 0; i < 15 && onTemp(); i++) {
          const left = visibleSyms();
          if (!left.length) break;
          const r = await a.deleteSymbol(left[0]);
          if (!r || (r.status !== 'removed' && r.status !== 'missing')) break;
        }
      }
    }
    return q;
  }

  async function handleQuoteTask(t) {
    const a = api();
    const sym = String(t.symbol || '').trim().toUpperCase();
    const p = t.params || {};
    const origin = currentGroup();
    const say = (x) => { try { a.renderScan(`📈 ${sym}：${x}`, 'task'); } catch (e) { } };
    let plan = Array.isArray(p.plan) && p.plan.length ? p.plan.slice() : [{ src: 'temp', group: TEMP_GROUP }];
    let pi = plan.findIndex(s => s.src !== 'positions');
    if (pi < 0) pi = plan.length;
    plan.splice(pi, 0, { src: 'current' });               // 当前分组可见行 = 零切换最快
    let ok = false, data = { symbol: sym };
    const tried = [];
    try { a.ensureHud('task'); } catch (e) { }
    say('收到取数任务…');
    try {
      if (!sym) throw new Error('symbol 为空');
      if (typeof a.findRowQuote !== 'function') throw new Error('watchlist.js 版本过旧（缺少 findRowQuote），请刷新页面');
      a.clearStopFlags(); a.cleanNavSearch();
      for (const step of plan) {
        let q = null, err = '';
        const label = step.src === 'group' ? `自选「${step.group}」` : (SRC_TXT[step.src] || step.src);
        try {
          if (step.src === 'positions') {
            say('从持仓页读取…');
            const r = await bg({ action: 'FT_POS_QUOTE', symbol: sym });
            if (r && r.ok && r.found) {
              q = Object.assign({}, r.quote || {}, { record: r.record || null });
              if (!q.change_pct && r.record && r.record.day_change) q.change_pct = r.record.day_change;
            } else err = (r && r.error) || '持仓页没有这只股票';
          } else if (step.src === 'current') {
            if (sameGroup(currentGroup(), TEMP_GROUP)) continue;
            q = a.rowQuote(sym);
            if (q && !quoteReady(q)) q = await waitQuote(sym, 1500);
            if (!q) continue;                               // 不在当前视图，静默跳过
            step.group = (window.__FT_WL_MEMBER__ ? window.__FT_WL_MEMBER__.cleanGroup(currentGroup()) : currentGroup());
          } else if (step.src === 'group') {
            say(`切到「${step.group}」读取…`);
            q = await quoteInGroup(sym, step.group);
          } else if (step.src === 'temp') {
            q = await quoteViaTemp(sym, step.group || TEMP_GROUP, say);
          }
        } catch (e) { err = String((e && e.message) || e); }
        if (quoteReady(q)) {
          ok = true;
          data = {
            symbol: sym, source: step.src, group: step.group || '',
            change_pct: q.change_pct, change_pct_num: q.change_pct_num,
            last: q.last || '', price: q.price || null, record: q.record || null
          };
          break;
        }
        tried.push(`${label}：${err || '未取到变更%'}`);
      }
    } catch (e) { tried.push(String((e && e.message) || e)); }
    const srcLabel = data.source === 'group' || data.source === 'current' ? `自选「${data.group}」`
      : (SRC_TXT[data.source] || data.source || '');
    const msg = ok
      ? `${sym} 变更% ${data.change_pct}｜现价 ${data.last || '--'}（${srcLabel}）`
      : `${sym} 取数失败：${tried.join('；') || '未知原因'}`;
    data.tried = tried;
    await reportTask(t, ok, msg, data, RESTORE, origin);
  }

  async function handleTask(t) {
    const action = String(t.action || 'add');
    if (action === 'scan_groups') return handleScanTask(t);
    if (action === 'remove') return handleRemoveTask(t);
    if (action === 'trade') return handleTradeTask(t);
    if (action === 'quote') return handleQuoteTask(t);

    const a = api();
    const sym = String(t.symbol || '').trim().toUpperCase();
    const grp = String(t.group || '').trim();
    const restore = (t.restore === undefined) ? RESTORE : (!!t.restore && RESTORE);
    const origin = currentGroup();
    let ok = false, msg = '';
    try { a.ensureHud('task'); a.renderScan(`收到任务：${sym} → 「${grp || '当前分组'}」`, 'task'); } catch (e) { }
    try {
      if (!sym) throw new Error('symbol 为空');
      a.clearStopFlags();
      a.cleanNavSearch();
      if (grp) {
        const sr = await switchGroup(grp);
        if (!sr.ok) throw new Error(sr.error);
        if (sr.changed) try { a.renderScan(`已切到「${grp}」，正在添加 ${sym}…`); } catch (e) { }
      }
      await waitGridSettled(4000);
      if (await alreadyHas(sym)) {
        ok = true;
        msg = `${sym} 已在「${grp || currentGroup()}」中，无需重复添加`;
      } else {
        const r = await a.addOneSymbol(sym);
        if (r && r.status === 'added') { ok = true; msg = `${sym} 已加入「${grp || currentGroup()}」`; }
        else msg = `${sym} 添加失败：${(r && (r.error || r.status)) || '未知原因'}`;
      }
    } catch (e) { ok = false; msg = String((e && e.message) || e); }
    await reportTask(t, ok, msg, { symbol: sym, group: grp }, restore, origin);
  }

  /* ---------------- 轮询 ---------------- */
  async function poll() {
    if (!ENABLED || busy || !isWatchlistPage()) return;
    const a = api();
    if (!a || !a.addOneSymbol) return;
    if (a.isBusy() || window.__FT_TRADE_BUSY__) return;
    busy = true;                                   // ★ 先占锁，防止 focus+interval 并发领两次
    try {
      const r = await bg({ action: 'FT_WL_TASKS', max: 3 });
      if (!r.ok) return;
      const tasks = (r.data && r.data.tasks) || [];
      if (!tasks.length) return;
      try { a.setExternalBusy(true); } catch (e) { }
      for (const t of tasks) {
        if (!ENABLED) break;
        await handleTask(t);
        await sleep(400);
      }
    } finally {
      busy = false;
      try { a.setExternalBusy(false); } catch (e) { }
    }
  }

  function loadSettings() {
    chrome.storage.local.get(['ftWlAgent', 'ftWlRestoreGroup', 'ftDebug'], (res) => {
      ENABLED = res.ftWlAgent !== false;
      RESTORE = res.ftWlRestoreGroup !== false;
      DEBUG = !!res.ftDebug;
    });
  }
  chrome.storage.onChanged.addListener((c, area) => {
    if (area !== 'local') return;
    if (c.ftWlAgent || c.ftWlRestoreGroup || c.ftDebug) loadSettings();
  });

  document.addEventListener('visibilitychange', () => { if (!document.hidden) poll(); });
  window.addEventListener('focus', () => poll());

  chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
    if (!msg) return;
    if (msg.action === 'FT_AGENT_STATUS') {
      sendResponse({
        ok: true, page: isWatchlistPage(), enabled: ENABLED, restore: RESTORE,
        busy, group: currentGroup(), apiReady: !!(api() && api().addOneSymbol)
      });
      return;
    }
    if (msg.action === 'FT_WAKE_UP') { poll(); sendResponse({ ok: true }); return; }
  });

  loadSettings();
  if (isWatchlistPage()) {
    setInterval(poll, POLL_MS);
    setTimeout(poll, 1000);
  }
  console.log(LOG, `wl_agent.js v3 就绪（isWatchlist=${isWatchlistPage()}）`);
})();

/* ============================================================================
 * Firstrade 自选股「分组归属」同步  wl_membership.js  v1   仅在 /app/watchlist 生效
 *
 *  目标：让本机知道「每个分组里有哪些 symbol」→ bridge_server.py 落盘到
 *        Modules/firstrade_wl_membership.json → Chart_input(_single) 显示「自选 [买] [Watch]」
 *
 *  更新来源（从便宜到贵）：
 *    ① 被动快照：分组表格稳定 3 秒后，DOM 行数 == 表格总行数 → 完整快照；否则只合并可见行
 *    ② 手动增删捕获：网页上「三点菜单 → 删除」/「添加自选股」弹层选中 → 精确回传事件
 *    ③ watchlist.js 每次完整滚动读取（比对/复核/行情抓取）→ 完整快照（挂钩在 watchlist.js）
 *    ④ Python F 键添加成功 → bridge 服务端直接记账（不依赖本脚本）
 *    ⑤ 全量扫描：popup 按钮 / 图表 M 键 → 逐组切换 + 滚动读取 → 完整快照 → 切回原分组
 * ==========================================================================*/
(() => {
  if (window.__FT_WL_MEMBER_V1__) return;
  window.__FT_WL_MEMBER_V1__ = true;

  const LOG = '[FT-MEMBER]';
  const TICK_MS = 1000;
  const STABLE_TICKS = 3;
  const ROW_EXCLUDE = '.ag-floating-top, .ag-floating-bottom, #app-quote-bar, header, #app-header';
  const FORBIDDEN = 'header, #app-header, nav, #app-quote-bar';
  const NOT_A_GROUP = /新建|创建|管理|编辑|重命名|删除|new|create|manage|edit|rename|delete/i;
  const REMOVE_TXT = /^(删除|移除|移出|删除自选|移除自选|Remove|Remove from watchlist|Delete)$/i;

  let DEBUG = false;
  let PASSIVE = true;
  let knownGroups = [];
  let scanning = false;

  const sleep = (ms) => new Promise(r => setTimeout(r, ms));
  const log = (...a) => { if (DEBUG) console.log(LOG, ...a); };
  const isWatchlistPage = () => /\/watchlist/i.test(location.pathname || '');
  const api = () => window.__FT_WL_API__ || null;
  const busy = () => window.__FT_AUTOMATION__ === true || scanning;
  const toast = (t) => { try { (window.__FT_TOAST__ || console.log)(t); } catch (e) { } };
  const normKey = (s) => String(s || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  const cleanGroup = (s) => String(s || '')
    .replace(/\u00a0/g, ' ')
    .replace(/[（(]\s*\d+\s*[）)]\s*$/, '')
    .replace(/\s+/g, ' ')
    .trim();

  function cleanText(el) {
    const t = (el && (el.innerText || el.textContent)) || '';
    return t.replace(/\u00a0/g, ' ').replace(/\s+/g, ' ').trim();
  }

  function bg(msg) {
    return new Promise((resolve) => {
      try {
        chrome.runtime.sendMessage(msg, (resp) => {
          if (chrome.runtime.lastError) { resolve({ ok: false, error: chrome.runtime.lastError.message }); return; }
          resolve(resp || { ok: false, error: 'no response' });
        });
      } catch (e) { resolve({ ok: false, error: String(e) }); }
    });
  }

  function symbolFromRowId(rowId) {
    if (!rowId) return '';
    const raw = String(rowId).split('|')[0].trim().toUpperCase();
    if (!/^[A-Z][A-Z0-9.\-]{0,9}$/.test(raw)) return '';
    return raw;
  }

  function visibleSymbols() {
    const set = new Set();
    document.querySelectorAll('[row-id]').forEach(r => {
      if (r.closest(ROW_EXCLUDE)) return;
      const s = symbolFromRowId(r.getAttribute('row-id'));
      if (s) set.add(s);
    });
    return set;
  }

  function currentGroup() { const a = api(); return a ? cleanGroup(a.groupName()) : ''; }
  function totalRows() { const a = api(); return a ? a.dataRowsTotal() : 0; }
  function hasSym(sym) {
    const k = normKey(sym);
    for (const s of visibleSymbols()) if (normKey(s) === k) return true;
    return false;
  }

  /* ---------------- 上报（带去重） ---------------- */
  const lastSent = Object.create(null);

  function sendSnapshot(group, symbols, complete, source, force) {
    const g = cleanGroup(group);
    if (!g) return Promise.resolve({ ok: false, error: 'no group' });
    const arr = Array.from(new Set((symbols || [])
      .map(s => String(s).trim().toUpperCase()).filter(Boolean))).sort();
    const key = g + (complete ? '#C' : '#P');
    const sig = arr.join(',');
    if (!force && lastSent[key] === sig) return Promise.resolve({ ok: true, skipped: true });
    lastSent[key] = sig;
    log('snapshot', g, complete ? '完整' : '部分', arr.length, source);
    return bg({
      action: 'FT_WL_MEMBERSHIP',
      payload: {
        group: g, symbols: arr, complete: !!complete, source: source || '',
        page_groups: knownGroups.length ? knownGroups : null
      }
    }).then(r => {
      if (!r || !r.ok) delete lastSent[key];
      else { try { window.dispatchEvent(new Event('ft-attr-dirty')); } catch (e) { } }
      return r;
    });
  }

  function sendEvent(group, symbol, op, source) {
    const g = cleanGroup(group);
    const sym = String(symbol || '').trim().toUpperCase();
    if (!g || !sym) return Promise.resolve({ ok: false });
    delete lastSent[g + '#C'];
    delete lastSent[g + '#P'];
    log('event', op, sym, g, source);
    return bg({ action: 'FT_WL_MEMBERSHIP_EVENT', payload: { group: g, symbol: sym, op, source } })
      .then(r => { if (r && r.ok) { try { window.dispatchEvent(new Event('ft-attr-dirty')); } catch (e) { } } return r; });
  }

  /* ---------------- ① 被动快照 ---------------- */
  let prev = { sig: '', stable: 0 };

  function passiveTick() {
    if (!PASSIVE || !isWatchlistPage() || busy()) { prev.stable = 0; prev.sig = ''; return; }
    const a = api();
    if (!a) return;
    const group = currentGroup();
    if (!group) { prev.stable = 0; return; }
    const syms = visibleSymbols();
    const total = a.dataRowsTotal();
    const sig = group + '|' + total + '|' + Array.from(syms).sort().join(',');
    if (sig !== prev.sig) { prev = { sig, stable: 0 }; return; }
    prev.stable++;
    if (prev.stable < STABLE_TICKS) return;

    if (syms.size === 0) {
      if (total === 0 && typeof a.gridSaysEmpty === 'function' && a.gridSaysEmpty()) {
        sendSnapshot(group, [], true, 'passive_empty');
      }
      return;
    }
    if (total > 0 && syms.size === total) sendSnapshot(group, Array.from(syms), true, 'passive');
    else sendSnapshot(group, Array.from(syms), false, 'passive_visible');
  }

  /* ---------------- ② 手动增删捕获 ---------------- */
  let menuCtx = null;
  const pendingAdds = new Set();

  function recordMenuCtx(target) {
    if (!target || !target.closest) return;
    const btn = target.closest('button[aria-haspopup="menu"]');
    if (!btn) return;
    const row = btn.closest('[row-id]');
    if (!row || row.closest(ROW_EXCLUDE)) return;
    const sym = symbolFromRowId(row.getAttribute('row-id'));
    if (!sym) return;
    menuCtx = { symbol: sym, group: currentGroup(), total: totalRows(), ts: Date.now() };
  }

  function isRemoveItem(el) {
    if (!el) return false;
    if (/watchlist-(remove|delete)/i.test(el.id || '')) return true;
    return REMOVE_TXT.test(cleanText(el));
  }

  function cmdValue(el) {
    if (!el) return '';
    const w = el.closest('[data-value]') || el;
    let v = w.getAttribute('data-value') || el.getAttribute('data-value') || '';
    if (!v) { const sp = el.querySelector('span span, span'); v = sp ? cleanText(sp) : cleanText(el); }
    v = String(v).trim().split(/\s+/)[0].toUpperCase();
    return /^[A-Z][A-Z0-9.\-]{0,9}$/.test(v) ? v : '';
  }

  async function onRemoveChosen() {
    const ctx = menuCtx; menuCtx = null;
    if (!ctx || !ctx.symbol || !ctx.group || Date.now() - ctx.ts > 60000) return;
    const t0 = Date.now();
    while (Date.now() - t0 < 15000) {       // 留时间给可能出现的二次确认对话框
      await sleep(300);
      if (currentGroup() !== ctx.group) return;
      const gone = !hasSym(ctx.symbol);
      const after = totalRows();
      if (gone && after < ctx.total) {
        await sendEvent(ctx.group, ctx.symbol, 'remove', 'manual_remove');
        toast(`🗂 已记录：${ctx.symbol} 移出「${ctx.group}」`);
        return;
      }
    }
  }

  async function onAddChosen(sym) {
    if (!sym) return;
    const group = currentGroup();
    if (!group) return;
    const key = group + '|' + normKey(sym);
    if (pendingAdds.has(key)) return;
    pendingAdds.add(key);
    const before = totalRows();
    const t0 = Date.now();
    try {
      while (Date.now() - t0 < 8000) {
        await sleep(300);
        if (currentGroup() !== group) return;
        if (hasSym(sym) || totalRows() > before) {
          await sendEvent(group, sym, 'add', 'manual_add');
          return;
        }
      }
    } finally { pendingAdds.delete(key); }
  }

  document.addEventListener('pointerdown', (e) => { if (isWatchlistPage()) recordMenuCtx(e.target); }, true);

  document.addEventListener('click', (e) => {
    if (!isWatchlistPage() || busy()) return;
    const t = e.target;
    if (!t || !t.closest) return;
    const item = t.closest('[role="menuitem"], [data-dropdown-menu-item]');
    if (item) { if (isRemoveItem(item)) onRemoveChosen(); return; }
    const cmd = t.closest('[data-command-root] [data-command-item], [data-command-root] [role="option"]');
    if (cmd && !cmd.closest(FORBIDDEN)) onAddChosen(cmdValue(cmd));
  }, true);

  document.addEventListener('keydown', (e) => {
    if (!isWatchlistPage()) return;
    const t = e.target;
    if (!t || !t.closest) return;
    if (e.key === 'Enter' || e.key === ' ') recordMenuCtx(t);
    if (e.key !== 'Enter' || busy()) return;
    const menu = t.closest('[role="menu"], [data-dropdown-menu-content]');
    if (menu) {
      const hl = menu.querySelector('[data-highlighted]') || (t.matches && t.matches('[role="menuitem"]') ? t : null);
      if (isRemoveItem(hl)) onRemoveChosen();
      return;
    }
    const cr = t.closest('[data-command-root]');
    if (cr && !cr.closest(FORBIDDEN)) {
      const sel = cr.querySelector('[data-command-item][aria-selected="true"], [data-command-item][data-selected="true"], [role="option"][aria-selected="true"]');
      if (sel) onAddChosen(cmdValue(sel));
    }
  }, true);

  /* ---------------- ⑤ 全量扫描 ---------------- */
  async function scanAllGroups(want) {
    const a = api();
    if (!isWatchlistPage()) return { ok: false, error: '当前不在 /app/watchlist 页面' };
    if (!a || !a.collectWatchlist) return { ok: false, error: 'watchlist.js 未就绪（请刷新页面）' };
    if (scanning) return { ok: false, error: '分组归属扫描已在进行中' };
    if (a.isBusy()) return { ok: false, error: '自选股同步/行情抓取进行中，请稍后' };

    scanning = true;
    const ownBusy = !window.__FT_AGENT_BUSY__;
    if (ownBusy) { try { a.setExternalBusy(true); } catch (e) { } }
    const origin = a.groupName();
    const results = [];
    let targets = [];
    try {
      a.clearStopFlags();
      a.cleanNavSearch();
      a.ensureHud('task');
      a.renderScan('🗂 正在读取分组列表…', 'task');

      const lr = await a.listGroupOptions();
      await sleep(300);
      let names = Array.from(new Set((lr.options || []).map(cleanGroup).filter(Boolean)))
        .filter(n => !NOT_A_GROUP.test(n));
      if (names.length) knownGroups = names;

      targets = names;
      if (Array.isArray(want) && want.length) {
        const w = new Set(want.map(x => a.normGroup(x)));
        targets = names.filter(n => w.has(a.normGroup(n)));
        if (!targets.length && !names.length) targets = want.map(cleanGroup).filter(Boolean);
      }
      if (!targets.length) targets = [cleanGroup(origin)].filter(Boolean);

      for (let i = 0; i < targets.length; i++) {
        const g = targets[i];
        const tag = `(${i + 1}/${targets.length})`;
        a.renderScan(`🗂 ${tag} 切到「${g}」…`, 'task');
        const sr = await a.switchGroup(g);
        if (!sr.ok) { results.push({ group: g, ok: false, error: sr.error || '切换失败' }); continue; }
        await a.waitGridSettled();
        await sleep(400);
        a.clearStopFlags();
        const buf = await a.collectWatchlist(n => a.renderScan(`🗂 ${tag}「${g}」已读 ${n} 只…`, 'task'));
        const syms = Object.keys(buf);
        const r = await sendSnapshot(currentGroup() || g, syms, true, 'scan_all', true);
        results.push({ group: g, ok: !!(r && r.ok), count: syms.length, error: r && !r.ok ? r.error : '' });
      }
    } catch (e) {
      results.push({ group: '?', ok: false, error: String((e && e.message) || e) });
    } finally {
      try {
        if (origin && a.normGroup(a.groupName()) !== a.normGroup(origin)) {
          a.renderScan(`🗂 正在切回原分组「${origin}」…`, 'task');
          await a.switchGroup(origin);
        }
      } catch (e) { }
      scanning = false;
      if (ownBusy) { try { a.setExternalBusy(false); } catch (e) { } }
    }

    const okN = results.filter(r => r.ok).length;
    const message = `分组归属扫描完成：${okN}/${targets.length} 组成功` +
      (results.length ? '（' + results.map(r => r.ok ? `${r.group}:${r.count}` : `${r.group}:失败`).join('，') + '）' : '');
    try { a.renderScan((okN ? '✅ ' : '❌ ') + message, 'task'); } catch (e) { }
    toast((okN ? '✅ ' : '❌ ') + message);
    return { ok: okN > 0, message, results, groups: targets };
  }

  /* ---------------- 设置 & 通信 ---------------- */
  function loadSettings() {
    chrome.storage.local.get(['ftDebug', 'ftWlMemberPassive'], (res) => {
      DEBUG = !!res.ftDebug;
      PASSIVE = res.ftWlMemberPassive !== false;
    });
  }
  chrome.storage.onChanged.addListener((c, area) => {
    if (area === 'local' && (c.ftDebug || c.ftWlMemberPassive)) loadSettings();
  });

  chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
    if (!msg || !msg.action) return;
    if (msg.action === 'FT_MEMBER_SCAN') {
      scanAllGroups(Array.isArray(msg.groups) ? msg.groups : null)
        .then(r => sendResponse(r))
        .catch(e => sendResponse({ ok: false, error: String(e) }));
      return true;
    }
  });

  window.__FT_WL_MEMBER__ = {
    version: 1,
    snapshot: sendSnapshot,
    event: sendEvent,
    scanAllGroups,
    cleanGroup,
    isScanning: () => scanning
  };

  loadSettings();
  setInterval(passiveTick, TICK_MS);
  console.log(LOG, `wl_membership.js v1 就绪（isWatchlist=${isWatchlistPage()}）`);
})();

