def _ft_layout_text_row(fig, x0, y, items, fontsize=12, gap_px=10, x_limit=0.345):
    """按像素宽度横排 [(文本, 颜色, 粗细[, 动作]), ...]；带动作的项渲染成可点击小按钮（pick 事件）"""
    arts = []
    try:
        renderer = fig.canvas.get_renderer()
    except Exception:
        renderer = None
    fig_w_px = max(1.0, fig.get_figwidth() * fig.dpi)
    x = x0
    for it in items:
        txt, color, weight = it[0], it[1], it[2]
        action = it[3] if len(it) > 3 else None
        if x > x_limit:
            break
        if action:
            t = fig.text(x, y, txt, color=NORD_THEME['text_bright'], fontsize=max(8, fontsize - 1),
                         fontweight=weight, ha='left', va='top', fontname='Arial Unicode MS',
                         picker=True,
                         bbox=dict(boxstyle="round,pad=0.15", fc=color, ec='none', alpha=0.85))
            t.ft_action = action
            extra_gap = gap_px + 4
        else:
            t = fig.text(x, y, txt, color=color, fontsize=fontsize, fontweight=weight,
                         ha='left', va='top', fontname='Arial Unicode MS')
            extra_gap = gap_px
        arts.append(t)
        w_frac = None
        if renderer is not None:
            try:
                w_frac = (t.get_window_extent(renderer=renderer).width + extra_gap) / fig_w_px
            except Exception:
                w_frac = None
        if not w_frac or w_frac <= 0:
            w_frac = (len(txt) * fontsize * 0.62 + extra_gap) / fig_w_px
        x += w_frac
    return arts


# ============ 全局实时价格管理器 ============
class _RealtimeManager:
    def __init__(self):
        self._lock = threading.Lock()
        self._symbol = None
        self._latest = {}
        self._thread = None
        self._stop = threading.Event()
        self._fetcher = None

    def _ensure_thread(self):
        if self._thread is None or not self._thread.is_alive():
            self._stop.clear()
            self._thread = threading.Thread(target=self._run, daemon=True)
            self._thread.start()

    def set_symbol(self, symbol):
        with self._lock:
            self._symbol = symbol
        self._ensure_thread()

    def get_latest(self, symbol):
        with self._lock:
            return self._latest.get(symbol)

    def _run(self):
        try:
            self._fetcher = _get_global_fetcher()
        except Exception as e:
            print(f"初始化 fetcher 失败: {e}")
            return
        while not self._stop.is_set():
            with self._lock:
                sym = self._symbol
            if sym:
                try:
                    quote = self._fetcher.get_realtime_quote(sym)
                    if quote and 'price' in quote:
                        with self._lock:
                            self._latest[sym] = quote['price']
                except Exception as e:
                    print(f"后台获取实时价格失败: {e}")
            if self._stop.wait(timeout=5.0):
                break


_RT_MANAGER = _RealtimeManager()


