    def _show_wl_status(self, text, color, ttl=6.0):
        try:
            self.wl_status_artist.set_text(text)
            self.wl_status_artist.set_color(color)
            self.wl_status_artist.set_visible(True)
            self._wl_hide_at = time.time() + ttl
            self.fig.canvas.draw_idle()
        except Exception:
            pass

    def _add_to_watchlist(self, group=None):
        if not FT_WL_ADD_OK:
            display_dialog("未找到 ft_watchlist_add.py，无法使用「一键加自选」")
            return
        sym = self.name
        if not sym:
            return
        if not group:
            group = choose_group_dialog(sym, watchlist_groups())
            if not group:
                self._show_wl_status("已取消", NORD_THEME['text_light'], ttl=1.5)
                return
        save_last_group(group)
        self._show_wl_status(f"⏳ 正在把 {sym} 加入「{group}」…（浏览器后台执行）",
                             NORD_THEME['accent_yellow'], ttl=90)
        add_symbol_async(sym, group, on_done=lambda res: self._wl_results.append(res), wait=45)

    def _drain_wl_results(self):
        now = time.time()
        while self._wl_results:
            res = self._wl_results.pop(0)
            ok = bool(res.get('ok'))
            msg = res.get('message') or ('成功' if ok else '失败')
            if res.get('action') == 'quote':
                qsym = str(res.get('symbol', '')).upper()
                self._quote_pending.discard(qsym)
                if ok and self.name and _ft_norm_sym(self.name) == _ft_norm_sym(qsym):
                    try:
                        self.draw_subtitle(current_prices=self.current_filtered_prices,
                                           pre_after_pct=self.current_pre_after_pct[0])
                    except Exception:
                        traceback.print_exc()
                self._show_wl_status(("✅ " if ok else "❌ ") + msg,
                                     NORD_THEME['accent_green'] if ok else NORD_THEME['accent_red'], ttl=8.0)
                print(f"[FT-QUOTE] {'OK' if ok else 'FAIL'} {msg}")
                continue
            if res.get('action') == 'remove':
                self._wl_pending.discard((str(res.get('symbol', '')).upper(), str(res.get('group', ''))))
                self._member_sig = None       # 立即重读归属文件
            self._show_wl_status(("✅ " if ok else "❌ ") + msg,
                                 NORD_THEME['accent_green'] if ok else NORD_THEME['accent_red'], ttl=7.0)
            try:
                arrow = '✕' if res.get('action') == 'remove' else '→'
                notify_mac("Firstrade 自选股", msg, subtitle=f"{res.get('symbol','')} {arrow} {res.get('group','')}")
            except Exception:
                pass
            print(f"[FT-WL] {'OK' if ok else 'FAIL'} {msg}")
        if self.wl_status_artist.get_visible() and self._wl_hide_at and now > self._wl_hide_at:
            self.wl_status_artist.set_visible(False)
            self._wl_hide_at = 0.0
            self.fig.canvas.draw_idle()

    def _draw_membership(self, force=False):
        """画「自选 [买] [Watch]」行；文件 mtime 或 symbol 没变则跳过，返回是否重画"""
        try:
            sig = (self.name, membership_signature())
        except Exception:
            sig = (self.name, None)
        if not force and sig == self._member_sig:
            return False
        self._member_sig = sig
        for a in self.member_artists:
            try: a.remove()
            except Exception: pass
        self.member_artists.clear()
        if not self.name:
            return True
        try:
            items = build_membership_items(self.name, NORD_THEME)
        except Exception as e:
            print(f"[FT] 分组归属读取失败: {e}")
            items = []
        if items:
            self.member_artists.extend(_ft_layout_text_row(self.fig, 0.045, 0.884, items, fontsize=12, x_limit=0.34))
        return True

    def _refresh_membership(self):
        if not FT_WL_ADD_OK:
            display_dialog("未找到 ft_watchlist_add.py，无法刷新分组归属")
            return
        self._show_wl_status("⏳ 正在让浏览器扫描全部自选分组…（约 10~90 秒）",
                             NORD_THEME['accent_yellow'], ttl=300)
        scan_groups_async(on_done=lambda res: self._wl_results.append(res),
                          groups=(watchlist_groups() or None), wait=300)

    def _quote_source_hint(self, sym):
        try:
            if get_firstrade_position(sym):
                return "持仓页"
            m = get_watchlist_membership(sym)
            if m and m.get('groups'):
                return f"自选「{m['groups'][0]}」"
        except Exception:
            pass
        return "临时分组 temp"

    def _refresh_ft_quote(self):
        """G 键：让浏览器抓该 symbol 最新「变更%」，完成后自动重画副标题"""
        if not FT_WL_ADD_OK or not self.name:
            return
        sym = str(self.name).upper()
        if sym in self._quote_pending:
            self._show_wl_status(f"⏳ {sym} 正在取数中，请稍候…", NORD_THEME['accent_yellow'], ttl=5)
            return
        self._quote_pending.add(sym)
        src = self._quote_source_hint(sym)
        self._show_wl_status(f"⏳ 正在从{src}抓取 {sym} 最新「变更%」…（浏览器后台执行）",
                             NORD_THEME['accent_yellow'], ttl=150)
        quote_symbol_async(sym, on_done=lambda res: self._wl_results.append(res), wait=120)

    def _g_refresh(self):
        self.refresh_description_data_and_redraw()
        self._refresh_ft_quote()

    def _handle_ft_action(self, action):
        if not action:
            return
        if action[0] == 'wl_remove' and len(action) > 1:
            self._remove_from_watchlist(action[1])

    def _remove_from_watchlist(self, group):
        self.mouse_pressed = False
        if not FT_WL_ADD_OK:
            display_dialog("未找到 ft_watchlist_add.py，无法删除自选股")
            return
        sym = self.name
        if not sym or not group:
            return
        key = (str(sym).upper(), str(group))
        if key in self._wl_pending:
            self._show_wl_status(f"⏳ {sym} ✕「{group}」已在执行中…", NORD_THEME['accent_yellow'], ttl=5)
            return
        ret = QMessageBox.question(
            None, "从自选股分组删除",
            f"确定把 {sym} 从 Firstrade 自选股分组「{group}」中删除？\n（浏览器将自动切到该分组完成删除）",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No)
        if ret != QMessageBox.StandardButton.Yes:
            return
        self._wl_pending.add(key)
        self._show_wl_status(f"⏳ 正在把 {sym} 从「{group}」删除…（浏览器后台执行）",
                             NORD_THEME['accent_yellow'], ttl=120)
        remove_symbol_async(sym, group, on_done=lambda res: self._wl_results.append(res), wait=90)

