    def apply_blacklist_action(self, op, grp, tag):
        if not TB_OK:
            return
        try:
            if op == "remove":
                TB.set_group(tag, None)
                msg = f"已将「{tag}」移出「{grp}」黑名单"
            else:
                TB.set_group(tag, grp)
                msg = f"已将「{tag}」{'转入' if op == 'move' else '加入'}「{grp}」黑名单"
        except Exception as e:
            QMessageBox.warning(self, "黑名单写入失败", str(e))
            return
        self._bl_sig = TB.signature()
        self.refresh_blacklist_view()
        self.statusBar().showMessage(msg + "（Check_Group / Chart 约 1 秒内同步）", 5000)

    def toggle_current_blacklist(self, grp):
        it = self.tags_list.currentItem()
        if not it or not TB_OK:
            return
        tag = it.text()
        cur = TB.group_of(tag)
        if cur == grp:
            self.apply_blacklist_action("remove", grp, tag)
        else:
            self.apply_blacklist_action("move" if cur else "add", grp, tag)

    def refresh_blacklist_view(self):
        self.tags_list.viewport().update()
        if not TB_OK:
            return
        c = TB.counts()
        hits = TB.blacklisted_tags(self._ui_tags())
        txt = f"黑名单  确定 {c[TB.GROUP_SURE]} ｜ 疑似 {c[TB.GROUP_MAYBE]}"
        if hits:
            txt += f"   本股命中 {len(hits)} 个"
        if TB.last_error():
            txt += "   ⚠ 文件解析失败"
        self.bl_summary.setText(txt)

    def _poll_blacklist(self):
        if not TB_OK:
            return
        sig = TB.signature()
        if sig != self._bl_sig:
            self._bl_sig = sig
            TB.load(force=True)
            self.refresh_blacklist_view()

    # ==================================================================
    # Tag 编辑（一律以 UI 列表为准 —— 修复拖拽后按行号改错数据的 bug）
    # ==================================================================
    def _ui_tags(self):
        return [self.tags_list.item(i).text() for i in range(self.tags_list.count())]

    def save_json_data(self):
        """只在确有改动时保存；保存前重新读取磁盘最新内容，只替换当前 symbol 的 tag，原子写入"""
        if not self.current_item:
            return True
        tags = self._ui_tags()
        if tags == self.original_tags:
            return True
        symbol = self.current_item.get('symbol')
        try:
            try:
                with open(self.json_file_path, 'r', encoding='utf-8') as f:
                    fresh = json.load(f)
            except Exception:
                fresh = self.data
            target = None
            for cat in [self.current_category, 'stocks', 'etfs']:
                for it in (fresh.get(cat) or []) if cat else []:
                    if it.get('symbol') == symbol:
                        target = it
                        break
                if target is not None:
                    break
            if target is None:            # 磁盘上找不到（被别处删了）→ 退回内存数据
                fresh = self.data
                target = self.current_item
            target['tag'] = tags

            dir_ = os.path.dirname(self.json_file_path)
            fd, tmp = tempfile.mkstemp(dir=dir_, prefix=".description.", suffix=".tmp")
            try:
                with os.fdopen(fd, 'w', encoding='utf-8') as f:
                    json.dump(fresh, f, ensure_ascii=False, indent=2)
                    f.flush()
                    os.fsync(f.fileno())
                os.replace(tmp, self.json_file_path)
            except Exception:
                try:
                    os.remove(tmp)
                except OSError:
                    pass
                raise
            self.data = fresh
            self.current_item = target
            self.original_tags = list(tags)
            return True
        except Exception as e:
            QMessageBox.critical(self, "Error", f"保存失败: {str(e)}")
            return False

    def add_tag(self, bottom=False):
        if not self.current_item:
            QMessageBox.warning(self, "警告", "没有加载任何项目，无法添加标签。")
            return
        new_tag = self.new_tag_input.toPlainText().strip()
        if not new_tag:
            self.new_tag_input.setFocus()
            return
        if new_tag in self._ui_tags():
            QMessageBox.information(self, "提示", "该标签已存在。")
            self.new_tag_input.clear()
            self.new_tag_input.setFocus()
            return
        if bottom:
            self.tags_list.addItem(new_tag)
            self.tags_list.setCurrentRow(self.tags_list.count() - 1)
        else:
            self.tags_list.insertItem(0, new_tag)
            self.tags_list.setCurrentRow(0)
        self.tags_list.scrollToItem(self.tags_list.currentItem())
        self.new_tag_input.clear()
        self.new_tag_input.setFocus()
        self.refresh_blacklist_view()
        if TB_OK and TB.group_of(new_tag):
            self.statusBar().showMessage(f"注意：「{new_tag}」在「{TB.group_of(new_tag)}」黑名单中", 5000)

    def edit_current_tag(self):
        item = self.tags_list.currentItem()
        if not item:
            return
        old_tag = item.text()
        new_tag, ok = QInputDialog.getText(self, "编辑标签", "请输入新标签:", QLineEdit.Normal, old_tag)
        new_tag = (new_tag or "").strip()
        if ok and new_tag and new_tag != old_tag:
            if new_tag in self._ui_tags():
                QMessageBox.information(self, "提示", "该标签已存在。")
                return
            item.setText(new_tag)
            self.refresh_blacklist_view()

    def delete_current_tag(self):
        item = self.tags_list.currentItem()
        if item and self.current_item:
            row = self.tags_list.row(item)
            self.tags_list.takeItem(row)
            if self.tags_list.count():
                self.tags_list.setCurrentRow(min(row, self.tags_list.count() - 1))
            self.refresh_blacklist_view()

    def show(self):
        super().show()
        self.activateWindow()
        self.raise_()
        self.new_tag_input.setFocus(Qt.OtherFocusReason)

    def showEvent(self, event):
        super().showEvent(event)
        QTimer.singleShot(100, self.new_tag_input.setFocus)

    def process_symbol(self, symbol):
        if not symbol:
            new_symbol = get_stock_symbol()
            if new_symbol:
                self.process_symbol(new_symbol)
            else:
                QTimer.singleShot(0, self.close)
            return

        original_symbol = symbol
        category, item = self.find_symbol(original_symbol)
        if not item:
            uppercase_symbol = original_symbol.upper()
            if uppercase_symbol != original_symbol:
                category, item = self.find_symbol(uppercase_symbol)

        if item:
            self.current_category = category
            self.current_item = item
            tags = item.get('tag') or []
            if isinstance(tags, str):
                tags = [tags]
            self.original_tags = [str(t) for t in tags]
            self.update_ui(item)
        else:
            new_symbol = get_stock_symbol(default_symbol=original_symbol)
            if new_symbol:
                self.process_symbol(new_symbol)
            else:
                QTimer.singleShot(0, self.close)

    def load_json_data(self):
        try:
            with open(self.json_file_path, 'r', encoding='utf-8') as file:
                self.data = json.load(file)
        except Exception as e:
            QMessageBox.critical(self, "Error", f"加载JSON文件失败: {str(e)}")
            self.data = {"stocks": [], "etfs": []}
            QTimer.singleShot(0, self.close)

    def on_double_click(self, item):
        # 双击落在右侧黑名单按钮上时不弹编辑框
        vp = self.tags_list.viewport()
        pos = vp.mapFromGlobal(QCursor.pos())
        if self.tag_delegate.hit(self.tags_list.indexAt(pos), pos):
            return
        self.edit_current_tag()

    def find_symbol(self, symbol):
        for category in ['stocks', 'etfs']:
            for item in self.data.get(category, []):
                if item.get('symbol') == symbol:
                    return category, item
        return None, None

    def update_ui(self, item):
        self.symbol_label.setText(f"Symbol: <b>{item['symbol']}</b>")
        self.tags_list.clear()
        if self.original_tags:
            self.tags_list.addItems(self.original_tags)
        if hasattr(self, 'bl_summary'):
            self.refresh_blacklist_view()

    def delete_tag(self):
        self.delete_current_tag()

    def save_changes(self):
        if self.current_item:
            if self.save_json_data():
                self.close()
        else:
            self.close()

    def closeEvent(self, event):
        if self.current_item:
            if self.save_json_data():
                event.accept()
            else:
                reply = QMessageBox.question(
                    self, '保存失败', "数据保存失败，是否仍要关闭程序？",
                    QMessageBox.Yes | QMessageBox.No, QMessageBox.No)
                if reply == QMessageBox.Yes:
                    event.accept()
                else:
                    event.ignore()
        else:
            event.accept()


def main():
    def _excepthook(t, v, tb):
        traceback.print_exception(t, v, tb)   # 只打印，不让 PyQt 调 abort
    sys.excepthook = _excepthook
    app = QApplication(sys.argv)
    init_symbol = sys.argv[1] if len(sys.argv) > 1 else None

    if not init_symbol:
        pyperclip.copy('')
        if not copy2clipboard():
            init_symbol = get_stock_symbol()
        else:
            time.sleep(0.1)
            new_content = get_clipboard_content()
            init_symbol = new_content if new_content else get_stock_symbol()

    if not init_symbol:
        return

    editor = TagEditor(init_symbol)
    if not editor.isVisible():
        editor.show()
        sys.exit(app.exec_())


if __name__ == "__main__":
    main()

"""
tag_blacklist.py —— Tag 黑名单共享读写层（纯 Python，不依赖 Qt；PyQt5 / PyQt6 程序都能直接用）

数据文件：~/Coding/Financial_System/Modules/Tag_Blacklist.json
{
  "_说明": "...",
  "确定": ["枪支", ...],
  "疑似": ["xxx", ...]
}

* 匹配规则：整词精确匹配（忽略首尾空格 / 大小写 / 全半角），不做子串匹配
* 同一 Tag 只属于一个分组；手动编辑时若两组都写了，以「确定」为准
* 写入：跨进程文件锁 + 临时文件 + os.replace 原子替换
* 文件被手动改坏：读取时沿用上次正确内容；写入时拒绝覆盖（避免冲掉手工修改）
"""
import os
import sys
import json
import tempfile
import threading
import subprocess
import unicodedata
from collections import OrderedDict
from contextlib import contextmanager

try:
    import fcntl
except ImportError:          # Windows
    fcntl = None

USER_HOME = os.path.expanduser("~")
BASE_CODING_DIR = os.path.join(USER_HOME, "Coding")
MODULES_DIR = os.path.join(BASE_CODING_DIR, "Financial_System", "Modules")
BLACKLIST_PATH = os.path.join(MODULES_DIR, "Tag_Blacklist.json")
_LOCK_PATH = os.path.join(MODULES_DIR, ".Tag_Blacklist.lock")

GROUP_SURE = "确定"
GROUP_MAYBE = "疑似"
GROUPS = (GROUP_SURE, GROUP_MAYBE)
DEFAULT_ACTIVE = frozenset({GROUP_SURE})
GROUP_COLORS = {GROUP_SURE: "#BF616A", GROUP_MAYBE: "#D08770"}

_NOTE_KEY = "_说明"
_NOTE = ("手动编辑说明：只认「确定」「疑似」两个键，值为 Tag 字符串数组；"
         "整词精确匹配（忽略首尾空格/大小写/全半角）；同一 Tag 两组都写时以「确定」为准；"
         "保存后 Check_Group / Chart / Editor_Tags 约 1 秒内自动生效。")

_lock = threading.RLock()
_state = {"sig": None, "data": {g: [] for g in GROUPS}, "map": {}, "error": None}


def norm_tag(tag):
    return unicodedata.normalize("NFKC", str(tag)).strip().casefold()


def signature(path=BLACKLIST_PATH):
    try:
        st = os.stat(path)
        return (st.st_mtime_ns, st.st_size)
    except OSError:
        return (0, 0)


def _empty():
    return {g: [] for g in GROUPS}


def _parse(raw):
    if not isinstance(raw, dict):
        raise ValueError("顶层必须是 JSON 对象 {...}")
    data, m = _empty(), {}
    for g in GROUPS:
        lst = raw.get(g, [])
        if lst is None:
            lst = []
        if isinstance(lst, str):
            lst = [lst]
        if not isinstance(lst, (list, tuple)):
            raise ValueError(f"「{g}」必须是数组")
        for t in lst:
            if t is None:
                continue
            s = str(t).strip()
            if not s:
                continue
            k = norm_tag(s)
            if k in m:
                continue
            m[k] = g
            data[g].append(s)
    return data, m


def _read_raw(path=BLACKLIST_PATH):
    with open(path, "r", encoding="utf-8-sig") as f:
        txt = f.read()
    if not txt.strip():
        return {}
    return json.loads(txt, object_pairs_hook=OrderedDict)


def load(force=False):
    """返回 {'确定': [...], '疑似': [...]} 的副本；按文件签名缓存"""
    with _lock:
        sig = signature()
        if force or sig != _state["sig"]:
            if not os.path.exists(BLACKLIST_PATH):
                _state.update(data=_empty(), map={}, error=None)
            else:
                try:
                    data, m = _parse(_read_raw())
                    _state.update(data=data, map=m, error=None)
                except Exception as e:
                    _state["error"] = f"{type(e).__name__}: {e}"
                    print(f"[黑名单] 解析 {BLACKLIST_PATH} 失败，沿用上次内容: {e}")
            _state["sig"] = sig
        return {g: list(v) for g, v in _state["data"].items()}


def last_error():
    load()
    return _state["error"]


def tag_map():
    load()
    return dict(_state["map"])


def group_of(tag):
    load()
    return _state["map"].get(norm_tag(tag))


def counts():
    d = load()
    return {g: len(d[g]) for g in GROUPS}


def blacklisted_tags(tags, groups=None):
    """返回 [(原tag, 分组), ...]；groups=None 表示所有分组"""
    if not tags:
        return []
    if isinstance(tags, str):
        tags = [tags]
    load()
    m = _state["map"]
    out, seen = [], set()
    for t in tags:
        k = norm_tag(t)
        g = m.get(k)
        if g and (groups is None or g in groups) and k not in seen:
            seen.add(k)
            out.append((str(t), g))
    return out


def is_blacklisted(tags, groups=None):
    return bool(blacklisted_tags(tags, groups))


@contextmanager
def _file_lock():
    os.makedirs(MODULES_DIR, exist_ok=True)
    fh = open(_LOCK_PATH, "a+")
    try:
        if fcntl:
            fcntl.flock(fh.fileno(), fcntl.LOCK_EX)
        yield
    finally:
        try:
            if fcntl:
                fcntl.flock(fh.fileno(), fcntl.LOCK_UN)
        finally:
            fh.close()


def _compose(raw, data):
    out = OrderedDict()
    out[_NOTE_KEY] = (raw or {}).get(_NOTE_KEY, _NOTE)
    for g in GROUPS:
        out[g] = data[g]
    for k, v in (raw or {}).items():
        if k not in out:
            out[k] = v          # 保留你手动加的其他键
    return out


def _write_raw(obj):
    os.makedirs(MODULES_DIR, exist_ok=True)
    fd, tmp = tempfile.mkstemp(dir=MODULES_DIR, prefix=".Tag_Blacklist.", suffix=".tmp")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(obj, f, ensure_ascii=False, indent=2)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, BLACKLIST_PATH)
    except Exception:
        try:
            os.remove(tmp)
        except OSError:
            pass
        raise


def set_group(tag, group):
    """把 tag 放进 group（'确定'/'疑似'）；group=None 表示移出黑名单。返回新分组"""
    s = str(tag).strip()
    if not s:
        raise ValueError("Tag 为空")
    if group is not None and group not in GROUPS:
        raise ValueError(f"未知分组: {group}")
    with _lock, _file_lock():
        if os.path.exists(BLACKLIST_PATH):
            try:
                raw = _read_raw()
                data, _ = _parse(raw)
            except Exception as e:
                raise RuntimeError(
                    f"黑名单文件格式有误，为避免覆盖你的手动修改，本次未写入。\n"
                    f"请先修复：{BLACKLIST_PATH}\n{e}")
        else:
            raw, data = {}, _empty()
        k = norm_tag(s)
        for g in GROUPS:
            data[g] = [t for t in data[g] if norm_tag(t) != k]
        if group:
            data[group].append(s)
        _write_raw(_compose(raw, data))
    load(force=True)
    return group


def add(tag, group=GROUP_SURE):
    return set_group(tag, group)


def remove(tag):
    return set_group(tag, None)


def toggle(tag, group):
    return set_group(tag, None if group_of(tag) == group else group)


def ensure_file():
    if os.path.exists(BLACKLIST_PATH):
        return
    with _lock, _file_lock():
        if not os.path.exists(BLACKLIST_PATH):
            _write_raw(_compose({}, _empty()))


def open_in_editor():
    ensure_file()
    try:
        if sys.platform == "darwin":
            subprocess.Popen(["open", "-t", BLACKLIST_PATH])
        elif sys.platform == "win32":
            os.startfile(BLACKLIST_PATH)   # noqa
        else:
            subprocess.Popen(["xdg-open", BLACKLIST_PATH])
    except Exception as e:
        print(f"[黑名单] 打开文件失败: {e}")

