def show_warning(msg):
    """弹窗警告（同时输出到 stderr，便于 AppleScript 日志记录）"""
    print(f"⚠️  {msg}", file=sys.stderr)
    try:
        root = tk.Tk()
        root.withdraw()
        root.attributes('-topmost', True)
        messagebox.showwarning("警告", msg)
        root.destroy()
    except Exception:
        pass


def die(msg, code=1):
    show_warning(msg)
    sys.exit(code)


