def get_all_url_keys(item: dict) -> list[str]:
    keys = [k for k in item.keys()
            if k == "url" or (k.startswith("url") and k[3:].isdigit())]

    def _sort_key(k):
        return -1 if k == "url" else int(k[3:])

    return sorted(keys, key=_sort_key)


def append_new_url_fields(old_entry: dict, ordered_detail: dict, new_url: str) -> str:
    old_url_keys = get_all_url_keys(old_entry)
    existing_url_vals = []
    max_idx = 0

    for k in old_url_keys:
        v = old_entry.get(k, "")
        existing_url_vals.append(v)
        if k != "url":
            ordered_detail[k] = v
            m = re.match(r"^url(\d+)$", k)
            if m:
                max_idx = max(max_idx, int(m.group(1)))

    if not new_url or new_url in existing_url_vals:
        return ""

    next_key = f"url{max_idx + 1}"
    ordered_detail[next_key] = new_url
    return next_key


def format_date_str(date_str: str) -> str:
    """
    上映日期规范化解析器：
    1. 在全文中定位首个符合标准的 YYYY-MM-DD (或 YYYY/M/D 等) 日期起始位置；
    2. 首部强制规范化为严格的 XXXX-XX-XX 格式；
    3. 保留该日期及其后的完整说明文本（包括多地公映、括号等信息）；
    4. 清洗全角斜杠与多余空白；若无完整年月日，则返回清洗后的原始字符串。
    """
    if not date_str:
        return ""
    s = clean_ws(str(date_str))
    # 移除前导说明文本及折叠标识
    s = re.sub(r"^(?:上映|首映|上映日期|公映时间)[:：\s]+", "", s)
    s = s.replace("[展开...]", "").replace("[展开]", "").strip()
    # 寻找首个符合 年-月-日 完整日期位置
    pattern = r"(\d{4})[-/.年](\d{1,2})[-/.月](\d{1,2})日?"
    match = re.search(pattern, s)
    if match:
        # 将首个日期规范化为 XXXX-XX-XX
        year, month, day = match.group(1), match.group(2).zfill(2), match.group(3).zfill(2)
        normalized_first_date = f"{year}-{month}-{day}"
        # 提取首个日期之后跟随的全部内容（从 match 的 end 处往后）
        tail_content = s[match.end():]
        # 清洗 tail_content：全角斜杠规范化为半角并保持间距
        tail_content = re.sub(r"\s*[／/]\s*", " / ", tail_content)
        tail_content = clean_ws(tail_content)
        full_result = (normalized_first_date + tail_content).strip()
        return full_result
    else:
        # ✅ 没有匹配到完整年月日，直接返回清洗后的原始内容
        # 依然统一斜杠格式
        raw_fixed = re.sub(r"\s*[／/]\s*", " / ", s)
        raw_fixed = clean_ws(raw_fixed)
        return raw_fixed


def get_url_path(url: str) -> str:
    try:
        return urlparse(url).path
    except Exception:
        return url


def ensure_dir(path: str):
    os.makedirs(path, exist_ok=True)


def clean_ws(s: str) -> str:
    return re.sub(r"\s+", " ", s).strip()


def has_chinese(text: str) -> bool:
    return bool(re.search(r"[\u4e00-\u9fa5]", text or ""))


def extract_episode_num(ep_name: str) -> int:
    m = re.search(r"(\d+)", ep_name)
    return int(m.group(1)) if m else 0


def extract_video_id(url: str, name: str) -> str:
    m = re.search(r"/(?:mv|vod|detail)/(\d+)", url)
    if m:
        return m.group(1)
    safe = re.sub(r"[^\w\u4e00-\u9fa5]+", "_", name).strip("_")
    return safe or "unknown"


