            .buttonStyle(PlainButtonStyle())
            .disabled(selectedCount == 0)
        }
        .padding(.horizontal, 18)
        .padding(.top, 16)
        .padding(.bottom, 12)
        .background(.ultraThinMaterial)
        .overlay(alignment: .top) { Divider().opacity(0.5) }
        .transition(.move(edge: .bottom).combined(with: .opacity))
    }
}

