                onWeChatAction: {
                    UIPasteboard.general.string = createShareText()
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) { showWeChatGuideSheet = true }
                },
                onSystemShareAction: {
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) { showSystemActivitySheet = true }
