            .font(.subheadline).fontWeight(.semibold)
            .lineLimit(1)
            .padding(.horizontal, 16).padding(.vertical, 10)
            .frame(maxWidth: .infinity)
            .background(Rectangle().fill(.ultraThinMaterial).ignoresSafeArea(edges: .top))
