                },
                onSystemShareAction: {
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) { showSystemActivitySheet = true }
                }
            )
        }
        .sheet(isPresented: $showWeChatGuideSheet) { WeChatGuideView() }
        .sheet(isPresented: $showSystemActivitySheet) {
