        // 语言/字号变更时预热新版本，避免下一帧同步构建
        .onChange(of: isEnglishMode) { _, newValue in
            ArticleBodyCache.shared.prefetch(article: article,
                                            english: newValue,
                                            fontSize: articleBodyFontSize)
